def read_exact(length: int) -> bytes | None:
    chunks: list[bytes] = []
    remaining = length
    while remaining > 0:
        chunk = sys.stdin.buffer.read(remaining)
        if not chunk:
            return None
        chunks.append(chunk)
        remaining -= len(chunk)
    return b"".join(chunks)


def read_message() -> dict[str, Any] | None:
    global TRANSPORT_MODE

    first = sys.stdin.buffer.read(1)
    while first in {b" ", b"\t", b"\r", b"\n"}:
        first = sys.stdin.buffer.read(1)
    if not first:
        return None

    if first == b"{":
        TRANSPORT_MODE = "ndjson"
        line = bytearray(first)
        while not line.endswith(b"\n"):
            char = sys.stdin.buffer.read(1)
            if not char:
                break
            line.extend(char)
            if len(line) > 16 * 1024 * 1024:
                raise ValueError("MCP JSON line is too large")
        return json.loads(line.decode("utf-8").strip())

    TRANSPORT_MODE = "content-length"
    header = bytearray(first)
    while True:
        char = sys.stdin.buffer.read(1)
        if not char:
            return None
        header.extend(char)
        if header.endswith(b"\r\n\r\n") or header.endswith(b"\n\n"):
            break
        if len(header) > 65536:
            raise ValueError("MCP header is too large")

    header_text = header.decode("ascii", errors="replace").replace("\r\n", "\n")
    content_length = None
    for line in header_text.split("\n"):
        if line.lower().startswith("content-length:"):
            content_length = int(line.split(":", 1)[1].strip())
            break
    if content_length is None:
        raise ValueError("Missing Content-Length header")

    body = read_exact(content_length)
    if body is None:
        return None
    return json.loads(body.decode("utf-8"))


def send_message(message: dict[str, Any]) -> None:
    payload = json.dumps(message, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    if TRANSPORT_MODE == "ndjson":
        sys.stdout.buffer.write(payload)
        sys.stdout.buffer.write(b"\n")
    else:
        sys.stdout.buffer.write(f"Content-Length: {len(payload)}\r\n\r\n".encode("ascii"))
        sys.stdout.buffer.write(payload)
    sys.stdout.buffer.flush()


def rpc_result(request_id: Any, result: dict[str, Any]) -> dict[str, Any]:
    return {"jsonrpc": "2.0", "id": request_id, "result": result}


def rpc_error(request_id: Any, code: int, message: str) -> dict[str, Any]:
    return {"jsonrpc": "2.0", "id": request_id, "error": {"code": code, "message": message}}


def json_safe_value(value: Any) -> Any:
    if isinstance(value, float):
        return value if math.isfinite(value) else None
    if isinstance(value, dict):
        return {str(key): json_safe_value(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [json_safe_value(item) for item in value]
    return value


def tool_result(data: Any, is_error: bool = False) -> dict[str, Any]:
    safe_data = json_safe_value(data)
    return {
        "content": [
            {
                "type": "text",
                "text": json.dumps(safe_data, ensure_ascii=False, indent=2, allow_nan=False),
            }
        ],
        "isError": is_error,
    }


def file_version(path: Path) -> dict[str, Any] | None:
    if not path.exists():
        return None
    script = (
        "[Console]::OutputEncoding=[Text.UTF8Encoding]::UTF8;"
        f"$v=(Get-Item -LiteralPath {json.dumps(str(path))}).VersionInfo;"
        "[PSCustomObject]@{"
        "FileVersion=$v.FileVersion;"
        "ProductVersion=$v.ProductVersion;"
        "ProductName=$v.ProductName;"
        "CompanyName=$v.CompanyName;"
        "FileDescription=$v.FileDescription"
        "} | ConvertTo-Json -Compress"
    )
    try:
        completed = subprocess.run(
            ["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", script],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=8,
        )
    except Exception as exc:
        return {"error": str(exc)}

    if completed.returncode != 0:
        return {"error": completed.stderr.decode("utf-8", errors="replace").strip()}
    text = completed.stdout.decode("utf-8", errors="replace").strip()
    if not text:
        return None
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        return {"raw": text}


def find_installation_data() -> dict[str, Any]:
    env_exe = os.environ.get("OWEN_LOGIC_EXE")
    candidates: list[Path] = []
    if env_exe:
        candidates.append(Path(env_exe))
    candidates.append(DEFAULT_EXE)
    candidates.append(Path(r"C:\Program Files (x86)\OWEN\OWEN Logic\ProgramRelayFBD.exe"))

    seen: set[str] = set()
    normalized: list[Path] = []
    for candidate in candidates:
        key = str(candidate).lower()
        if key not in seen:
            seen.add(key)
            normalized.append(candidate)

    installed = [path for path in normalized if path.exists()]
    exe = installed[0] if installed else normalized[0]
    install_dir = exe.parent if exe.exists() else None
    converter = DEFAULT_CONVERTER_EXE if DEFAULT_CONVERTER_EXE.exists() else None

    return {
        "found": bool(installed),
        "executable": str(exe),
        "install_dir": str(install_dir) if install_dir else None,
        "converter_executable": str(converter) if converter else None,
        "version": file_version(exe) if exe.exists() else None,
        "converter_version": file_version(converter) if converter else None,
        "checked_candidates": [str(path) for path in normalized],
    }


def memory_status_snapshot() -> dict[str, Any]:
    if os.name != "nt" or kernel32 is None:
        return {"available": False, "reason": "GlobalMemoryStatusEx is only available on Windows"}

    class MEMORYSTATUSEX(ctypes.Structure):
        _fields_ = [
            ("dwLength", wintypes.DWORD),
            ("dwMemoryLoad", wintypes.DWORD),
            ("ullTotalPhys", ctypes.c_ulonglong),
            ("ullAvailPhys", ctypes.c_ulonglong),
            ("ullTotalPageFile", ctypes.c_ulonglong),
            ("ullAvailPageFile", ctypes.c_ulonglong),
            ("ullTotalVirtual", ctypes.c_ulonglong),
            ("ullAvailVirtual", ctypes.c_ulonglong),
            ("ullAvailExtendedVirtual", ctypes.c_ulonglong),
        ]

    status = MEMORYSTATUSEX()
    status.dwLength = ctypes.sizeof(MEMORYSTATUSEX)
    if not kernel32.GlobalMemoryStatusEx(ctypes.byref(status)):
        return {"available": False, "error": ctypes.get_last_error()}
    return {
        "available": True,
        "memory_load_percent": int(status.dwMemoryLoad),
        "total_physical_bytes": int(status.ullTotalPhys),
        "available_physical_bytes": int(status.ullAvailPhys),
    }


def disk_usage_snapshot(path: Path | None) -> dict[str, Any]:
    target = path if path and path.exists() else Path(os.environ.get("SystemDrive", "C:") + "\\")
    try:
        usage = shutil.disk_usage(target)
    except OSError as exc:
        return {"available": False, "path": str(target), "error": str(exc)}
    return {
        "available": True,
        "path": str(target),
        "total_bytes": int(usage.total),
        "used_bytes": int(usage.used),
        "free_bytes": int(usage.free),
    }


def system_environment_snapshot(install: dict[str, Any]) -> dict[str, Any]:
    install_dir = Path(str(install["install_dir"])) if install.get("install_dir") else None
    return {
        "platform": platform.platform(),
        "system": platform.system(),
        "release": platform.release(),
        "version": platform.version(),
        "machine": platform.machine(),
        "python_version": platform.python_version(),
        "system_root": os.environ.get("SystemRoot") or os.environ.get("SYSTEMROOT"),
        "windir": os.environ.get("windir") or os.environ.get("WINDIR"),
        "program_files": os.environ.get("ProgramFiles"),
        "program_files_x86": os.environ.get("ProgramFiles(x86)"),
        "memory": memory_status_snapshot(),
        "disk": disk_usage_snapshot(install_dir),
    }


def installed_asset_audit(install: dict[str, Any]) -> dict[str, Any]:
    install_dir_value = install.get("install_dir")
    if not install_dir_value:
        return {
            "install_dir_found": False,
            "help_pages_xml_exists": False,
            "project_json_converter_exists": bool(install.get("converter_executable")),
            "target_catalog_files": [],
            "selected_asset_count": 0,
            "selected_assets": [],
        }
    install_dir = Path(str(install_dir_value))
    selected_names = (
        "ProgramRelayFBD.exe",
        "Help/HelpPages.xml",
        "mapVersion.xml",
        "ProjectJsonConverter/ProgramRelayFBD.exe",
        "ProjectJsonConverter/mapVersion.xml",
    )
    selected_assets: list[dict[str, Any]] = []
    selected_asset_exists = 0
    for name in selected_names:
        asset = install_dir / Path(name)
        if asset.exists():
            selected_asset_exists += 1
        selected_assets.append({**safe_file_info(asset), "exists": asset.exists(), "relative_path": name})
    target_catalog_files = [
        str(path)
        for path in (install_dir, install_dir / "ProjectJsonConverter")
        for path in [path / "mapVersion.xml"]
        if path.exists()
    ]
    return {
        "install_dir_found": install_dir.exists(),
        "help_pages_xml_exists": (install_dir / "Help" / "HelpPages.xml").exists(),
        "project_json_converter_exists": bool(install.get("converter_executable")),
        "target_catalog_files": target_catalog_files,
        "selected_asset_count": selected_asset_exists,
        "selected_assets": selected_assets,
    }


def installation_audit(args: dict[str, Any]) -> dict[str, Any]:
    include_manual_evidence = bool(args.get("include_manual_evidence", True))
    max_results = clamp_int(args.get("max_results"), 4, 1, 20)
    context_chars = clamp_int(args.get("context_chars"), 240, 40, 1000)
    root_value = args.get("root_path")
    root = Path(str(root_value)).expanduser().resolve() if root_value else default_manual_text_root()
    install = find_installation_data()
    assets = installed_asset_audit(install)
    help_summary: dict[str, Any] = {}
    if install.get("install_dir"):
        try:
            help_data = help_index({"query": "Owen Logic", "max_items": 8})
            help_summary = {
                "source": help_data.get("source"),
                "total_matches": help_data.get("total_matches"),
                "returned": help_data.get("returned"),
                "items_returned": len(help_data.get("items") or []),
            }
        except Exception as exc:
            help_summary = {"error": str(exc)}

    manual_queries = [
        {"section": "1", "title": "О программе", "query": "О программе"},
        {"section": "1.1", "title": "Системные требования для работы Owen Logic", "query": "Сист"},
        {"section": "1.2", "title": "Используемые аббревиатуры и термины", "query": "аббревиат"},
        {"section": "2", "title": "Установка", "query": "Установка"},
        {"section": "2", "title": "Installer executable", "query": "Owen Logic.exe"},
    ]
    manual_evidence: list[dict[str, Any]] = []
    if include_manual_evidence:
        if root is None or not root.exists():
            raise FileNotFoundError("Manual evidence root was not found; pass root_path explicitly")
        for query in manual_queries:
            evidence = manual_evidence_search(
                {
                    "query": query["query"],
                    "root_path": str(root),
                    "max_results": max_results,
                    "context_chars": context_chars,
                }
            )
            manual_evidence.append(
                {
                    **query,
                    "root_path": evidence.get("root_path"),
                    "match_count": evidence.get("match_count"),
                    "matches": evidence.get("matches"),
                }
            )

    dangerous_system_guardrail = guardrail_policy()["risk_classes"].get("dangerous_system", {})
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": bool(install.get("found")) and bool(assets.get("help_pages_xml_exists")),
        "installation": install,
        "installed_assets": assets,
        "system_environment": system_environment_snapshot(install),
        "help_index_summary": help_summary,
        "manual_evidence_root": str(root) if root else None,
        "manual_evidence": manual_evidence,
        "manual_evidence_sections_covered": sorted(
            {
                str(row.get("section"))
                for row in manual_evidence
                if int(row.get("match_count") or 0) > 0
            }
        ),
        "installer_plan": {
            "source_manual_section": "rp_owen_logic.pdf section 2",
            "execution_policy": "read_only_audit_no_installer_action",
            "guardrail": dangerous_system_guardrail,
            "installer_action_executed": False,
            "system_change_performed": False,
            "network_action_executed": False,
        },
        "read_only": True,
        "opened_gui": False,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "project_write_performed": False,
        "live_device_action_executed": False,
        "scope": "manual_sections_1_2_installation_system_requirements_read_only_audit",
        "limitation": "This tool audits installation/system-requirement evidence and installed assets only. It does not download, run, repair, update, uninstall, or configure OWEN Logic.",
        "guardrail": "Installer/update/system-changing actions remain dangerous_system and require explicit install/system-change approval outside this read-only audit.",
    }


COMPILER_SURFACE_FILES = (
    "ProgramRelayFBD.exe",
    "Owen.Compiling.dll",
    "CommandProcessor.dll",
    "Owen.ProgrammableRelay.dll",
    "Simulator.dll",
)

COMPILER_SURFACE_KEYWORDS = (
    "compil",
    "compiler",
    "compile",
    "diagnostic",
    "error",
    "warning",
    "validate",
    "convert",
    "converter",
    "command",
    "pipeline",
    "pipe",
    "project",
    "program",
    "симуля",
    "компил",
    "ошиб",
    "предуп",
    "провер",
)


def bounded_binary_strings(path: Path, max_items: int) -> list[str]:
    if not path.exists() or not path.is_file():
        return []
    try:
        data = path.read_bytes()
    except OSError:
        return []

    values: list[str] = []
    seen: set[str] = set()

    def add(value: str) -> None:
        compacted = re.sub(r"\s+", " ", value).strip()
        if len(compacted) < 5 or compacted in seen:
            return
        haystack = compacted.casefold()
        if not any(keyword in haystack for keyword in COMPILER_SURFACE_KEYWORDS):
            return
        seen.add(compacted)
        values.append(compacted[:400])

    for match in re.finditer(rb"[ -~]{5,}", data):
        add(match.group(0).decode("ascii", errors="ignore"))
        if len(values) >= max_items:
            return values

    utf16_pattern = rb"(?:[\x20-\x7e]\x00){5,}"
    for match in re.finditer(utf16_pattern, data):
        try:
            add(match.group(0).decode("utf-16le", errors="ignore"))
        except UnicodeDecodeError:
            continue
        if len(values) >= max_items:
            break
    return values


def compiler_reflection_probe(converter_dir: Path) -> dict[str, Any]:
    program = converter_dir / "ProgramRelayFBD.exe"
    if not program.exists():
        return {"ok": False, "error": f"ProjectJsonConverter executable not found: {program}"}
    script = f"""
$ErrorActionPreference = 'Stop'
$base = {json.dumps(str(converter_dir))}
Push-Location $base
try {{
  $asm = [System.Reflection.Assembly]::LoadFrom((Join-Path $base 'ProgramRelayFBD.exe'))
  $typePattern = 'Compil|Convert|Command|Diagnostic|Error|Project|Validate|Build|Pipe'
  $types = @($asm.GetTypes() | Where-Object {{ $_.FullName -match $typePattern }} | Select-Object -First 160 | ForEach-Object {{
    [pscustomobject]@{{
      full_name = $_.FullName
      is_public = $_.IsPublic
      is_class = $_.IsClass
      is_interface = $_.IsInterface
      base_type = if ($_.BaseType) {{ $_.BaseType.FullName }} else {{ $null }}
    }}
  }})
  $parser = $asm.GetType('ProgramRelayFBD.Helper.CommandLineParser')
  $parserFields = @()
  $parserMethods = @()
  if ($parser) {{
    $parserFields = @($parser.GetFields([System.Reflection.BindingFlags]'Static,Public,NonPublic') | ForEach-Object {{
      [pscustomobject]@{{ name = $_.Name; value = [string]$_.GetValue($null) }}
    }})
    $parserMethods = @($parser.GetMethods([System.Reflection.BindingFlags]'Instance,Static,Public,NonPublic,DeclaredOnly') | ForEach-Object {{
      [string]$_.ToString()
    }})
  }}
  [pscustomobject]@{{
    ok = $true
    assembly = [string]$asm.FullName
    matched_types = $types
    command_line_parser_fields = $parserFields
    command_line_parser_methods = $parserMethods
  }} | ConvertTo-Json -Depth 7 -Compress
}} finally {{
  Pop-Location
}}
"""
    completed = subprocess.run(
        ["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", script],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        encoding="utf-8",
        errors="replace",
        timeout=20,
    )
    if completed.returncode != 0:
        return {"ok": False, "returncode": completed.returncode, "stderr": completed.stderr.strip()}
    text = completed.stdout.strip()
    if not text:
        return {"ok": False, "error": "PowerShell reflection returned no JSON"}
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        return {"ok": False, "raw": text[:4000]}


def taskkill_pid(pid: int) -> dict[str, Any]:
    try:
        completed = subprocess.run(
            ["taskkill", "/PID", str(int(pid)), "/F"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=10,
        )
        return {
            "pid": int(pid),
            "returncode": completed.returncode,
            "stdout": completed.stdout.strip(),
            "stderr": completed.stderr.strip(),
        }
    except Exception as exc:
        return {"pid": int(pid), "error": str(exc)}


def windows_gui_runtime_env() -> tuple[dict[str, str], dict[str, Any]]:
    env = dict(os.environ)
    fixes: dict[str, Any] = {}
    system_root = env.get("SystemRoot") or env.get("SYSTEMROOT") or env.get("windir") or env.get("WINDIR")
    if not system_root:
        system_root = str(Path(os.environ.get("SystemDrive", "C:")) / "Windows")
        fixes["system_root_defaulted"] = True
    if not env.get("windir") and not env.get("WINDIR"):
        env["windir"] = system_root
        fixes["windir_added"] = system_root
    if not env.get("SystemRoot") and not env.get("SYSTEMROOT"):
        env["SystemRoot"] = system_root
        fixes["system_root_added"] = system_root
    return env, fixes


def run_converter_probe_case(
    converter_exe: Path,
    source_project: Path,
    case_dir: Path,
    case_name: str,
    argument_templates: list[str],
    timeout_seconds: int,
    cleanup_launched_process: bool,
) -> dict[str, Any]:
    case_dir.mkdir(parents=True, exist_ok=True)
    project_copy = case_dir / "probe.owle"
    shutil.copy2(source_project, project_copy)
    source_hash = sha256_file(source_project)
    copy_hash_before = sha256_file(project_copy)
    output_project = case_dir / "out.owle"
    stdout_path = case_dir / "stdout.txt"
    stderr_path = case_dir / "stderr.txt"
    args = [str(project_copy)]
    for template in argument_templates:
        if template == "{out}":
            args.append(str(output_project))
        else:
            args.append(template.replace("{out}", str(output_project)))

    before_pids = {int(row["pid"]) for row in tasklist_programrelay() if isinstance(row.get("pid"), int)}
    start = time.monotonic()
    timed_out = False
    error: str | None = None
    returncode: int | None = None
    try:
        with stdout_path.open("w", encoding="utf-8", errors="replace") as stdout_fh, stderr_path.open(
            "w", encoding="utf-8", errors="replace"
        ) as stderr_fh:
            process = subprocess.Popen(
                [str(converter_exe), *args],
                cwd=str(case_dir),
                stdout=stdout_fh,
                stderr=stderr_fh,
                stdin=subprocess.DEVNULL,
                env=windows_gui_runtime_env()[0],
            )
            try:
                returncode = process.wait(timeout=timeout_seconds)
            except subprocess.TimeoutExpired:
                timed_out = True
                process.kill()
                returncode = process.wait(timeout=10)
    except Exception as exc:
        error = str(exc)
    elapsed_ms = int((time.monotonic() - start) * 1000)
    after_pids = {int(row["pid"]) for row in tasklist_programrelay() if isinstance(row.get("pid"), int)}
    new_pids = sorted(after_pids - before_pids)
    cleanup_results: list[dict[str, Any]] = []
    if cleanup_launched_process:
        for pid in new_pids:
            cleanup_results.append(taskkill_pid(pid))
        after_cleanup_pids = {int(row["pid"]) for row in tasklist_programrelay() if isinstance(row.get("pid"), int)}
    else:
        after_cleanup_pids = after_pids

    files_after = [safe_file_info(path, include_hash=path.suffix.lower() in {".owle", ".json"}) for path in sorted(case_dir.iterdir()) if path.is_file()]
    stdout_text = stdout_path.read_text(encoding="utf-8", errors="replace") if stdout_path.exists() else ""
    stderr_text = stderr_path.read_text(encoding="utf-8", errors="replace") if stderr_path.exists() else ""
    output_exists = output_project.exists()
    copy_hash_after = sha256_file(project_copy) if project_copy.exists() else None
    return {
        "case": case_name,
        "args": args,
        "returncode": returncode,
        "timed_out": timed_out,
        "error": error,
        "elapsed_ms": elapsed_ms,
        "stdout_chars": len(stdout_text),
        "stderr_chars": len(stderr_text),
        "stdout_preview": stdout_text[:1000],
        "stderr_preview": stderr_text[:1000],
        "files_after": files_after,
        "output_project_exists": output_exists,
        "source_hash_preserved": sha256_file(source_project) == source_hash,
        "project_copy_hash_before": copy_hash_before,
        "project_copy_hash_after": copy_hash_after,
        "project_copy_modified": copy_hash_after != copy_hash_before,
        "new_programrelayfbd_pids": new_pids,
        "cleanup_results": cleanup_results,
        "programrelayfbd_pids_after_cleanup": sorted(after_cleanup_pids),
    }


def compiler_surface_probe(args: dict[str, Any]) -> dict[str, Any]:
    require_windows()
    include_strings = bool(args.get("include_strings", True))
    include_reflection = bool(args.get("include_reflection", False))
    run_converter_probe = bool(args.get("run_converter_probe", False))
    allow_safe_runtime = bool(args.get("allow_safe_runtime", False))
    max_strings = clamp_int(args.get("max_strings_per_file"), 80, 1, 300)
    case_timeout_seconds = clamp_int(args.get("case_timeout_seconds"), 20, 3, 60)
    cleanup_launched_process = bool(args.get("cleanup_launched_process", True))
    baseline_pids = {int(row["pid"]) for row in tasklist_programrelay() if isinstance(row.get("pid"), int)} if cleanup_launched_process else set()

    install = find_installation_data()
    converter_exe = Path(str(install.get("converter_executable") or DEFAULT_CONVERTER_EXE))
    converter_dir = converter_exe.parent
    install_dir = Path(str(install.get("install_dir") or DEFAULT_EXE.parent))
    candidate_dirs = [converter_dir, install_dir]

    assemblies: list[dict[str, Any]] = []
    seen_paths: set[str] = set()
    for directory in candidate_dirs:
        for name in COMPILER_SURFACE_FILES:
            path = directory / name
            key = str(path).lower()
            if key in seen_paths:
                continue
            seen_paths.add(key)
            row: dict[str, Any] = {
                "role": "ProjectJsonConverter" if directory == converter_dir else "OWEN Logic install",
                "expected_name": name,
                "path": str(path),
                "exists": path.exists(),
            }
            if path.exists():
                row.update(safe_file_info(path, include_hash=True))
                if path.suffix.lower() == ".exe":
                    row["version_info"] = file_version(path)
                if include_strings:
                    row["matched_strings"] = bounded_binary_strings(path, max_strings)
                    row["matched_string_count"] = len(row["matched_strings"])
            assemblies.append(row)

    reflection = compiler_reflection_probe(converter_dir) if include_reflection else {"skipped": True}
    after_reflection_pids = {int(row["pid"]) for row in tasklist_programrelay() if isinstance(row.get("pid"), int)} if cleanup_launched_process else set()
    reflection_launched_pids = sorted(after_reflection_pids - baseline_pids)
    reflection_cleanup: list[dict[str, Any]] = []
    if include_reflection and cleanup_launched_process:
        for pid in reflection_launched_pids:
            reflection_cleanup.append(taskkill_pid(pid))

    converter_cases: list[dict[str, Any]] = []
    scratch_project_info: dict[str, Any] | None = None
    if run_converter_probe:
        if not allow_safe_runtime:
            raise ValueError("owen_logic_compiler_surface_probe requires allow_safe_runtime=true when run_converter_probe=true")
        project_path = Path(str(args.get("project_path") or "")).expanduser().resolve()
        if not project_path.exists():
            raise FileNotFoundError(f"Project file not found: {project_path}")
        workbench = find_workbench_root()
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        scratch_dir = Path(str(args.get("scratch_dir") or "")).expanduser()
        if not str(scratch_dir):
            scratch_dir = (
                workbench / "30_LOCAL_HEAVY" / "sandbox_tmp" / "owen_compiler_surface_probe" / timestamp
                if workbench
                else Path.home() / ".codex" / "tmp" / "owen_compiler_surface_probe" / timestamp
            )
        scratch_dir = scratch_dir.resolve()
        if not is_scratch_destination(scratch_dir):
            raise ValueError(f"Refusing converter probe output outside scratch/sandbox/local-heavy path: {scratch_dir}")
        scratch_dir.mkdir(parents=True, exist_ok=True)
        scratch_project_info = safe_file_info(project_path, include_hash=True)
        case_specs = [
            ("info_plain", ["info"]),
            ("info_hide", ["info", "hide"]),
            ("reformat_equals", ["reformat={out}"]),
            ("version_plain", ["version"]),
        ]
        for case_name, templates in case_specs:
            converter_cases.append(
                run_converter_probe_case(
                    converter_exe=converter_exe,
                    source_project=project_path,
                    case_dir=scratch_dir / case_name,
                    case_name=case_name,
                    argument_templates=templates,
                    timeout_seconds=case_timeout_seconds,
                    cleanup_launched_process=cleanup_launched_process,
                )
            )

    successful_converter_cases = [
        case
        for case in converter_cases
        if case.get("returncode") == 0
        and not case.get("timed_out")
        and (case.get("stdout_chars") or case.get("stderr_chars") or case.get("output_project_exists"))
    ]
    output_cases = [case for case in converter_cases if case.get("output_project_exists")]
    new_pids_after_cleanup = sorted(
        {
            int(pid)
            for case in converter_cases
            for pid in case.get("programrelayfbd_pids_after_cleanup", [])
            if isinstance(pid, int)
        }
    )
    final_pids = {int(row["pid"]) for row in tasklist_programrelay() if isinstance(row.get("pid"), int)} if cleanup_launched_process else set()
    compiler_surface_detected = any(path.get("exists") for path in assemblies)
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": compiler_surface_detected,
        "installation": install,
        "compiler_surface_detected": compiler_surface_detected,
        "assemblies": assemblies,
        "reflection": reflection,
        "reflection_process_guard": {
            "baseline_programrelayfbd_pids": sorted(baseline_pids),
            "launched_programrelayfbd_pids": reflection_launched_pids,
            "cleanup_attempts": reflection_cleanup,
            "final_programrelayfbd_pids": sorted(final_pids),
        },
        "converter_probe": {
            "ran": run_converter_probe,
            "source_project": scratch_project_info,
            "cases": converter_cases,
            "case_count": len(converter_cases),
            "successful_case_count": len(successful_converter_cases),
            "output_project_case_count": len(output_cases),
            "new_programrelayfbd_pids_after_cleanup": new_pids_after_cleanup,
        },
        "command_line_arguments_detected": (reflection.get("command_line_parser_fields") if isinstance(reflection, dict) else None),
        "headless_compiler_cli_confirmed": False,
        "full_compiler_diagnostics_claimed": False,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "live_device_action_executed": False,
        "scope": "installed_compiler_converter_surface_discovery_plus_optional_scratch_only_converter_cli_probe",
        "limitation": "This tool discovers local compiler/converter assemblies, command-line parser fields, diagnostic strings, and converter behavior on scratch copies. It does not instantiate OWEN compiler internals as a full compiler and does not parse authoritative compiler diagnostics.",
        "guardrail": "Read-only installation inspection by default. Optional converter execution requires allow_safe_runtime=true, copies the project to scratch, preserves the source hash, does not open COM/IP, and cleans up only newly spawned ProgramRelayFBD.exe processes.",
    }


def compiler_diagnostics_deep_reflection(converter_dir: Path, cleanup_launched_process: bool) -> dict[str, Any]:
    baseline_pids = {int(row["pid"]) for row in tasklist_programrelay() if isinstance(row.get("pid"), int)} if cleanup_launched_process else set()
    script = f"""
$ErrorActionPreference = 'Stop'
$base = {json.dumps(str(converter_dir))}
Push-Location $base
try {{
  $targets = @(
    @{{ assembly = 'Owen.Compiling.dll'; types = @(
      'Owen.Compiling.ProgramLinker',
      'Owen.Compiling.ProgramItem',
      'Owen.Compiling.ICompiler',
      'Owen.Compiling.ICompilerState',
      'Owen.Compiling.IBuildingElement',
      'Owen.Compiling.ClassError',
      'Owen.Compiling.BuilderFactory'
    ) }},
    @{{ assembly = 'Owen.ProgrammableRelay.dll'; types = @(
      'Owen.ProgrammableRelay.ProgramCode',
      'Owen.ProgrammableRelay.Generator',
      'Owen.ProgrammableRelay.GeneratorDefault',
      'Owen.ProgrammableRelay.GeneratorSeries200',
      'Owen.ProgrammableRelay.ContainersVer2.ContainersGeneratorVer2',
      'Owen.ProgrammableRelay.DeviceFamily'
    ) }},
    @{{ assembly = 'ProgramRelayFBD.exe'; types = @(
      'ProgramRelayFBD.DrawingView',
      'ProgramRelayFBD.DrawingDocument',
      'ProgramRelayFBD.CompilerException',
      'ProgramRelayFBD.ApplicationLayer.ICompilerFactory',
      'ProgramRelayFBD.DataCompiler',
      'ProgramRelayFBD.IPreBuilding'
    ) }},
    @{{ assembly = 'ProgramRelayFbd.Messages.dll'; types = @(
      'ProgramRelayFbd.Messages.Commands.BuildProjectCommand',
      'ProgramRelayFbd.Messages.Events.ProjectBuilding.BuildProcessCompletedEvent',
      'ProgramRelayFbd.Messages.Events.ProjectBuilding.BuildProcessCompletedVer2Event',
      'ProgramRelayFbd.Messages.Events.ProjectBuilding.BuildProcessFailedEvent',
      'ProgramRelayFbd.Messages.Events.ProjectBuilding.ProjectInBuildProcessEvent'
    ) }}
  )
  $rows = foreach ($entry in $targets) {{
    $path = Join-Path $base $entry.assembly
    if (!(Test-Path -LiteralPath $path)) {{
      [pscustomobject]@{{ assembly = $entry.assembly; path = $path; exists = $false }}
      continue
    }}
    try {{
      $asm = [System.Reflection.Assembly]::LoadFrom($path)
      try {{
        $allTypes = @($asm.GetTypes())
      }} catch [System.Reflection.ReflectionTypeLoadException] {{
        $allTypes = @($_.Exception.Types | Where-Object {{ $_ -ne $null }})
      }}
      $matchedTypes = @($allTypes | Where-Object {{ $_.FullName -match 'Compil|Build|Diagnostic|Error|Warning|Validate|Program|Project|Generate|Message|Event' }})
      $selected = foreach ($typeName in $entry.types) {{
        $t = $asm.GetType($typeName)
        if ($null -eq $t) {{
          [pscustomobject]@{{ full_name = $typeName; found = $false }}
          continue
        }}
        $methods = @($t.GetMethods([System.Reflection.BindingFlags]'Instance,Static,Public,NonPublic,DeclaredOnly') |
          Where-Object {{ $_.ToString() -match 'Compil|Build|Diagnostic|Error|Warning|Validate|Program|Generate|Run|Execute|Create|Handle|Add' }} |
          Select-Object -First 80 | ForEach-Object {{ $_.ToString() }})
        [pscustomobject]@{{
          full_name = $t.FullName
          found = $true
          is_public = $t.IsPublic
          is_class = $t.IsClass
          is_interface = $t.IsInterface
          is_abstract = $t.IsAbstract
          base_type = if ($t.BaseType) {{ $t.BaseType.FullName }} else {{ $null }}
          constructors = @($t.GetConstructors([System.Reflection.BindingFlags]'Instance,Public,NonPublic') | Select-Object -First 30 | ForEach-Object {{ $_.ToString() }})
          methods = $methods
          properties = @($t.GetProperties([System.Reflection.BindingFlags]'Instance,Static,Public,NonPublic,DeclaredOnly') |
            Where-Object {{ $_.ToString() -match 'Compil|Build|Diagnostic|Error|Warning|Validate|Program|Generate|State|Elements' }} |
            Select-Object -First 50 | ForEach-Object {{ $_.ToString() }})
          fields = @($t.GetFields([System.Reflection.BindingFlags]'Instance,Static,Public,NonPublic,DeclaredOnly') |
            Where-Object {{ $_.ToString() -match 'Compil|Build|Diagnostic|Error|Warning|Validate|Program|Generate|State|Elements' }} |
            Select-Object -First 50 | ForEach-Object {{ $_.ToString() }})
        }}
      }}
      [pscustomobject]@{{
        assembly = $entry.assembly
        path = $path
        exists = $true
        assembly_name = [string]$asm.FullName
        type_count = $allTypes.Count
        matched_type_count = $matchedTypes.Count
        selected_types = @($selected)
      }}
    }} catch {{
      [pscustomobject]@{{ assembly = $entry.assembly; path = $path; exists = $true; error = $_.Exception.Message }}
    }}
  }}
  [pscustomobject]@{{ ok = $true; assemblies = @($rows) }} | ConvertTo-Json -Depth 9 -Compress
}} finally {{
  Pop-Location
}}
"""
    completed = subprocess.run(
        ["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", script],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        encoding="utf-8",
        errors="replace",
        timeout=45,
    )
    after_pids = {int(row["pid"]) for row in tasklist_programrelay() if isinstance(row.get("pid"), int)} if cleanup_launched_process else set()
    launched_pids = sorted(after_pids - baseline_pids)
    cleanup_results: list[dict[str, Any]] = []
    if cleanup_launched_process:
        for pid in launched_pids:
            cleanup_results.append(taskkill_pid(pid))
    final_pids = {int(row["pid"]) for row in tasklist_programrelay() if isinstance(row.get("pid"), int)} if cleanup_launched_process else set()
    process_guard = {
        "baseline_programrelayfbd_pids": sorted(baseline_pids),
        "launched_programrelayfbd_pids": launched_pids,
        "cleanup_attempts": cleanup_results,
        "final_programrelayfbd_pids": sorted(final_pids),
    }
    if completed.returncode != 0:
        return {
            "ok": False,
            "returncode": completed.returncode,
            "stderr": completed.stderr.strip(),
            "process_guard": process_guard,
        }
    try:
        parsed = json.loads(completed.stdout.strip().lstrip("\ufeff"))
    except json.JSONDecodeError as exc:
        return {
            "ok": False,
            "error": f"deep reflection JSON parse failed: {exc}",
            "stdout_preview": completed.stdout[:4000],
            "stderr": completed.stderr.strip(),
            "process_guard": process_guard,
        }
    parsed["process_guard"] = process_guard
    selected_names = [
        str(item.get("full_name") or "")
        for assembly in parsed.get("assemblies") or []
        for item in assembly.get("selected_types") or []
        if item.get("found")
    ]
    parsed["compile_api_surface_confirmed"] = all(
        required in selected_names
        for required in (
            "Owen.Compiling.ProgramLinker",
            "Owen.Compiling.ProgramItem",
            "Owen.Compiling.ICompiler",
            "Owen.Compiling.ICompilerState",
            "ProgramRelayFBD.DrawingView",
            "ProgramRelayFBD.DrawingDocument",
            "ProgramRelayFBD.CompilerException",
            "ProgramRelayFbd.Messages.Commands.BuildProjectCommand",
            "ProgramRelayFbd.Messages.Events.ProjectBuilding.BuildProcessFailedEvent",
        )
    )
    return parsed


def decompiled_compiler_source_inventory() -> dict[str, Any]:
    workbench = find_workbench_root()
    if not workbench:
        return {"ok": False, "error": "workbench root not found"}
    root = workbench / "20_PRIVATE_UNSAFE" / "engineering" / "owen_reverse_engineering" / "source"
    if not root.exists():
        return {"ok": False, "root": str(root), "error": "decompiled OWEN source root not found"}
    directories = [
        root / "decompiled_owen_compiling",
        root / "decompiled_programmablerelay",
        root / "decompiled_programrelay",
    ]
    keywords = ("компил", "ошиб", "предуп", "build", "compile", "compiler", "error", "warning", "diagnostic")
    rows: list[dict[str, Any]] = []
    resource_messages: list[dict[str, Any]] = []
    for directory in directories:
        files = [path for path in directory.rglob("*") if path.is_file()] if directory.exists() else []
        cs_files = [path for path in files if path.suffix.lower() == ".cs"]
        resx_files = [path for path in files if path.suffix.lower() == ".resx"]
        rows.append(
            {
                "path": str(directory),
                "exists": directory.exists(),
                "file_count": len(files),
                "cs_file_count": len(cs_files),
                "resx_file_count": len(resx_files),
            }
        )
        for resx in resx_files:
            try:
                root_xml = ElementTree.parse(resx).getroot()
            except Exception:
                continue
            for data in root_xml.findall("data"):
                name = str(data.get("name") or "")
                value_element = data.find("value")
                value = "".join(value_element.itertext()).strip() if value_element is not None else ""
                if value and any(keyword in value.casefold() for keyword in keywords):
                    resource_messages.append(
                        {
                            "path": str(resx),
                            "name": name,
                            "value": compact_string(value, 300),
                        }
                    )
                    if len(resource_messages) >= 80:
                        break
            if len(resource_messages) >= 80:
                break
    return {
        "ok": True,
        "root": str(root),
        "directories": rows,
        "compiler_or_diagnostic_resource_messages": resource_messages,
        "compiler_or_diagnostic_resource_message_count": len(resource_messages),
        "limitation": "The local decompiled source corpus is partial. It contributes resource/string evidence and a few host types, but it is not a complete source-level compiler implementation.",
    }


def latest_ilspy_selected_decompile_dir(workbench: Path | None) -> Path | None:
    if not workbench:
        return None
    root = workbench / "30_LOCAL_HEAVY" / "scratch" / "owen_ilspy_tool"
    if not root.exists():
        return None
    candidates = [path for path in root.glob("selected_decompile_*") if path.is_dir()]
    if not candidates:
        return None
    return sorted(candidates, key=lambda item: item.stat().st_mtime, reverse=True)[0]


def execution_path_line_hits(path: Path, patterns: tuple[str, ...], max_hits: int = 16) -> list[dict[str, Any]]:
    if not path.exists():
        return []
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return []
    hits: list[dict[str, Any]] = []
    lowered_patterns = tuple(pattern.casefold() for pattern in patterns)
    for index, line in enumerate(text.splitlines(), start=1):
        lowered = line.casefold()
        if any(pattern in lowered for pattern in lowered_patterns):
            hits.append({"line": index, "text": compact_string(line.strip(), 260)})
            if len(hits) >= max_hits:
                break
    return hits


def compiler_diagnostics_execution_path_inventory() -> dict[str, Any]:
    """Inventory the real OWEN compiler-diagnostics execution routes found by decompilation.

    This deliberately reports paths and limitations; it does not invoke any compiler,
    live device action, or unsafe write-program command.
    """

    workbench = find_workbench_root()
    selected_dir = latest_ilspy_selected_decompile_dir(workbench)
    reverse_root = (
        workbench / "20_PRIVATE_UNSAFE" / "engineering" / "owen_reverse_engineering" / "source"
        if workbench
        else None
    )
    files: dict[str, Path] = {}
    if selected_dir:
        files.update(
            {
                "command_line_parser": selected_dir / "ProgramRelayFBD.Helper.CommandLineParser.cs",
                "pipe_command_factory": selected_dir / "ProgramRelayFBD.Factories.PipeCommandFactory.cs",
                "form1": selected_dir / "ProgramRelayFBD.PresentationLayer.Form1.cs",
                "replication_build_handler": selected_dir / "ProgramRelayFBD.InfrastructureLayer.Adapters.ReplicationAddOnCommandHandler.cs",
                "base_compiler": selected_dir / "ProgramRelayFBD.DomainLayer.Compilers.BaseCompiler.cs",
                "compiler_exception_handler": selected_dir / "ProgramRelayFBD.ApplicationLayer.CompilerExceptionHandler.cs",
                "serialization_presenter": selected_dir / "ProgramRelayFBD.InfrastructureLayer.Adapters.SerializationPresenter.cs",
            }
        )
    if reverse_root:
        notify_path = (
            reverse_root
            / "decompiled_programrelay"
            / "ProgramRelayFBD.ApplicationLayer.AddOns"
            / "NotifyOnError.cs"
        )
        if notify_path.exists():
            files["notify_on_error"] = notify_path

    def read(path: Path | None) -> str:
        if not path or not path.exists():
            return ""
        try:
            return path.read_text(encoding="utf-8", errors="replace")
        except Exception:
            return ""

    command_line_text = read(files.get("command_line_parser"))
    pipe_text = read(files.get("pipe_command_factory"))
    form_text = read(files.get("form1"))
    replication_text = read(files.get("replication_build_handler"))
    base_compiler_text = read(files.get("base_compiler"))
    notify_text = read(files.get("notify_on_error"))

    cli_arguments_detected = [
        arg
        for arg in ("info", "testupdater", "reformat", "hide", "culture", "pipe", "version")
        if f'"{arg}"' in command_line_text
    ]
    cli_compile_command_detected = bool(re.search(r'"(?:compile|build|diagnostic|validate)"', command_line_text, re.I))
    pipe_commands_detected = [
        command
        for command in ("CONNECTTODEVICE", "EXIT")
        if command in pipe_text
    ]
    pipe_compile_command_detected = bool(re.search(r"COMPILE|BUILD|DIAGNOSTIC|VALIDATE", pipe_text, re.I))
    safe_gui_auto_update_compiler_path_detected = all(
        token in form_text
        for token in (
            "UpdateUserProgramAsync",
            "RunCompilerWithCancellation",
            "CompilerException",
            "SetStatusMessage",
        )
    )
    build_project_command_programming_path_detected = all(
        token in replication_text
        for token in (
            "HandleBuildProjectCommand",
            "WriteUserProgramAsync",
            "BuildProjectCommand",
        )
    )
    build_error_event_surface_detected = (
        "BuildProcessFailedEvent" in notify_text
        or "NotifyOnError" in replication_text
        and "WriteMessage" in replication_text
    )
    base_compiler_error_marking_detected = all(
        token in base_compiler_text
        for token in ("CompilePrograms", "AddElementWithError", "RunAsync")
    )
    menu_compiler_device_write_surface_detected = (
        "menuCompiler" in form_text and "DeviceWrite" in form_text and "NShortcut(118, 131072)" in form_text
    )

    file_rows = []
    for key, path in sorted(files.items()):
        row = {
            "key": key,
            "path": str(path),
            "exists": path.exists(),
        }
        if path.exists():
            row.update(safe_file_info(path, include_hash=True))
        file_rows.append(row)

    line_hits = {
        "command_line_parser": execution_path_line_hits(
            files.get("command_line_parser") or Path(),
            ("InfoArgumentName", "ReformatArgumentName", "PipeArgumentName", "VersionArgumentName", "AddOpenFileCommand"),
        ),
        "pipe_command_factory": execution_path_line_hits(
            files.get("pipe_command_factory") or Path(),
            ("CONNECTTODEVICE", "EXIT", "CommandNotSupported"),
        ),
        "form1_safe_compile_path": execution_path_line_hits(
            files.get("form1") or Path(),
            ("UpdateUserProgramAsync", "RunCompilerWithCancellation", "CompilerException", "SetStatusMessage"),
        ),
        "form1_menu_compiler": execution_path_line_hits(
            files.get("form1") or Path(),
            ("menuCompiler", "DeviceWrite", "NShortcut(118, 131072)"),
        ),
        "replication_build_handler": execution_path_line_hits(
            files.get("replication_build_handler") or Path(),
            ("HandleBuildProjectCommand", "BuildProjectCommand", "WriteUserProgramAsync", "NotifyOnError"),
        ),
        "notify_on_error": execution_path_line_hits(
            files.get("notify_on_error") or Path(),
            ("BuildProcessFailedEvent", "WriteMessage"),
        ),
        "base_compiler": execution_path_line_hits(
            files.get("base_compiler") or Path(),
            ("RunAsync", "CompilePrograms", "AddElementWithError", "CompilerException"),
        ),
    }

    return {
        "ok": bool(selected_dir) and safe_gui_auto_update_compiler_path_detected,
        "selected_decompile_dir": str(selected_dir) if selected_dir else None,
        "file_count": len([row for row in file_rows if row.get("exists")]),
        "files": file_rows,
        "cli_arguments_detected": cli_arguments_detected,
        "cli_compile_command_detected": cli_compile_command_detected,
        "pipe_commands_detected": pipe_commands_detected,
        "pipe_compile_command_detected": pipe_compile_command_detected,
        "safe_gui_auto_update_compiler_path_detected": safe_gui_auto_update_compiler_path_detected,
        "build_project_command_programming_path_detected": build_project_command_programming_path_detected,
        "build_error_event_surface_detected": build_error_event_surface_detected,
        "base_compiler_error_marking_detected": base_compiler_error_marking_detected,
        "menu_compiler_device_write_surface_detected": menu_compiler_device_write_surface_detected,
        "line_hits": line_hits,
        "safe_offline_route": [
            "Open scratch .owle through OWEN Logic GUI or command-line file open.",
            "Let Form1.SetNeedUpdateProgram/UpdateUserProgramAsync create a BaseCompiler for the active DrawingView.",
            "Capture status/error diagnostics from CompilerExceptionHandler/CompilerErrorData/UI status panels.",
        ],
        "unsafe_or_live_related_routes": [
            "PipeCommandFactory supports CONNECTTODEVICE and EXIT only; it is not a compiler diagnostics channel.",
            "BuildProjectCommand enters ReplicationAddOnCommandHandler.HandleBuildProjectCommand and calls WriteUserProgramAsync; treat it as write-program/live-device-adjacent unless a separate scratch proof shows otherwise.",
            "menuCompiler uses DeviceWrite icon/shortcut evidence and must not be used as offline compile without live-device preflight.",
        ],
        "headless_compiler_cli_confirmed": False,
        "authoritative_headless_compiler_diagnostics_confirmed": False,
        "full_compiler_diagnostics_claimed": False,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "live_device_action_executed": False,
        "limitation": "This inventory is a decompiled execution-path audit. It narrows the safe route for future GUI diagnostic smoke, but does not itself execute the compiler or prove full diagnostics for arbitrary projects.",
    }


def compiler_diagnostics_audit(args: dict[str, Any]) -> dict[str, Any]:
    require_windows()
    include_strings = bool(args.get("include_strings", True))
    include_deep_reflection = bool(args.get("include_deep_reflection", True))
    include_decompiled_sources = bool(args.get("include_decompiled_sources", True))
    run_gui_diagnostics_probe = bool(args.get("run_gui_diagnostics_probe", False))
    allow_safe_runtime = bool(args.get("allow_safe_runtime", False))
    cleanup_launched_process = bool(args.get("cleanup_launched_process", True))
    max_strings = clamp_int(args.get("max_strings_per_file"), 80, 1, 300)
    if run_gui_diagnostics_probe and not allow_safe_runtime:
        raise ValueError("owen_logic_compiler_diagnostics_audit requires allow_safe_runtime=true when run_gui_diagnostics_probe=true")

    install = find_installation_data()
    converter_exe = Path(str(install.get("converter_executable") or DEFAULT_CONVERTER_EXE))
    converter_dir = converter_exe.parent
    surface = compiler_surface_probe(
        {
            "include_strings": include_strings,
            "include_reflection": False,
            "run_converter_probe": False,
            "max_strings_per_file": max_strings,
            "cleanup_launched_process": cleanup_launched_process,
        }
    )
    deep_reflection = (
        compiler_diagnostics_deep_reflection(converter_dir, cleanup_launched_process)
        if include_deep_reflection
        else {"skipped": True}
    )
    decompiled_sources = decompiled_compiler_source_inventory() if include_decompiled_sources else {"skipped": True}
    execution_path = compiler_diagnostics_execution_path_inventory()

    gui_probe = None
    if run_gui_diagnostics_probe:
        project_value = str(args.get("project_path") or "").strip()
        if not project_value:
            raise ValueError("project_path is required when run_gui_diagnostics_probe=true")
        gui_args: dict[str, Any] = {
            "project_path": project_value,
            "allow_safe_runtime": True,
            "exercise_enter_simulator": True,
            "exercise_step": bool(args.get("exercise_step", False)),
            "exercise_start_stop": bool(args.get("exercise_start_stop", False)),
            "include_ui_tree": True,
            "save_ui_tree": True,
            "include_offscreen": bool(args.get("include_offscreen", False)),
            "max_depth": clamp_int(args.get("max_depth"), 7, 0, 10),
            "max_children": clamp_int(args.get("max_children"), 250, 1, 1000),
            "max_diagnostic_controls": clamp_int(args.get("max_diagnostic_controls"), 80, 1, 500),
            "screenshot": True,
            "wait_seconds": max(1, min(float(args.get("wait_seconds", 8)), 120)),
            "action_wait_seconds": max(0, min(float(args.get("action_wait_seconds", 1)), 10)),
            "cleanup_launched_process": cleanup_launched_process,
        }
        scratch_value = str(args.get("scratch_dir") or "").strip()
        if scratch_value:
            gui_args["scratch_dir"] = scratch_value
        gui_probe = project_gui_diagnostics_smoke(gui_args)

    compile_api_surface_confirmed = bool(deep_reflection.get("compile_api_surface_confirmed")) if isinstance(deep_reflection, dict) else False
    gui_diagnostic_surface_confirmed = bool(
        isinstance(gui_probe, dict)
        and gui_probe.get("ok")
        and int(gui_probe.get("diagnostic_snapshot_count") or 0) > 0
        and int(gui_probe.get("ui_snapshot_ok_count") or 0) > 0
    )
    ok = bool(surface.get("ok")) and (not include_deep_reflection or bool(deep_reflection.get("ok"))) and (
        not run_gui_diagnostics_probe or gui_diagnostic_surface_confirmed
    )
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": ok,
        "installation": install,
        "compiler_surface": {
            "ok": surface.get("ok"),
            "compiler_surface_detected": surface.get("compiler_surface_detected"),
            "assembly_count": len(surface.get("assemblies") or []),
            "assemblies": surface.get("assemblies"),
            "headless_compiler_cli_confirmed": surface.get("headless_compiler_cli_confirmed"),
            "full_compiler_diagnostics_claimed": surface.get("full_compiler_diagnostics_claimed"),
            "limitation": surface.get("limitation"),
        },
        "deep_reflection": deep_reflection,
        "decompiled_sources": decompiled_sources,
        "execution_path_inventory": execution_path,
        "gui_diagnostics_probe": gui_probe,
        "compile_api_surface_confirmed": compile_api_surface_confirmed,
        "gui_diagnostic_surface_confirmed": gui_diagnostic_surface_confirmed,
        "safe_gui_auto_update_compiler_path_detected": bool(
            execution_path.get("safe_gui_auto_update_compiler_path_detected")
        ),
        "cli_compile_command_detected": bool(execution_path.get("cli_compile_command_detected")),
        "pipe_compile_command_detected": bool(execution_path.get("pipe_compile_command_detected")),
        "build_project_command_programming_path_detected": bool(
            execution_path.get("build_project_command_programming_path_detected")
        ),
        "menu_compiler_device_write_surface_detected": bool(
            execution_path.get("menu_compiler_device_write_surface_detected")
        ),
        "headless_compiler_cli_confirmed": False,
        "authoritative_headless_compiler_diagnostics_confirmed": False,
        "full_compiler_diagnostics_claimed": False,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "live_device_action_executed": False,
        "remaining_requirements_for_full_closure": [
            "load or reconstruct OWEN DrawingDocument/ProgramItem from .owle without relying on manual GUI-only state",
            "execute the safe Form1.UpdateUserProgramAsync/DrawingView compile path on a scratch project and capture status diagnostics",
            "capture authoritative compiler diagnostics for both passing and intentionally broken projects",
            "map diagnostics back to affected FBD/ST/display/Modbus/manual sections without overbroad inference",
            "do not use BuildProjectCommand/menuCompiler as an offline compile shortcut unless a separate preflight proves it cannot write to or contact a device",
        ],
        "scope": "compiler_build_api_reflection_and_optional_gui_diagnostic_surface_audit",
        "limitation": "This audit proves the local compiler/build API surface, decompiled execution-path evidence, and optional bounded GUI diagnostic/status evidence. It still does not prove a complete headless OWEN compiler diagnostic pipeline for arbitrary projects.",
        "guardrail": "Read-only installation/reflection/source inventory by default. Optional GUI diagnostics opens only a scratch .owle copy and executes no COM/IP, network, live-device, download, firmware, calibration or device-settings actions.",
    }


def guardrail_policy() -> dict[str, Any]:
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "risk_classes": {
            "safe_read": {
                "allowed_by_default": True,
                "description": "Read-only operations such as installation discovery, process/window enumeration, screenshots and UI snapshots.",
                "requirements": ["No project mutation", "No live device writes", "No network side effects"],
            },
            "safe_runtime": {
                "allowed_by_default": True,
                "description": "Local simulator/runtime operations on scratch or explicitly selected project copies.",
                "requirements": ["No COM/IP live target", "Collect before/after evidence when state changes"],
            },
            "safe_write_project": {
                "allowed_by_default": False,
                "description": "Operations that edit an OWEN Logic project file or project canvas.",
                "requirements": [
                    "Use only an explicit project path or scratch copy",
                    "Create a backup or preserve the original input",
                    "Report changed project paths",
                ],
            },
            "network": {
                "allowed_by_default": False,
                "description": "OwenCloud, OPC export, update checks and other operations with external destinations.",
                "requirements": ["Require opt-in", "Confirm endpoint/destination", "Record exported file paths"],
            },
            "sensitive": {
                "allowed_by_default": False,
                "description": "Passwords, project keys and other secret-bearing operations.",
                "requirements": ["Never echo secret values", "Use user-supplied secret paths", "Redact evidence"],
            },
            "live_device": {
                "allowed_by_default": False,
                "description": "Operations that connect to or read/write a physical controller over COM/IP.",
                "requirements": [
                    "Run owen_logic_live_device_preflight before any execution",
                    "Explicit live-device confirmation",
                    "Confirm selected COM/IP target",
                    "Provide readback and abort path",
                ],
            },
            "dangerous_live_device": {
                "allowed_by_default": False,
                "description": "Firmware update, calibration, program download and other operations that can alter a physical device.",
                "requirements": [
                    "Run owen_logic_live_device_preflight before any execution",
                    "Explicit confirmation for the exact target",
                    "Backup/readback plan",
                    "Dry-run when available",
                    "No unattended execution",
                ],
            },
            "dangerous_system": {
                "allowed_by_default": False,
                "description": "Installer or system-level changes.",
                "requirements": ["Default to plan/check only", "Require explicit install/system-change approval"],
            },
        },
    }


