def normalize_guarded_action(value: Any) -> str:
    text = str(value or "").strip().casefold()
    aliases = {
        "project_key": "project_key_protect",
        "project_password": "project_key_protect",
        "password": "project_key_protect",
        "key": "project_key_protect",
        "owencloud": "owencloud_export",
        "cloud": "owencloud_export",
        "cloud_check": "cloud_connection_check",
        "connection_check": "cloud_connection_check",
        "opc": "opc_export",
        "extension": "extension_update",
        "extensions": "extension_update",
        "update": "extension_update",
        "replication": "replication_wizard",
        "replication_master": "replication_wizard",
    }
    key = re.sub(r"[^a-z0-9_]+", "_", text).strip("_")
    return aliases.get(key, key)


def guarded_action_profile(action: str, source_section: str | None) -> tuple[str, dict[str, Any]]:
    normalized = normalize_guarded_action(action)
    if normalized in GUARDED_ACTION_PROFILES:
        return normalized, GUARDED_ACTION_PROFILES[normalized]
    section = (source_section or "").strip()
    if section == "4.2.1":
        return "project_key_protect", GUARDED_ACTION_PROFILES["project_key_protect"]
    if section == "5.7":
        return "owencloud_export", GUARDED_ACTION_PROFILES["owencloud_export"]
    if section == "9.1":
        return "replication_wizard", GUARDED_ACTION_PROFILES["replication_wizard"]
    if section == "9.2":
        return "opc_export", GUARDED_ACTION_PROFILES["opc_export"]
    if section == "9.3":
        return "owencloud_export", GUARDED_ACTION_PROFILES["owencloud_export"]
    if section == "9":
        return "extension_update", GUARDED_ACTION_PROFILES["extension_update"]
    raise ValueError(
        "Unsupported guarded action. Use project_key_protect, project_key_remove, owencloud_export, "
        "cloud_connection_check, opc_export, extension_update or replication_wizard."
    )


def guarded_action_preflight(args: dict[str, Any]) -> dict[str, Any]:
    action = str(args.get("action") or "").strip()
    if not action:
        raise ValueError("'action' must be a non-empty string")
    source_section = str(args.get("source_section") or "").strip() or None
    normalized_action, profile = guarded_action_profile(action, source_section)
    include_manual_evidence = bool(args.get("include_manual_evidence", True))
    max_results = clamp_int(args.get("max_results"), 4, 1, 20)
    context_chars = clamp_int(args.get("context_chars"), 240, 40, 1000)
    endpoint_description = str(args.get("endpoint_description") or "").strip() or None
    secret_reference = str(args.get("secret_reference") or "").strip() or None
    root_value = args.get("root_path")
    root = Path(str(root_value)).expanduser().resolve() if root_value else default_manual_text_root()

    policy = guardrail_policy()["risk_classes"]
    required_policy = {
        key: policy.get(key, {})
        for key in profile.get("required_policy", [])
    }
    manual_evidence: list[dict[str, Any]] = []
    if include_manual_evidence:
        if root is None or not root.exists():
            raise FileNotFoundError("Manual evidence root was not found; pass root_path explicitly")
        for query in profile.get("manual_queries", []):
            evidence = manual_evidence_search(
                {
                    "query": query,
                    "root_path": str(root),
                    "max_results": max_results,
                    "context_chars": context_chars,
                }
            )
            manual_evidence.append(
                {
                    "query": query,
                    "match_count": evidence.get("match_count"),
                    "matches": evidence.get("matches"),
                }
            )

    read_only_catalog: dict[str, Any] | None = None
    if profile.get("kind") in {"network", "network_and_live_device"}:
        read_only_catalog = extensions_catalog({"max_items": 60})

    preflight_steps = [
        {
            "step": "manual_and_catalog_evidence",
            "status": "executed_read_only",
            "tools": ["owen_logic_manual_evidence_search"] + (["owen_logic_extensions_catalog"] if read_only_catalog else []),
        },
        {
            "step": "operator_confirmation",
            "status": "required_before_execution",
            "requirements": [
                "Explicit user opt-in for this exact action",
                "Exact target/project/destination confirmation",
                "Abort path before any action",
            ],
        },
        {
            "step": "sensitive_or_network_execution",
            "status": "guarded_not_executed",
            "planned_tools": profile.get("planned_tools", []),
            "forbidden_effects": profile.get("forbidden_effects", []),
        },
    ]
    if profile.get("kind") == "sensitive":
        preflight_steps.insert(
            2,
            {
                "step": "secret_handling",
                "status": "required_before_execution",
                "secret_reference_supplied": bool(secret_reference),
                "requirements": [
                    "Never pass or echo the secret value",
                    "Use a user-confirmed secret reference or secure prompt",
                    "Redact evidence artifacts",
                    "Use only a scratch project copy until explicit source-project approval",
                ],
            },
        )
    if profile.get("kind") == "network_and_live_device":
        preflight_steps.insert(
            2,
            {
                "step": "live_device_preflight",
                "status": "required_before_execution",
                "tool": "owen_logic_live_device_preflight",
                "requirements": [
                    "Exact COM/IP target confirmation",
                    "Backup/readback evidence",
                    "Abort plan",
                    "No unattended replication/write action",
                ],
            },
        )

    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": True,
        "action": action,
        "normalized_action": normalized_action,
        "source_section": source_section or profile.get("sections", [None])[0],
        "kind": profile.get("kind"),
        "manual_evidence_root": str(root) if root else None,
        "manual_evidence": manual_evidence,
        "manual_evidence_match_count": sum(int(row.get("match_count") or 0) for row in manual_evidence),
        "read_only_catalog": {
            "included": read_only_catalog is not None,
            "installed_asset_count_returned": read_only_catalog.get("installed_asset_count_returned") if read_only_catalog else 0,
            "manual_extension_items": read_only_catalog.get("manual_extension_items") if read_only_catalog else [],
        },
        "required_policy": required_policy,
        "endpoint_description": endpoint_description,
        "secret_reference_supplied": bool(secret_reference),
        "preflight_steps": preflight_steps,
        "actions_executed": ["owen_logic_manual_evidence_search"] + (["owen_logic_extensions_catalog"] if read_only_catalog else []),
        "read_only": True,
        "opened_gui": False,
        "project_write_performed": False,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "network_action_executed": False,
        "installer_action_executed": False,
        "live_device_action_executed": False,
        "sensitive_action_executed": False,
        "secret_value_read": False,
        "secret_value_echoed": False,
        "scope": "manual_backed_guarded_action_preflight_no_execution",
        "guardrail": "Only local manual evidence and installed extension/catalog inventory execute automatically. Sensitive, network, cloud, OPC, replication and live-device actions remain planned guarded steps requiring explicit follow-up confirmation.",
    }


