def normalize_live_device_action(action: Any) -> str:
    key = re.sub(r"[^a-z0-9]+", "_", str(action or "").strip().lower()).strip("_")
    return LIVE_DEVICE_ACTION_ALIASES.get(key, key)


def first_text(mapping: dict[str, Any], keys: tuple[str, ...]) -> str | None:
    for key in keys:
        value = mapping.get(key)
        if value is None:
            continue
        text = str(value).strip()
        if text:
            return text
    return None


def live_device_target_summary(target: Any) -> dict[str, Any]:
    if not isinstance(target, dict) or not target:
        return {"valid": False, "label": "unspecified-target", "details": {}, "reason": "target object is required"}

    target_type = first_text(target, ("type", "transport", "interface", "kind")) or "unspecified"
    port = first_text(target, ("port", "com_port", "serial_port"))
    host = first_text(target, ("ip", "host", "address", "hostname"))
    tcp_port = first_text(target, ("tcp_port", "network_port"))
    unit_id = first_text(target, ("unit_id", "slave_id", "device_address", "modbus_address"))
    serial_number = first_text(target, ("serial_number", "serial", "sn"))
    device_model = first_text(target, ("device_model", "model", "controller_model"))
    target_id = first_text(target, ("target_id", "device_id", "name"))

    details = {
        "type": target_type,
        "port": port,
        "host": host,
        "tcp_port": tcp_port,
        "unit_id": unit_id,
        "serial_number": serial_number,
        "device_model": device_model,
        "target_id": target_id,
    }
    details = {key: value for key, value in details.items() if value is not None}

    if port:
        label = f"serial:{port.upper()}"
        if unit_id:
            label += f":unit={unit_id}"
        return {"valid": True, "label": label, "details": details}
    if host:
        label = f"tcp:{host}"
        if tcp_port:
            label += f":port={tcp_port}"
        if unit_id:
            label += f":unit={unit_id}"
        return {"valid": True, "label": label, "details": details}
    if serial_number or device_model or target_id:
        parts = [part for part in (target_id, device_model, serial_number) if part]
        return {"valid": True, "label": "device:" + ":".join(parts), "details": details}
    return {
        "valid": False,
        "label": "unspecified-target",
        "details": details,
        "reason": "target must include COM port, IP/host, serial_number, device_model or target_id",
    }


def live_device_confirmation_phrase(action: str, target_label: str) -> str:
    return f"OWEN LIVE DEVICE PREFLIGHT {action.upper()} -> {target_label}"


def normalize_readback_plan(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, str):
        text = value.strip()
        return [text] if text else []
    if isinstance(value, list):
        return [str(item).strip() for item in value if str(item).strip()]
    return [str(value).strip()] if str(value).strip() else []


def live_device_preflight(args: dict[str, Any]) -> dict[str, Any]:
    requested_action = str(args.get("action") or "")
    action = normalize_live_device_action(requested_action)
    action_meta = LIVE_DEVICE_ACTIONS.get(action)
    target = live_device_target_summary(args.get("target"))
    target_label = str(target["label"])
    required_confirmation = live_device_confirmation_phrase(action or "unknown", target_label)
    readback_plan = normalize_readback_plan(args.get("readback_plan"))
    abort_plan = str(args.get("abort_plan") or "").strip()
    backup_plan = str(args.get("backup_plan") or "").strip()
    backup_path_value = str(args.get("backup_path") or "").strip()
    backup_confirmed = bool(args.get("backup_confirmed", False))
    dry_run = bool(args.get("dry_run", True))
    allow_live_device = bool(args.get("allow_live_device", False))
    operator_confirmation = str(args.get("operator_confirmation") or "")
    issues: list[str] = []

    if action_meta is None:
        issues.append(f"unsupported live-device action: {requested_action}")
        risk_class = "unknown"
    else:
        risk_class = str(action_meta["risk_class"])

    if not allow_live_device:
        issues.append("allow_live_device=true is required for live-device preflight")
    if not target.get("valid"):
        issues.append(str(target.get("reason") or "valid target is required"))
    if operator_confirmation != required_confirmation:
        issues.append("operator_confirmation must exactly match required_confirmation_phrase")
    if not readback_plan:
        issues.append("readback_plan must include at least one concrete readback check")
    if not abort_plan:
        issues.append("abort_plan is required")
    if action_meta and bool(action_meta.get("dry_run_required", False)) and not dry_run:
        issues.append("dry_run=true is required for this action preflight")

    project_info = None
    project_validation = None
    project_value = str(args.get("project_path") or "").strip()
    if project_value:
        try:
            project = Path(project_value).expanduser().resolve()
            project_info = safe_file_info(project, include_hash=True)
            if project.suffix.lower() != ".owle":
                issues.append(f"project_path must be a .owle file for live-device preflight: {project.suffix}")
            loaded = read_owle_sections(project, include_hashes=False)
            project_section = loaded["sections"].get("Project")
            project_validation = {
                "owle_zip_valid": True,
                "entry_count": len(loaded["entries"]),
                "project_document_count": len(project_documents(project_section)),
            }
        except Exception as exc:
            issues.append(f"project_path validation failed: {exc}")
            project_validation = {"owle_zip_valid": False, "error": str(exc)}
    elif action_meta and bool(action_meta.get("project_required", False)):
        issues.append(f"project_path is required for action {action}")

    backup_path_info = None
    if backup_path_value:
        backup_path = Path(backup_path_value).expanduser().resolve()
        backup_path_info = {
            "path": str(backup_path),
            "exists": backup_path.exists(),
            "parent_exists": backup_path.parent.exists(),
            "is_scratch_or_local_heavy_path": is_scratch_destination(backup_path),
        }
        if backup_path.exists() and backup_path.is_file():
            backup_path_info.update(safe_file_info(backup_path, include_hash=False))

    if action_meta and bool(action_meta.get("backup_required", False)):
        if not backup_plan and not backup_path_value:
            issues.append("backup_plan or backup_path is required for dangerous live-device actions")
        if not backup_confirmed:
            issues.append("backup_confirmed=true is required for dangerous live-device actions")

    preflight_passed = not issues
    required_backup_steps = list(action_meta.get("backup_steps", [])) if action_meta else []
    required_readback_steps = list(action_meta.get("readback_steps", [])) if action_meta else []
    required_abort_steps = [
        "stop before any write/download if target identity differs from the approved target",
        "abort on communication loss, checksum mismatch, unexpected firmware/model, or operator cancellation",
        "record the failure state and do not retry automatically",
    ]
    if abort_plan:
        required_abort_steps.append(f"operator abort plan: {abort_plan}")

    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "requested_action": requested_action,
        "action": action,
        "risk_class": risk_class,
        "preflight_passed": preflight_passed,
        "issues": issues,
        "target": target,
        "required_confirmation_phrase": required_confirmation,
        "confirmation_matched": operator_confirmation == required_confirmation,
        "allow_live_device": allow_live_device,
        "dry_run": dry_run,
        "project": project_info,
        "project_validation": project_validation,
        "backup": {
            "backup_path": backup_path_info,
            "backup_plan": backup_plan or None,
            "backup_confirmed": backup_confirmed,
            "required_backup_steps": required_backup_steps,
        },
        "readback": {
            "operator_readback_plan": readback_plan,
            "required_readback_steps": required_readback_steps,
        },
        "abort": {
            "operator_abort_plan": abort_plan or None,
            "required_abort_steps": required_abort_steps,
        },
        "actions_executed": [],
        "opened_serial_port": False,
        "opened_network_socket": False,
        "launched_gui": False,
        "wrote_project": False,
        "execution_permitted_by_this_tool": False,
        "dedicated_executor_available": False,
        "available_actions": sorted(LIVE_DEVICE_ACTIONS.keys()),
        "guardrail": "This preflight is plan/check only. It never opens COM/IP, launches OWEN Logic, downloads, writes settings, updates firmware or calibrates a device.",
    }


def require_windows() -> None:
    if user32 is None:
        raise RuntimeError("OWEN Logic GUI tools are available only on Windows")


def enum_windows(
    include_invisible: bool = False,
    pid: int | None = None,
    title_filter: str | None = None,
    owen_only: bool = True,
) -> list[dict[str, Any]]:
    require_windows()
    results: list[dict[str, Any]] = []
    title_filter_lower = title_filter.lower() if title_filter else None

    enum_proc_type = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)

    def callback(hwnd: wintypes.HWND, _lparam: wintypes.LPARAM) -> bool:
        visible = bool(user32.IsWindowVisible(hwnd))
        if not include_invisible and not visible:
            return True

        length = user32.GetWindowTextLengthW(hwnd)
        title_buffer = ctypes.create_unicode_buffer(length + 1)
        user32.GetWindowTextW(hwnd, title_buffer, length + 1)
        title = title_buffer.value

        class_buffer = ctypes.create_unicode_buffer(256)
        user32.GetClassNameW(hwnd, class_buffer, 256)
        class_name = class_buffer.value

        process_id = wintypes.DWORD()
        user32.GetWindowThreadProcessId(hwnd, ctypes.byref(process_id))
        process_id_int = int(process_id.value)

        if pid is not None and process_id_int != int(pid):
            return True
        if title_filter_lower and title_filter_lower not in title.lower():
            return True
        if owen_only:
            marker = f"{title} {class_name}".lower()
            if "owen" not in marker and "programrelayfbd" not in marker:
                return True

        rect = RECT()
        user32.GetWindowRect(hwnd, ctypes.byref(rect))
        width = int(rect.right - rect.left)
        height = int(rect.bottom - rect.top)
        if not include_invisible and (width <= 0 or height <= 0):
            return True

        results.append(
            {
                "hwnd": int(hwnd),
                "pid": process_id_int,
                "title": title,
                "class_name": class_name,
                "visible": visible,
                "rect": {
                    "left": int(rect.left),
                    "top": int(rect.top),
                    "right": int(rect.right),
                    "bottom": int(rect.bottom),
                    "width": width,
                    "height": height,
                },
            }
        )
        return True

    user32.EnumWindows(enum_proc_type(callback), 0)
    return results


def window_info_from_hwnd(hwnd_value: int) -> dict[str, Any]:
    require_windows()
    hwnd = wintypes.HWND(int(hwnd_value))
    if not user32.IsWindow(hwnd):
        raise RuntimeError(f"Window handle is not valid: {hwnd_value}")

    visible = bool(user32.IsWindowVisible(hwnd))
    length = user32.GetWindowTextLengthW(hwnd)
    title_buffer = ctypes.create_unicode_buffer(length + 1)
    user32.GetWindowTextW(hwnd, title_buffer, length + 1)
    title = title_buffer.value

    class_buffer = ctypes.create_unicode_buffer(256)
    user32.GetClassNameW(hwnd, class_buffer, 256)
    class_name = class_buffer.value

    process_id = wintypes.DWORD()
    user32.GetWindowThreadProcessId(hwnd, ctypes.byref(process_id))

    rect = RECT()
    user32.GetWindowRect(hwnd, ctypes.byref(rect))
    width = int(rect.right - rect.left)
    height = int(rect.bottom - rect.top)
    return {
        "hwnd": int(hwnd_value),
        "pid": int(process_id.value),
        "title": title,
        "class_name": class_name,
        "visible": visible,
        "rect": {
            "left": int(rect.left),
            "top": int(rect.top),
            "right": int(rect.right),
            "bottom": int(rect.bottom),
            "width": width,
            "height": height,
        },
    }


def tasklist_programrelay() -> list[dict[str, Any]]:
    completed = subprocess.run(
        ["tasklist", "/FI", "IMAGENAME eq ProgramRelayFBD.exe", "/FO", "CSV", "/NH"],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        encoding="utf-8",
        errors="replace",
        timeout=10,
    )
    rows: list[dict[str, Any]] = []
    if completed.returncode != 0:
        return [{"error": completed.stderr.strip()}]
    text = completed.stdout.strip()
    if not text or text.startswith("INFO:"):
        return []
    for row in csv.reader(text.splitlines()):
        if len(row) >= 5:
            try:
                pid = int(row[1])
            except ValueError:
                pid = None
            rows.append(
                {
                    "image_name": row[0],
                    "pid": pid,
                    "session_name": row[2],
                    "session_number": row[3],
                    "memory_usage": row[4],
                }
            )
    return rows


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as fh:
        for chunk in iter(lambda: fh.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest().upper()


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest().upper()


def safe_file_info(path: Path, include_hash: bool = False) -> dict[str, Any]:
    stat = path.stat()
    info: dict[str, Any] = {
        "path": str(path),
        "name": path.name,
        "extension": path.suffix.lower(),
        "bytes": int(stat.st_size),
        "modified": datetime.fromtimestamp(stat.st_mtime).isoformat(timespec="seconds"),
    }
    if include_hash:
        info["sha256"] = sha256_file(path)
    return info


def safe_relative(path: Path, root: Path) -> str:
    try:
        return str(path.relative_to(root))
    except ValueError:
        return str(path)


def list_files_limited(root: Path, patterns: tuple[str, ...], max_files: int) -> list[Path]:
    files: list[Path] = []
    for pattern in patterns:
        files.extend(path for path in root.rglob(pattern) if path.is_file())
    files.sort(key=lambda item: str(item).lower())
    return files[:max_files]


def find_workbench_root() -> Path | None:
    candidates = [Path.cwd()]
    try:
        candidates.append(Path(__file__).resolve())
    except NameError:
        pass
    for start in candidates:
        current = start if start.is_dir() else start.parent
        for parent in [current, *current.parents]:
            if (parent / "00_ROUTING" / "AI_ROUTING.md").exists():
                return parent
    env_root = os.environ.get("WORKBENCH_ROOT")
    if env_root:
        path = Path(env_root).expanduser()
        if (path / "00_ROUTING" / "AI_ROUTING.md").exists():
            return path.resolve()
    return None


def default_manual_text_root() -> Path | None:
    root = find_workbench_root()
    if not root:
        return None
    candidate = (
        root
        / "20_PRIVATE_UNSAFE"
        / "engineering"
        / "owen_logic_full_coverage"
        / "project"
        / "evidence"
        / "page_text_20260612_msk"
    )
    return candidate if candidate.exists() else None


def strip_xml_namespace(tag: str) -> str:
    return tag.rsplit("}", 1)[-1] if "}" in tag else tag


def help_item_category(help_id: str, file_name: str) -> str:
    text = f"{help_id} {file_name}".lower()
    if "display" in text or "screen" in text or "visual" in text:
        return "display"
    if "modbus" in text or "net" in text:
        return "modbus"
    if "variable" in text or "var" in text:
        return "variable"
    if "fb_" in text or "pid" in text or "trigger" in text or "timer" in text or "counter" in text:
        return "function_block"
    if "func_" in text or "element" in text:
        return "function"
    return "manual"


def help_item_group(file_name: str, help_id: str) -> str:
    stem = Path(file_name).stem
    if "_" in stem:
        pieces = [piece for piece in stem.split("_") if piece]
        if len(pieces) >= 2:
            return pieces[1].split("-")[0]
    match = re.search(r"Element([A-Za-z0-9]+)", help_id)
    return match.group(1) if match else "other"


def parse_help_pages(install_dir: Path) -> list[dict[str, Any]]:
    help_pages_path = install_dir / "Help" / "HelpPages.xml"
    if not help_pages_path.exists():
        return []
    tree = ElementTree.parse(help_pages_path)
    rows: list[dict[str, Any]] = []
    for element in tree.getroot().iter():
        if strip_xml_namespace(element.tag) != "HelpPageCollectionItem":
            continue
        file_name = ""
        help_id = ""
        for child in element:
            tag = strip_xml_namespace(child.tag)
            if tag == "FileName":
                file_name = (child.text or "").strip()
            elif tag == "Id":
                help_id = (child.text or "").strip()
        if not file_name and not help_id:
            continue
        category = help_item_category(help_id, file_name)
        rows.append(
            {
                "id": help_id,
                "file_name": file_name,
                "category": category,
                "group": help_item_group(file_name, help_id),
                "help_file_path": str(install_dir / "Help" / file_name) if file_name else None,
            }
        )
    rows.sort(key=lambda row: (str(row.get("category")), str(row.get("group")), str(row.get("id"))))
    return rows


def help_index(args: dict[str, Any]) -> dict[str, Any]:
    install = find_installation_data()
    install_dir_value = install.get("install_dir")
    if not install_dir_value:
        raise FileNotFoundError("OWEN Logic installation directory was not found")
    install_dir = Path(str(install_dir_value))
    max_items = clamp_int(args.get("max_items"), 200, 1, 5000)
    query = str(args.get("query") or "").strip().lower()
    rows = parse_help_pages(install_dir)
    if query:
        rows = [
            row
            for row in rows
            if query in " ".join(str(row.get(key) or "").lower() for key in ("id", "file_name", "category", "group"))
        ]
    category_counts: dict[str, int] = {}
    group_counts: dict[str, int] = {}
    for row in rows:
        category = str(row.get("category") or "unknown")
        group = str(row.get("group") or "unknown")
        category_counts[category] = category_counts.get(category, 0) + 1
        group_counts[group] = group_counts.get(group, 0) + 1
    return {
        "installation": install,
        "source": str(install_dir / "Help" / "HelpPages.xml"),
        "query": query or None,
        "total_matches": len(rows),
        "returned": min(len(rows), max_items),
        "category_counts": dict(sorted(category_counts.items())),
        "top_group_counts": dict(sorted(group_counts.items(), key=lambda item: (-item[1], item[0]))[:50]),
        "items": rows[:max_items],
        "read_only": True,
    }


