def compact_control(control: dict[str, Any]) -> dict[str, Any]:
    return {
        "path": compact_string(str(control.get("path") or ""), 240),
        "name": compact_string(str(control.get("name") or ""), 240),
        "automation_id": compact_string(str(control.get("automation_id") or ""), 120),
        "class_name": compact_string(str(control.get("class_name") or ""), 120),
        "control_type": compact_string(str(control.get("control_type") or ""), 120),
        "localized_control_type": compact_string(str(control.get("localized_control_type") or ""), 120),
        "text": compact_string(str(control.get("text_pattern_text") or ""), 500),
        "value": compact_string(str(control.get("value_pattern_value") or ""), 500),
        "legacy_name": compact_string(str(control.get("legacy_name") or ""), 240),
        "legacy_value": compact_string(str(control.get("legacy_value") or ""), 500),
        "help_text": compact_string(str(control.get("help_text") or ""), 240),
        "is_enabled": control.get("is_enabled"),
        "is_offscreen": control.get("is_offscreen"),
        "bounding_rect": control.get("bounding_rect"),
    }


def control_haystack(control: dict[str, Any]) -> str:
    return " ".join(
        str(control.get(key) or "")
        for key in (
            "path",
            "name",
            "automation_id",
            "class_name",
            "control_type",
            "localized_control_type",
            "text_pattern_text",
            "value_pattern_value",
            "legacy_name",
            "legacy_value",
            "help_text",
        )
    ).lower()


def collect_diagnostic_controls(ui_tree: dict[str, Any], max_controls: int) -> dict[str, Any]:
    controls = flatten_ui_tree(ui_tree)
    named_controls = [control for control in controls if str(control.get("name") or "").strip()]
    diagnostic_controls: list[dict[str, Any]] = []
    status_controls: list[dict[str, Any]] = []
    error_controls: list[dict[str, Any]] = []
    for control in controls:
        haystack = control_haystack(control)
        if any(marker in haystack for marker in DIAGNOSTIC_TEXT_MARKERS):
            diagnostic_controls.append(compact_control(control))
        if any(marker in haystack for marker in STATUS_TEXT_MARKERS):
            status_controls.append(compact_control(control))
        if any(marker in haystack for marker in ERROR_TEXT_MARKERS):
            error_controls.append(compact_control(control))
    return {
        "control_count": len(controls),
        "named_control_count": len(named_controls),
        "diagnostic_control_count": len(diagnostic_controls),
        "status_control_count": len(status_controls),
        "error_control_count": len(error_controls),
        "diagnostic_controls": diagnostic_controls[:max_controls],
        "status_controls": status_controls[:max_controls],
        "error_controls": error_controls[:max_controls],
        "truncated": len(diagnostic_controls) > max_controls or len(status_controls) > max_controls or len(error_controls) > max_controls,
    }


def project_gui_diagnostics_smoke(args: dict[str, Any]) -> dict[str, Any]:
    require_windows()
    if not bool(args.get("allow_safe_runtime", False)):
        raise ValueError("owen_logic_project_gui_diagnostics_smoke requires allow_safe_runtime=true")

    source = Path(str(args.get("project_path") or "")).expanduser().resolve()
    source_hash_before = sha256_file(source)
    scratch_value = args.get("scratch_dir")
    if scratch_value:
        scratch_dir = Path(str(scratch_value)).expanduser().resolve()
    else:
        workbench = find_workbench_root()
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        scratch_dir = (
            workbench / "30_LOCAL_HEAVY" / "sandbox_tmp" / "owen_project_gui_diagnostics_smoke" / timestamp
            if workbench
            else Path.home() / ".codex" / "tmp" / "owen_project_gui_diagnostics_smoke" / timestamp
        ).resolve()
    if not is_scratch_destination(scratch_dir):
        raise ValueError(f"Refusing GUI diagnostics smoke output outside scratch/sandbox/local-heavy path: {scratch_dir}")
    screenshot_dir = scratch_dir / "screenshots"
    ui_dir = scratch_dir / "ui_snapshots"
    screenshot_dir.mkdir(parents=True, exist_ok=True)
    ui_dir.mkdir(parents=True, exist_ok=True)

    scratch = project_scratch_copy(
        {
            "project_path": str(source),
            "scratch_dir": str(scratch_dir),
            "name_suffix": "_gui_diagnostics_smoke",
        }
    )
    scratch_project = Path(scratch["scratch_copy"]["path"])
    scratch_hash_before = sha256_file(scratch_project)
    static_validation_before = project_validate({"project_path": str(scratch_project), "include_warnings": True})
    wait_seconds = max(1, min(float(args.get("wait_seconds", 8)), 120))
    action_wait_seconds = max(0, min(float(args.get("action_wait_seconds", 1)), 10))
    screenshot_enabled = bool(args.get("screenshot", True))
    include_ui_tree = bool(args.get("include_ui_tree", True))
    save_ui_tree = bool(args.get("save_ui_tree", True))
    include_offscreen = bool(args.get("include_offscreen", False))
    max_depth = clamp_int(args.get("max_depth"), 7, 0, 10)
    max_children = clamp_int(args.get("max_children"), 250, 1, 1000)
    max_diagnostic_controls = clamp_int(args.get("max_diagnostic_controls"), 80, 1, 500)
    dismiss_post_open_dialogs = bool(args.get("dismiss_post_open_information_dialogs", True))
    cleanup = bool(args.get("cleanup_launched_process", True))
    launch = None
    pid: int | None = None
    actions: list[dict[str, Any]] = []
    diagnostic_snapshots: list[dict[str, Any]] = []
    post_open_dismissal_result = None
    cleanup_result = None
    result: dict[str, Any] | None = None

    def capture_diagnostic_snapshot(label: str) -> dict[str, Any]:
        running = bool(pid and process_is_running(pid))
        windows_after = enum_windows(pid=pid, owen_only=False) if pid and running else []
        classification = classify_gui_validation_windows(windows_after)
        blocking_dialogs = [
            window
            for window in windows_after
            if select_post_open_information_dialog([window]) is not None
        ]
        shot = lifecycle_screenshot(int(pid), screenshot_dir, label, screenshot_enabled) if pid and running else None
        snapshot: dict[str, Any] = {
            "label": label,
            "running": running,
            "windows": windows_after,
            "window_classification": classification,
            "blocking_dialogs": blocking_dialogs,
            "blocking_messages": [],
            "blocking_message_count": 0,
            "blocking_dialog_count": len(blocking_dialogs),
            "screenshot": shot,
            "ui_snapshot_attempted": include_ui_tree and running,
            "ui_snapshot_ok": False,
            "ui_snapshot_path": None,
            "ui_summary": None,
            "ui_error": None,
        }
        if include_ui_tree and running and pid:
            try:
                ui_snapshot = ui_automation_snapshot(
                    {
                        "pid": pid,
                        "owen_only": False,
                        "max_depth": max_depth,
                        "max_children": max_children,
                        "include_offscreen": include_offscreen,
                        "timeout_seconds": 30,
                    }
                )
                ui_tree = ui_snapshot.get("ui_tree") if isinstance(ui_snapshot.get("ui_tree"), dict) else {}
                ui_summary = collect_diagnostic_controls(ui_tree, max_diagnostic_controls) if isinstance(ui_tree, dict) else None
                snapshot["ui_snapshot_ok"] = True
                snapshot["ui_summary"] = ui_summary
                if save_ui_tree:
                    output_path = ui_dir / f"{label}.ui.json"
                    output_path.write_text(json.dumps(ui_snapshot, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
                    snapshot["ui_snapshot_path"] = str(output_path)
            except Exception as exc:
                snapshot["ui_error"] = str(exc)
        diagnostic_snapshots.append(snapshot)
        return snapshot

    def record_diagnostic_action(label: str, keys: list[str]) -> None:
        running_before = bool(pid and process_is_running(pid))
        sent = None
        send_error = None
        if running_before:
            try:
                sent = send_hotkey({"pid": pid, "keys": keys, "delay_ms": 250})
            except Exception as exc:
                send_error = str(exc)
        else:
            send_error = "OWEN Logic process was not running before hotkey"
        if action_wait_seconds > 0:
            time.sleep(action_wait_seconds)
        snapshot = capture_diagnostic_snapshot(label)
        actions.append(
            {
                "label": label,
                "keys": keys,
                "running_before": running_before,
                "running_after": snapshot.get("running"),
                "sent": sent,
                "send_error": send_error,
                "diagnostic_snapshot_label": snapshot.get("label"),
            }
        )

    try:
        launch = launch_owen_logic({"project_path": str(scratch_project), "wait_seconds": wait_seconds})
        pid = int(launch["pid"])
        windows = wait_for_owen_window(pid, wait_seconds)
        initial_idle = wait_for_lifecycle_idle(pid, max(wait_seconds, 15))
        if dismiss_post_open_dialogs and pid and process_is_running(pid):
            post_open_dismissal_result = dismiss_post_open_information_dialogs(
                pid,
                screenshot_dir,
                screenshot_enabled,
            )
            if post_open_dismissal_result.get("attempted"):
                time.sleep(0.8)
        initial_snapshot = capture_diagnostic_snapshot("opened_scratch")
        if bool(args.get("exercise_enter_simulator", True)):
            record_diagnostic_action("after_enter_simulator_shift_f5", GUI_VALIDATION_HOTKEYS["enter_simulator_shift_f5"])
        if bool(args.get("exercise_step", True)):
            record_diagnostic_action("after_step_f10", GUI_VALIDATION_HOTKEYS["step_f10"])
        if bool(args.get("exercise_start_stop", False)):
            record_diagnostic_action("after_start_f6", GUI_VALIDATION_HOTKEYS["start_f6"])
            record_diagnostic_action("after_stop_f7", GUI_VALIDATION_HOTKEYS["stop_f7"])

        source_hash_after = sha256_file(source)
        scratch_hash_after = sha256_file(scratch_project)
        static_validation_after = project_validate({"project_path": str(scratch_project), "include_warnings": True})
        ui_ok_snapshots = [snapshot for snapshot in diagnostic_snapshots if snapshot.get("ui_snapshot_ok")]
        diagnostic_control_count = sum(int((snapshot.get("ui_summary") or {}).get("diagnostic_control_count") or 0) for snapshot in diagnostic_snapshots)
        status_control_count = sum(int((snapshot.get("ui_summary") or {}).get("status_control_count") or 0) for snapshot in diagnostic_snapshots)
        error_control_count = sum(int((snapshot.get("ui_summary") or {}).get("error_control_count") or 0) for snapshot in diagnostic_snapshots)
        named_control_count = sum(int((snapshot.get("ui_summary") or {}).get("named_control_count") or 0) for snapshot in diagnostic_snapshots)
        error_like_windows = [
            snapshot
            for snapshot in diagnostic_snapshots
            if snapshot.get("window_classification", {}).get("has_error_like_window")
        ]
        send_errors = [action for action in actions if action.get("send_error") or not action.get("running_after")]
        result = {
            "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
            "ok": bool(
                static_validation_before.get("ok")
                and static_validation_after.get("ok")
                and source_hash_before == source_hash_after
                and diagnostic_snapshots
                and (not include_ui_tree or ui_ok_snapshots)
                and not send_errors
            ),
            "source_project": safe_file_info(source, include_hash=True),
            "scratch_copy": safe_file_info(scratch_project, include_hash=True),
            "scratch_dir": str(scratch_dir),
            "launch": launch,
            "windows_after_launch": windows,
            "idle_after_launch": initial_idle,
            "post_open_information_dialog_dismissal_result": post_open_dismissal_result,
            "initial_snapshot": initial_snapshot,
            "actions": actions,
            "diagnostic_snapshots": diagnostic_snapshots,
            "diagnostic_snapshot_count": len(diagnostic_snapshots),
            "ui_snapshot_ok_count": len(ui_ok_snapshots),
            "named_control_count_total": named_control_count,
            "diagnostic_control_count_total": diagnostic_control_count,
            "status_control_count_total": status_control_count,
            "error_control_count_total": error_control_count,
            "error_like_window_snapshot_count": len(error_like_windows),
            "static_validation_before": static_validation_before,
            "static_validation_after": static_validation_after,
            "source_hash_before": source_hash_before,
            "source_hash_after": source_hash_after,
            "source_hash_preserved": source_hash_before == source_hash_after,
            "scratch_hash_before": scratch_hash_before,
            "scratch_hash_after": scratch_hash_after,
            "scratch_project_exists": scratch_project.exists(),
            "screenshots": [str(path) for path in sorted(screenshot_dir.glob("*.png"))],
            "ui_snapshot_files": [str(path) for path in sorted(ui_dir.glob("*.ui.json"))],
            "risk_class": "safe_runtime",
            "validation_scope": "bounded_gui_diagnostic_status_error_list_capture_plus_static_owle_validation",
            "headless_compiler_used": False,
            "full_compiler_diagnostics_claimed": False,
            "live_simulator_value_readback_claimed": False,
            "opened_serial_port": False,
            "opened_network_socket": False,
            "live_device_action_executed": False,
            "compiler_limitation": "This captures GUI status/error-list/diagnostic UIA evidence from OWEN Logic after safe simulator shortcuts on a scratch copy. It is not a headless compiler and does not parse full OWEN compiler diagnostics.",
            "simulator_runtime_limitation": "This tool captures GUI diagnostic/status surfaces only. It does not prove live simulator variable value readback.",
            "guardrail": "Only a scratch copy is opened in OWEN Logic. No live-device, COM/IP, network, download, firmware, calibration, or device-setting action is executed.",
        }
    finally:
        if cleanup and pid:
            cleanup_result = stop_process_best_effort(pid)
            try:
                (scratch_dir / "cleanup_result.json").write_text(
                    json.dumps(cleanup_result, ensure_ascii=False, indent=2) + "\n",
                    encoding="utf-8",
                )
            except Exception:
                pass
    if result is None:
        raise RuntimeError("OWEN Logic GUI diagnostics smoke did not produce a result")
    result["cleanup_requested"] = cleanup
    result["cleanup_result"] = cleanup_result
    result["cleanup_sidecar_path"] = str(scratch_dir / "cleanup_result.json") if cleanup_result else None
    result["processes_after_cleanup"] = tasklist_programrelay()
    return result


def make_intentionally_broken_st_source(source: str, marker: str) -> str:
    insertion = (
        f"\n(* {marker}: intentionally invalid compiler diagnostics case. *)\n"
        "    IF TRUE THEN\n"
        "    __codex_invalid_assignment := ;\n"
    )
    match = list(re.finditer(r"\bEND_FUNCTION_BLOCK\b", source, flags=re.IGNORECASE))
    if match:
        last = match[-1]
        return source[: last.start()] + insertion + source[last.start() :]
    return source.rstrip() + insertion + "\nEND_FUNCTION_BLOCK\n"


def collect_project_function_block_uid_references(project_section: Any) -> dict[str, list[str]]:
    references: dict[str, list[str]] = {}

    def walk(value: Any, path: str) -> None:
        if isinstance(value, dict):
            for key, child in value.items():
                child_path = f"{path}/{key}" if path else f"/{key}"
                if key == "FunctionBlockUId" and isinstance(child, str) and child.strip():
                    references.setdefault(child, []).append(child_path)
                walk(child, child_path)
        elif isinstance(value, list):
            for index, child in enumerate(value):
                walk(child, f"{path}[{index}]")

    walk(project_section, "")
    return references


def select_st_block_for_compiler_case(
    sections: dict[str, Any],
    blocks: Any,
    args: dict[str, Any],
) -> dict[str, Any]:
    references = collect_project_function_block_uid_references(sections.get("Project"))
    explicit_id = str(args.get("st_block_id") or "").strip() or None
    explicit_name = str(args.get("st_block_name") or "").strip() or None
    explicit_index = args.get("st_block_index") if args.get("st_block_index") is not None else None

    if explicit_id or explicit_name or explicit_index is not None:
        index, block = find_st_block(blocks, explicit_id, explicit_name, explicit_index)
        if explicit_id:
            mode = "explicit_st_block_id"
        elif explicit_name:
            mode = "explicit_st_block_name"
        else:
            mode = "explicit_st_block_index"
    else:
        if not isinstance(blocks, list):
            raise ValueError("StFunctionBlocks section is missing or is not a list")
        index = -1
        block = None
        for candidate_index, candidate in enumerate(blocks):
            if not isinstance(candidate, dict):
                continue
            block_id = str(candidate.get("Id") or "")
            if block_id in references and str(candidate.get("SourceCode") or "").strip():
                index = candidate_index
                block = candidate
                break
        if block is None:
            for candidate_index, candidate in enumerate(blocks):
                if isinstance(candidate, dict) and str(candidate.get("SourceCode") or "").strip():
                    index = candidate_index
                    block = candidate
                    break
            mode = "auto_first_nonempty_unreferenced_fallback"
        else:
            mode = "auto_first_project_referenced"
        if block is None:
            raise ValueError("No ST block with non-empty SourceCode was found")

    block_id = str(block.get("Id") or "")
    return {
        "index": index,
        "block": block,
        "mode": mode,
        "block_reference_paths": references.get(block_id, []),
        "project_function_block_uid_reference_count_total": sum(len(paths) for paths in references.values()),
        "project_function_block_uid_unique_count": len(references),
    }


def gui_diagnostics_signal_summary(result: dict[str, Any]) -> dict[str, Any]:
    snapshots = result.get("diagnostic_snapshots") if isinstance(result.get("diagnostic_snapshots"), list) else []
    controls: list[dict[str, Any]] = []
    for snapshot in snapshots:
        summary = snapshot.get("ui_summary") if isinstance(snapshot, dict) else None
        if not isinstance(summary, dict):
            continue
        for key in ("error_controls", "diagnostic_controls", "status_controls"):
            for control in summary.get(key) or []:
                if isinstance(control, dict):
                    controls.append(control)
    text_fragments: list[str] = []
    for control in controls:
        for key in ("name", "text", "automation_id", "class_name", "control_type"):
            value = control.get(key)
            if value is not None:
                text_fragments.append(str(value))
    combined = "\n".join(text_fragments).casefold()
    markers = (
        "error",
        "exception",
        "failed",
        "failure",
        "critical",
        "\u043a\u0440\u0438\u0442\u0438\u0447",
        "\u0437\u0430\u043c\u0435\u0447\u0430\u043d",
        "\u0443\u0441\u0442\u0440\u0430\u043d",
        "\u043f\u0435\u0440\u0435\u0434 \u0437\u0430\u043f\u0443\u0441\u043a\u043e\u043c",
        "ошиб",
        "сбой",
        "недопуст",
        "не удалось",
        "РѕС€РёР±".casefold(),
    )
    marker_hits = [marker for marker in markers if marker and marker in combined]
    project_load_error_markers = (
        "jsonexception",
        "modificationlabel",
        "could not be converted",
        "not in a supported guid format",
        "deserialize",
        "не удалось открыть файл",
        "РЅРµ СѓРґР°Р»РѕСЃСЊ РѕС‚РєСЂС‹С‚СЊ С„Р°Р№Р»".casefold(),
    )
    project_load_hits = [marker for marker in project_load_error_markers if marker and marker in combined]
    gui_error_signal = bool(
        int(result.get("error_like_window_snapshot_count") or 0) > 0
        or int(result.get("error_control_count_total") or 0) > 0
        or marker_hits
    )
    return {
        "diagnostic_snapshot_count": int(result.get("diagnostic_snapshot_count") or 0),
        "ui_snapshot_ok_count": int(result.get("ui_snapshot_ok_count") or 0),
        "diagnostic_control_count_total": int(result.get("diagnostic_control_count_total") or 0),
        "status_control_count_total": int(result.get("status_control_count_total") or 0),
        "error_control_count_total": int(result.get("error_control_count_total") or 0),
        "error_like_window_snapshot_count": int(result.get("error_like_window_snapshot_count") or 0),
        "marker_hits": marker_hits,
        "project_load_error_marker_hits": project_load_hits,
        "sample_text": [compact_string(text, 220) for text in text_fragments[:20]],
        "gui_error_signal": gui_error_signal,
        "project_load_error_signal": bool(project_load_hits),
        "compiler_or_runtime_error_signal": bool(gui_error_signal and not project_load_hits),
    }


def diagnostics_case_authoritative_broken_confirmed(
    valid_signal: dict[str, Any],
    broken_signal: dict[str, Any],
    broken_gui: dict[str, Any],
    broken_marker: str,
) -> bool:
    if not broken_signal or broken_signal.get("project_load_error_signal"):
        return False
    try:
        valid_error_count = int(valid_signal.get("error_control_count_total") or 0)
        broken_error_count = int(broken_signal.get("error_control_count_total") or 0)
    except (TypeError, ValueError):
        valid_error_count = 0
        broken_error_count = 0
    broken_marker_visible = bool(
        broken_marker
        and broken_marker in json.dumps(broken_gui, ensure_ascii=False, default=str)
    )
    return bool(broken_marker_visible or broken_error_count > valid_error_count)


def compiler_diagnostics_case_probe(args: dict[str, Any]) -> dict[str, Any]:
    require_windows()
    if not bool(args.get("allow_safe_runtime", False)):
        raise ValueError("owen_logic_compiler_diagnostics_case_probe requires allow_safe_runtime=true")
    if not bool(args.get("allow_broken_project", False)):
        raise ValueError("owen_logic_compiler_diagnostics_case_probe requires allow_broken_project=true")
    source = Path(str(args.get("project_path") or "")).expanduser().resolve()
    if not source.exists():
        raise FileNotFoundError(f"Project file not found: {source}")
    source_hash_before = sha256_file(source)
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    scratch_value = str(args.get("scratch_dir") or "").strip()
    if scratch_value:
        scratch_dir = Path(scratch_value).expanduser().resolve()
    else:
        workbench = find_workbench_root()
        scratch_dir = (
            workbench / "30_LOCAL_HEAVY" / "sandbox_tmp" / "owen_compiler_diagnostics_case_probe" / timestamp
            if workbench
            else Path.home() / ".codex" / "tmp" / "owen_compiler_diagnostics_case_probe" / timestamp
        ).resolve()
    if not is_scratch_destination(scratch_dir):
        raise ValueError(f"Refusing compiler diagnostics case output outside scratch/sandbox/local-heavy path: {scratch_dir}")
    scratch_dir.mkdir(parents=True, exist_ok=True)

    entries = read_owle_raw_entries(source)
    sections = parse_json_sections_from_entries(entries)
    blocks = sections.get("StFunctionBlocks")
    selected = select_st_block_for_compiler_case(sections, blocks, args)
    st_block_index = int(selected["index"])
    selected_block = selected["block"]
    original_source = str(selected_block.get("SourceCode") or "")
    if not original_source.strip():
        raise ValueError(f"Selected ST block has empty SourceCode: index={st_block_index}")
    marker = f"CODEX_BROKEN_COMPILER_DIAGNOSTIC_{timestamp}"
    broken_source = make_intentionally_broken_st_source(original_source, marker)
    patch_selector = (
        {"st_block_id": str(selected_block.get("Id"))}
        if selected_block.get("Id")
        else {"st_block_index": st_block_index}
    )
    broken_patch = project_st_patch(
        {
            "project_path": str(source),
            "scratch_dir": str(scratch_dir / "broken_source"),
            **patch_selector,
            "source_code": broken_source,
            "allow_lint_errors": True,
        }
    )
    broken_project_value = (broken_patch.get("scratch_copy") or {}).get("path")
    if not broken_project_value:
        raise RuntimeError("Broken scratch ST patch did not return a scratch project path")
    broken_project = Path(str(broken_project_value)).resolve()

    common_gui_args = {
        "allow_safe_runtime": True,
        "exercise_enter_simulator": True,
        "exercise_step": True,
        "exercise_start_stop": False,
        "include_ui_tree": True,
        "save_ui_tree": True,
        "include_offscreen": bool(args.get("include_offscreen", False)),
        "max_depth": clamp_int(args.get("max_depth"), 8, 0, 10),
        "max_children": clamp_int(args.get("max_children"), 350, 1, 1000),
        "max_diagnostic_controls": clamp_int(args.get("max_diagnostic_controls"), 160, 1, 500),
        "screenshot": True,
        "wait_seconds": max(1, min(float(args.get("wait_seconds", 10)), 120)),
        "action_wait_seconds": max(0, min(float(args.get("action_wait_seconds", 2)), 10)),
        "cleanup_launched_process": bool(args.get("cleanup_launched_process", True)),
    }
    valid_gui = project_gui_diagnostics_smoke(
        {
            **common_gui_args,
            "project_path": str(source),
            "scratch_dir": str(scratch_dir / "valid_gui"),
        }
    )
    broken_gui = project_gui_diagnostics_smoke(
        {
            **common_gui_args,
            "project_path": str(broken_project),
            "scratch_dir": str(scratch_dir / "broken_gui"),
        }
    )
    valid_signal = gui_diagnostics_signal_summary(valid_gui)
    broken_signal = gui_diagnostics_signal_summary(broken_gui)
    broken_static_before = broken_gui.get("static_validation_before") if isinstance(broken_gui.get("static_validation_before"), dict) else {}
    broken_patch_lint = broken_patch.get("lint") if isinstance(broken_patch.get("lint"), dict) else {}
    broken_static_error_count = max(
        int(broken_static_before.get("error_count") or 0),
        int(broken_patch_lint.get("error_count") or 0),
    )
    source_hash_after = sha256_file(source)
    valid_case_executed = bool(valid_gui.get("diagnostic_snapshot_count") and valid_gui.get("ui_snapshot_ok_count"))
    broken_case_executed = bool(broken_gui.get("diagnostic_snapshot_count") and broken_gui.get("ui_snapshot_ok_count"))
    broken_marker_visible = bool(
        marker and marker in json.dumps(broken_gui, ensure_ascii=False, default=str)
    )
    authoritative_broken = bool(
        broken_case_executed
        and diagnostics_case_authoritative_broken_confirmed(
            valid_signal,
            broken_signal,
            broken_gui,
            marker,
        )
    )
    passing_case_no_gui_error = bool(
        valid_case_executed
        and valid_gui.get("static_validation_before", {}).get("ok")
        and not valid_signal.get("gui_error_signal")
    )
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": bool(valid_case_executed and broken_case_executed and source_hash_before == source_hash_after),
        "source_project": safe_file_info(source, include_hash=True),
        "scratch_dir": str(scratch_dir),
        "st_block_index": st_block_index,
        "st_block_id": selected_block.get("Id"),
        "st_block_name": selected_block.get("Name"),
        "st_block_selection_mode": selected["mode"],
        "st_block_reference_count": len(selected["block_reference_paths"]),
        "st_block_reference_paths": selected["block_reference_paths"][:30],
        "project_function_block_uid_reference_count_total": selected["project_function_block_uid_reference_count_total"],
        "project_function_block_uid_unique_count": selected["project_function_block_uid_unique_count"],
        "broken_marker": marker,
        "broken_patch": broken_patch,
        "valid_gui": valid_gui,
        "broken_gui": broken_gui,
        "valid_signal": valid_signal,
        "broken_signal": broken_signal,
        "valid_case_executed": valid_case_executed,
        "broken_case_executed": broken_case_executed,
        "passing_case_no_gui_error_confirmed": passing_case_no_gui_error,
        "broken_static_validation_error_count": broken_static_error_count,
        "broken_patch_lint_error_count": int(broken_patch_lint.get("error_count") or 0),
        "broken_marker_visible_in_gui": broken_marker_visible,
        "authoritative_broken_gui_diagnostic_confirmed": authoritative_broken,
        "source_hash_before": source_hash_before,
        "source_hash_after": source_hash_after,
        "source_hash_preserved": source_hash_before == source_hash_after,
        "headless_compiler_cli_confirmed": False,
        "build_project_command_used": False,
        "menu_compiler_used": False,
        "full_compiler_diagnostics_claimed": False,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "live_device_action_executed": False,
        "scope": "paired_valid_and_intentionally_broken_scratch_gui_diagnostics_cases",
        "limitation": "This case probe exercises the mapped safe GUI diagnostics route on valid and intentionally broken scratch projects. It does not use BuildProjectCommand/menuCompiler and still does not claim full arbitrary-project compiler diagnostics unless the returned diagnostic confirmation fields prove enough coverage for a caller's scope.",
        "guardrail": "The source .owle is never modified. The broken project is created only as a scratch copy, and OWEN Logic is launched only against scratch copies. No COM/IP, live-device, download, firmware, calibration or device-settings action is executed.",
    }


