def project_modbus_gui_probe(args: dict[str, Any]) -> dict[str, Any]:
    require_windows()
    if not bool(args.get("allow_safe_runtime", False)):
        raise ValueError("owen_logic_project_modbus_gui_probe requires allow_safe_runtime=true")

    source = Path(str(args.get("project_path") or "")).expanduser().resolve()
    source_hash_before = sha256_file(source)
    scratch_value = args.get("scratch_dir")
    if scratch_value:
        scratch_dir = Path(str(scratch_value)).expanduser().resolve()
    else:
        workbench = find_workbench_root()
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        scratch_dir = (
            workbench / "30_LOCAL_HEAVY" / "sandbox_tmp" / "owen_project_modbus_gui_probe" / timestamp
            if workbench
            else Path.home() / ".codex" / "tmp" / "owen_project_modbus_gui_probe" / timestamp
        ).resolve()
    if not is_scratch_destination(scratch_dir):
        raise ValueError(f"Refusing Modbus GUI probe output outside scratch/sandbox/local-heavy path: {scratch_dir}")
    screenshot_dir = scratch_dir / "screenshots"
    ui_dir = scratch_dir / "ui_snapshots"
    screenshot_dir.mkdir(parents=True, exist_ok=True)
    ui_dir.mkdir(parents=True, exist_ok=True)

    baseline_pids = programrelay_pids()
    wait_seconds = max(1, min(float(args.get("wait_seconds", 8)), 120))
    open_wait_seconds = max(1, min(float(args.get("open_wait_seconds", 12)), 60))
    open_attempts = clamp_int(args.get("open_attempts"), 2, 1, 3)
    post_open_idle_wait_seconds = max(
        1,
        min(
            float(args.get("post_open_idle_wait_seconds", args.get("open_idle_wait_seconds", max(open_wait_seconds, 45)))),
            120,
        ),
    )
    dismiss_post_open_dialogs = bool(args.get("dismiss_post_open_information_dialogs", True))
    screenshot_enabled = bool(args.get("screenshot", True))
    include_ui_tree = bool(args.get("include_ui_tree", True))
    save_ui_tree = bool(args.get("save_ui_tree", True))
    include_menu_snapshot = bool(args.get("include_menu_snapshot", True))
    max_depth = clamp_int(args.get("max_depth"), 8, 0, 10)
    max_children = clamp_int(args.get("max_children"), 350, 1, 1000)
    cleanup = bool(args.get("cleanup_launched_process", True))
    terms_raw = args.get("search_terms")
    terms = [str(term) for term in terms_raw] if isinstance(terms_raw, list) and terms_raw else list(MODBUS_GUI_DEFAULT_TERMS)

    cleanup_results: list[dict[str, Any]] = []
    cleanup_result = None
    result: dict[str, Any] | None = None

    def cleanup_new_processes() -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        for cleanup_pid in sorted(programrelay_pids() - baseline_pids):
            rows.append(stop_process_best_effort(int(cleanup_pid)))
        if rows:
            time.sleep(0.5)
        return rows

    gui_open_short_base: Path | None = None

    def gui_open_attempt_dir(attempt: int) -> Path:
        nonlocal gui_open_short_base
        if gui_open_short_base is None:
            workbench = find_workbench_root()
            short_token = f"mb_{datetime.now().strftime('%H%M%S')}_{uuid.uuid4().hex[:6]}"
            gui_open_short_base = (
                workbench / "30_LOCAL_HEAVY" / "sandbox_tmp" / "og" / short_token
                if workbench
                else Path.home() / ".codex" / "tmp" / "og" / short_token
            ).resolve()
        return gui_open_short_base / f"a{int(attempt)}"

    def select_project_pid(candidates: list[int], project: Path) -> int:
        project_name = project.name.lower()
        project_path = str(project).lower()
        for candidate in candidates:
            try:
                windows = enum_windows(pid=candidate, owen_only=False)
            except Exception:
                continue
            for window in windows:
                title = str(window.get("title") or "").lower()
                if project_name in title or project_path in title:
                    return int(candidate)
        return int(candidates[0])

    def opened_project_window_candidates(active_pids: list[int], scratch_project: Path) -> list[dict[str, Any]]:
        scratch_name = scratch_project.name.lower()
        scratch_path = str(scratch_project).lower()
        candidates: list[dict[str, Any]] = []
        for candidate_pid in active_pids:
            try:
                windows = enum_windows(pid=int(candidate_pid), owen_only=False)
            except Exception:
                continue
            for window in windows:
                if not bool(window.get("visible")):
                    continue
                title = str(window.get("title") or "").lower()
                rect_value = window.get("rect") or {}
                area = int(rect_value.get("width") or 0) * int(rect_value.get("height") or 0)
                score = 0
                if scratch_path and scratch_path in title:
                    score += 8
                if scratch_name and scratch_name in title:
                    score += 4
                if "owen logic" in title:
                    score += 2
                if area >= 100000:
                    score += 1
                candidates.append(
                    {
                        "pid": int(candidate_pid),
                        "hwnd": int(window.get("hwnd") or 0),
                        "score": score,
                        "title_matches_scratch_path": bool(scratch_path and scratch_path in title),
                        "title_matches_scratch_name": bool(scratch_name and scratch_name in title),
                        "area": area,
                        "window": window,
                    }
                )
        candidates.sort(key=lambda item: (-int(item.get("score") or 0), -int(item.get("area") or 0)))
        return candidates

    try:
        open_attempt_summaries: list[dict[str, Any]] = []
        direct_launch_dir = gui_open_attempt_dir(1)
        scratch = project_scratch_copy(
            {
                "project_path": str(source),
                "scratch_dir": str(direct_launch_dir),
                "name_suffix": "_modbus_gui_probe",
            }
        )
        scratch_project = Path(str(scratch["scratch_copy"]["path"])).resolve()
        launch = launch_owen_logic({"project_path": str(scratch_project), "wait_seconds": wait_seconds})
        launched_pid = int(launch["pid"])
        active_pids = [launched_pid] if process_is_running(launched_pid) else []
        windows_after_launch = wait_for_owen_window(launched_pid, wait_seconds) if active_pids else []
        idle_after_launch = (
            wait_for_lifecycle_idle(launched_pid, post_open_idle_wait_seconds)
            if active_pids
            else {"idle": False, "process_exited": True, "windows": [], "blocking_windows": []}
        )
        windows_after_idle = enum_windows(pid=launched_pid, owen_only=False) if process_is_running(launched_pid) else []
        post_open_information_dialog_dismissals: list[dict[str, Any]] = []
        if dismiss_post_open_dialogs and process_is_running(launched_pid):
            if select_post_open_information_dialog(windows_after_idle):
                post_open_information_dialog_dismissals.append(
                    {
                        "pid": launched_pid,
                        "result": dismiss_post_open_information_dialogs(
                            launched_pid,
                            screenshot_dir,
                            screenshot_enabled,
                        ),
                    }
                )
                time.sleep(0.5)
        active_pids = [pid for pid in sorted(programrelay_pids() - baseline_pids) if process_is_running(pid)]
        windows_after_dialog_dismiss_idle = {
            str(current_pid): enum_windows(pid=current_pid, owen_only=False)
            for current_pid in active_pids
        }
        open_dialogs_after_dialog_dismiss_idle = [
            window
            for windows in windows_after_dialog_dismiss_idle.values()
            for window in windows
            if str(window.get("class_name") or "").lower() == "#32770"
        ]
        open_result = {
            "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
            "ok": bool(active_pids and scratch_project.exists() and not open_dialogs_after_dialog_dismiss_idle),
            "direct_project_launch": True,
            "gui_open_completed": bool(active_pids and scratch_project.exists() and not open_dialogs_after_dialog_dismiss_idle),
            "project_model_loaded_in_gui_claimed": bool(active_pids and scratch_project.exists() and not open_dialogs_after_dialog_dismiss_idle),
            "scratch_copy": safe_file_info(scratch_project, include_hash=True),
            "launch": launch,
            "windows_after_launch": windows_after_launch,
            "idle_after_launch": idle_after_launch,
            "windows_after_idle": windows_after_idle,
            "post_open_information_dialog_dismissals": post_open_information_dialog_dismissals,
            "programrelayfbd_pids_after_post_open_dialog_dismiss": active_pids,
            "windows_by_pid_after_post_open_dialog_dismiss": windows_after_dialog_dismiss_idle,
            "open_dialogs_after_post_open_dialog_dismiss_idle": open_dialogs_after_dialog_dismiss_idle,
        }
        open_attempt_summaries.append(
            {
                "attempt": 1,
                "scratch_dir": str(direct_launch_dir),
                "ok": open_result.get("ok"),
                "direct_project_launch": True,
                "gui_open_completed": open_result.get("gui_open_completed"),
                "project_model_loaded_in_gui_claimed": open_result.get("project_model_loaded_in_gui_claimed"),
                "error": None,
                "scratch_copy": open_result.get("scratch_copy"),
                "active_programrelayfbd_pids": active_pids,
                "process_exited_after_open": launched_pid not in programrelay_pids(),
                "open_dialogs_after_enter_count": 0,
                "open_dialogs_after_post_open_idle_count": len(open_dialogs_after_dialog_dismiss_idle),
            }
        )
        if not scratch_project.exists() or not open_result.get("gui_open_completed"):
            cleanup_results.extend(cleanup_new_processes())
            raise RuntimeError(
                "Direct OWEN Logic project launch did not produce a stable opened scratch project for Modbus GUI probe: "
                + json.dumps(json_safe_value(open_attempt_summaries), ensure_ascii=False)
            )
        if not active_pids:
            raise RuntimeError(
                "No OWEN Logic PID remained after direct project launch for Modbus GUI probe: "
                + json.dumps(json_safe_value(open_attempt_summaries), ensure_ascii=False)
            )

        scratch_hash_before = sha256_file(scratch_project)
        static_validation_before = project_validate({"project_path": str(scratch_project), "include_warnings": True})
        modbus_inspect = project_modbus_inspect({"project_path": str(scratch_project), "max_matches": 80})
        modbus_map = project_modbus_export_map(
            {"project_path": str(scratch_project), "include_empty_devices": True, "max_rows": 80}
        )
        opened_candidates = opened_project_window_candidates(active_pids, scratch_project)
        selected_candidate = opened_candidates[0] if opened_candidates else None
        if selected_candidate and int(selected_candidate.get("score") or 0) > 0:
            main_window = selected_candidate["window"]
            pid = int(selected_candidate["pid"])
            focus = focus_window({"pid": pid, "hwnd": int(main_window["hwnd"]), "owen_only": False})
            main_window = focus.get("window") or main_window
        else:
            pid = int(active_pids[0])
            focus = focus_window({"pid": pid, "owen_only": False})
            main_window = focus.get("window") or select_window({"pid": pid, "owen_only": False})
        main_hwnd = int(main_window["hwnd"])
        windows_after_dialog_dismiss = {
            str(current_pid): enum_windows(pid=current_pid, owen_only=False)
            for current_pid in active_pids
        }
        remaining_dialogs = [
            window
            for windows in windows_after_dialog_dismiss.values()
            for window in windows
            if str(window.get("class_name") or "").lower() == "#32770"
        ]
        screenshot = lifecycle_screenshot_hwnd(
            pid,
            main_hwnd,
            screenshot_dir,
            "opened_scratch_modbus_probe_after_dialog_dismiss",
            screenshot_enabled,
        )

        ui_snapshot_path = None
        ui_error = None
        ui_controls: list[dict[str, Any]] = []
        ui_snapshot_data = None
        ui_snapshot_attempts: list[dict[str, Any]] = []
        if include_ui_tree:
            for attempt in range(1, 4):
                if not process_is_running(pid):
                    ui_error = "OWEN Logic process exited before UI Automation snapshot"
                    ui_snapshot_attempts.append({"attempt": attempt, "ok": False, "error": ui_error})
                    break
                if attempt > 1:
                    time.sleep(1.0)
                    try:
                        focus_window({"pid": pid, "owen_only": False})
                    except Exception:
                        pass
                try:
                    ui_snapshot = ui_automation_snapshot(
                        {
                            "pid": pid,
                            "owen_only": False,
                            "max_depth": max_depth,
                            "max_children": max_children,
                            "include_offscreen": False,
                            "timeout_seconds": 30,
                        }
                    )
                    ui_tree = ui_snapshot.get("ui_tree") if isinstance(ui_snapshot.get("ui_tree"), dict) else {}
                    ui_controls = flatten_ui_tree(ui_tree) if isinstance(ui_tree, dict) else []
                    ui_snapshot_data = ui_snapshot
                    ui_error = None if ui_controls else "UI Automation snapshot returned zero controls"
                    ui_snapshot_attempts.append(
                        {
                            "attempt": attempt,
                            "ok": bool(ui_controls),
                            "control_count": len(ui_controls),
                            "window": ui_snapshot.get("window"),
                            "error": ui_error,
                        }
                    )
                    if save_ui_tree:
                        suffix = "" if ui_controls else f".attempt{attempt}"
                        ui_snapshot_path = ui_dir / f"opened_scratch_modbus_probe_after_dialog_dismiss{suffix}.ui.json"
                        ui_snapshot_path.write_text(json.dumps(ui_snapshot, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
                    if ui_controls:
                        break
                except Exception as exc:
                    ui_error = str(exc)
                    ui_snapshot_attempts.append({"attempt": attempt, "ok": False, "error": ui_error})

        menu_error = None
        menu_controls: list[dict[str, Any]] = []
        menu_snapshot_data = None
        menu_snapshot_attempts: list[dict[str, Any]] = []
        menu_snapshot_fallback_from_ui_tree = False
        if include_menu_snapshot:
            for attempt in range(1, 4):
                if not process_is_running(pid):
                    menu_error = "OWEN Logic process exited before menu snapshot"
                    menu_snapshot_attempts.append({"attempt": attempt, "ok": False, "error": menu_error})
                    break
                if attempt > 1:
                    time.sleep(1.0)
                    try:
                        focus_window({"pid": pid, "owen_only": False})
                    except Exception:
                        pass
                try:
                    menu_snapshot_data = menu_snapshot(
                        {
                            "pid": pid,
                            "owen_only": False,
                            "include_buttons": True,
                            "max_depth": max_depth,
                            "max_children": max_children,
                        }
                    )
                    menu_controls = [
                        control
                        for control in menu_snapshot_data.get("controls") or []
                        if isinstance(control, dict)
                    ]
                    menu_error = None if menu_controls else "Menu snapshot returned zero controls"
                    menu_snapshot_attempts.append(
                        {
                            "attempt": attempt,
                            "ok": bool(menu_controls),
                            "control_count": len(menu_controls),
                            "window": menu_snapshot_data.get("window"),
                            "error": menu_error,
                        }
                    )
                    if menu_controls:
                        break
                except Exception as exc:
                    menu_error = str(exc)
                    menu_snapshot_attempts.append({"attempt": attempt, "ok": False, "error": menu_error})
            if not menu_controls and ui_controls:
                menu_controls = menu_like_controls_from(ui_controls)
                if menu_controls:
                    menu_snapshot_fallback_from_ui_tree = True
                    menu_error = None
                    menu_snapshot_data = {
                        "window": (ui_snapshot_data or {}).get("window"),
                        "control_count": len(menu_controls),
                        "controls": menu_controls,
                        "include_buttons": True,
                        "backend": "Windows UI Automation reused from Modbus GUI UI tree",
                        "fallback_from_ui_tree": True,
                    }

        all_controls = ui_controls + menu_controls
        gui_surface_summary = summarize_gui_surface(all_controls)
        ui_hits = collect_term_hits(ui_controls, terms)
        menu_hits = collect_term_hits(menu_controls, terms)
        source_hash_after = sha256_file(source)
        scratch_hash_after = sha256_file(scratch_project)
        static_validation_after = project_validate({"project_path": str(scratch_project), "include_warnings": True})
        screenshot_paths = [str(path) for path in sorted(screenshot_dir.glob("*.png"))]
        modbus_device_count = int(modbus_map.get("device_count") or 0)
        result = {
            "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
            "ok": bool(
                static_validation_before.get("ok")
                and static_validation_after.get("ok")
                and open_result.get("gui_open_completed")
                and not remaining_dialogs
                and source_hash_before == source_hash_after
                and modbus_device_count >= 1
                and (not screenshot_enabled or screenshot_paths)
                and (not include_ui_tree or (ui_controls and not ui_error))
                and (not include_menu_snapshot or (menu_controls and not menu_error))
            ),
            "source_project": safe_file_info(source, include_hash=True),
            "scratch_copy": safe_file_info(scratch_project, include_hash=True),
            "scratch_dir": str(scratch_dir),
            "gui_open_short_scratch_base": str(gui_open_short_base) if gui_open_short_base else None,
            "baseline_programrelayfbd_pids": sorted(baseline_pids),
            "open_attempts": open_attempts,
            "open_attempt_summaries": open_attempt_summaries,
            "open_probe": open_result,
            "opened_project_window_candidates": [
                {
                    "pid": candidate.get("pid"),
                    "hwnd": candidate.get("hwnd"),
                    "score": candidate.get("score"),
                    "title_matches_scratch_path": candidate.get("title_matches_scratch_path"),
                    "title_matches_scratch_name": candidate.get("title_matches_scratch_name"),
                    "area": candidate.get("area"),
                    "window": {
                        "hwnd": candidate.get("window", {}).get("hwnd"),
                        "pid": candidate.get("window", {}).get("pid"),
                        "title": candidate.get("window", {}).get("title"),
                        "class_name": candidate.get("window", {}).get("class_name"),
                        "visible": candidate.get("window", {}).get("visible"),
                        "enabled": candidate.get("window", {}).get("enabled"),
                        "rect": candidate.get("window", {}).get("rect"),
                    },
                }
                for candidate in opened_candidates[:10]
            ],
            "pid": pid,
            "active_programrelayfbd_pids": active_pids,
            "focus_after_dialog_dismiss": focus,
            "main_window": main_window,
            "main_hwnd": main_hwnd,
            "windows_after_dialog_dismiss": windows_after_dialog_dismiss,
            "remaining_dialogs_after_dialog_dismiss": remaining_dialogs,
            "screenshot": screenshot,
            "screenshots": screenshot_paths,
            "ui_snapshot_path": str(ui_snapshot_path) if ui_snapshot_path else None,
            "ui_error": ui_error,
            "ui_snapshot_attempts": ui_snapshot_attempts,
            "ui_control_count": len(ui_controls),
            "menu_error": menu_error,
            "menu_snapshot_attempts": menu_snapshot_attempts,
            "menu_snapshot_fallback_from_ui_tree": menu_snapshot_fallback_from_ui_tree,
            "menu_control_count": len(menu_controls),
            "menu_snapshot": menu_snapshot_data,
            "search_terms": terms,
            "ui_hits": ui_hits,
            "menu_hits": menu_hits,
            "modbus_gui_surface_hit_count": len(ui_hits) + len(menu_hits),
            "gui_surface_summary": gui_surface_summary,
            "modbus_inspect_summary": {
                "setting_count": len(modbus_inspect.get("modbus_settings") or []),
                "device_model_count": len(modbus_inspect.get("device_models") or []),
                "keyword_match_count": modbus_inspect.get("keyword_match_count"),
            },
            "modbus_map_summary": {
                "device_count": modbus_map.get("device_count"),
                "variable_model_count": modbus_map.get("variable_model_count"),
                "rows_returned": modbus_map.get("rows_returned"),
                "rows_truncated": modbus_map.get("rows_truncated"),
                "source_hash_preserved": modbus_map.get("source_hash_preserved"),
            },
            "static_validation_before": static_validation_before,
            "static_validation_after": static_validation_after,
            "source_hash_before": source_hash_before,
            "source_hash_after": source_hash_after,
            "source_hash_preserved": source_hash_before == source_hash_after,
            "scratch_hash_before": scratch_hash_before,
            "scratch_hash_after": scratch_hash_after,
            "scratch_project_exists": scratch_project.exists(),
            "risk_class": "safe_runtime",
            "gui_modbus_surface_probe_executed": True,
            "gui_modbus_dialog_completion_verified": False,
            "gui_modbus_edit_executed": False,
            "opened_serial_port": False,
            "opened_network_socket": False,
            "live_device_action_executed": False,
            "validation_scope": "bounded_gui_modbus_surface_probe_plus_offline_modbus_model_readback",
            "limitation": "This opens a scratch project through the real OWEN Logic File > Open path, dismisses safe post-open informational dialogs when requested, captures screenshot evidence plus offline Modbus model/map readback and, when stable, GUI/menu/UIA evidence. It does not edit or complete OWEN Logic Modbus master/slave dialogs, register-map GUI import/export dialogs, COM/TCP or live-device communication.",
            "guardrail": "Only a scratch copy is opened in OWEN Logic. Source hash is checked before/after. No live-device, COM/IP, network, download, firmware, calibration, device-setting, or live Modbus action is executed.",
        }
    finally:
        if cleanup:
            for cleanup_pid in sorted(programrelay_pids() - baseline_pids):
                cleanup_results.append(stop_process_best_effort(int(cleanup_pid)))
            cleanup_result = {
                "baseline_programrelayfbd_pids": sorted(baseline_pids),
                "cleanup_results": cleanup_results,
            }
            try:
                (scratch_dir / "cleanup_result.json").write_text(
                    json.dumps(cleanup_result, ensure_ascii=False, indent=2) + "\n",
                    encoding="utf-8",
                )
            except Exception:
                pass
    if result is None:
        raise RuntimeError("OWEN Logic Modbus GUI probe did not produce a result")
    result["cleanup_requested"] = cleanup
    result["cleanup_result"] = cleanup_result
    result["cleanup_sidecar_path"] = str(scratch_dir / "cleanup_result.json") if cleanup_result else None
    result["processes_after_cleanup"] = tasklist_programrelay()
    return result


