def variable_table_target_tab_terms(target_name: str) -> list[str]:
    target = str(target_name or "").strip().lower()
    if not target:
        return []
    terms: list[str] = []
    for term in re.split(r"[\s,;/|]+", target):
        if term:
            terms.append(term)
    terms.append(target)
    for key, values in VARIABLE_TABLE_TARGET_TAB_SYNONYMS.items():
        if key in target or target in key:
            terms.extend(values)
    expanded: list[str] = []
    for term in terms:
        if not term or term in expanded:
            continue
        expanded.append(term)
        try:
            mojibake = term.encode("utf-8").decode("cp1251").lower()
            if mojibake and mojibake not in expanded:
                expanded.append(mojibake)
        except Exception:
            pass
    return expanded


def variable_table_control_click_point(control: dict[str, Any]) -> tuple[float, float]:
    rect = control.get("bounding_rect") or control.get("rect") or {}
    left = float(rect.get("x", rect.get("left", 0)) or 0)
    top = float(rect.get("y", rect.get("top", 0)) or 0)
    width = float(rect.get("width", 0) or 0)
    height = float(rect.get("height", 0) or 0)
    if width <= 0 and rect.get("right") is not None:
        width = float(rect.get("right") or 0) - left
    if height <= 0 and rect.get("bottom") is not None:
        height = float(rect.get("bottom") or 0) - top
    if width <= 0 or height <= 0:
        raise ValueError("Control has no clickable bounding rectangle")
    return (left + (width / 2.0), top + (height / 2.0))


def variable_table_target_tab_candidate(ui_tree: dict[str, Any], target_name: str) -> dict[str, Any] | None:
    terms = variable_table_target_tab_terms(target_name)
    if not terms:
        return None
    controls = flatten_ui_tree(ui_tree) if isinstance(ui_tree, dict) else []
    candidates: list[dict[str, Any]] = []
    for control in controls:
        if control.get("is_offscreen") is True or control.get("is_enabled") is False:
            continue
        rect = control.get("bounding_rect") or {}
        width = float(rect.get("width") or 0)
        height = float(rect.get("height") or 0)
        if width <= 0 or height <= 0 or height > 90:
            continue
        text = visible_control_text(control)
        haystack = text.lower()
        matched = sorted({term for term in terms if term and term in haystack})
        if not matched:
            continue
        control_type = str(control.get("control_type") or "").lower()
        class_name = str(control.get("class_name") or "").lower()
        if "window" in control_type or "edit" in control_type:
            continue
        if ("dataitem" in control_type or "header" in control_type) and "tab" not in control_type:
            continue
        score = 10 * len(matched)
        if "tabitem" in control_type:
            score += 50
        elif "tab" in control_type or "tab" in class_name:
            score += 35
        elif "button" in control_type:
            score += 15
        elif "custom" in control_type or "pane" in control_type:
            score += 8
        if height <= 45:
            score += 8
        if width <= 260:
            score += 4
        candidates.append(
            {
                "score": score,
                "matched_terms": matched,
                "name": control.get("name"),
                "automation_id": control.get("automation_id"),
                "class_name": control.get("class_name"),
                "control_type": control.get("control_type"),
                "localized_control_type": control.get("localized_control_type"),
                "is_enabled": control.get("is_enabled"),
                "is_offscreen": control.get("is_offscreen"),
                "bounding_rect": rect,
                "path": control.get("path"),
                "text": text[:1000],
            }
        )
    candidates.sort(
        key=lambda item: (
            -int(item.get("score") or 0),
            float((item.get("bounding_rect") or {}).get("y") or (item.get("bounding_rect") or {}).get("top") or 0),
            float((item.get("bounding_rect") or {}).get("x") or (item.get("bounding_rect") or {}).get("left") or 0),
        )
    )
    return candidates[0] if candidates else None


def variable_table_target_tab_child_window_candidate(
    child_windows: list[dict[str, Any]],
    target_name: str,
) -> dict[str, Any] | None:
    terms = variable_table_target_tab_terms(target_name)
    if not terms:
        return None
    candidates: list[dict[str, Any]] = []
    for child in child_windows:
        if not bool(child.get("visible")) or not bool(child.get("enabled")):
            continue
        rect = child.get("rect") or {}
        width = float(rect.get("width") or 0)
        height = float(rect.get("height") or 0)
        if width <= 0 or height <= 0 or height > 90:
            continue
        text = " ".join(str(child.get(key) or "") for key in ("text", "class_name")).strip()
        haystack = text.lower()
        matched = sorted({term for term in terms if term and term in haystack})
        if not matched:
            continue
        class_name = str(child.get("class_name") or "").lower()
        score = 10 * len(matched)
        if "tab" in class_name:
            score += 40
        if height <= 45:
            score += 8
        if width <= 280:
            score += 4
        candidates.append(
            {
                "score": score,
                "source": "win32_child_window",
                "matched_terms": matched,
                "name": child.get("text"),
                "automation_id": None,
                "class_name": child.get("class_name"),
                "control_type": "Win32.ChildWindow",
                "localized_control_type": None,
                "is_enabled": child.get("enabled"),
                "is_offscreen": False,
                "bounding_rect": {
                    "x": rect.get("left"),
                    "y": rect.get("top"),
                    "width": rect.get("width"),
                    "height": rect.get("height"),
                },
                "hwnd": child.get("hwnd"),
                "text": text[:1000],
            }
        )
    candidates.sort(
        key=lambda item: (
            -int(item.get("score") or 0),
            float((item.get("bounding_rect") or {}).get("y") or 0),
            float((item.get("bounding_rect") or {}).get("x") or 0),
        )
    )
    return candidates[0] if candidates else None


def variable_table_target_tab_geometry_fallback(
    target_window: dict[str, Any] | None,
    target_name: str,
) -> dict[str, Any] | None:
    terms = set(variable_table_target_tab_terms(target_name))
    if not terms.intersection({"slave", "master", "network", "modbus", "\u0441\u0435\u0442\u0435\u0432"}):
        return None
    rect = (target_window or {}).get("rect") or {}
    left = float(rect.get("left") or 0)
    top = float(rect.get("top") or 0)
    width = float(rect.get("width") or 0)
    if left <= 0 or top <= 0 or width < 360:
        return None
    return {
        "score": 1,
        "source": "network_tab_geometry_fallback",
        "matched_terms": sorted(terms.intersection({"slave", "master", "network", "modbus", "\u0441\u0435\u0442\u0435\u0432"})),
        "name": "\u0421\u0435\u0442\u0435\u0432\u044b\u0435, \u0421\u043b\u043e\u0442 1",
        "automation_id": None,
        "class_name": None,
        "control_type": "GeometryFallback.TabItem",
        "localized_control_type": None,
        "is_enabled": True,
        "is_offscreen": False,
        "bounding_rect": {"x": left + 170, "y": top + 34, "width": 122, "height": 24},
        "text": "Geometry fallback for the visible OWEN Logic network variables tab when UIA/Win32 child text omits tab labels.",
    }


def modbus_map_rows_for_variable_name(modbus_map: dict[str, Any], variable_name: str) -> list[dict[str, Any]]:
    marker = str(variable_name or "")
    if not marker:
        return []
    rows: list[dict[str, Any]] = []
    for row in modbus_map.get("rows") or []:
        if isinstance(row, dict) and str(row.get("variable_name") or "") == marker:
            rows.append(row)
    return rows


