def variable_table_coverage_audit(args: dict[str, Any]) -> dict[str, Any]:
    include_details = bool(args.get("include_operation_details", True))
    include_tool_names = bool(args.get("include_tool_names", True))
    operations: list[dict[str, Any]] = []
    for row in VARIABLE_TABLE_OPERATION_COVERAGE:
        item = dict(row)
        if not include_tool_names:
            item.pop("tools", None)
        operations.append(item)

    status_counts: dict[str, int] = {}
    for row in VARIABLE_TABLE_OPERATION_COVERAGE:
        status = str(row.get("status") or "unknown")
        status_counts[status] = status_counts.get(status, 0) + 1

    proven = [
        row["operation"]
        for row in VARIABLE_TABLE_OPERATION_COVERAGE
        if row.get("status") == "proven_current_safe_scope"
    ]
    partial = [
        row["operation"]
        for row in VARIABLE_TABLE_OPERATION_COVERAGE
        if row.get("status") == "partial_semantic_gap"
    ]
    blocked = [
        row["operation"]
        for row in VARIABLE_TABLE_OPERATION_COVERAGE
        if str(row.get("status") or "").startswith("blocked_")
    ]
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": True,
        "read_only": True,
        "opened_gui": False,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "live_device_action_executed": False,
        "coverage_domain": "owen_logic_variable_table",
        "status_counts": status_counts,
        "proven_operation_count": len(proven),
        "partial_operation_count": len(partial),
        "blocked_operation_count": len(blocked),
        "proven_operations": proven,
        "partial_operations": partial,
        "blocked_operations": blocked,
        "operations": operations if include_details else [],
        "remaining_gap_bucket": "variable_table_gui_dialog_parity",
        "remaining_gap_summary": (
            "Bounded scratch GUI open, toolbar surface, create/delete marker, CSV import commit/export, targeted "
            "network-table CSV import/export, offline variable model operations, and ST array declaration are covered. "
            "Arbitrary GUI catalog-tree editing, GUI variable-table array-tree authoring, broader network/register "
            "wizard or live parity, and live controller execution remain unproven or blocked by live-device preflight."
        ),
        "guardrail": (
            "This audit is read-only and does not open OWEN Logic or mutate projects. Treat only "
            "proven_current_safe_scope operations as callable under their own required opt-ins; do not promote "
            "partial_semantic_gap or blocked_without_explicit_live_preflight rows to completion evidence."
        ),
    }


