def project_device_menu_dialog_probe(args: dict[str, Any]) -> dict[str, Any]:
    require_windows()
    if not bool(args.get("allow_safe_runtime", False)):
        raise ValueError("owen_logic_project_device_menu_dialog_probe requires allow_safe_runtime=true")

    source = Path(str(args.get("project_path") or "")).expanduser().resolve()
    source_hash_before = sha256_file(source)
    scratch_value = args.get("scratch_dir")
    if scratch_value:
        scratch_dir = Path(str(scratch_value)).expanduser().resolve()
    else:
        workbench = find_workbench_root()
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        scratch_dir = (
            workbench / "30_LOCAL_HEAVY" / "sandbox_tmp" / "owen_project_device_menu_dialog_probe" / timestamp
            if workbench
            else Path.home() / ".codex" / "tmp" / "owen_project_device_menu_dialog_probe" / timestamp
        ).resolve()
    if not is_scratch_destination(scratch_dir):
        raise ValueError(f"Refusing Device menu dialog probe output outside scratch/sandbox/local-heavy path: {scratch_dir}")
    screenshot_root = scratch_dir / "screenshots"
    ui_root = scratch_dir / "ui_snapshots"
    screenshot_root.mkdir(parents=True, exist_ok=True)
    ui_root.mkdir(parents=True, exist_ok=True)

    requested_commands_raw = args.get("commands")
    if requested_commands_raw is None:
        requested_commands = ["variable_table", "port_settings"]
    elif isinstance(requested_commands_raw, list):
        requested_commands = [str(command) for command in requested_commands_raw]
    else:
        raise ValueError("commands must be an array when provided")
    unknown_commands = [command for command in requested_commands if command not in DEVICE_MENU_DIALOG_COMMANDS]
    if unknown_commands:
        raise ValueError(f"Unknown Device menu dialog command(s): {unknown_commands}")
    if not requested_commands:
        raise ValueError("At least one Device menu dialog command is required")
    toolbar_actions_raw = args.get("variable_table_toolbar_actions")
    if toolbar_actions_raw is None:
        variable_table_toolbar_actions: list[str] = []
    elif isinstance(toolbar_actions_raw, list):
        variable_table_toolbar_actions = [str(action) for action in toolbar_actions_raw]
    else:
        raise ValueError("variable_table_toolbar_actions must be an array when provided")
    unknown_toolbar_actions = [
        action for action in variable_table_toolbar_actions if action not in VARIABLE_TABLE_TOOLBAR_ACTIONS
    ]
    if unknown_toolbar_actions:
        raise ValueError(f"Unknown variable-table toolbar action(s): {unknown_toolbar_actions}")
    variable_table_target_tab_name = str(args.get("variable_table_target_tab_name") or "").strip()
    require_variable_table_target_tab = bool(args.get("require_variable_table_target_tab", False))
    variable_table_target_tab_wait_seconds = max(
        0.1,
        min(float(args.get("variable_table_target_tab_wait_seconds", 1.0)), 10),
    )
    if require_variable_table_target_tab and not variable_table_target_tab_name:
        raise ValueError("require_variable_table_target_tab=true requires variable_table_target_tab_name")
    allow_gui_csv_import = bool(args.get("allow_gui_csv_import", False))
    allow_gui_csv_import_commit = bool(args.get("allow_gui_csv_import_commit", False))
    csv_import_wait_seconds = max(1, min(float(args.get("csv_import_wait_seconds", 10)), 60))
    csv_import_source: Path | None = None
    csv_import_marker = str(args.get("csv_import_marker") or "").strip()
    if csv_import_marker and ("\r" in csv_import_marker or "\n" in csv_import_marker or len(csv_import_marker) > 120):
        raise ValueError("csv_import_marker must be a single-line marker no longer than 120 characters")
    if allow_gui_csv_import:
        if "csv_import_dialog" not in variable_table_toolbar_actions:
            raise ValueError("allow_gui_csv_import=true requires variable_table_toolbar_actions to include csv_import_dialog")
        if not csv_import_marker:
            raise ValueError("allow_gui_csv_import=true requires csv_import_marker for UIA readback evidence")
        csv_import_value = args.get("csv_import_path")
        if not csv_import_value:
            raise ValueError("allow_gui_csv_import=true requires csv_import_path")
        csv_import_source = Path(str(csv_import_value)).expanduser().resolve()
        if csv_import_source.suffix.lower() != ".csv":
            raise ValueError(f"Refusing GUI CSV import from a non-.csv path: {csv_import_source}")
        if not is_scratch_destination(csv_import_source):
            raise ValueError(f"Refusing GUI CSV import from outside scratch/sandbox/local-heavy path: {csv_import_source}")
        if not csv_import_source.is_file():
            raise FileNotFoundError(f"GUI CSV import source file not found: {csv_import_source}")
    if allow_gui_csv_import_commit and not allow_gui_csv_import:
        raise ValueError("allow_gui_csv_import_commit=true requires allow_gui_csv_import=true")
    allow_gui_csv_export = bool(args.get("allow_gui_csv_export", False))
    csv_export_wait_seconds = max(1, min(float(args.get("csv_export_wait_seconds", 10)), 60))
    csv_export_target: Path | None = None
    if allow_gui_csv_export:
        if "csv_export_dialog" not in variable_table_toolbar_actions:
            raise ValueError("allow_gui_csv_export=true requires variable_table_toolbar_actions to include csv_export_dialog")
        csv_export_value = args.get("csv_export_path")
        if csv_export_value:
            csv_export_target = Path(str(csv_export_value)).expanduser().resolve()
        else:
            csv_export_target = (
                scratch_dir
                / "exports"
                / f"variable_table_gui_export_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv"
            ).resolve()
        if csv_export_target.suffix.lower() != ".csv":
            raise ValueError(f"Refusing GUI CSV export to a non-.csv path: {csv_export_target}")
        if not is_scratch_destination(csv_export_target):
            raise ValueError(f"Refusing GUI CSV export outside scratch/sandbox/local-heavy path: {csv_export_target}")
        csv_export_target.parent.mkdir(parents=True, exist_ok=True)
        if csv_export_target.exists():
            raise ValueError(f"Refusing to overwrite existing GUI CSV export target: {csv_export_target}")
    allow_port_settings_ok_close = bool(args.get("allow_port_settings_ok_close", False))
    confirm_port_settings_no_change = bool(args.get("confirm_port_settings_no_change", False))
    port_settings_ok_wait_seconds = max(0.2, min(float(args.get("port_settings_ok_wait_seconds", 1.2)), 5.0))
    if allow_port_settings_ok_close:
        if "port_settings" not in requested_commands:
            raise ValueError("allow_port_settings_ok_close=true requires commands to include port_settings")
        if not confirm_port_settings_no_change:
            raise ValueError("allow_port_settings_ok_close=true requires confirm_port_settings_no_change=true")

    baseline_pids = programrelay_pids()
    wait_seconds = max(1, min(float(args.get("wait_seconds", 8)), 120))
    open_wait_seconds = max(1, min(float(args.get("open_wait_seconds", 16)), 60))
    open_attempts = clamp_int(args.get("open_attempts"), 2, 1, 3)
    post_open_idle_wait_seconds = max(
        1,
        min(float(args.get("post_open_idle_wait_seconds", 45)), 120),
    )
    command_wait_seconds = max(0.5, min(float(args.get("command_wait_seconds", 2.5)), 15))
    inter_command_cooldown_seconds = max(0.0, min(float(args.get("inter_command_cooldown_seconds", 3.0)), 15))
    dismiss_post_open_dialogs = bool(args.get("dismiss_post_open_information_dialogs", True))
    screenshot_enabled = bool(args.get("screenshot", True))
    include_ui_tree = bool(args.get("include_ui_tree", True))
    save_ui_tree = bool(args.get("save_ui_tree", True))
    max_depth = clamp_int(args.get("max_depth"), 9, 0, 10)
    max_children = clamp_int(args.get("max_children"), 950, 1, 1000)
    cleanup = bool(args.get("cleanup_launched_process", True))
    terms_raw = args.get("search_terms")
    terms = (
        [str(term) for term in terms_raw if str(term).strip()]
        if isinstance(terms_raw, list) and terms_raw
        else list(DEVICE_MENU_DIALOG_DEFAULT_TERMS)
    )
    if csv_import_marker and csv_import_marker not in terms:
        terms.append(csv_import_marker)
    for tab_term in variable_table_target_tab_terms(variable_table_target_tab_name):
        if tab_term and tab_term not in terms:
            terms.append(tab_term)

    def active_pids_after_open(open_result: dict[str, Any]) -> list[int]:
        candidates: list[int] = []
        for key in (
            "programrelayfbd_pids_after_post_open_dialog_dismiss",
            "programrelayfbd_pids_after_post_open_idle",
            "programrelayfbd_pids_after_open",
            "programrelayfbd_pids_after_launch",
        ):
            value = open_result.get(key)
            if isinstance(value, list):
                for pid_value in value:
                    try:
                        candidates.append(int(pid_value))
                    except (TypeError, ValueError):
                        pass
        launch = open_result.get("launch") or {}
        if launch.get("pid") is not None:
            candidates.append(int(launch["pid"]))
        candidates.extend(sorted(programrelay_pids() - baseline_pids))
        result_pids: list[int] = []
        for candidate in candidates:
            if candidate in baseline_pids or candidate in result_pids:
                continue
            if process_is_running(candidate):
                result_pids.append(candidate)
        return result_pids

    def wait_for_device_popup(pid: int, timeout_seconds: float = 3.0) -> dict[str, Any] | None:
        deadline = time.time() + max(0.5, min(timeout_seconds, 10))
        while time.time() < deadline:
            popup = find_windowsforms_menu_popup(pid, min_height=50)
            if popup:
                return popup
            time.sleep(0.2)
        return None

    def cleanup_new_processes() -> list[dict[str, Any]]:
        cleanup_results: list[dict[str, Any]] = []
        for _attempt in range(4):
            current_new_pids = sorted(programrelay_pids() - baseline_pids)
            if not current_new_pids:
                break
            for cleanup_pid in current_new_pids:
                cleanup_results.append(stop_process_best_effort(int(cleanup_pid)))
            time.sleep(0.7)
        return cleanup_results

    gui_open_short_base: Path | None = None

    def gui_open_attempt_dir(command_name: str, attempt: int) -> Path:
        nonlocal gui_open_short_base
        if gui_open_short_base is None:
            workbench = find_workbench_root()
            short_token = f"dm_{datetime.now().strftime('%H%M%S')}_{uuid.uuid4().hex[:6]}"
            gui_open_short_base = (
                workbench / "30_LOCAL_HEAVY" / "sandbox_tmp" / "og" / short_token
                if workbench
                else Path.home() / ".codex" / "tmp" / "og" / short_token
            ).resolve()
        return gui_open_short_base / str(command_name) / f"a{int(attempt)}"

    def compact_window(window: dict[str, Any] | None) -> dict[str, Any] | None:
        if not isinstance(window, dict):
            return None
        return {
            "hwnd": window.get("hwnd"),
            "pid": window.get("pid"),
            "title": window.get("title"),
            "class_name": window.get("class_name"),
            "visible": window.get("visible"),
            "enabled": window.get("enabled"),
            "rect": window.get("rect"),
        }

    def classify_csv_action_windows(
        windows: list[dict[str, Any]],
        main_hwnd: int,
        target_hwnd: int,
    ) -> dict[str, list[dict[str, Any]]]:
        file_dialogs: list[dict[str, Any]] = []
        dropdowns: list[dict[str, Any]] = []
        other: list[dict[str, Any]] = []
        for window in windows:
            hwnd = int(window.get("hwnd") or 0)
            if not hwnd or hwnd in {int(main_hwnd), int(target_hwnd)}:
                continue
            if not bool(window.get("visible")):
                continue
            class_name = str(window.get("class_name") or "")
            class_name_lower = class_name.lower()
            title = str(window.get("title") or "")
            marker = f"{title} {class_name}".lower()
            rect_value = window.get("rect") or {}
            area = int(rect_value.get("width") or 0) * int(rect_value.get("height") or 0)
            if area <= 0 or area > 1000000:
                continue
            looks_like_file_dialog = (
                "#32770" in class_name
                or "open" in marker
                or "save" in marker
                or "\u043e\u0442\u043a\u0440" in marker
                or "\u0441\u043e\u0445\u0440" in marker
                or "\u0438\u043c\u043f\u043e\u0440" in marker
                or "\u044d\u043a\u0441\u043f\u043e\u0440" in marker
            )
            looks_like_dropdown = (
                "windowsforms10.window.20000" in class_name_lower
                or ("windowsforms10.window" in class_name_lower and area <= 60000 and not title.strip())
            )
            compact = compact_window(window)
            if compact is None:
                continue
            if looks_like_file_dialog and area >= 40000:
                file_dialogs.append(compact)
            elif looks_like_dropdown:
                dropdowns.append(compact)
            elif looks_like_file_dialog:
                other.append(compact)
        return {
            "file_dialogs": file_dialogs,
            "toolbar_dropdowns": dropdowns,
            "other_dialog_like_windows": other,
        }

    def csv_file_dialog_kind(dialog: dict[str, Any]) -> str:
        marker = f"{dialog.get('title') or ''} {dialog.get('class_name') or ''}".lower()
        if any(term in marker for term in ("save", "\u0441\u043e\u0445\u0440", "\u044d\u043a\u0441\u043f\u043e\u0440")):
            return "save"
        if any(term in marker for term in ("open", "\u043e\u0442\u043a\u0440", "\u0438\u043c\u043f\u043e\u0440")):
            return "open"
        try:
            child_text = " ".join(
                str(child.get("text") or "").lower()
                for child in enum_child_windows(int(dialog.get("hwnd") or 0))
            )
            if any(term in child_text for term in ("\u0441\u043e\u0445\u0440", "save")):
                return "save"
            if any(term in child_text for term in ("\u043e\u0442\u043a\u0440", "open")):
                return "open"
        except Exception:
            pass
        return "unknown"

    def opened_project_window_candidates(active_pids: list[int], scratch_project: Path) -> list[dict[str, Any]]:
        scratch_name = scratch_project.name.lower()
        scratch_path = str(scratch_project).lower()
        candidates: list[dict[str, Any]] = []
        for candidate_pid in active_pids:
            try:
                windows = enum_windows(pid=int(candidate_pid), owen_only=False)
            except Exception:
                continue
            for window in windows:
                if not bool(window.get("visible")):
                    continue
                title = str(window.get("title") or "").lower()
                rect_value = window.get("rect") or {}
                area = int(rect_value.get("width") or 0) * int(rect_value.get("height") or 0)
                score = 0
                if scratch_path and scratch_path in title:
                    score += 8
                if scratch_name and scratch_name in title:
                    score += 4
                if "owen logic" in title:
                    score += 2
                if area >= 100000:
                    score += 1
                candidates.append(
                    {
                        "pid": int(candidate_pid),
                        "hwnd": int(window.get("hwnd") or 0),
                        "score": score,
                        "title_matches_scratch_path": bool(scratch_path and scratch_path in title),
                        "title_matches_scratch_name": bool(scratch_name and scratch_name in title),
                        "area": area,
                        "window": window,
                    }
                )
        candidates.sort(key=lambda item: (-int(item.get("score") or 0), -int(item.get("area") or 0)))
        return candidates

    def capture_window(
        pid: int,
        hwnd: int,
        label: str,
        command_screenshot_dir: Path,
        command_ui_dir: Path,
    ) -> dict[str, Any]:
        capture: dict[str, Any] = {"label": label, "pid": pid, "hwnd": hwnd}
        try:
            capture["window"] = compact_window(window_info_from_hwnd(hwnd))
        except Exception as exc:
            capture["window_error"] = str(exc)
        try:
            capture["screenshot"] = lifecycle_screenshot_hwnd(pid, hwnd, command_screenshot_dir, label, screenshot_enabled)
        except Exception as exc:
            capture["screenshot_error"] = str(exc)
        if include_ui_tree:
            try:
                snapshot = ui_automation_snapshot(
                    {
                        "pid": pid,
                        "hwnd": hwnd,
                        "owen_only": False,
                        "max_depth": max_depth,
                        "max_children": max_children,
                        "include_offscreen": False,
                        "timeout_seconds": 30,
                    }
                )
                tree = snapshot.get("ui_tree") if isinstance(snapshot.get("ui_tree"), dict) else {}
                controls = flatten_ui_tree(tree) if isinstance(tree, dict) else []
                hits = collect_term_hits(controls, terms, max_hits=120)
                capture["ui_control_count"] = len(controls)
                capture["ui_hits"] = hits
                capture["ui_hit_count"] = len(hits)
                if save_ui_tree:
                    snapshot_path = command_ui_dir / f"{label}.ui.json"
                    snapshot_path.write_text(
                        json.dumps(json_safe_value(snapshot), ensure_ascii=False, indent=2) + "\n",
                        encoding="utf-8",
                    )
                    capture["ui_snapshot_path"] = str(snapshot_path)
            except Exception as exc:
                capture["ui_error"] = str(exc)
        return capture

    def select_variable_table_target_tab(
        pid: int,
        hwnd: int,
        command_screenshot_dir: Path,
        command_ui_dir: Path,
    ) -> dict[str, Any]:
        selection: dict[str, Any] = {
            "requested_tab_name": variable_table_target_tab_name,
            "required": require_variable_table_target_tab,
            "selected": False,
            "candidate": None,
            "candidate_click_point": None,
        }
        selection["capture_before"] = capture_window(
            pid,
            hwnd,
            "variable_table_target_tab_before_select",
            command_screenshot_dir,
            command_ui_dir,
        )
        try:
            snapshot = ui_automation_snapshot(
                {
                    "pid": pid,
                    "hwnd": hwnd,
                    "owen_only": False,
                    "max_depth": max_depth,
                    "max_children": max_children,
                    "include_offscreen": False,
                    "timeout_seconds": 30,
                }
            )
            tree = snapshot.get("ui_tree") if isinstance(snapshot.get("ui_tree"), dict) else {}
            controls = flatten_ui_tree(tree) if isinstance(tree, dict) else []
            selection["ui_control_count"] = len(controls)
            candidate = variable_table_target_tab_candidate(tree, variable_table_target_tab_name)
            if candidate:
                candidate["source"] = candidate.get("source") or "uia_tree"
            try:
                child_windows = enum_child_windows(hwnd)
                selection["child_windows"] = child_windows
                if not candidate:
                    candidate = variable_table_target_tab_child_window_candidate(
                        child_windows,
                        variable_table_target_tab_name,
                    )
            except Exception as exc:
                selection["child_window_lookup_error"] = str(exc)
            if not candidate:
                candidate = variable_table_target_tab_geometry_fallback(
                    (selection.get("capture_before") or {}).get("window"),
                    variable_table_target_tab_name,
                )
            selection["candidate"] = candidate
            if candidate:
                click_x, click_y = variable_table_control_click_point(candidate)
                selection["candidate_click_point"] = {"x": click_x, "y": click_y}
                try:
                    selection["focus_before_click"] = focus_window({"pid": pid, "hwnd": hwnd, "owen_only": False})
                except Exception as exc:
                    selection["focus_before_click_error"] = str(exc)
                selection["click"] = mouse_click_screen(
                    click_x,
                    click_y,
                    wait_seconds=variable_table_target_tab_wait_seconds,
                )
                selection["selected"] = bool((selection.get("click") or {}).get("ok"))
            else:
                selection["matching_terms"] = variable_table_target_tab_terms(variable_table_target_tab_name)
        except Exception as exc:
            selection["error"] = str(exc)
        selection["capture_after"] = capture_window(
            pid,
            hwnd,
            "variable_table_target_tab_after_select",
            command_screenshot_dir,
            command_ui_dir,
        )
        return selection

    def run_one_command(command_name: str) -> dict[str, Any]:
        command_meta = DEVICE_MENU_DIALOG_COMMANDS[command_name]
        command_dir = scratch_dir / command_name
        command_screenshot_dir = screenshot_root / command_name
        command_ui_dir = ui_root / command_name
        command_screenshot_dir.mkdir(parents=True, exist_ok=True)
        command_ui_dir.mkdir(parents=True, exist_ok=True)
        command_source_hash_before = sha256_file(source)
        command_result: dict[str, Any] = {
            "command": command_name,
            "menu_item_ru": command_meta["menu_item_ru"],
            "expected_surface": command_meta["expected_surface"],
            "scratch_dir": str(command_dir),
            "screenshot_dir": str(command_screenshot_dir),
            "ui_snapshot_dir": str(command_ui_dir),
            "source_hash_before": command_source_hash_before,
            "serial_or_network_access_attempted": False,
            "opened_serial_port": False,
            "opened_network_socket": False,
            "live_device_action_executed": False,
            "write_to_controller_attempted": False,
            "firmware_or_calibration_action_attempted": False,
            "port_settings_no_change_ok_close_requested": bool(
                command_name == "port_settings" and allow_port_settings_ok_close
            ),
            "port_settings_no_change_confirmed": bool(
                command_name == "port_settings" and confirm_port_settings_no_change
            ),
            "port_settings_no_change_ok_close_executed": False,
            "port_settings_no_change_ok_close_verified": False,
            "port_settings_dialog_completion_verified": False,
            "port_settings_edit_executed": False,
            "port_settings_apply_changed_settings_executed": False,
            "errors": [],
            "captures": [],
        }
        cleanup_results: list[dict[str, Any]] = []
        try:
            open_attempt_summaries: list[dict[str, Any]] = []
            open_result: dict[str, Any] | None = None
            scratch_project: Path | None = None
            active_pids: list[int] = []
            for attempt in range(1, open_attempts + 1):
                attempt_dir = gui_open_attempt_dir(command_name, attempt)
                command_result["gui_open_short_scratch_base"] = str(gui_open_short_base) if gui_open_short_base else None
                current_open_result = project_gui_open_probe(
                    {
                        "project_path": str(source),
                        "scratch_dir": str(attempt_dir),
                        "allow_safe_runtime": True,
                        "wait_seconds": wait_seconds,
                        "open_wait_seconds": open_wait_seconds,
                        "post_open_idle_wait_seconds": post_open_idle_wait_seconds,
                        "screenshot": screenshot_enabled,
                        "cleanup_launched_process": False,
                        "dismiss_post_open_information_dialogs": dismiss_post_open_dialogs,
                    }
                )
                scratch_project_value = (current_open_result.get("scratch_copy") or {}).get("path")
                current_scratch_project = Path(str(scratch_project_value)).resolve() if scratch_project_value else None
                current_active_pids = active_pids_after_open(current_open_result)
                current_opened_candidates = (
                    opened_project_window_candidates(current_active_pids, current_scratch_project)
                    if current_scratch_project and current_scratch_project.exists() and current_active_pids
                    else []
                )
                open_attempt_summaries.append(
                    {
                        "attempt": attempt,
                        "scratch_dir": str(attempt_dir),
                        "ok": current_open_result.get("ok"),
                        "gui_open_completed": current_open_result.get("gui_open_completed"),
                        "project_model_loaded_in_gui_claimed": current_open_result.get("project_model_loaded_in_gui_claimed"),
                        "error": current_open_result.get("error"),
                        "scratch_copy": current_open_result.get("scratch_copy"),
                        "active_programrelayfbd_pids": current_active_pids,
                        "opened_project_window_candidate_count": len(current_opened_candidates),
                        "process_exited_after_open": current_open_result.get("process_exited_after_open"),
                        "open_dialogs_after_enter_count": len(current_open_result.get("open_dialogs_after_enter") or []),
                        "open_dialogs_after_post_open_idle_count": len(current_open_result.get("open_dialogs_after_post_open_idle") or []),
                    }
                )
                if (
                    current_scratch_project
                    and current_scratch_project.exists()
                    and current_active_pids
                    and bool(current_open_result.get("gui_open_completed"))
                ):
                    open_result = current_open_result
                    scratch_project = current_scratch_project
                    active_pids = current_active_pids
                    break
                cleanup_results.extend(cleanup_new_processes())
            if open_result is None:
                cleanup_results.extend(cleanup_new_processes())
                time.sleep(2.0)
                direct_dir = gui_open_attempt_dir(command_name, open_attempts + 1)
                scratch = project_scratch_copy(
                    {
                        "project_path": str(source),
                        "scratch_dir": str(direct_dir),
                        "name_suffix": "_device_menu_probe",
                    }
                )
                direct_scratch_project = Path(str(scratch["scratch_copy"]["path"])).resolve()
                launch = launch_owen_logic({"project_path": str(direct_scratch_project), "wait_seconds": wait_seconds})
                launched_pid = int(launch["pid"])
                if process_is_running(launched_pid):
                    wait_for_lifecycle_idle(launched_pid, post_open_idle_wait_seconds)
                windows_after_idle = enum_windows(pid=launched_pid, owen_only=False) if process_is_running(launched_pid) else []
                post_open_dismissal_result = None
                if dismiss_post_open_dialogs and process_is_running(launched_pid):
                    if select_post_open_information_dialog(windows_after_idle):
                        post_open_dismissal_result = dismiss_post_open_information_dialogs(
                            launched_pid,
                            command_screenshot_dir,
                            screenshot_enabled,
                        )
                        time.sleep(0.5)
                direct_active_pids = [
                    current_pid
                    for current_pid in sorted(programrelay_pids() - baseline_pids)
                    if process_is_running(current_pid)
                ]
                windows_after_dialog_dismiss = {
                    str(current_pid): enum_windows(pid=current_pid, owen_only=False)
                    for current_pid in direct_active_pids
                }
                open_dialogs_after_dialog_dismiss = [
                    window
                    for windows in windows_after_dialog_dismiss.values()
                    for window in windows
                    if str(window.get("class_name") or "").lower() == "#32770"
                ]
                direct_opened_candidates = opened_project_window_candidates(direct_active_pids, direct_scratch_project)
                residual_dialog_dismissals: list[dict[str, Any]] = []
                if direct_opened_candidates and open_dialogs_after_dialog_dismiss:
                    for dialog in open_dialogs_after_dialog_dismiss[:4]:
                        dismissal: dict[str, Any] = {
                            "window_before": compact_window(dialog),
                            "escape_sent": None,
                        }
                        try:
                            focus_window(
                                {
                                    "pid": int(dialog.get("pid") or launched_pid),
                                    "hwnd": int(dialog.get("hwnd") or 0),
                                    "owen_only": False,
                                }
                            )
                            dismissal["escape_sent"] = send_raw_hotkey(["ESC"], wait_seconds=0.4)
                            time.sleep(0.4)
                        except Exception as exc:
                            dismissal["error"] = str(exc)
                        residual_dialog_dismissals.append(dismissal)
                    direct_active_pids = [
                        current_pid
                        for current_pid in sorted(programrelay_pids() - baseline_pids)
                        if process_is_running(current_pid)
                    ]
                    windows_after_dialog_dismiss = {
                        str(current_pid): enum_windows(pid=current_pid, owen_only=False)
                        for current_pid in direct_active_pids
                    }
                    open_dialogs_after_dialog_dismiss = [
                        window
                        for windows in windows_after_dialog_dismiss.values()
                        for window in windows
                        if str(window.get("class_name") or "").lower() == "#32770"
                    ]
                    direct_opened_candidates = opened_project_window_candidates(direct_active_pids, direct_scratch_project)
                dismissed_count = 0
                if isinstance(post_open_dismissal_result, dict):
                    dismissed_count = sum(
                        1
                        for row in post_open_dismissal_result.get("dismissals", [])
                        if row.get("dismissed_after_confirm_click")
                        or row.get("dismissed_after_enter")
                        or row.get("dismissed_after_escape")
                    )
                direct_completed = bool(
                    direct_scratch_project.exists()
                    and direct_active_pids
                    and direct_opened_candidates
                    and not open_dialogs_after_dialog_dismiss
                )
                open_result = {
                    "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
                    "ok": direct_completed,
                    "open_method": "direct_project_launch_fallback_after_file_open_attempts",
                    "launch": launch,
                    "scratch_copy": safe_file_info(direct_scratch_project, include_hash=True),
                    "gui_open_completed": direct_completed,
                    "project_model_loaded_in_gui_claimed": direct_completed,
                    "post_open_information_dialogs_dismissed_count": dismissed_count,
                    "post_open_information_dialog_dismissal_result": post_open_dismissal_result,
                    "programrelayfbd_pids_after_open": direct_active_pids,
                    "programrelayfbd_pids_after_post_open_dialog_dismiss": direct_active_pids,
                    "windows_by_pid_after_post_open_dialog_dismiss": windows_after_dialog_dismiss,
                    "remaining_dialogs_after_dialog_dismiss": open_dialogs_after_dialog_dismiss,
                    "residual_dialog_dismissals": residual_dialog_dismissals,
                    "opened_project_window_candidates": [
                        {
                            "pid": candidate.get("pid"),
                            "hwnd": candidate.get("hwnd"),
                            "score": candidate.get("score"),
                            "title_matches_scratch_path": candidate.get("title_matches_scratch_path"),
                            "title_matches_scratch_name": candidate.get("title_matches_scratch_name"),
                            "area": candidate.get("area"),
                            "window": compact_window(candidate.get("window")),
                        }
                        for candidate in direct_opened_candidates[:10]
                    ],
                    "screenshot_dir": str(command_screenshot_dir),
                }
                open_attempt_summaries.append(
                    {
                        "attempt": "direct_launch_fallback",
                        "scratch_dir": str(direct_dir),
                        "ok": open_result.get("ok"),
                        "gui_open_completed": open_result.get("gui_open_completed"),
                        "project_model_loaded_in_gui_claimed": open_result.get("project_model_loaded_in_gui_claimed"),
                        "error": open_result.get("error"),
                        "scratch_copy": open_result.get("scratch_copy"),
                        "active_programrelayfbd_pids": direct_active_pids,
                        "opened_project_window_candidate_count": len(direct_opened_candidates),
                        "process_exited_after_open": launched_pid not in programrelay_pids(),
                        "residual_dialog_dismissal_count": len(residual_dialog_dismissals),
                        "open_dialogs_after_enter_count": 0,
                        "open_dialogs_after_post_open_idle_count": len(open_dialogs_after_dialog_dismiss),
                    }
                )
                if direct_completed:
                    scratch_project = direct_scratch_project
                    active_pids = direct_active_pids
            command_result["open_attempts"] = open_attempts
            command_result["open_attempt_summaries"] = open_attempt_summaries
            if not scratch_project or not scratch_project.exists() or not open_result:
                raise RuntimeError(
                    "GUI open probe did not return an existing scratch project path: "
                    + json.dumps(json_safe_value(open_attempt_summaries), ensure_ascii=False)
                )
            if not active_pids:
                raise RuntimeError(
                    "No OWEN Logic PID remained after File > Open: "
                    + json.dumps(json_safe_value(open_attempt_summaries), ensure_ascii=False)
                )
            scratch_hash_before_command = sha256_file(scratch_project)
            static_validation_before = project_validate({"project_path": str(scratch_project), "include_warnings": True})
            command_result["open_probe_summary"] = {
                "ok": open_result.get("ok"),
                "gui_open_completed": open_result.get("gui_open_completed"),
                "project_model_loaded_in_gui_claimed": open_result.get("project_model_loaded_in_gui_claimed"),
                "post_open_information_dialogs_dismissed_count": open_result.get(
                    "post_open_information_dialogs_dismissed_count"
                ),
                "remaining_dialogs_after_dialog_dismiss": open_result.get("remaining_dialogs_after_dialog_dismiss"),
                "scratch_copy": open_result.get("scratch_copy"),
                "screenshot_dir": open_result.get("screenshot_dir"),
            }
            command_result["scratch_copy"] = safe_file_info(scratch_project, include_hash=True)
            command_result["active_programrelayfbd_pids_after_open"] = active_pids
            opened_candidates = opened_project_window_candidates(active_pids, scratch_project)
            command_result["opened_project_window_candidates"] = [
                {
                    "pid": candidate.get("pid"),
                    "hwnd": candidate.get("hwnd"),
                    "score": candidate.get("score"),
                    "title_matches_scratch_path": candidate.get("title_matches_scratch_path"),
                    "title_matches_scratch_name": candidate.get("title_matches_scratch_name"),
                    "area": candidate.get("area"),
                    "window": compact_window(candidate.get("window")),
                }
                for candidate in opened_candidates[:10]
            ]
            selected_candidate = opened_candidates[0] if opened_candidates else None
            if selected_candidate and int(selected_candidate.get("score") or 0) > 0:
                main_window = selected_candidate["window"]
                pid = int(selected_candidate["pid"])
                focus = focus_window({"pid": pid, "hwnd": int(main_window["hwnd"]), "owen_only": False})
                main_window = focus.get("window") or main_window
            else:
                pid = int(active_pids[0])
                focus = focus_window({"pid": pid, "owen_only": False})
                main_window = focus.get("window") or select_window({"pid": pid, "owen_only": False}, owen_only=False)
            time.sleep(0.5)
            refreshed_candidates = opened_project_window_candidates(active_pids, scratch_project)
            command_result["opened_project_window_candidates_after_focus_delay"] = [
                {
                    "pid": candidate.get("pid"),
                    "hwnd": candidate.get("hwnd"),
                    "score": candidate.get("score"),
                    "title_matches_scratch_path": candidate.get("title_matches_scratch_path"),
                    "title_matches_scratch_name": candidate.get("title_matches_scratch_name"),
                    "area": candidate.get("area"),
                    "window": compact_window(candidate.get("window")),
                }
                for candidate in refreshed_candidates[:10]
            ]
            refreshed_candidate = refreshed_candidates[0] if refreshed_candidates else None
            if refreshed_candidate and int(refreshed_candidate.get("score") or 0) > 0:
                main_window = refreshed_candidate["window"]
                pid = int(refreshed_candidate["pid"])
                try:
                    refreshed_focus = focus_window({"pid": pid, "hwnd": int(main_window["hwnd"]), "owen_only": False})
                    command_result["focus_after_project_window_refresh"] = {
                        "foreground_matches_target": refreshed_focus.get("foreground_matches_target"),
                        "window": compact_window(refreshed_focus.get("window") or main_window),
                    }
                    main_window = refreshed_focus.get("window") or main_window
                except Exception as exc:
                    command_result["focus_after_project_window_refresh_error"] = str(exc)
            command_result["pid"] = pid
            main_hwnd = int(main_window["hwnd"])

            def refresh_main_window_handle(reason: str) -> dict[str, Any]:
                nonlocal pid, main_window, main_hwnd
                refresh: dict[str, Any] = {
                    "reason": reason,
                    "previous": compact_window(main_window),
                    "previous_hwnd": main_hwnd,
                }
                try:
                    live_window = window_info_from_hwnd(main_hwnd)
                    rect_value = live_window.get("rect") or {}
                    area = int(rect_value.get("width") or 0) * int(rect_value.get("height") or 0)
                    if bool(live_window.get("visible")) and area > 0:
                        main_window = live_window
                        pid = int(live_window.get("pid") or pid)
                        main_hwnd = int(live_window["hwnd"])
                        refresh["source"] = "existing_hwnd"
                except Exception as exc:
                    refresh["existing_hwnd_error"] = str(exc)

                if not refresh.get("source"):
                    try:
                        candidates = opened_project_window_candidates(active_pids, scratch_project)
                        refresh["opened_project_window_candidates"] = [
                            {
                                "pid": candidate.get("pid"),
                                "hwnd": candidate.get("hwnd"),
                                "score": candidate.get("score"),
                                "title_matches_scratch_path": candidate.get("title_matches_scratch_path"),
                                "title_matches_scratch_name": candidate.get("title_matches_scratch_name"),
                                "area": candidate.get("area"),
                                "window": compact_window(candidate.get("window")),
                            }
                            for candidate in candidates[:10]
                        ]
                        candidate = candidates[0] if candidates else None
                        if candidate and int(candidate.get("score") or 0) > 0:
                            main_window = candidate["window"]
                            pid = int(candidate["pid"])
                            main_hwnd = int(main_window["hwnd"])
                            refresh["source"] = "project_window_candidate"
                    except Exception as exc:
                        refresh["opened_project_window_candidates_error"] = str(exc)

                if not refresh.get("source"):
                    fallback_windows: list[dict[str, Any]] = []
                    for candidate_pid in dict.fromkeys([pid, *active_pids]):
                        try:
                            fallback_windows.extend(enum_windows(pid=int(candidate_pid), owen_only=False))
                        except Exception:
                            continue
                    fallback_windows = [
                        window
                        for window in fallback_windows
                        if bool(window.get("visible"))
                        and int((window.get("rect") or {}).get("width") or 0) > 0
                        and int((window.get("rect") or {}).get("height") or 0) > 0
                    ]
                    fallback_windows.sort(
                        key=lambda window: -(
                            int((window.get("rect") or {}).get("width") or 0)
                            * int((window.get("rect") or {}).get("height") or 0)
                        )
                    )
                    refresh["fallback_windows"] = [compact_window(window) for window in fallback_windows[:10]]
                    if fallback_windows:
                        main_window = fallback_windows[0]
                        pid = int(main_window.get("pid") or pid)
                        main_hwnd = int(main_window["hwnd"])
                        refresh["source"] = "largest_visible_window"

                if refresh.get("source"):
                    try:
                        focus_after_refresh = focus_window({"pid": pid, "hwnd": main_hwnd, "owen_only": False})
                        main_window = focus_after_refresh.get("window") or main_window
                        refresh["focus"] = {
                            "foreground_matches_target": focus_after_refresh.get("foreground_matches_target"),
                            "window": compact_window(main_window),
                        }
                    except Exception as exc:
                        refresh["focus_error"] = str(exc)
                    refresh["selected"] = compact_window(main_window)
                    refresh["selected_hwnd"] = main_hwnd
                    refresh["selected_pid"] = pid
                else:
                    refresh["error"] = "No visible OWEN project window could be selected."
                return refresh

            command_result.setdefault("main_window_handle_refreshes", []).append(
                refresh_main_window_handle("before_device_menu_capture")
            )
            command_result["pid"] = pid
            command_result["focus_before_device_menu"] = {
                "foreground_matches_target": focus.get("foreground_matches_target"),
                "window": compact_window(main_window),
            }
            command_result["main_window"] = compact_window(main_window)
            command_result["main_hwnd"] = main_hwnd
            command_result["captures"].append(
                capture_window(
                    pid,
                    main_hwnd,
                    f"{command_name}_main_before_device_menu",
                    command_screenshot_dir,
                    command_ui_dir,
                )
            )
            rect = main_window["rect"]

            def main_menu_pane_click_points() -> list[dict[str, Any]]:
                points: list[dict[str, Any]] = []
                try:
                    snapshot = ui_automation_snapshot(
                        {
                            "pid": pid,
                            "hwnd": main_hwnd,
                            "owen_only": False,
                            "max_depth": 4,
                            "max_children": 1000,
                            "include_offscreen": False,
                            "timeout_seconds": 30,
                        }
                    )
                    tree = snapshot.get("ui_tree") if isinstance(snapshot.get("ui_tree"), dict) else {}
                    controls = flatten_ui_tree(tree) if isinstance(tree, dict) else []
                    for control in controls:
                        if control.get("name") != "Главное меню":
                            continue
                        bounds = control.get("bounding_rect") or {}
                        x = int(float(bounds.get("x") or 0))
                        y = int(float(bounds.get("y") or 0))
                        width = int(float(bounds.get("width") or 0))
                        height = int(float(bounds.get("height") or 0))
                        if width <= 0 or height <= 0:
                            continue
                        points.append(
                            {
                                "method": "uia_main_menu_pane",
                                "control": {
                                    "name": control.get("name"),
                                    "automation_id": control.get("automation_id"),
                                    "class_name": control.get("class_name"),
                                    "control_type": control.get("control_type"),
                                    "bounding_rect": bounds,
                                },
                                "x": x + 90,
                                "y": y + max(4, height // 2),
                            }
                        )
                        break
                except Exception as exc:
                    command_result["main_menu_pane_lookup_error"] = str(exc)
                return points

            device_menu_attempts: list[dict[str, Any]] = []
            popup = None
            click_points = main_menu_pane_click_points()
            click_points.extend(
                {
                    "method": "window_relative",
                    "offset": {"x": offset[0], "y": offset[1]},
                    "x": int(rect["left"]) + int(offset[0]),
                    "y": int(rect["top"]) + int(offset[1]),
                }
                for offset in ((90, 41), (100, 41), (112, 41), (118, 42), (106, 42))
            )
            for attempt_index, point in enumerate(click_points, start=1):
                try:
                    focus_window({"pid": pid, "hwnd": main_hwnd, "owen_only": False})
                except Exception:
                    pass
                click = mouse_click_screen(int(point["x"]), int(point["y"]), wait_seconds=0.7)
                popup = wait_for_device_popup(pid)
                menu_window_sample = menu_popup_debug_windows(pid)
                device_menu_attempts.append(
                    {
                        "attempt": attempt_index,
                        "method": point.get("method"),
                        "offset": point.get("offset"),
                        "point": {"x": point.get("x"), "y": point.get("y")},
                        "control": point.get("control"),
                        "click": click,
                        "popup_detected": popup is not None,
                        "popup_window": compact_window(popup),
                        "menu_window_sample_after_click": menu_window_sample,
                    }
                )
                if popup is not None:
                    break
                try:
                    send_raw_hotkey(["ESC"], wait_seconds=0.2)
                except Exception:
                    pass
            if popup is None:
                try:
                    focus_window({"pid": pid, "hwnd": main_hwnd, "owen_only": False})
                except Exception:
                    pass
                keyboard_steps: list[dict[str, Any]] = []
                for keys in (["ALT"], ["RIGHT"], ["RIGHT"], ["DOWN"]):
                    try:
                        keyboard_steps.append(send_raw_hotkey(keys, wait_seconds=0.35))
                    except Exception as exc:
                        keyboard_steps.append({"sent": keys, "error": str(exc)})
                        break
                popup = wait_for_device_popup(pid)
                device_menu_attempts.append(
                    {
                        "attempt": len(device_menu_attempts) + 1,
                        "method": "keyboard_menu_navigation",
                        "sequence": [["ALT"], ["RIGHT"], ["RIGHT"], ["DOWN"]],
                        "steps": keyboard_steps,
                        "popup_detected": popup is not None,
                        "popup_window": compact_window(popup),
                        "menu_window_sample_after_navigation": menu_popup_debug_windows(pid),
                    }
                )
            if popup is None:
                for hotkey_attempt, keys in enumerate((["ALT", "\u041f"], ["ALT", "P"]), start=1):
                    try:
                        focus_window({"pid": pid, "hwnd": main_hwnd, "owen_only": False})
                    except Exception:
                        pass
                    try:
                        sent = send_raw_hotkey(keys, wait_seconds=0.7)
                    except Exception as exc:
                        sent = {"error": str(exc), "sent": keys}
                    popup = wait_for_device_popup(pid)
                    device_menu_attempts.append(
                        {
                            "attempt": len(device_menu_attempts) + 1,
                            "method": "hotkey",
                            "hotkey_attempt": hotkey_attempt,
                            "keys": keys,
                            "hotkey": sent,
                            "popup_detected": popup is not None,
                            "popup_window": compact_window(popup),
                            "menu_window_sample_after_hotkey": menu_popup_debug_windows(pid),
                        }
                    )
                    if popup is not None:
                        break
                    try:
                        send_raw_hotkey(["ESC"], wait_seconds=0.2)
                    except Exception:
                        pass
            command_result["device_menu_click_attempts"] = device_menu_attempts
            command_result["device_menu_popup_window"] = compact_window(popup)
            if popup is None and command_name in {"variable_table", "port_settings"}:
                shortcut_keys = ["CTRL", "SHIFT", "V"] if command_name == "variable_table" else ["CTRL", "SHIFT", "S"]
                try:
                    focus_window({"pid": pid, "hwnd": main_hwnd, "owen_only": False})
                except Exception:
                    pass
                command_result["device_menu_shortcut_fallback"] = {
                    "used": True,
                    "reason": "device_menu_popup_not_detected",
                    "shortcut": "Ctrl+Shift+V" if command_name == "variable_table" else "Ctrl+Shift+S",
                    "keys": shortcut_keys,
                    "invocation": send_hotkey(
                        {
                            "pid": pid,
                            "hwnd": main_hwnd,
                            "keys": shortcut_keys,
                            "delay_ms": max(200, int(command_wait_seconds * 1000)),
                            "owen_only": False,
                        }
                    ),
                }
                time.sleep(max(0.5, command_wait_seconds))
                windows_after = enum_windows(pid=pid, owen_only=False)
            else:
                if popup is None:
                    raise RuntimeError("Device menu popup was not detected")
                popup_hwnd = int(popup["hwnd"])
                command_result["captures"].append(
                    capture_window(pid, popup_hwnd, f"{command_name}_device_menu_popup", command_screenshot_dir, command_ui_dir)
                )
                popup_rect = popup.get("rect") or {}
                click_offset = command_meta["popup_click_offset"]
                command_result["menu_item_click"] = mouse_click_screen(
                    int(popup_rect.get("left") or 0) + int(click_offset["x"]),
                    int(popup_rect.get("top") or 0) + int(click_offset["y"]),
                    wait_seconds=command_wait_seconds,
                )
                windows_after = enum_windows(pid=pid, owen_only=False)
            command_result["windows_after_menu_item_click"] = [compact_window(window) for window in windows_after]
            foreground_hwnd = None
            if user32 is not None:
                try:
                    foreground_hwnd = int(user32.GetForegroundWindow())
                    command_result["foreground_after_click"] = compact_window(window_info_from_hwnd(foreground_hwnd))
                except Exception as exc:
                    command_result["foreground_after_click_error"] = str(exc)
            hwnds: list[int] = []
            for candidate_hwnd in (foreground_hwnd, main_hwnd):
                if candidate_hwnd and int(candidate_hwnd) not in hwnds:
                    hwnds.append(int(candidate_hwnd))
            windows_by_area = sorted(
                windows_after,
                key=lambda window: -int((window.get("rect") or {}).get("width") or 0)
                * int((window.get("rect") or {}).get("height") or 0),
            )
            for window in windows_by_area:
                if not bool(window.get("visible")):
                    continue
                hwnd = int(window.get("hwnd") or 0)
                rect_value = window.get("rect") or {}
                area = int(rect_value.get("width") or 0) * int(rect_value.get("height") or 0)
                if hwnd and hwnd not in hwnds and area >= 12000:
                    hwnds.append(hwnd)
                if len(hwnds) >= 5:
                    break
            command_result["captured_hwnds_after_click"] = hwnds
            for hwnd in hwnds:
                command_result["captures"].append(
                    capture_window(
                        pid,
                        hwnd,
                        f"{command_name}_after_click_hwnd_{hwnd}",
                        command_screenshot_dir,
                        command_ui_dir,
                    )
                )
            if command_name == "port_settings" and allow_port_settings_ok_close:
                port_close_record: dict[str, Any] = {
                    "requested": True,
                    "confirm_port_settings_no_change": confirm_port_settings_no_change,
                    "target_hwnd": None,
                    "target_reason": None,
                    "target_window_before": None,
                    "focus_before_ok": None,
                    "ok_button_click": None,
                    "dialog_closed": False,
                    "edit_executed": False,
                    "apply_changed_settings_executed": False,
                }
                target_hwnd: int | None = None
                target_reason = None
                for candidate_hwnd in hwnds:
                    if int(candidate_hwnd) != int(main_hwnd):
                        target_hwnd = int(candidate_hwnd)
                        target_reason = "captured_non_main_hwnd_after_port_settings_click"
                        break
                if target_hwnd is None and foreground_hwnd and int(foreground_hwnd) != int(main_hwnd):
                    target_hwnd = int(foreground_hwnd)
                    target_reason = "foreground_hwnd_after_port_settings_click"
                if target_hwnd is None:
                    for window in windows_by_area:
                        hwnd = int(window.get("hwnd") or 0)
                        if hwnd and hwnd != int(main_hwnd) and bool(window.get("visible")):
                            target_hwnd = hwnd
                            target_reason = "largest_visible_non_main_window_after_port_settings_click"
                            break
                port_close_record["target_hwnd"] = target_hwnd
                port_close_record["target_reason"] = target_reason
                if target_hwnd is None:
                    command_result["port_settings_ok_close"] = port_close_record
                    raise RuntimeError("allow_port_settings_ok_close=true, but no port-settings dialog hwnd was detected")
                try:
                    target_window_before = compact_window(window_info_from_hwnd(int(target_hwnd)))
                    port_close_record["target_window_before"] = target_window_before
                except Exception as exc:
                    port_close_record["target_window_before_error"] = str(exc)
                try:
                    port_close_record["focus_before_ok"] = focus_window(
                        {"pid": pid, "hwnd": int(target_hwnd), "owen_only": False}
                    )
                except Exception as exc:
                    port_close_record["focus_before_ok_error"] = str(exc)
                port_close_record["ok_button_click"] = click_dialog_ok_button(
                    pid,
                    int(target_hwnd),
                    port_settings_ok_wait_seconds,
                )
                port_close_record["dialog_closed"] = bool(
                    (port_close_record.get("ok_button_click") or {}).get("dialog_closed_after_click")
                )
                command_result["port_settings_ok_close"] = port_close_record
                command_result["port_settings_no_change_ok_close_executed"] = bool(
                    (port_close_record.get("ok_button_click") or {}).get("clicked")
                    and port_close_record["dialog_closed"]
                )
                command_result["port_settings_dialog_completion_verified"] = bool(
                    command_result["port_settings_no_change_ok_close_executed"]
                )
                if not command_result["port_settings_no_change_ok_close_executed"]:
                    raise RuntimeError("Port-settings OK/no-change close did not click OK and close the dialog")
            if command_name == "variable_table" and variable_table_toolbar_actions:
                target_hwnd: int | None = None
                target_reason = None
                for candidate_hwnd in hwnds:
                    if int(candidate_hwnd) != int(main_hwnd):
                        target_hwnd = int(candidate_hwnd)
                        target_reason = "captured_non_main_hwnd_after_variable_table_click"
                        break
                if target_hwnd is None and foreground_hwnd and int(foreground_hwnd) != int(main_hwnd):
                    target_hwnd = int(foreground_hwnd)
                    target_reason = "foreground_hwnd_after_variable_table_click"
                if target_hwnd is None:
                    for window in windows_by_area:
                        hwnd = int(window.get("hwnd") or 0)
                        if hwnd and hwnd != int(main_hwnd) and bool(window.get("visible")):
                            target_hwnd = hwnd
                            target_reason = "largest_visible_non_main_window_after_variable_table_click"
                            break
                if target_hwnd is None:
                    try:
                        focus_window({"pid": pid, "hwnd": main_hwnd, "owen_only": False})
                    except Exception:
                        pass
                    shortcut_fallback = send_hotkey(
                        {
                            "pid": pid,
                            "hwnd": main_hwnd,
                            "keys": ["CTRL", "SHIFT", "V"],
                            "delay_ms": max(200, int(command_wait_seconds * 1000)),
                            "owen_only": False,
                        }
                    )
                    time.sleep(max(0.5, command_wait_seconds))
                    windows_after_shortcut = enum_windows(pid=pid, owen_only=False)
                    foreground_after_shortcut = None
                    if user32 is not None:
                        try:
                            foreground_after_shortcut = int(user32.GetForegroundWindow())
                        except Exception:
                            foreground_after_shortcut = None
                    command_result["variable_table_toolbar_shortcut_open_fallback"] = {
                        "shortcut": "Ctrl+Shift+V",
                        "invocation": shortcut_fallback,
                        "foreground_hwnd": foreground_after_shortcut,
                        "windows_after_shortcut": [compact_window(window) for window in windows_after_shortcut],
                    }
                    if foreground_after_shortcut and int(foreground_after_shortcut) != int(main_hwnd):
                        target_hwnd = int(foreground_after_shortcut)
                        target_reason = "foreground_hwnd_after_ctrl_shift_v_fallback"
                    if target_hwnd is None:
                        for window in sorted(
                            windows_after_shortcut,
                            key=lambda item: -int((item.get("rect") or {}).get("width") or 0)
                            * int((item.get("rect") or {}).get("height") or 0),
                        ):
                            hwnd = int(window.get("hwnd") or 0)
                            if hwnd and hwnd != int(main_hwnd) and bool(window.get("visible")):
                                target_hwnd = hwnd
                                target_reason = "largest_visible_non_main_window_after_ctrl_shift_v_fallback"
                                break
                if target_hwnd is None:
                    raise RuntimeError("Variable-table toolbar action requested, but no variable-table dialog hwnd was detected")
                command_result["variable_table_toolbar_action_target_hwnd"] = target_hwnd
                command_result["variable_table_toolbar_action_target_reason"] = target_reason
                variable_table_target_tab_selection: dict[str, Any] | None = None
                if variable_table_target_tab_name:
                    variable_table_target_tab_selection = select_variable_table_target_tab(
                        pid,
                        target_hwnd,
                        command_screenshot_dir,
                        command_ui_dir,
                    )
                    command_result["variable_table_target_tab_selection"] = variable_table_target_tab_selection
                    command_result["variable_table_target_tab_selected"] = bool(
                        variable_table_target_tab_selection.get("selected")
                    )
                    if require_variable_table_target_tab and not command_result["variable_table_target_tab_selected"]:
                        raise RuntimeError(
                            f"Required variable-table target tab was not selected: {variable_table_target_tab_name}"
                        )
                toolbar_action_records: list[dict[str, Any]] = []
                for action_name in variable_table_toolbar_actions:
                    action_meta = VARIABLE_TABLE_TOOLBAR_ACTIONS[action_name]
                    click_offset = action_meta["dialog_relative_click"]
                    action_record: dict[str, Any] = {
                        "action": action_name,
                        "description": action_meta.get("description"),
                        "target_hwnd": target_hwnd,
                        "target_reason": target_reason,
                        "dialog_relative_click": click_offset,
                        "expected_dialog_kind": action_meta.get("expected_dialog_kind"),
                        "csv_dialog_surface_only": bool(action_meta.get("csv_dialog_surface_only", False)),
                        "clicked": False,
                        "target_tab_selection": variable_table_target_tab_selection,
                        "commit_executed": False,
                        "save_executed": False,
                        "csv_import_commit_requested": bool(
                            action_name == "csv_import_dialog" and allow_gui_csv_import_commit
                        ),
                        "csv_import_export_executed": False,
                        "csv_import_completed": False,
                        "csv_import_marker_visible": False,
                        "csv_import_marker_persisted_in_scratch_model": False,
                        "csv_export_completed": False,
                    }
                    try:
                        target_before = compact_window(window_info_from_hwnd(target_hwnd))
                        action_record["target_window_before"] = target_before
                        action_record["capture_before"] = capture_window(
                            pid,
                            target_hwnd,
                            f"{command_name}_toolbar_{action_name}_before",
                            command_screenshot_dir,
                            command_ui_dir,
                        )
                        target_rect = (target_before or {}).get("rect") or {}
                        if not target_rect:
                            raise RuntimeError(f"Cannot resolve target window rect for toolbar action {action_name}")
                        action_record["click"] = mouse_click_screen(
                            int(target_rect.get("left") or 0) + int(click_offset["x"]),
                            int(target_rect.get("top") or 0) + int(click_offset["y"]),
                            wait_seconds=max(0.5, command_wait_seconds),
                        )
                        action_record["clicked"] = True
                        after_action_windows = enum_windows(pid=pid, owen_only=False)
                        action_record["windows_after_action"] = [
                            compact_window(window) for window in after_action_windows
                        ]
                        foreground_after_action = None
                        if user32 is not None:
                            try:
                                foreground_after_action = int(user32.GetForegroundWindow())
                                action_record["foreground_after_action"] = compact_window(
                                    window_info_from_hwnd(foreground_after_action)
                                )
                            except Exception as exc:
                                action_record["foreground_after_action_error"] = str(exc)
                        csv_action_windows = classify_csv_action_windows(
                            after_action_windows,
                            main_hwnd,
                            target_hwnd,
                        )
                        dialog_candidates_after_action = list(csv_action_windows["file_dialogs"])
                        action_record["dialog_candidates_after_action"] = dialog_candidates_after_action
                        action_record["toolbar_dropdown_candidates_after_action"] = csv_action_windows["toolbar_dropdowns"]
                        action_record["other_dialog_like_windows_after_action"] = csv_action_windows[
                            "other_dialog_like_windows"
                        ]
                        if action_record["csv_dialog_surface_only"]:
                            action_record["csv_import_export_dialog_surface_probed"] = bool(
                                dialog_candidates_after_action or csv_action_windows["toolbar_dropdowns"]
                            )
                            action_record["csv_import_export_executed"] = False
                        if (
                            action_name in {"csv_import_dialog", "csv_export_dialog"}
                            and not dialog_candidates_after_action
                            and csv_action_windows["toolbar_dropdowns"]
                        ):
                            dropdown = csv_action_windows["toolbar_dropdowns"][0]
                            dropdown_rect = dropdown.get("rect") or {}
                            dropdown_x = int(dropdown_rect.get("left") or 0) + max(
                                10,
                                int((dropdown_rect.get("width") or 0) * 0.55),
                            )
                            dropdown_y = int(dropdown_rect.get("top") or 0) + max(
                                8,
                                int((dropdown_rect.get("height") or 0) * 0.65),
                            )
                            action_record["csv_toolbar_dropdown_click"] = mouse_click_screen(
                                dropdown_x,
                                dropdown_y,
                                wait_seconds=max(0.5, command_wait_seconds),
                            )
                            windows_after_dropdown_click = enum_windows(pid=pid, owen_only=False)
                            action_record["windows_after_dropdown_click"] = [
                                compact_window(window) for window in windows_after_dropdown_click
                            ]
                            csv_windows_after_dropdown = classify_csv_action_windows(
                                windows_after_dropdown_click,
                                main_hwnd,
                                target_hwnd,
                            )
                            action_record["dialog_candidates_after_dropdown_click"] = csv_windows_after_dropdown[
                                "file_dialogs"
                            ]
                            action_record["toolbar_dropdown_candidates_after_dropdown_click"] = (
                                csv_windows_after_dropdown["toolbar_dropdowns"]
                            )
                            if csv_windows_after_dropdown["file_dialogs"]:
                                dialog_candidates_after_action = list(csv_windows_after_dropdown["file_dialogs"])
                                action_record["dialog_candidates_after_action"] = dialog_candidates_after_action
                        after_action_hwnds: list[int] = [target_hwnd]
                        if (
                            foreground_after_action
                            and int(foreground_after_action) not in after_action_hwnds
                            and int(foreground_after_action) != int(main_hwnd)
                        ):
                            after_action_hwnds.append(int(foreground_after_action))
                        for window in sorted(
                            after_action_windows,
                            key=lambda item: -int((item.get("rect") or {}).get("width") or 0)
                            * int((item.get("rect") or {}).get("height") or 0),
                        ):
                            hwnd = int(window.get("hwnd") or 0)
                            rect_value = window.get("rect") or {}
                            area = int(rect_value.get("width") or 0) * int(rect_value.get("height") or 0)
                            if (
                                hwnd
                                and hwnd not in after_action_hwnds
                                and hwnd != int(main_hwnd)
                                and bool(window.get("visible"))
                                and area >= 8000
                            ):
                                after_action_hwnds.append(hwnd)
                            if len(after_action_hwnds) >= 4:
                                break
                        action_record["captured_hwnds_after_action"] = after_action_hwnds
                        action_record["captures_after"] = [
                            capture_window(
                                pid,
                                hwnd,
                                f"{command_name}_toolbar_{action_name}_after_hwnd_{hwnd}",
                                command_screenshot_dir,
                                command_ui_dir,
                            )
                            for hwnd in after_action_hwnds
                        ]
                        if action_name == "csv_import_dialog" and allow_gui_csv_import:
                            if not csv_import_source:
                                raise RuntimeError("GUI CSV import source was not resolved")
                            if not dialog_candidates_after_action:
                                raise RuntimeError("GUI CSV import was allowed, but no Open dialog candidate was detected")
                            import_dialog = dialog_candidates_after_action[0]
                            import_dialog_kind = csv_file_dialog_kind(import_dialog)
                            action_record["csv_import_dialog_kind"] = import_dialog_kind
                            if import_dialog_kind == "save":
                                raise RuntimeError(
                                    "GUI CSV import expected an Open dialog, but OWEN Logic opened a Save dialog"
                                )
                            action_record["csv_import_source_path"] = str(csv_import_source)
                            action_record["csv_import_marker"] = csv_import_marker
                            action_record["csv_import_filename_fill"] = fill_file_dialog_filename_with_clipboard(
                                import_dialog,
                                csv_import_source,
                                command_screenshot_dir,
                                screenshot_enabled,
                            )
                            action_record["csv_import_open_button_click"] = click_file_dialog_open_button(import_dialog)
                            deadline = time.time() + csv_import_wait_seconds
                            dialog_closed = False
                            while time.time() < deadline:
                                try:
                                    dialog_window = window_info_from_hwnd(int(import_dialog["hwnd"]))
                                    if not bool(dialog_window.get("visible")):
                                        dialog_closed = True
                                        break
                                except Exception:
                                    dialog_closed = True
                                    break
                                time.sleep(0.25)
                            action_record["csv_import_wait_seconds"] = csv_import_wait_seconds
                            action_record["csv_import_dialog_closed"] = dialog_closed
                            time.sleep(min(1.0, max(0.2, command_wait_seconds)))
                            action_record["csv_import_capture_after_import"] = capture_window(
                                pid,
                                target_hwnd,
                                f"{command_name}_toolbar_{action_name}_after_import",
                                command_screenshot_dir,
                                command_ui_dir,
                            )
                            marker_hits = []
                            if csv_import_marker:
                                for hit in (action_record["csv_import_capture_after_import"].get("ui_hits") or []):
                                    hit_text = str(hit.get("text") or "")
                                    hit_name = str(hit.get("name") or "")
                                    if csv_import_marker in hit_text or csv_import_marker in hit_name:
                                        marker_hits.append(hit)
                            action_record["csv_import_marker_hits"] = marker_hits
                            action_record["csv_import_marker_visible"] = bool(
                                csv_import_marker and marker_hits
                            )
                            action_record["csv_import_completed"] = bool(
                                action_record["csv_import_marker_visible"]
                                and (action_record.get("csv_import_open_button_click") or {}).get("clicked")
                            )
                            action_record["csv_import_export_executed"] = bool(action_record["csv_import_completed"])
                            if allow_gui_csv_import_commit:
                                commit_window = None
                                try:
                                    commit_window = compact_window(window_info_from_hwnd(target_hwnd))
                                except Exception as exc:
                                    action_record["csv_import_commit_target_refresh_error"] = str(exc)
                                commit_rect = (commit_window or target_before or {}).get("rect") or {}
                                if not commit_rect:
                                    raise RuntimeError("Cannot resolve variable-table dialog rect for GUI CSV import commit")
                                action_record["csv_import_commit_target_window"] = commit_window or target_before
                                ok_x = int(commit_rect.get("right") or 0) - 74
                                ok_y = int(commit_rect.get("bottom") or 0) - 25
                                action_record["csv_import_ok_button_click"] = mouse_click_screen(
                                    ok_x,
                                    ok_y,
                                    wait_seconds=1.5,
                                )
                                action_record["commit_executed"] = bool(
                                    action_record["csv_import_ok_button_click"].get("clicked", True)
                                )
                                time.sleep(1.0)
                                try:
                                    action_record["csv_import_focus_main_before_save"] = focus_window(
                                        {"pid": pid, "hwnd": main_hwnd, "owen_only": False}
                                    )
                                except Exception as exc:
                                    action_record["csv_import_focus_main_before_save_error"] = str(exc)
                                action_record["csv_import_ctrl_s_save_scratch"] = send_raw_hotkey(
                                    ["CTRL", "S"],
                                    wait_seconds=2.0,
                                )
                                action_record["save_executed"] = True
                                time.sleep(1.0)
                                validation_after_commit = project_validate(
                                    {"project_path": str(scratch_project), "include_warnings": True}
                                )
                                variables_after_commit = project_variables_inspect(
                                    {"project_path": str(scratch_project), "max_items": 600}
                                )
                                marker_variables_after_commit = [
                                    variable
                                    for variable in variables_after_commit.get("variables") or []
                                    if isinstance(variable, dict)
                                    and str(variable.get("name") or "") == csv_import_marker
                                ]
                                modbus_map_after_commit = None
                                marker_modbus_rows_after_commit: list[dict[str, Any]] = []
                                try:
                                    modbus_map_after_commit = project_modbus_export_map(
                                        {
                                            "project_path": str(scratch_project),
                                            "include_empty_devices": True,
                                            "max_rows": 1000,
                                        }
                                    )
                                    marker_modbus_rows_after_commit = modbus_map_rows_for_variable_name(
                                        modbus_map_after_commit,
                                        csv_import_marker,
                                    )
                                except Exception as exc:
                                    action_record["csv_import_modbus_map_readback_error"] = str(exc)
                                action_record["csv_import_static_validation_after_commit"] = {
                                    "ok": validation_after_commit.get("ok"),
                                    "error_count": validation_after_commit.get("error_count"),
                                    "warning_count": validation_after_commit.get("warning_count"),
                                }
                                action_record["csv_import_variables_after_commit_summary"] = {
                                    "variable_count": variables_after_commit.get("variable_count"),
                                    "returned_count": len(variables_after_commit.get("variables") or []),
                                    "marker_count": len(marker_variables_after_commit),
                                }
                                action_record["csv_import_marker_variables_after_commit"] = marker_variables_after_commit
                                action_record["csv_import_modbus_map_after_commit_summary"] = {
                                    "row_count": (modbus_map_after_commit or {}).get("row_count"),
                                    "device_count": (modbus_map_after_commit or {}).get("device_count"),
                                    "variable_model_count": (modbus_map_after_commit or {}).get("variable_model_count"),
                                    "marker_count": len(marker_modbus_rows_after_commit),
                                }
                                action_record["csv_import_marker_modbus_rows_after_commit"] = marker_modbus_rows_after_commit[:10]
                                action_record["csv_import_marker_persisted_in_variable_model"] = bool(
                                    marker_variables_after_commit
                                )
                                action_record["csv_import_marker_persisted_in_modbus_map"] = bool(
                                    marker_modbus_rows_after_commit
                                )
                                action_record["csv_import_marker_persisted_in_scratch_model"] = bool(
                                    marker_variables_after_commit or marker_modbus_rows_after_commit
                                )
                                action_record["csv_import_completed"] = bool(
                                    (action_record.get("csv_import_open_button_click") or {}).get("clicked")
                                    and action_record["csv_import_marker_persisted_in_scratch_model"]
                                    and validation_after_commit.get("ok")
                                )
                                action_record["csv_import_export_executed"] = bool(
                                    action_record["csv_import_completed"]
                                )
                            if not action_record["csv_import_completed"]:
                                raise RuntimeError(
                                    "GUI CSV import did not persist the expected marker in the scratch model"
                                    if allow_gui_csv_import_commit
                                    else "GUI CSV import did not complete with the expected marker visible"
                                    if csv_import_marker
                                    else "GUI CSV import did not complete"
                                )
                        if action_name == "csv_export_dialog" and allow_gui_csv_export:
                            if not csv_export_target:
                                raise RuntimeError("GUI CSV export target was not resolved")
                            if not dialog_candidates_after_action:
                                raise RuntimeError("GUI CSV export was allowed, but no Save dialog candidate was detected")
                            export_dialog = dialog_candidates_after_action[0]
                            export_dialog_kind = csv_file_dialog_kind(export_dialog)
                            action_record["csv_export_dialog_kind"] = export_dialog_kind
                            if export_dialog_kind == "open":
                                raise RuntimeError(
                                    "GUI CSV export expected a Save dialog, but OWEN Logic opened an Open dialog"
                                )
                            action_record["csv_export_target_path"] = str(csv_export_target)
                            action_record["csv_export_filename_fill"] = fill_file_dialog_filename_with_clipboard(
                                export_dialog,
                                csv_export_target,
                                command_screenshot_dir,
                                screenshot_enabled,
                            )
                            action_record["csv_export_save_button_click"] = click_file_dialog_save_button(export_dialog)
                            action_record["csv_export_save_dialog_confirmed"] = bool(
                                (action_record.get("csv_export_save_button_click") or {}).get("clicked")
                            )
                            deadline = time.time() + csv_export_wait_seconds
                            while time.time() < deadline and not csv_export_target.exists():
                                time.sleep(0.25)
                            csv_export_exists = csv_export_target.exists()
                            csv_export_bytes = csv_export_target.stat().st_size if csv_export_exists else 0
                            action_record["csv_export_wait_seconds"] = csv_export_wait_seconds
                            action_record["csv_export_completed"] = bool(csv_export_exists and csv_export_bytes > 0)
                            action_record["csv_export_file"] = (
                                safe_file_info(csv_export_target, include_hash=True)
                                if csv_export_exists
                                else None
                            )
                            action_record["csv_import_export_executed"] = bool(action_record["csv_export_completed"])
                            if not action_record["csv_export_completed"]:
                                raise RuntimeError(
                                    f"GUI CSV export did not create a non-empty file at {csv_export_target}"
                                )
                        if action_record["csv_dialog_surface_only"]:
                            dismiss_hwnd = None
                            if action_record.get("csv_export_completed") or action_record.get("csv_import_completed"):
                                dismiss_hwnd = None
                            elif dialog_candidates_after_action:
                                dismiss_hwnd = int(dialog_candidates_after_action[0].get("hwnd") or 0)
                            elif foreground_after_action and int(foreground_after_action) != int(main_hwnd):
                                dismiss_hwnd = int(foreground_after_action)
                            if dismiss_hwnd:
                                try:
                                    action_record["focus_csv_dialog_before_dismiss"] = focus_window(
                                        {"pid": pid, "hwnd": dismiss_hwnd, "owen_only": False}
                                    )
                                except Exception as exc:
                                    action_record["focus_csv_dialog_before_dismiss_error"] = str(exc)
                                try:
                                    action_record["csv_dialog_dismiss_escape"] = send_raw_hotkey(["ESC"], wait_seconds=0.7)
                                except Exception as exc:
                                    action_record["csv_dialog_dismiss_escape_error"] = str(exc)
                    except Exception as exc:
                        action_record["error"] = str(exc)
                        command_result["errors"].append(str(exc))
                    toolbar_action_records.append(action_record)
                command_result["variable_table_toolbar_actions"] = toolbar_action_records
                command_result["variable_table_toolbar_add_clicked"] = any(
                    record.get("action") == "add_variable" and bool(record.get("clicked"))
                    for record in toolbar_action_records
                )
                command_result["variable_table_create_button_surface_probed"] = bool(
                    command_result["variable_table_toolbar_add_clicked"]
                )
                command_result["variable_table_csv_import_dialog_surface_probed"] = any(
                    record.get("action") == "csv_import_dialog"
                    and bool(record.get("csv_import_export_dialog_surface_probed"))
                    for record in toolbar_action_records
                )
                command_result["variable_table_csv_export_dialog_surface_probed"] = any(
                    record.get("action") == "csv_export_dialog"
                    and bool(record.get("csv_import_export_dialog_surface_probed"))
                    for record in toolbar_action_records
                )
                command_result["variable_table_csv_dialog_surface_probed"] = bool(
                    command_result["variable_table_csv_import_dialog_surface_probed"]
                    or command_result["variable_table_csv_export_dialog_surface_probed"]
                )
                command_result["variable_table_csv_import_executed"] = any(
                    record.get("action") == "csv_import_dialog"
                    and bool(record.get("csv_import_completed"))
                    for record in toolbar_action_records
                )
                command_result["variable_table_csv_import_markers"] = [
                    record.get("csv_import_marker")
                    for record in toolbar_action_records
                    if record.get("action") == "csv_import_dialog" and record.get("csv_import_marker")
                ]
                command_result["variable_table_csv_export_executed"] = any(
                    record.get("action") == "csv_export_dialog"
                    and bool(record.get("csv_export_completed"))
                    for record in toolbar_action_records
                )
                command_result["variable_table_csv_export_files"] = [
                    record.get("csv_export_file")
                    for record in toolbar_action_records
                    if record.get("action") == "csv_export_dialog" and record.get("csv_export_file")
                ]
                command_result["variable_table_csv_import_committed"] = any(
                    record.get("action") == "csv_import_dialog"
                    and bool(record.get("csv_import_marker_persisted_in_scratch_model"))
                    for record in toolbar_action_records
                )
                command_result["variable_table_commit_executed"] = any(
                    bool(record.get("commit_executed")) for record in toolbar_action_records
                )
                command_result["variable_table_saved_to_project"] = any(
                    bool(record.get("save_executed")) for record in toolbar_action_records
                )
                command_result["variable_table_csv_import_export_executed"] = any(
                    bool(record.get("csv_import_export_executed"))
                    for record in toolbar_action_records
                )
            if command_result.get("port_settings_no_change_ok_close_executed"):
                command_result["dismiss_escape"] = {"skipped": "port_settings_ok_close_already_closed_dialog"}
                command_result["dismiss_alt_f4"] = {"skipped": "port_settings_ok_close_already_closed_dialog"}
            else:
                try:
                    command_result["dismiss_escape"] = send_raw_hotkey(["ESC"], wait_seconds=0.5)
                except Exception as exc:
                    command_result["dismiss_escape_error"] = str(exc)
                try:
                    command_result["dismiss_alt_f4"] = send_raw_hotkey(["ALT", "F4"], wait_seconds=0.8)
                except Exception as exc:
                    command_result["dismiss_alt_f4_error"] = str(exc)
            static_validation_after = project_validate({"project_path": str(scratch_project), "include_warnings": True})
            scratch_hash_after_command = sha256_file(scratch_project)
            command_result["static_validation_before"] = static_validation_before
            command_result["static_validation_after"] = static_validation_after
            command_result["scratch_hash_before_command"] = scratch_hash_before_command
            command_result["scratch_hash_after_command"] = scratch_hash_after_command
            command_result["scratch_hash_preserved"] = scratch_hash_before_command == scratch_hash_after_command
            if command_name == "port_settings":
                command_result["port_settings_no_change_ok_close_verified"] = bool(
                    command_result.get("port_settings_no_change_ok_close_executed")
                    and command_result["scratch_hash_preserved"]
                    and bool(static_validation_after.get("ok"))
                )
                command_result["port_settings_dialog_completion_verified"] = bool(
                    command_result["port_settings_no_change_ok_close_verified"]
                )
            if command_name == "variable_table":
                try:
                    variables = project_variables_inspect({"project_path": str(scratch_project), "max_items": 80})
                    command_result["offline_model_summary"] = {
                        "kind": "variables",
                        "variable_count": variables.get("variable_count"),
                        "returned_count": len(variables.get("variables") or []),
                    }
                except Exception as exc:
                    command_result["offline_model_summary_error"] = str(exc)
            if command_name == "port_settings":
                try:
                    modbus = project_modbus_inspect({"project_path": str(scratch_project), "max_matches": 80})
                    command_result["offline_model_summary"] = {
                        "kind": "modbus_settings",
                        "setting_count": len(modbus.get("modbus_settings") or []),
                        "device_model_count": len(modbus.get("device_models") or []),
                        "keyword_match_count": modbus.get("keyword_match_count"),
                    }
                except Exception as exc:
                    command_result["offline_model_summary_error"] = str(exc)
            screenshot_paths = [str(path) for path in sorted(command_screenshot_dir.glob("*.png"))]
            command_result["screenshots"] = screenshot_paths
            command_result["device_dialog_or_surface_opened"] = bool(command_result["captured_hwnds_after_click"])
            command_result["device_dialog_ui_hit_count"] = sum(
                int(capture.get("ui_hit_count") or 0)
                for capture in command_result["captures"]
                if "after_click" in str(capture.get("label") or "")
            )
        except Exception as exc:
            command_result["errors"].append(str(exc))
        finally:
            if cleanup:
                cleanup_results.extend(cleanup_new_processes())
            command_result["cleanup_requested"] = cleanup
            command_result["cleanup_results"] = cleanup_results
            command_result["remaining_new_pids_after_cleanup"] = sorted(programrelay_pids() - baseline_pids)
            command_result["source_hash_after"] = sha256_file(source)
            command_result["source_hash_preserved"] = command_result["source_hash_before"] == command_result["source_hash_after"]
            cleanup_ok = (not cleanup) or not command_result["remaining_new_pids_after_cleanup"]
            open_probe_ok = bool((command_result.get("open_probe_summary") or {}).get("gui_open_completed"))
            command_result["ok"] = bool(
                not command_result["errors"]
                and open_probe_ok
                and command_result.get("device_dialog_or_surface_opened")
                and command_result.get("source_hash_preserved")
                and (
                    not command_result.get("port_settings_no_change_ok_close_requested")
                    or command_result.get("port_settings_no_change_ok_close_verified")
                )
                and cleanup_ok
            )
        return command_result

    command_results = []
    for command_index, command in enumerate(requested_commands):
        if command_index > 0 and inter_command_cooldown_seconds > 0:
            time.sleep(inter_command_cooldown_seconds)
        command_results.append(run_one_command(command))
    cleanup_sidecar_path = scratch_dir / "cleanup_result.json"
    cleanup_summary = {
        "baseline_programrelayfbd_pids": sorted(baseline_pids),
        "remaining_new_pids_after_all_cleanup": sorted(programrelay_pids() - baseline_pids),
        "commands": [
            {
                "command": command.get("command"),
                "ok": command.get("ok"),
                "cleanup_results": command.get("cleanup_results"),
                "remaining_new_pids_after_cleanup": command.get("remaining_new_pids_after_cleanup"),
            }
            for command in command_results
        ],
    }
    try:
        cleanup_sidecar_path.write_text(json.dumps(json_safe_value(cleanup_summary), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    except Exception:
        pass
    source_hash_after = sha256_file(source)
    csv_export_files = [
        export_file
        for command in command_results
        for export_file in (command.get("variable_table_csv_export_files") or [])
        if export_file
    ]
    csv_import_markers = [
        marker
        for command in command_results
        for marker in (command.get("variable_table_csv_import_markers") or [])
        if marker
    ]
    variable_table_target_tab_selections = [
        command.get("variable_table_target_tab_selection")
        for command in command_results
        if command.get("variable_table_target_tab_selection")
    ]
    variable_table_target_tab_selected = any(
        bool(command.get("variable_table_target_tab_selected")) for command in command_results
    )
    variable_table_csv_import_executed = any(
        bool(command.get("variable_table_csv_import_executed")) for command in command_results
    )
    variable_table_csv_import_committed = any(
        bool(command.get("variable_table_csv_import_committed")) for command in command_results
    )
    variable_table_csv_export_executed = any(
        bool(command.get("variable_table_csv_export_executed")) for command in command_results
    )
    variable_table_csv_import_export_executed = any(
        bool(command.get("variable_table_csv_import_export_executed")) for command in command_results
    )
    port_settings_no_change_ok_close_requested = any(
        bool(command.get("port_settings_no_change_ok_close_requested")) for command in command_results
    )
    port_settings_no_change_ok_close_executed = any(
        bool(command.get("port_settings_no_change_ok_close_executed")) for command in command_results
    )
    port_settings_no_change_ok_close_verified = any(
        bool(command.get("port_settings_no_change_ok_close_verified")) for command in command_results
    )
    if variable_table_csv_import_committed and variable_table_csv_export_executed:
        validation_scope = "bounded_gui_device_menu_dialog_probe_with_opt_in_variable_table_csv_import_commit_export"
        limitation = (
            "This opens selected safe Device menu dialogs on scratch project copies and captures screenshots/UIA evidence. "
            "With explicit opt-in it completed variable-table CSV import from a scratch CSV path, pressed OK, saved only the scratch .owle, "
            "verified the marker in the scratch project model, and completed CSV export to a scratch CSV path. It does not apply settings, "
            "open COM/TCP, download to a controller, update firmware, calibrate, or communicate with a live device."
        )
    elif variable_table_csv_import_committed:
        validation_scope = "bounded_gui_device_menu_dialog_probe_with_opt_in_variable_table_csv_import_commit"
        limitation = (
            "This opens selected safe Device menu dialogs on scratch project copies and captures screenshots/UIA evidence. "
            "With explicit opt-in it completed variable-table CSV import from a scratch CSV path, pressed OK, saved only the scratch .owle, "
            "and verified the marker in the scratch project model. It does not apply settings, open COM/TCP, download to a controller, "
            "update firmware, calibrate, or communicate with a live device."
        )
    elif variable_table_csv_import_executed and variable_table_csv_export_executed:
        validation_scope = "bounded_gui_device_menu_dialog_probe_with_opt_in_variable_table_csv_import_export"
        limitation = (
            "This opens selected safe Device menu dialogs on scratch project copies and captures screenshots/UIA evidence. "
            "With explicit opt-in it completed variable-table CSV import from a scratch CSV path and CSV export to a scratch CSV path. "
            "It does not save the project, apply settings, open COM/TCP, download to a controller, update firmware, calibrate, or communicate with a live device."
        )
    elif variable_table_csv_import_executed:
        validation_scope = "bounded_gui_device_menu_dialog_probe_with_opt_in_variable_table_csv_import"
        limitation = (
            "This opens selected safe Device menu dialogs on scratch project copies and captures screenshots/UIA evidence. "
            "With explicit opt-in it completed variable-table CSV import from a scratch CSV path. It does not save the project, "
            "apply settings, open COM/TCP, download to a controller, update firmware, calibrate, or communicate with a live device."
        )
    elif variable_table_csv_export_executed:
        validation_scope = "bounded_gui_device_menu_dialog_probe_with_opt_in_variable_table_csv_export"
        limitation = (
            "This opens selected safe Device menu dialogs on scratch project copies and captures screenshots/UIA evidence. "
            "With explicit opt-in it completed variable-table CSV export to a scratch CSV path. It does not import CSV data, "
            "apply settings, edit variables, open COM/TCP, download to a controller, update firmware, calibrate, or communicate with a live device."
        )
    elif port_settings_no_change_ok_close_verified:
        validation_scope = "bounded_gui_device_menu_dialog_probe_with_opt_in_port_settings_no_change_ok_close"
        limitation = (
            "This opens the Device port-settings dialog on a scratch project copy, clicks only OK after explicit no-change confirmation, "
            "and verifies scratch project hash plus static validation preservation. It does not edit or apply changed settings, open COM/TCP, "
            "download to a controller, update firmware, calibrate, or communicate with a live device."
        )
    else:
        validation_scope = "bounded_gui_device_menu_dialog_probe_for_variable_table_and_connection_port_settings"
        limitation = (
            "This opens selected safe Device menu dialogs on scratch project copies and captures screenshots/UIA evidence. "
            "It does not apply settings, edit variables, run variable-table CSV import/export, open COM/TCP, download to a controller, "
            "update firmware, calibrate, or communicate with a live device."
        )
    result = {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": bool(all(command.get("ok") for command in command_results) and source_hash_before == source_hash_after),
        "probe_kind": "scratch_project_device_menu_dialog_probe",
        "source_project": safe_file_info(source, include_hash=True),
        "scratch_dir": str(scratch_dir),
        "baseline_programrelayfbd_pids": sorted(baseline_pids),
        "commands_requested": requested_commands,
        "commands": command_results,
        "source_hash_before": source_hash_before,
        "source_hash_after": source_hash_after,
        "source_hash_preserved": source_hash_before == source_hash_after,
        "cleanup_requested": cleanup,
        "cleanup_summary": cleanup_summary,
        "cleanup_sidecar_path": str(cleanup_sidecar_path),
        "processes_after_cleanup": tasklist_programrelay(),
        "opened_serial_port": False,
        "opened_network_socket": False,
        "serial_or_network_access_attempted": False,
        "live_device_action_executed": False,
        "write_to_controller_attempted": False,
        "firmware_or_calibration_action_attempted": False,
        "variable_table_target_tab_name": variable_table_target_tab_name or None,
        "variable_table_target_tab_selected": variable_table_target_tab_selected,
        "variable_table_target_tab_selections": variable_table_target_tab_selections,
        "variable_table_csv_import_executed": variable_table_csv_import_executed,
        "variable_table_csv_import_committed": variable_table_csv_import_committed,
        "variable_table_csv_import_markers": csv_import_markers,
        "variable_table_csv_export_executed": variable_table_csv_export_executed,
        "variable_table_csv_export_files": csv_export_files,
        "variable_table_csv_import_export_executed": variable_table_csv_import_export_executed,
        "port_settings_no_change_ok_close_requested": port_settings_no_change_ok_close_requested,
        "port_settings_no_change_ok_close_executed": port_settings_no_change_ok_close_executed,
        "port_settings_no_change_ok_close_verified": port_settings_no_change_ok_close_verified,
        "validation_scope": validation_scope,
        "limitation": limitation,
        "guardrail": "Only scratch copies are opened in OWEN Logic through the real File > Open path. Source hash is checked before/after. Cleanup stops only ProgramRelayFBD.exe processes created by this probe.",
    }
    return result


def project_variable_table_gui_probe(args: dict[str, Any]) -> dict[str, Any]:
    if "commands" in args:
        raise ValueError("owen_logic_project_variable_table_gui_probe always probes the variable_table command; do not pass commands")
    child_args = dict(args)
    child_args["commands"] = ["variable_table"]
    device_result = project_device_menu_dialog_probe(child_args)
    variable_result = None
    for command in device_result.get("commands") or []:
        if isinstance(command, dict) and command.get("command") == "variable_table":
            variable_result = command
            break
    if variable_result is None:
        raise RuntimeError("Device menu probe did not return a variable_table command result")
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": bool(device_result.get("ok") and variable_result.get("ok")),
        "probe_kind": "scratch_project_variable_table_gui_probe",
        "source_project": device_result.get("source_project"),
        "scratch_dir": device_result.get("scratch_dir"),
        "variable_table": variable_result,
        "device_menu_probe": device_result,
        "source_hash_before": device_result.get("source_hash_before"),
        "source_hash_after": device_result.get("source_hash_after"),
        "source_hash_preserved": device_result.get("source_hash_preserved"),
        "cleanup_requested": device_result.get("cleanup_requested"),
        "cleanup_summary": device_result.get("cleanup_summary"),
        "cleanup_sidecar_path": device_result.get("cleanup_sidecar_path"),
        "processes_after_cleanup": device_result.get("processes_after_cleanup"),
        "opened_serial_port": False,
        "opened_network_socket": False,
        "serial_or_network_access_attempted": False,
        "live_device_action_executed": False,
        "variable_table_gui_surface_probe_executed": True,
        "variable_table_edit_executed": False,
        "variable_table_csv_import_export_executed": False,
        "validation_scope": "bounded_gui_variable_table_surface_probe",
        "limitation": "This opens the OWEN Logic variable table dialog/surface on a scratch project copy and captures screenshot/UIA evidence. It does not edit variables, create/delete variable rows through the GUI, execute variable-table CSV import/export, open COM/TCP, or contact a live device.",
        "guardrail": "Only a scratch copy is opened in OWEN Logic through the real File > Open path. Source hash is checked before/after. Cleanup stops only ProgramRelayFBD.exe processes created by this probe.",
    }


def project_variable_table_toolbar_probe(args: dict[str, Any]) -> dict[str, Any]:
    if "commands" in args:
        raise ValueError("owen_logic_project_variable_table_toolbar_probe always probes the variable_table command; do not pass commands")
    actions_raw = args.get("actions")
    if actions_raw is None:
        actions = ["add_variable"]
    elif isinstance(actions_raw, list):
        actions = [str(action) for action in actions_raw]
    else:
        raise ValueError("actions must be an array when provided")
    if not actions:
        raise ValueError("At least one variable-table toolbar action is required")
    unknown_actions = [action for action in actions if action not in VARIABLE_TABLE_TOOLBAR_ACTIONS]
    if unknown_actions:
        raise ValueError(f"Unknown variable-table toolbar action(s): {unknown_actions}")
    allow_gui_csv_import = bool(args.get("allow_gui_csv_import", False))
    allow_gui_csv_export = bool(args.get("allow_gui_csv_export", False))
    child_args = dict(args)
    child_args.pop("actions", None)
    child_args["commands"] = ["variable_table"]
    child_args["variable_table_toolbar_actions"] = actions
    device_result = project_device_menu_dialog_probe(child_args)
    variable_result = None
    for command in device_result.get("commands") or []:
        if isinstance(command, dict) and command.get("command") == "variable_table":
            variable_result = command
            break
    if variable_result is None:
        raise RuntimeError("Device menu probe did not return a variable_table command result")
    toolbar_action_records = variable_result.get("variable_table_toolbar_actions") or []
    action_success: dict[str, bool] = {}
    for action_name in actions:
        matching_records = [
            record for record in toolbar_action_records
            if isinstance(record, dict) and record.get("action") == action_name
        ]
        if action_name == "add_variable":
            action_success[action_name] = any(bool(record.get("clicked")) for record in matching_records)
        elif action_name == "csv_import_dialog" and allow_gui_csv_import:
            action_success[action_name] = any(
                bool(record.get("csv_import_completed"))
                for record in matching_records
            )
        elif action_name == "csv_export_dialog" and allow_gui_csv_export:
            action_success[action_name] = any(
                bool(record.get("csv_export_completed"))
                for record in matching_records
            )
        elif action_name in {"csv_import_dialog", "csv_export_dialog"}:
            action_success[action_name] = any(
                bool(record.get("csv_import_export_dialog_surface_probed"))
                for record in matching_records
            )
        else:
            action_success[action_name] = any(bool(record.get("clicked")) for record in matching_records)
    all_requested_actions_succeeded = bool(actions) and all(action_success.values())
    variable_table_csv_import_executed = bool(variable_result.get("variable_table_csv_import_executed"))
    variable_table_csv_import_committed = bool(variable_result.get("variable_table_csv_import_committed"))
    variable_table_csv_export_executed = bool(variable_result.get("variable_table_csv_export_executed"))
    variable_table_csv_import_export_executed = bool(variable_result.get("variable_table_csv_import_export_executed"))
    validation_scope = (
        "bounded_gui_variable_table_toolbar_with_opt_in_csv_import_commit_export_probe"
        if variable_table_csv_import_committed and variable_table_csv_export_executed
        else "bounded_gui_variable_table_toolbar_with_opt_in_csv_import_commit_probe"
        if variable_table_csv_import_committed
        else "bounded_gui_variable_table_toolbar_with_opt_in_csv_import_export_probe"
        if variable_table_csv_import_executed and variable_table_csv_export_executed
        else "bounded_gui_variable_table_toolbar_with_opt_in_csv_import_probe"
        if variable_table_csv_import_executed
        else
        "bounded_gui_variable_table_toolbar_with_opt_in_csv_export_probe"
        if variable_table_csv_export_executed
        else "bounded_gui_variable_table_toolbar_and_csv_dialog_surface_probe"
    )
    limitation = (
        "This opens the OWEN Logic variable table on a scratch project copy, clicks selected toolbar action(s), "
        "and captures screenshot/UIA evidence. With explicit opt-in it completed CSV import from a scratch CSV path, "
        "pressed OK, saved only the scratch .owle, verified the imported marker in the scratch model, and completed CSV export "
        "through the GUI Save dialog to a scratch CSV path. It does not edit/delete variables beyond this imported marker path, "
        "open COM/TCP, or contact a live device."
        if variable_table_csv_import_committed and variable_table_csv_export_executed
        else "This opens the OWEN Logic variable table on a scratch project copy, clicks selected toolbar action(s), "
        "and captures screenshot/UIA evidence. With explicit opt-in it completed CSV import from a scratch CSV path, "
        "pressed OK, saved only the scratch .owle, and verified the imported marker in the scratch model. It does not "
        "edit/delete variables beyond this imported marker path, open COM/TCP, or contact a live device."
        if variable_table_csv_import_committed
        else "This opens the OWEN Logic variable table on a scratch project copy, clicks selected toolbar action(s), "
        "and captures screenshot/UIA evidence. With explicit opt-in it completed CSV import from a scratch CSV path "
        "and CSV export through the GUI Save dialog to a scratch CSV path. It does not press OK, save the project, "
        "commit a created row, edit/delete variables beyond the in-memory CSV import operation, open COM/TCP, or contact a live device."
        if variable_table_csv_import_executed and variable_table_csv_export_executed
        else "This opens the OWEN Logic variable table on a scratch project copy, clicks selected toolbar action(s), "
        "and captures screenshot/UIA evidence. With explicit opt-in it completed CSV import from a scratch CSV path. "
        "It does not press OK, save the project, commit a created row, edit/delete variables beyond the in-memory CSV import operation, "
        "open COM/TCP, or contact a live device."
        if variable_table_csv_import_executed
        else
        "This opens the OWEN Logic variable table on a scratch project copy, clicks selected toolbar action(s), "
        "and captures screenshot/UIA evidence. With explicit opt-in it completed CSV export through the GUI Save dialog "
        "to a scratch CSV path. It does not import CSV data, press OK, save the project, commit a created row, "
        "edit/delete variables, open COM/TCP, or contact a live device."
        if variable_table_csv_export_executed
        else "This opens the OWEN Logic variable table on a scratch project copy, clicks selected toolbar action(s), and captures screenshot/UIA evidence. CSV actions stop at the file-dialog surface and dismiss it; they do not choose a file, press Save/Open, import/export CSV data, press OK, save the project, commit a created row, edit/delete variables, open COM/TCP, or contact a live device."
    )
    scratch_project_state_ok = bool(
        variable_result.get("scratch_hash_preserved")
        or (variable_table_csv_import_committed and variable_result.get("variable_table_saved_to_project"))
    )
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": bool(
            device_result.get("ok")
            and variable_result.get("ok")
            and all_requested_actions_succeeded
            and variable_result.get("source_hash_preserved")
            and scratch_project_state_ok
        ),
        "probe_kind": "scratch_project_variable_table_toolbar_probe",
        "source_project": device_result.get("source_project"),
        "scratch_dir": device_result.get("scratch_dir"),
        "actions_requested": actions,
        "variable_table": variable_result,
        "device_menu_probe": device_result,
        "source_hash_before": device_result.get("source_hash_before"),
        "source_hash_after": device_result.get("source_hash_after"),
        "source_hash_preserved": device_result.get("source_hash_preserved"),
        "scratch_hash_before_command": variable_result.get("scratch_hash_before_command"),
        "scratch_hash_after_command": variable_result.get("scratch_hash_after_command"),
        "scratch_hash_preserved": variable_result.get("scratch_hash_preserved"),
        "scratch_project_state_ok": scratch_project_state_ok,
        "cleanup_requested": device_result.get("cleanup_requested"),
        "cleanup_summary": device_result.get("cleanup_summary"),
        "cleanup_sidecar_path": device_result.get("cleanup_sidecar_path"),
        "processes_after_cleanup": device_result.get("processes_after_cleanup"),
        "opened_serial_port": False,
        "opened_network_socket": False,
        "serial_or_network_access_attempted": False,
        "live_device_action_executed": False,
        "variable_table_toolbar_probe_executed": True,
        "variable_table_toolbar_actions": toolbar_action_records,
        "variable_table_toolbar_action_success": action_success,
        "variable_table_all_requested_actions_succeeded": all_requested_actions_succeeded,
        "variable_table_target_tab_name": variable_result.get("variable_table_target_tab_name"),
        "variable_table_target_tab_selected": bool(variable_result.get("variable_table_target_tab_selected")),
        "variable_table_target_tab_selection": variable_result.get("variable_table_target_tab_selection"),
        "variable_table_target_tab_selections": (
            variable_result.get("variable_table_target_tab_selections")
            or ([variable_result.get("variable_table_target_tab_selection")] if variable_result.get("variable_table_target_tab_selection") else [])
        ),
        "variable_table_toolbar_add_clicked": bool(variable_result.get("variable_table_toolbar_add_clicked")),
        "variable_table_create_button_surface_probed": bool(
            variable_result.get("variable_table_create_button_surface_probed")
        ),
        "variable_table_csv_dialog_surface_probed": bool(
            variable_result.get("variable_table_csv_dialog_surface_probed")
        ),
        "variable_table_csv_import_dialog_surface_probed": bool(
            variable_result.get("variable_table_csv_import_dialog_surface_probed")
        ),
        "variable_table_csv_export_dialog_surface_probed": bool(
            variable_result.get("variable_table_csv_export_dialog_surface_probed")
        ),
        "variable_table_csv_import_executed": variable_table_csv_import_executed,
        "variable_table_csv_import_committed": variable_table_csv_import_committed,
        "variable_table_csv_import_markers": variable_result.get("variable_table_csv_import_markers") or [],
        "variable_table_csv_export_executed": variable_table_csv_export_executed,
        "variable_table_csv_export_files": variable_result.get("variable_table_csv_export_files") or [],
        "variable_table_commit_executed": bool(variable_result.get("variable_table_commit_executed")),
        "variable_table_saved_to_project": bool(variable_result.get("variable_table_saved_to_project")),
        "variable_table_edit_executed": False,
        "variable_table_csv_import_export_executed": variable_table_csv_import_export_executed,
        "validation_scope": validation_scope,
        "limitation": limitation,
        "guardrail": "Only a scratch copy is opened in OWEN Logic through the real File > Open path. Source and scratch project hashes are checked before/after. Cleanup stops only ProgramRelayFBD.exe processes created by this probe.",
    }


def project_variable_table_gui_edit_probe(args: dict[str, Any]) -> dict[str, Any]:
    require_windows()
    if not bool(args.get("allow_safe_runtime", False)):
        raise ValueError("owen_logic_project_variable_table_gui_edit_probe requires allow_safe_runtime=true")
    if not bool(args.get("allow_gui_variable_edit", False)):
        raise ValueError("owen_logic_project_variable_table_gui_edit_probe requires allow_gui_variable_edit=true")

    source = Path(str(args.get("project_path") or "")).expanduser().resolve()
    source_hash_before = sha256_file(source)
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    marker = str(args.get("marker") or f"CODEX_GUI_VAR_{timestamp}").strip()
    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{2,47}", marker):
        raise ValueError("marker must be an ASCII variable identifier, 3-48 chars, starting with a letter or underscore")

    scratch_value = args.get("scratch_dir")
    if scratch_value:
        scratch_dir = Path(str(scratch_value)).expanduser().resolve()
    else:
        workbench = find_workbench_root()
        scratch_dir = (
            workbench / "30_LOCAL_HEAVY" / "sandbox_tmp" / "owen_project_variable_table_gui_edit_probe" / timestamp
            if workbench
            else Path.home() / ".codex" / "tmp" / "owen_project_variable_table_gui_edit_probe" / timestamp
        ).resolve()
    if not is_scratch_destination(scratch_dir):
        raise ValueError(f"Refusing variable-table GUI edit output outside scratch/sandbox/local-heavy path: {scratch_dir}")
    screenshot_dir = scratch_dir / "screenshots"
    ui_dir = scratch_dir / "ui_snapshots"
    screenshot_dir.mkdir(parents=True, exist_ok=True)
    ui_dir.mkdir(parents=True, exist_ok=True)

    baseline_pids = programrelay_pids()
    wait_seconds = max(1, min(float(args.get("wait_seconds", 8)), 120))
    open_wait_seconds = max(1, min(float(args.get("open_wait_seconds", 16)), 60))
    open_attempts = clamp_int(args.get("open_attempts"), 2, 1, 3)
    post_open_idle_wait_seconds = max(1, min(float(args.get("post_open_idle_wait_seconds", 45)), 120))
    command_wait_seconds = max(0.5, min(float(args.get("command_wait_seconds", 2.5)), 15))
    dismiss_post_open_dialogs = bool(args.get("dismiss_post_open_information_dialogs", True))
    screenshot_enabled = bool(args.get("screenshot", True))
    include_ui_tree = bool(args.get("include_ui_tree", True))
    save_ui_tree = bool(args.get("save_ui_tree", True))
    cleanup = bool(args.get("cleanup_launched_process", True))
    delete_marker_after_create = bool(args.get("delete_marker_after_create", False))
    delete_existing_marker_only = bool(args.get("delete_existing_marker_only", False))
    skip_filter_for_visible_marker = bool(args.get("skip_filter_for_visible_marker", False))

    result: dict[str, Any] = {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": False,
        "probe_kind": "scratch_project_variable_table_gui_edit_probe",
        "source_project": safe_file_info(source, include_hash=True),
        "scratch_dir": str(scratch_dir),
        "marker": marker,
        "baseline_programrelayfbd_pids": sorted(baseline_pids),
        "source_hash_before": source_hash_before,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "serial_or_network_access_attempted": False,
        "live_device_action_executed": False,
        "write_to_controller_attempted": False,
        "firmware_or_calibration_action_attempted": False,
        "gui_variable_table_edit_attempted": False,
        "gui_variable_table_delete_attempted": False,
        "gui_variable_table_create_delete_cycle_requested": delete_marker_after_create,
        "gui_variable_table_delete_existing_marker_requested": delete_existing_marker_only,
        "gui_variable_table_skip_filter_for_visible_marker": skip_filter_for_visible_marker,
        "gui_variable_table_create_executed": False,
        "gui_variable_table_delete_executed": False,
        "gui_variable_table_csv_import_export_executed": False,
        "errors": [],
        "steps": [],
    }
    cleanup_results: list[dict[str, Any]] = []

    def add_step(name: str, data: Any) -> Any:
        result["steps"].append({"name": name, "data": json_safe_value(data)})
        return data

    def active_pids() -> list[int]:
        return sorted(programrelay_pids() - baseline_pids)

    def cleanup_new_processes() -> None:
        if not cleanup:
            return
        for _attempt in range(5):
            current = active_pids()
            if not current:
                break
            for cleanup_pid in current:
                cleanup_results.append(stop_process_best_effort(int(cleanup_pid)))
            time.sleep(0.8)

    gui_open_short_base: Path | None = None

    def gui_open_attempt_dir(attempt: int) -> Path:
        nonlocal gui_open_short_base
        if gui_open_short_base is None:
            workbench = find_workbench_root()
            short_token = f"vt_{datetime.now().strftime('%H%M%S')}_{uuid.uuid4().hex[:6]}"
            gui_open_short_base = (
                workbench / "30_LOCAL_HEAVY" / "sandbox_tmp" / "og" / short_token
                if workbench
                else Path.home() / ".codex" / "tmp" / "og" / short_token
            ).resolve()
            result["gui_open_short_scratch_base"] = str(gui_open_short_base)
        return gui_open_short_base / f"a{int(attempt)}"

    def variable_count(inspected: dict[str, Any]) -> int:
        count = 0
        for summary in inspected.get("document_summaries") or []:
            if isinstance(summary, dict):
                try:
                    count += int(summary.get("variable_count") or 0)
                except (TypeError, ValueError):
                    pass
        return count

    def compact_window_info(window: Any) -> dict[str, Any] | None:
        if not isinstance(window, dict):
            return None
        return {
            "hwnd": window.get("hwnd"),
            "pid": window.get("pid"),
            "title": window.get("title"),
            "class_name": window.get("class_name"),
            "visible": window.get("visible"),
            "enabled": window.get("enabled"),
            "rect": window.get("rect"),
        }

    def save_ui_snapshot(label: str, hwnd: int) -> dict[str, Any] | None:
        if not include_ui_tree:
            return None
        snapshot = ui_automation_snapshot(
            {
                "pid": pid,
                "hwnd": hwnd,
                "owen_only": False,
                "max_depth": 9,
                "max_children": 1200,
                "include_offscreen": False,
                "timeout_seconds": 30,
            }
        )
        tree = snapshot.get("ui_tree") if isinstance(snapshot.get("ui_tree"), dict) else {}
        controls = flatten_ui_tree(tree) if isinstance(tree, dict) else []
        compact = {
            "label": label,
            "control_count": len(controls),
            "window": compact_window_info(snapshot.get("window") or {}),
        }
        if save_ui_tree:
            path = ui_dir / f"{label}.ui.json"
            path.write_text(json.dumps(json_safe_value(snapshot), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            compact["ui_snapshot_path"] = str(path)
        else:
            compact["snapshot"] = snapshot
        return compact

    def find_variable_table_filter_edit(dialog_hwnd: int, dialog_window: dict[str, Any]) -> dict[str, Any] | None:
        snapshot = ui_automation_snapshot(
            {
                "pid": pid,
                "hwnd": dialog_hwnd,
                "owen_only": False,
                "max_depth": 5,
                "max_children": 400,
                "include_offscreen": False,
                "timeout_seconds": 20,
            }
        )
        tree = snapshot.get("ui_tree") if isinstance(snapshot.get("ui_tree"), dict) else {}
        controls = flatten_ui_tree(tree) if isinstance(tree, dict) else []
        rect = dialog_window.get("rect") or {}
        left = float(rect.get("left") or 0)
        top = float(rect.get("top") or 0)
        width = float(rect.get("width") or 0)
        candidates: list[dict[str, Any]] = []
        for control in controls:
            class_name = str(control.get("class_name") or "")
            bounding = control.get("bounding_rect") or {}
            try:
                x = float(bounding.get("x") or 0)
                y = float(bounding.get("y") or 0)
                control_width = float(bounding.get("width") or 0)
                control_height = float(bounding.get("height") or 0)
            except (TypeError, ValueError):
                continue
            if "WindowsForms10.Edit" not in class_name:
                continue
            if control_width < 100 or control_height < 10 or control_height > 45:
                continue
            if y < top or y > top + 130:
                continue
            if width > 0 and x < left + width * 0.45:
                continue
            candidates.append(control)
        candidates.sort(
            key=lambda control: (
                -float((control.get("bounding_rect") or {}).get("width") or 0),
                float((control.get("bounding_rect") or {}).get("y") or 0),
                -float((control.get("bounding_rect") or {}).get("x") or 0),
            )
        )
        if not candidates:
            return None
        return candidates[0]

    def select_main_window(scratch_project: Path, pids: list[int]) -> dict[str, Any]:
        scratch_name = scratch_project.name.lower()
        scratch_path = str(scratch_project).lower()
        candidates: list[tuple[int, int, dict[str, Any]]] = []
        for candidate_pid in pids:
            for window in enum_windows(pid=int(candidate_pid), owen_only=False):
                if not bool(window.get("visible")):
                    continue
                title = str(window.get("title") or "").lower()
                rect_value = window.get("rect") or {}
                area = int(rect_value.get("width") or 0) * int(rect_value.get("height") or 0)
                score = 0
                if scratch_path and scratch_path in title:
                    score += 8
                if scratch_name and scratch_name in title:
                    score += 4
                if "owen logic" in title:
                    score += 2
                if area >= 100000:
                    score += 1
                candidates.append((score, area, window))
        candidates.sort(key=lambda item: (-item[0], -item[1]))
        if not candidates:
            raise RuntimeError("No visible OWEN project window candidate after scratch File > Open")
        return candidates[0][2]

    def select_variable_table_dialog(windows_after_click: list[dict[str, Any]]) -> dict[str, Any]:
        candidates: list[tuple[int, int, dict[str, Any]]] = []
        for window in windows_after_click:
            if not bool(window.get("visible")):
                continue
            title = str(window.get("title") or "")
            title_lower = title.lower()
            rect_value = window.get("rect") or {}
            area = int(rect_value.get("width") or 0) * int(rect_value.get("height") or 0)
            is_main_window = title_lower.startswith("owen logic") or "owen logic -" in title_lower
            if area >= 100000 and area < 900000 and not is_main_window:
                score = 10
                if "variable" in title_lower or "\u043f\u0435\u0440\u0435\u043c" in title_lower or "\u0441\u043e\u0437\u0434" in title_lower:
                    score += 2
                candidates.append((score, area, window))
        candidates.sort(key=lambda item: (-item[0], -item[1]))
        if not candidates:
            raise RuntimeError("Variable table dialog was not detected after Device menu click")
        return candidates[0][2]

    def open_device_variable_table(pid_value: int, main_window: dict[str, Any]) -> dict[str, Any]:
        main_hwnd = int(main_window["hwnd"])
        focus_window({"pid": pid_value, "hwnd": main_hwnd, "owen_only": False})
        rect = main_window["rect"]

        def wait_for_device_popup(timeout_seconds: float = 3.0) -> dict[str, Any] | None:
            deadline = time.time() + max(0.5, min(timeout_seconds, 10))
            while time.time() < deadline:
                popup_window = find_windowsforms_menu_popup(pid_value, min_height=50)
                if popup_window:
                    return popup_window
                time.sleep(0.2)
            return None

        def wait_for_variable_table_dialog(timeout_seconds: float = 5.0) -> tuple[dict[str, Any] | None, list[dict[str, Any]]]:
            deadline = time.time() + max(0.5, min(timeout_seconds, 15))
            last_windows: list[dict[str, Any]] = []
            while time.time() < deadline:
                last_windows = enum_windows(pid=pid_value, owen_only=False)
                try:
                    return select_variable_table_dialog(last_windows), last_windows
                except Exception:
                    time.sleep(0.25)
            return None, last_windows

        def main_menu_pane_click_points() -> list[dict[str, Any]]:
            points: list[dict[str, Any]] = []
            try:
                snapshot = ui_automation_snapshot(
                    {
                        "pid": pid_value,
                        "hwnd": main_hwnd,
                        "owen_only": False,
                        "max_depth": 4,
                        "max_children": 1000,
                        "include_offscreen": False,
                        "timeout_seconds": 30,
                    }
                )
                tree = snapshot.get("ui_tree") if isinstance(snapshot.get("ui_tree"), dict) else {}
                controls = flatten_ui_tree(tree) if isinstance(tree, dict) else []
                for control in controls:
                    if control.get("name") != "Главное меню":
                        continue
                    bounds = control.get("bounding_rect") or {}
                    x = int(float(bounds.get("x") or 0))
                    y = int(float(bounds.get("y") or 0))
                    width = int(float(bounds.get("width") or 0))
                    height = int(float(bounds.get("height") or 0))
                    if width <= 0 or height <= 0:
                        continue
                    points.append(
                        {
                            "method": "uia_main_menu_pane",
                            "control": {
                                "name": control.get("name"),
                                "automation_id": control.get("automation_id"),
                                "class_name": control.get("class_name"),
                                "control_type": control.get("control_type"),
                                "bounding_rect": bounds,
                            },
                            "x": x + 90,
                            "y": y + max(4, height // 2),
                        }
                    )
                    break
            except Exception as exc:
                result["main_menu_pane_lookup_error"] = str(exc)
            return points

        popup = None
        attempts: list[dict[str, Any]] = []
        click_points = main_menu_pane_click_points()
        click_points.extend(
            {
                "method": "window_relative",
                "offset": {"x": offset[0], "y": offset[1]},
                "x": int(rect["left"]) + int(offset[0]),
                "y": int(rect["top"]) + int(offset[1]),
            }
            for offset in ((90, 41), (100, 41), (112, 41), (118, 42), (106, 42))
        )
        for attempt_index, point in enumerate(click_points, start=1):
            try:
                focus_window({"pid": pid_value, "hwnd": main_hwnd, "owen_only": False})
            except Exception:
                pass
            click = mouse_click_screen(int(point["x"]), int(point["y"]), wait_seconds=0.7)
            popup = wait_for_device_popup()
            menu_window_sample = menu_popup_debug_windows(pid_value)
            attempts.append(
                {
                    "attempt": attempt_index,
                    "method": point.get("method"),
                    "offset": point.get("offset"),
                    "point": {"x": point.get("x"), "y": point.get("y")},
                    "control": point.get("control"),
                    "click": click,
                    "popup_detected": popup is not None,
                    "popup_window": compact_window_info(popup) if popup else None,
                    "menu_window_sample_after_click": menu_window_sample,
                }
            )
            if popup is not None:
                break
            try:
                send_raw_hotkey(["ESC"], wait_seconds=0.2)
            except Exception:
                pass
        if popup is None:
            try:
                focus_window({"pid": pid_value, "hwnd": main_hwnd, "owen_only": False})
            except Exception:
                pass
            keyboard_steps: list[dict[str, Any]] = []
            for keys in (["ALT"], ["RIGHT"], ["RIGHT"], ["DOWN"]):
                try:
                    keyboard_steps.append(send_raw_hotkey(keys, wait_seconds=0.35))
                except Exception as exc:
                    keyboard_steps.append({"sent": keys, "error": str(exc)})
                    break
            popup = wait_for_device_popup()
            attempts.append(
                {
                    "attempt": len(attempts) + 1,
                    "method": "keyboard_menu_navigation",
                    "sequence": [["ALT"], ["RIGHT"], ["RIGHT"], ["DOWN"]],
                    "steps": keyboard_steps,
                    "popup_detected": popup is not None,
                    "popup_window": compact_window_info(popup) if popup else None,
                    "menu_window_sample_after_navigation": menu_popup_debug_windows(pid_value),
                }
            )
        if popup is None:
            for hotkey_attempt, keys in enumerate((["ALT", "\u041f"], ["ALT", "P"]), start=1):
                try:
                    focus_window({"pid": pid_value, "hwnd": main_hwnd, "owen_only": False})
                except Exception:
                    pass
                try:
                    sent = send_raw_hotkey(keys, wait_seconds=0.7)
                except Exception as exc:
                    sent = {"error": str(exc), "sent": keys}
                popup = wait_for_device_popup()
                attempts.append(
                    {
                        "attempt": len(attempts) + 1,
                        "method": "hotkey",
                        "hotkey_attempt": hotkey_attempt,
                        "keys": keys,
                        "hotkey": sent,
                        "popup_detected": popup is not None,
                        "popup_window": compact_window_info(popup) if popup else None,
                        "menu_window_sample_after_hotkey": menu_popup_debug_windows(pid_value),
                    }
                )
                if popup is not None:
                    break
                try:
                    send_raw_hotkey(["ESC"], wait_seconds=0.2)
                except Exception:
                    pass
        result["device_menu_click_attempts"] = attempts
        result["device_menu_popup_window"] = compact_window_info(popup) if popup else None
        if popup is None:
            raise RuntimeError("Device menu popup was not detected")
        popup_rect = popup.get("rect") or {}
        result["variable_table_menu_click"] = mouse_click_screen(
            int(popup_rect.get("left") or 0) + 120,
            int(popup_rect.get("top") or 0) + 82,
            wait_seconds=command_wait_seconds,
        )
        dialog, windows_after = wait_for_variable_table_dialog()
        result["windows_after_variable_table_click"] = [compact_window_info(window) for window in windows_after]
        if dialog is None:
            raise RuntimeError("Variable table dialog was not detected after Device menu click")
        return dialog

    try:
        open_attempt_summaries: list[dict[str, Any]] = []
        open_result: dict[str, Any] | None = None
        scratch_project: Path | None = None
        current_pids: list[int] = []
        for attempt in range(1, open_attempts + 1):
            attempt_dir = gui_open_attempt_dir(attempt)
            current_open_result = project_gui_open_probe(
                {
                    "project_path": str(source),
                    "scratch_dir": str(attempt_dir),
                    "allow_safe_runtime": True,
                    "wait_seconds": wait_seconds,
                    "open_wait_seconds": open_wait_seconds,
                    "post_open_idle_wait_seconds": post_open_idle_wait_seconds,
                    "screenshot": screenshot_enabled,
                    "cleanup_launched_process": False,
                    "dismiss_post_open_information_dialogs": dismiss_post_open_dialogs,
                }
            )
            add_step(f"project_gui_open_probe_attempt_{attempt}", current_open_result)
            scratch_project_value = (current_open_result.get("scratch_copy") or {}).get("path")
            current_scratch_project = Path(str(scratch_project_value)).resolve() if scratch_project_value else None
            current_pids = active_pids()
            open_attempt_summaries.append(
                {
                    "attempt": attempt,
                    "scratch_dir": str(attempt_dir),
                    "ok": current_open_result.get("ok"),
                    "gui_open_completed": current_open_result.get("gui_open_completed"),
                    "project_model_loaded_in_gui_claimed": current_open_result.get("project_model_loaded_in_gui_claimed"),
                    "error": current_open_result.get("error"),
                    "scratch_copy": current_open_result.get("scratch_copy"),
                    "active_programrelayfbd_pids": current_pids,
                    "open_dialogs_after_enter_count": len(current_open_result.get("open_dialogs_after_enter") or []),
                    "open_dialogs_after_post_open_idle_count": len(current_open_result.get("open_dialogs_after_post_open_idle") or []),
                    "open_dialogs_after_post_open_dialog_dismiss_idle_count": len(
                        current_open_result.get("open_dialogs_after_post_open_dialog_dismiss_idle") or []
                    ),
                }
            )
            if (
                current_scratch_project
                and current_scratch_project.exists()
                and current_pids
                and bool(current_open_result.get("gui_open_completed"))
            ):
                open_result = current_open_result
                scratch_project = current_scratch_project
                break
            cleanup_new_processes()
        if open_result is None:
            cleanup_new_processes()
            direct_dir = gui_open_attempt_dir(open_attempts + 1)
            scratch = project_scratch_copy(
                {
                    "project_path": str(source),
                    "scratch_dir": str(direct_dir),
                    "name_suffix": "_variable_table_gui_probe",
                }
            )
            direct_scratch_project = Path(str(scratch["scratch_copy"]["path"])).resolve()
            launch = launch_owen_logic({"project_path": str(direct_scratch_project), "wait_seconds": wait_seconds})
            launched_pid = int(launch["pid"])
            windows_after_launch = wait_for_owen_window(launched_pid, wait_seconds) if process_is_running(launched_pid) else []
            idle_after_launch = (
                wait_for_lifecycle_idle(launched_pid, post_open_idle_wait_seconds)
                if process_is_running(launched_pid)
                else {"idle": False, "process_exited": True, "windows": [], "blocking_windows": []}
            )
            windows_after_idle = enum_windows(pid=launched_pid, owen_only=False) if process_is_running(launched_pid) else []
            post_open_dismissal_result = None
            if dismiss_post_open_dialogs and process_is_running(launched_pid):
                if select_post_open_information_dialog(windows_after_idle):
                    post_open_dismissal_result = dismiss_post_open_information_dialogs(
                        launched_pid,
                        screenshot_dir,
                        screenshot_enabled,
                    )
                    time.sleep(0.5)
            current_pids = active_pids()
            windows_after_dialog_dismiss = {
                str(current_pid): enum_windows(pid=current_pid, owen_only=False)
                for current_pid in current_pids
            }
            open_dialogs_after_dialog_dismiss = [
                window
                for windows in windows_after_dialog_dismiss.values()
                for window in windows
                if str(window.get("class_name") or "").lower() == "#32770"
            ]
            direct_main_window = None
            try:
                direct_main_window = select_main_window(direct_scratch_project, current_pids) if current_pids else None
            except Exception:
                direct_main_window = None
            residual_dialog_dismissals: list[dict[str, Any]] = []
            if direct_main_window and open_dialogs_after_dialog_dismiss:
                for dialog in open_dialogs_after_dialog_dismiss[:4]:
                    dismissal: dict[str, Any] = {
                        "window_before": compact_window_info(dialog),
                        "escape_sent": None,
                    }
                    try:
                        focus_window(
                            {
                                "pid": int(dialog.get("pid") or launched_pid),
                                "hwnd": int(dialog.get("hwnd") or 0),
                                "owen_only": False,
                            }
                        )
                        dismissal["escape_sent"] = send_raw_hotkey(["ESC"], wait_seconds=0.4)
                        time.sleep(0.4)
                    except Exception as exc:
                        dismissal["error"] = str(exc)
                    residual_dialog_dismissals.append(dismissal)
                current_pids = active_pids()
                windows_after_dialog_dismiss = {
                    str(current_pid): enum_windows(pid=current_pid, owen_only=False)
                    for current_pid in current_pids
                }
                open_dialogs_after_dialog_dismiss = [
                    window
                    for windows in windows_after_dialog_dismiss.values()
                    for window in windows
                    if str(window.get("class_name") or "").lower() == "#32770"
                ]
                try:
                    direct_main_window = select_main_window(direct_scratch_project, current_pids) if current_pids else None
                except Exception:
                    direct_main_window = None
            direct_completed = bool(
                direct_scratch_project.exists()
                and current_pids
                and direct_main_window
                and not open_dialogs_after_dialog_dismiss
            )
            open_result = {
                "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
                "ok": direct_completed,
                "open_method": "direct_project_launch_fallback_after_file_open_attempts",
                "launch": launch,
                "windows_after_launch": windows_after_launch,
                "idle_after_launch": idle_after_launch,
                "windows_after_idle": windows_after_idle,
                "scratch_copy": safe_file_info(direct_scratch_project, include_hash=True),
                "gui_open_completed": direct_completed,
                "project_model_loaded_in_gui_claimed": direct_completed,
                "post_open_information_dialog_dismissal_result": post_open_dismissal_result,
                "programrelayfbd_pids_after_open": current_pids,
                "programrelayfbd_pids_after_post_open_dialog_dismiss": current_pids,
                "windows_by_pid_after_post_open_dialog_dismiss": windows_after_dialog_dismiss,
                "remaining_dialogs_after_dialog_dismiss": open_dialogs_after_dialog_dismiss,
                "residual_dialog_dismissals": residual_dialog_dismissals,
                "selected_main_window": compact_window_info(direct_main_window) if direct_main_window else None,
            }
            add_step("direct_project_launch_fallback", open_result)
            open_attempt_summaries.append(
                {
                    "attempt": "direct_launch_fallback",
                    "scratch_dir": str(direct_dir),
                    "ok": open_result.get("ok"),
                    "gui_open_completed": open_result.get("gui_open_completed"),
                    "project_model_loaded_in_gui_claimed": open_result.get("project_model_loaded_in_gui_claimed"),
                    "error": open_result.get("error"),
                    "scratch_copy": open_result.get("scratch_copy"),
                    "active_programrelayfbd_pids": current_pids,
                    "residual_dialog_dismissal_count": len(residual_dialog_dismissals),
                    "open_dialogs_after_enter_count": 0,
                    "open_dialogs_after_post_open_idle_count": len(open_dialogs_after_dialog_dismiss),
                    "open_dialogs_after_post_open_dialog_dismiss_idle_count": len(open_dialogs_after_dialog_dismiss),
                    "process_exited_after_open": launched_pid not in programrelay_pids(),
                }
            )
            if direct_completed:
                scratch_project = direct_scratch_project
        result["open_attempts"] = open_attempts
        result["open_attempt_summaries"] = open_attempt_summaries
        if not open_result or scratch_project is None or not scratch_project.exists():
            raise RuntimeError(
                "GUI open probe did not complete before variable-table GUI edit/delete probe: "
                + json.dumps(json_safe_value(open_attempt_summaries), ensure_ascii=False)
            )
        result["scratch_copy"] = safe_file_info(scratch_project, include_hash=True)
        result["active_programrelayfbd_pids_after_open"] = current_pids
        if not current_pids:
            raise RuntimeError("No OWEN Logic PID remained after File > Open")
        main_window = select_main_window(scratch_project, current_pids)
        pid = int(main_window.get("pid") or current_pids[0])
        main_hwnd = int(main_window["hwnd"])
        result["main_window"] = compact_window_info(main_window)
        result["main_hwnd"] = main_hwnd

        variables_before = add_step("variables_before", project_variables_inspect({"project_path": str(scratch_project), "max_items": 400}))
        count_before = variable_count(variables_before)
        result["variable_count_before"] = count_before
        marker_variables_before = [
            variable
            for variable in variables_before.get("variables") or []
            if isinstance(variable, dict) and str(variable.get("name") or "") == marker
        ]
        result["marker_found_before_gui_action"] = bool(marker_variables_before)
        result["marker_variables_before_gui_action"] = marker_variables_before
        if delete_existing_marker_only and not marker_variables_before:
            raise RuntimeError(f"Marker variable is not present before GUI delete: {marker}")

        dialog = open_device_variable_table(pid, main_window)
        dialog_hwnd = int(dialog["hwnd"])
        dialog_rect = dialog["rect"]
        result["variable_table_dialog"] = compact_window_info(dialog)
        result["screenshot_before_edit"] = lifecycle_screenshot_hwnd(pid, dialog_hwnd, screenshot_dir, "variable_table_before_add", screenshot_enabled)
        ui_before = save_ui_snapshot("variable_table_before_add", dialog_hwnd)
        if ui_before:
            result["ui_before_edit"] = ui_before

        name_cell_x = int(dialog_rect["left"]) + 300
        name_cell_y = int(dialog_rect["top"]) + 140
        if delete_existing_marker_only and not skip_filter_for_visible_marker:
            result["gui_variable_table_edit_attempted"] = True
            filter_control = None
            try:
                filter_control = find_variable_table_filter_edit(dialog_hwnd, dialog)
            except Exception as exc:
                result["filter_edit_control_error"] = str(exc)
            result["filter_edit_control"] = compact_control(filter_control) if filter_control else None
            filter_center = control_center(filter_control) if filter_control else None
            if filter_center:
                result["filter_marker_click_strategy"] = "uia_filter_edit_center"
                result["filter_marker_click"] = mouse_click_screen(
                    int(filter_center[0]),
                    int(filter_center[1]),
                    wait_seconds=0.2,
                )
            else:
                result["filter_marker_click_strategy"] = "coordinate_fallback"
                filter_x = int(dialog_rect["left"]) + 730
                filter_y = int(dialog_rect["top"]) + 73
                result["filter_marker_click"] = mouse_click_screen(filter_x, filter_y, wait_seconds=0.2)
            old_clipboard = clipboard_get_text()
            result["clipboard_set_marker_filter"] = {
                key: value for key, value in clipboard_set_text(marker).items() if key != "stdout"
            }
            result["filter_select_all"] = send_raw_hotkey(["CTRL", "A"], wait_seconds=0.2)
            result["filter_clear_existing_text"] = send_raw_hotkey(["BACKSPACE"], wait_seconds=0.2)
            result["filter_paste_marker"] = send_raw_hotkey(["CTRL", "V"], wait_seconds=1.0)
            if old_clipboard.get("ok"):
                result["clipboard_restore_after_filter"] = {
                    key: value
                    for key, value in clipboard_set_text(str(old_clipboard.get("stdout") or "")).items()
                    if key != "stdout"
                }
            result["screenshot_after_marker_filter"] = lifecycle_screenshot_hwnd(
                pid,
                dialog_hwnd,
                screenshot_dir,
                "variable_table_after_marker_filter",
                screenshot_enabled,
            )
            ui_after_filter = save_ui_snapshot("variable_table_after_marker_filter", dialog_hwnd)
            if ui_after_filter:
                result["ui_after_marker_filter"] = ui_after_filter
        elif delete_existing_marker_only:
            result["gui_variable_table_edit_attempted"] = True
            result["filter_marker_click"] = {
                "skipped": True,
                "reason": "marker was preseeded at a visible table position; delete pass selects the first visible row without using the GUI filter",
            }
            result["filter_marker_click_strategy"] = "skipped_visible_preseed_marker"
        else:
            # Coordinates are based on the stable WinForms variable-table toolbar and first editable name cell.
            add_x = int(dialog_rect["left"]) + 265
            add_y = int(dialog_rect["top"]) + 73
            result["toolbar_add_variable_click"] = mouse_click_screen(add_x, add_y, wait_seconds=1.0)
            result["gui_variable_table_edit_attempted"] = True
            result["screenshot_after_add_click"] = lifecycle_screenshot_hwnd(pid, dialog_hwnd, screenshot_dir, "variable_table_after_add_click", screenshot_enabled)

            result["name_cell_click"] = mouse_click_screen(name_cell_x, name_cell_y, wait_seconds=0.3)
            result["name_cell_f2"] = send_raw_hotkey(["F2"], wait_seconds=0.2)
            old_clipboard = clipboard_get_text()
            result["clipboard_set_marker"] = {key: value for key, value in clipboard_set_text(marker).items() if key != "stdout"}
            result["name_cell_select_all"] = send_raw_hotkey(["CTRL", "A"], wait_seconds=0.2)
            result["name_cell_paste_marker"] = send_raw_hotkey(["CTRL", "V"], wait_seconds=0.4)
            result["name_cell_enter"] = send_raw_hotkey(["ENTER"], wait_seconds=0.5)
            result["gui_variable_table_marker_entered_in_gui"] = True
            if old_clipboard.get("ok"):
                result["clipboard_restore"] = {key: value for key, value in clipboard_set_text(str(old_clipboard.get("stdout") or "")).items() if key != "stdout"}

            windows_after_marker_entry = enum_windows(pid=pid, owen_only=False)
            result["windows_after_marker_entry"] = [
                compact_window_info(window) for window in windows_after_marker_entry
            ]
            try:
                refreshed_dialog = select_variable_table_dialog(windows_after_marker_entry)
                dialog_hwnd = int(refreshed_dialog["hwnd"])
                dialog_rect = refreshed_dialog["rect"]
                result["variable_table_dialog_after_marker_entry"] = compact_window_info(refreshed_dialog)
            except Exception as exc:
                result["variable_table_dialog_after_marker_entry_error"] = str(exc)

            try:
                result["screenshot_after_marker"] = lifecycle_screenshot_hwnd(
                    pid,
                    dialog_hwnd,
                    screenshot_dir,
                    "variable_table_after_marker",
                    screenshot_enabled,
                )
            except Exception as exc:
                result["screenshot_after_marker_error"] = str(exc)
            try:
                ui_after = save_ui_snapshot("variable_table_after_marker", dialog_hwnd)
                if ui_after:
                    result["ui_after_marker"] = ui_after
            except Exception as exc:
                result["ui_after_marker_error"] = str(exc)

        if delete_marker_after_create or delete_existing_marker_only:
            result["gui_variable_table_delete_attempted"] = True
            result["marker_row_select_click_before_delete"] = mouse_click_screen(
                name_cell_x,
                name_cell_y,
                wait_seconds=0.5,
            )
            result["screenshot_after_marker_row_select"] = lifecycle_screenshot_hwnd(
                pid,
                dialog_hwnd,
                screenshot_dir,
                "variable_table_after_marker_row_select",
                screenshot_enabled,
            )
            delete_x = int(dialog_rect["left"]) + 318
            delete_y = int(dialog_rect["top"]) + 73
            result["toolbar_delete_variable_click"] = mouse_click_screen(delete_x, delete_y, wait_seconds=1.0)
            windows_after_delete = enum_windows(pid=pid, owen_only=False)
            result["windows_after_delete_click"] = [compact_window_info(window) for window in windows_after_delete]
            confirmation_candidates: list[tuple[int, int, dict[str, Any]]] = []
            for window in windows_after_delete:
                if not bool(window.get("visible")):
                    continue
                hwnd = int(window.get("hwnd") or 0)
                if hwnd in {main_hwnd, dialog_hwnd}:
                    continue
                rect_value = window.get("rect") or {}
                area = int(rect_value.get("width") or 0) * int(rect_value.get("height") or 0)
                if area <= 0 or area > 250000:
                    continue
                title = str(window.get("title") or "").lower()
                class_name = str(window.get("class_name") or "").lower()
                score = 1
                if "#32770" in class_name or "windowsforms" in class_name:
                    score += 4
                if any(term in title for term in ("delete", "remove", "variable", "\u0443\u0434\u0430\u043b", "\u043f\u0435\u0440\u0435\u043c")):
                    score += 2
                confirmation_candidates.append((score, area, window))
            confirmation_candidates.sort(key=lambda item: (-item[0], -item[1]))
            if confirmation_candidates:
                confirmation_window = confirmation_candidates[0][2]
                confirmation_hwnd = int(confirmation_window["hwnd"])
                result["delete_confirmation_window"] = compact_window_info(confirmation_window)
                try:
                    result["focus_delete_confirmation"] = focus_window(
                        {"pid": pid, "hwnd": confirmation_hwnd, "owen_only": False}
                    )
                except Exception as exc:
                    result["focus_delete_confirmation_error"] = str(exc)
                result["delete_confirmation_enter"] = send_raw_hotkey(["ENTER"], wait_seconds=0.8)
            else:
                result["delete_confirmation_window"] = None
            windows_after_delete_resolution = enum_windows(pid=pid, owen_only=False)
            result["windows_after_delete_resolution"] = [
                compact_window_info(window) for window in windows_after_delete_resolution
            ]
            dialog_candidates_after_delete: list[tuple[int, int, dict[str, Any]]] = []
            for window in windows_after_delete_resolution:
                if not bool(window.get("visible")):
                    continue
                hwnd = int(window.get("hwnd") or 0)
                if hwnd == main_hwnd:
                    continue
                rect_value = window.get("rect") or {}
                area = int(rect_value.get("width") or 0) * int(rect_value.get("height") or 0)
                if area >= 100000 and area < 900000:
                    dialog_candidates_after_delete.append((0 if hwnd == dialog_hwnd else 1, -area, window))
            dialog_candidates_after_delete.sort(key=lambda item: (item[0], item[1]))
            if dialog_candidates_after_delete:
                dialog_after_delete = dialog_candidates_after_delete[0][2]
                dialog_hwnd = int(dialog_after_delete["hwnd"])
                dialog_rect = dialog_after_delete["rect"]
                result["variable_table_dialog_after_delete"] = compact_window_info(dialog_after_delete)
                result["variable_table_dialog_closed_after_delete"] = False
                result["screenshot_after_delete_click"] = lifecycle_screenshot_hwnd(
                    pid,
                    dialog_hwnd,
                    screenshot_dir,
                    "variable_table_after_delete_click",
                    screenshot_enabled,
                )
                try:
                    ui_after_delete = save_ui_snapshot("variable_table_after_delete_click", dialog_hwnd)
                    if ui_after_delete:
                        result["ui_after_delete_click"] = ui_after_delete
                except Exception as exc:
                    result["ui_after_delete_click_error"] = str(exc)
            else:
                result["variable_table_dialog_after_delete"] = None
                result["variable_table_dialog_closed_after_delete"] = True
                result["screenshot_after_delete_click"] = {
                    "skipped": True,
                    "reason": "variable table dialog was closed or recreated after delete click",
                    "hwnd": dialog_hwnd,
                }

        if result.get("variable_table_dialog_closed_after_delete"):
            result["ok_button_click"] = {
                "skipped": True,
                "reason": "variable table dialog was already closed after delete click",
            }
        else:
            ok_x = int(dialog_rect["right"]) - 74
            ok_y = int(dialog_rect["bottom"]) - 25
            result["ok_button_click"] = mouse_click_screen(ok_x, ok_y, wait_seconds=1.5)
            time.sleep(1.0)

        def wait_for_main_window_before_save(timeout_seconds: float = 8.0) -> dict[str, Any]:
            deadline = time.time() + max(1.0, min(timeout_seconds, 20.0))
            attempts: list[dict[str, Any]] = []
            while time.time() < deadline:
                candidate_pids = active_pids()
                if process_is_running(pid) and pid not in candidate_pids:
                    candidate_pids.append(pid)
                for current_pid in sorted(programrelay_pids() - baseline_pids):
                    if current_pid not in candidate_pids and process_is_running(current_pid):
                        candidate_pids.append(current_pid)
                attempt: dict[str, Any] = {"pids": candidate_pids}
                if candidate_pids:
                    try:
                        exact_window = select_main_window(scratch_project, candidate_pids)
                        attempt["method"] = "scratch_title_match"
                        attempt["window"] = compact_window_info(exact_window)
                        attempts.append(attempt)
                        result["main_window_wait_before_save_attempts"] = attempts
                        return exact_window
                    except Exception as exc:
                        attempt["scratch_title_match_error"] = str(exc)
                    fallback_candidates: list[tuple[int, int, dict[str, Any]]] = []
                    for candidate_pid in candidate_pids:
                        try:
                            windows = enum_windows(pid=int(candidate_pid), owen_only=False)
                        except Exception as exc:
                            attempt.setdefault("enum_errors", []).append({"pid": candidate_pid, "error": str(exc)})
                            continue
                        for window in windows:
                            if not bool(window.get("visible")):
                                continue
                            hwnd = int(window.get("hwnd") or 0)
                            if not hwnd:
                                continue
                            title = str(window.get("title") or "")
                            class_name = str(window.get("class_name") or "")
                            rect_value = window.get("rect") or {}
                            area = int(rect_value.get("width") or 0) * int(rect_value.get("height") or 0)
                            if area < 100000:
                                continue
                            score = 0
                            if "owen logic" in title.lower():
                                score += 5
                            if str(scratch_project.name).lower() in title.lower():
                                score += 4
                            if str(scratch_project).lower() in title.lower():
                                score += 8
                            if "windowsforms10.window.8" in class_name.lower() or class_name.startswith("HwndWrapper"):
                                score += 2
                            fallback_candidates.append((score, area, window))
                    fallback_candidates.sort(key=lambda item: (-item[0], -item[1]))
                    attempt["fallback_candidates"] = [
                        {
                            "score": score,
                            "area": area,
                            "window": compact_window_info(window),
                        }
                        for score, area, window in fallback_candidates[:8]
                    ]
                    if fallback_candidates:
                        fallback_window = fallback_candidates[0][2]
                        attempt["method"] = "large_visible_programrelay_window"
                        attempt["window"] = compact_window_info(fallback_window)
                        attempts.append(attempt)
                        result["main_window_wait_before_save_attempts"] = attempts
                        return fallback_window
                attempts.append(attempt)
                time.sleep(0.4)
            result["main_window_wait_before_save_attempts"] = attempts
            raise RuntimeError("No visible OWEN Logic main window found before save")

        try:
            result["focus_main_before_save"] = focus_window({"pid": pid, "hwnd": main_hwnd, "owen_only": False})
        except Exception as exc:
            result["focus_main_before_save_error"] = str(exc)
            refreshed_pids = active_pids()
            if pid not in refreshed_pids:
                refreshed_pids.append(pid)
            result["main_window_refresh_before_save_pids"] = refreshed_pids
            try:
                refreshed_main_window = select_main_window(scratch_project, refreshed_pids)
                main_hwnd = int(refreshed_main_window["hwnd"])
                pid = int(refreshed_main_window.get("pid") or pid)
                result["main_window_refreshed_before_save"] = compact_window_info(refreshed_main_window)
                result["focus_main_before_save"] = focus_window({"pid": pid, "hwnd": main_hwnd, "owen_only": False})
            except Exception as refresh_exc:
                result["main_window_refresh_before_save_error"] = str(refresh_exc)
                refreshed_main_window = wait_for_main_window_before_save()
                main_hwnd = int(refreshed_main_window["hwnd"])
                pid = int(refreshed_main_window.get("pid") or pid)
                result["main_window_waited_before_save"] = compact_window_info(refreshed_main_window)
                result["focus_main_before_save"] = focus_window({"pid": pid, "hwnd": main_hwnd, "owen_only": False})
        result["ctrl_s_save_scratch"] = send_raw_hotkey(["CTRL", "S"], wait_seconds=2.0)
        time.sleep(1.0)

        validation_after = add_step("validation_after", project_validate({"project_path": str(scratch_project), "include_warnings": True}))
        variables_after = add_step("variables_after", project_variables_inspect({"project_path": str(scratch_project), "max_items": 500}))
        count_after = variable_count(variables_after)
        marker_variables = [
            variable
            for variable in variables_after.get("variables") or []
            if isinstance(variable, dict) and str(variable.get("name") or "") == marker
        ]
        result["variable_count_after"] = count_after
        result["variable_count_delta"] = count_after - count_before
        result["marker_found_in_scratch_model"] = bool(marker_variables)
        result["marker_absent_in_scratch_model"] = not bool(marker_variables)
        result["marker_variables"] = marker_variables
        result["validation_after"] = {
            "ok": validation_after.get("ok"),
            "error_count": validation_after.get("error_count"),
            "warning_count": validation_after.get("warning_count"),
            "issues_returned": validation_after.get("issues_returned"),
            "issues_truncated": validation_after.get("issues_truncated"),
            "issues": (validation_after.get("issues") or [])[:10],
            "summary": validation_after.get("summary"),
        }
        result["scratch_hash_after_save"] = sha256_file(scratch_project)
        if delete_marker_after_create:
            result["gui_variable_table_create_then_delete_cycle_executed"] = bool(
                result["gui_variable_table_delete_attempted"]
                and result["marker_absent_in_scratch_model"]
                and result["variable_count_delta"] == 0
                and result["validation_after"].get("ok")
            )
            result["gui_variable_table_delete_executed"] = result["gui_variable_table_create_then_delete_cycle_executed"]
            result["ok"] = bool(
                result["gui_variable_table_create_then_delete_cycle_executed"]
                and result["validation_after"].get("ok")
                and sha256_file(source) == source_hash_before
            )
        elif delete_existing_marker_only:
            result["gui_variable_table_delete_executed"] = bool(
                result["gui_variable_table_delete_attempted"]
                and result["marker_found_before_gui_action"]
                and result["marker_absent_in_scratch_model"]
                and result["variable_count_delta"] == -1
                and result["validation_after"].get("ok")
            )
            result["ok"] = bool(
                result["gui_variable_table_delete_executed"]
                and result["validation_after"].get("ok")
                and sha256_file(source) == source_hash_before
            )
        else:
            result["gui_variable_table_create_executed"] = bool(
                result["marker_found_in_scratch_model"]
                and result["variable_count_delta"] == 1
                and result["validation_after"].get("ok")
            )
            result["ok"] = bool(
                result["gui_variable_table_create_executed"]
                and result["validation_after"].get("ok")
                and sha256_file(source) == source_hash_before
            )
    except Exception as exc:
        result["errors"].append(str(exc))
    finally:
        source_hash_after = sha256_file(source)
        result["source_hash_after"] = source_hash_after
        result["source_hash_preserved"] = source_hash_after == source_hash_before
        cleanup_new_processes()
        result["cleanup_requested"] = cleanup
        result["cleanup_results"] = cleanup_results
        result["remaining_new_pids_after_cleanup"] = active_pids()
        result["processes_after_cleanup"] = tasklist_programrelay()
        if delete_marker_after_create:
            result["validation_scope"] = "bounded_gui_variable_table_create_then_delete_marker_on_scratch_copy"
            result["limitation"] = (
                "This probe creates and names exactly one marker variable through the real OWEN Logic variable-table GUI, "
                "uses the variable-table delete toolbar action on the selected marker row, saves only the scratch .owle, "
                "and verifies the marker is absent with the variable count restored. It does not claim arbitrary "
                "variable-table edit/delete parity, catalog tree editing, array authoring, broader network-register wizard/live "
                "parity, COM/TCP access, live-device contact, controller writes, firmware, or calibration."
            )
        elif delete_existing_marker_only:
            result["validation_scope"] = "bounded_gui_variable_table_delete_existing_marker_on_scratch_copy"
            result["limitation"] = (
                "This probe opens a scratch copy that already contains exactly one marker variable, filters the real "
                "OWEN Logic variable table to that marker, uses the variable-table delete toolbar action on the selected "
                "marker row, saves only the scratch .owle, and verifies the marker is absent with the variable count "
                "reduced by one. It does not claim arbitrary variable-table edit/delete parity, catalog tree editing, "
                "array authoring, broader network-register wizard/live parity, COM/TCP access, "
                "live-device contact, controller writes, firmware, or calibration."
            )
        else:
            result["validation_scope"] = "bounded_gui_variable_table_create_one_marker_variable_on_scratch_copy"
            result["limitation"] = (
                "This probe creates and names exactly one marker variable through the real OWEN Logic variable-table GUI, "
                "saves only the scratch .owle, and verifies the marker in the scratch model. It does not claim arbitrary "
                "variable-table edit/delete parity, catalog tree editing, array authoring, broader network-register wizard/live "
                "parity, COM/TCP access, live-device contact, controller writes, firmware, or calibration."
            )
        result["guardrail"] = (
            "Requires allow_safe_runtime=true and allow_gui_variable_edit=true. Source hash is checked before/after; "
            "all GUI edits target a scratch copy. Cleanup stops only ProgramRelayFBD.exe processes created after the probe baseline."
        )
    return result


def project_variable_table_gui_delete_probe(args: dict[str, Any]) -> dict[str, Any]:
    require_windows()
    if not bool(args.get("allow_safe_runtime", False)):
        raise ValueError("owen_logic_project_variable_table_gui_delete_probe requires allow_safe_runtime=true")
    if not bool(args.get("allow_gui_variable_delete", False)):
        raise ValueError("owen_logic_project_variable_table_gui_delete_probe requires allow_gui_variable_delete=true")

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    source = Path(str(args.get("project_path") or "")).expanduser().resolve()
    source_hash_before = sha256_file(source)
    marker = str(args.get("marker") or f"CODEX_GUI_DEL_{timestamp}").strip()
    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{2,47}", marker):
        raise ValueError("marker must be an ASCII variable identifier, 3-48 chars, starting with a letter or underscore")

    scratch_value = args.get("scratch_dir")
    if scratch_value:
        scratch_dir = Path(str(scratch_value)).expanduser().resolve()
    else:
        workbench = find_workbench_root()
        scratch_dir = (
            workbench / "30_LOCAL_HEAVY" / "sandbox_tmp" / "owen_project_variable_table_gui_delete_probe" / timestamp
            if workbench
            else Path.home() / ".codex" / "tmp" / "owen_project_variable_table_gui_delete_probe" / timestamp
        ).resolve()
    if not is_scratch_destination(scratch_dir):
        raise ValueError(f"Refusing variable-table GUI delete output outside scratch/sandbox/local-heavy path: {scratch_dir}")
    scratch_dir.mkdir(parents=True, exist_ok=True)

    preseed_create = project_variable_create(
        {
            "project_path": str(source),
            "scratch_dir": str(scratch_dir / "preseed_variable"),
            "variable_name": marker,
            "data_type": int(args.get("data_type", 0) or 0),
            "default_value": args.get("default_value", 0),
            "is_retain": bool(args.get("is_retain", False)),
            "insert_index": int(args.get("preseed_insert_index", 0)),
        }
    )
    create_scratch_path = (preseed_create.get("scratch_copy") or {}).get("path")
    preseed_validation: dict[str, Any] | None = None
    preseed_marker_variables: list[dict[str, Any]] = []
    preseed_variable_count_after = preseed_create.get("variable_count_after")
    if create_scratch_path:
        preseed_validation = project_validate({"project_path": str(create_scratch_path), "include_warnings": True})
        preseed_variables = project_variables_inspect({"project_path": str(create_scratch_path), "max_items": 500})
        preseed_variable_count_after = sum(
            int(summary.get("variable_count") or 0)
            for summary in preseed_variables.get("document_summaries") or []
            if isinstance(summary, dict)
        )
        preseed_marker_variables = [
            variable
            for variable in preseed_variables.get("variables") or []
            if isinstance(variable, dict) and str(variable.get("name") or "") == marker
        ]
    preseed_ok = bool(
        create_scratch_path
        and preseed_create.get("changed")
        and preseed_marker_variables
        and preseed_validation
        and preseed_validation.get("ok")
        and sha256_file(source) == source_hash_before
    )
    create_probe = {
        "ok": preseed_ok,
        "probe_kind": "scratch_project_variable_preseed_offline_for_gui_delete",
        "source_project": preseed_create.get("source_project"),
        "scratch_copy": preseed_create.get("scratch_copy"),
        "marker": marker,
        "variable_count_before": preseed_create.get("variable_count_before"),
        "variable_count_after": preseed_variable_count_after,
        "variable_count_delta": (
            int(preseed_variable_count_after) - int(preseed_create.get("variable_count_before"))
            if preseed_variable_count_after is not None and preseed_create.get("variable_count_before") is not None
            else None
        ),
        "marker_found_in_scratch_model": bool(preseed_marker_variables),
        "marker_variables": preseed_marker_variables,
        "validation_after": {
            "ok": preseed_validation.get("ok") if isinstance(preseed_validation, dict) else None,
            "error_count": preseed_validation.get("error_count") if isinstance(preseed_validation, dict) else None,
            "warning_count": preseed_validation.get("warning_count") if isinstance(preseed_validation, dict) else None,
        },
        "source_hash_preserved": sha256_file(source) == source_hash_before,
        "offline_variable_preseed_created": preseed_ok,
        "gui_variable_table_create_executed": False,
        "gui_variable_table_edit_attempted": False,
        "cleanup_requested": False,
        "cleanup_results": [],
        "remaining_new_pids_after_cleanup": [],
        "processes_after_cleanup": tasklist_programrelay(),
        "raw_create_result": preseed_create,
    }

    delete_probe: dict[str, Any]
    if preseed_ok and create_scratch_path:
        delete_args = dict(args)
        delete_args.pop("allow_gui_variable_delete", None)
        delete_args.pop("delete_marker_after_create", None)
        delete_args["allow_gui_variable_edit"] = True
        delete_args["delete_existing_marker_only"] = True
        delete_args["skip_filter_for_visible_marker"] = True
        delete_args["project_path"] = str(create_scratch_path)
        delete_args["scratch_dir"] = str(scratch_dir / "delete_probe")
        delete_args["marker"] = marker
        delete_probe = project_variable_table_gui_edit_probe(delete_args)
    else:
        delete_probe = {
            "ok": False,
            "errors": ["Offline preseed did not produce a validated scratch project with an unused marker variable."],
            "marker": marker,
            "source_hash_preserved": None,
            "gui_variable_table_edit_attempted": False,
            "gui_variable_table_delete_attempted": False,
            "gui_variable_table_delete_executed": False,
            "marker_found_in_scratch_model": None,
            "marker_absent_in_scratch_model": None,
            "variable_count_delta": None,
            "validation_after": None,
            "cleanup_requested": args.get("cleanup_launched_process", True),
            "cleanup_results": [],
            "remaining_new_pids_after_cleanup": [],
            "processes_after_cleanup": tasklist_programrelay(),
        }

    source_hash_after = sha256_file(source)
    source_hash_preserved = source_hash_after == source_hash_before
    create_ok = bool(
        create_probe.get("ok")
        and create_probe.get("offline_variable_preseed_created")
        and create_probe.get("marker_found_in_scratch_model")
        and create_probe.get("source_hash_preserved")
    )
    delete_ok = bool(
        delete_probe.get("ok")
        and delete_probe.get("gui_variable_table_delete_executed")
        and delete_probe.get("marker_absent_in_scratch_model")
        and delete_probe.get("variable_count_delta") == -1
        and delete_probe.get("source_hash_preserved")
    )
    wrapper_ok = bool(create_ok and delete_ok and source_hash_preserved)

    errors: list[str] = []
    for label, probe in (("create", create_probe), ("delete", delete_probe)):
        for error in probe.get("errors") or []:
            errors.append(f"{label}: {error}")

    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": wrapper_ok,
        "probe_kind": "scratch_project_variable_table_gui_delete_probe",
        "source_project": safe_file_info(source, include_hash=True),
        "scratch_dir": str(scratch_dir),
        "scratch_copy": delete_probe.get("scratch_copy"),
        "marker": marker,
        "create_probe": create_probe,
        "preseed_create": preseed_create,
        "preseed_validation": create_probe.get("validation_after"),
        "delete_probe": delete_probe,
        "edit_cycle_probe": delete_probe,
        "errors": errors,
        "baseline_programrelayfbd_pids": delete_probe.get("baseline_programrelayfbd_pids") or [],
        "source_hash_before": source_hash_before,
        "source_hash_after": source_hash_after,
        "source_hash_preserved": source_hash_preserved,
        "create_source_hash_preserved": create_probe.get("source_hash_preserved"),
        "delete_source_hash_preserved": delete_probe.get("source_hash_preserved"),
        "variable_count_before": create_probe.get("variable_count_before"),
        "variable_count_after_create": create_probe.get("variable_count_after"),
        "variable_count_before_delete": delete_probe.get("variable_count_before"),
        "variable_count_after": delete_probe.get("variable_count_after"),
        "variable_count_delta": delete_probe.get("variable_count_delta"),
        "marker_found_after_create": create_probe.get("marker_found_in_scratch_model"),
        "marker_preseeded_offline": create_probe.get("offline_variable_preseed_created"),
        "marker_found_in_scratch_model": delete_probe.get("marker_found_in_scratch_model"),
        "marker_absent_in_scratch_model": delete_probe.get("marker_absent_in_scratch_model"),
        "validation_after": delete_probe.get("validation_after"),
        "cleanup_requested": bool(create_probe.get("cleanup_requested")) or bool(delete_probe.get("cleanup_requested")),
        "cleanup_results": [
            {"pass": "create", "cleanup_results": create_probe.get("cleanup_results") or []},
            {"pass": "delete", "cleanup_results": delete_probe.get("cleanup_results") or []},
        ],
        "remaining_new_pids_after_cleanup": delete_probe.get("remaining_new_pids_after_cleanup"),
        "processes_after_cleanup": delete_probe.get("processes_after_cleanup"),
        "opened_serial_port": False,
        "opened_network_socket": False,
        "serial_or_network_access_attempted": False,
        "live_device_action_executed": False,
        "write_to_controller_attempted": False,
        "firmware_or_calibration_action_attempted": False,
        "gui_variable_table_delete_probe_executed": delete_ok,
        "offline_variable_preseed_created": create_probe.get("offline_variable_preseed_created"),
        "gui_variable_table_create_executed": False,
        "gui_variable_table_edit_attempted": bool(
            create_probe.get("gui_variable_table_edit_attempted")
            or delete_probe.get("gui_variable_table_edit_attempted")
        ),
        "gui_variable_table_delete_attempted": delete_probe.get("gui_variable_table_delete_attempted"),
        "gui_variable_table_delete_executed": delete_probe.get("gui_variable_table_delete_executed"),
        "gui_variable_table_create_then_delete_cycle_executed": False,
        "offline_preseed_then_gui_delete_executed": bool(create_ok and delete_ok),
        "gui_variable_table_two_pass_delete_executed": bool(create_ok and delete_ok),
        "gui_variable_table_csv_import_export_executed": False,
        "validation_scope": "bounded_gui_variable_table_delete_unused_marker_on_scratch_copy",
        "limitation": "This pre-seeds one unused marker variable in a scratch project with the guarded offline variable-create tool, then opens that scratch project in OWEN Logic, deletes the marker row through the real GUI toolbar, and verifies the marker is absent with a valid scratch project. It does not claim GUI creation in this delete probe, arbitrary GUI variable-table edit/delete parity, deleting linked variables without model impact, catalog tree editing, array authoring, broader network-register wizard/live parity, COM/TCP access, or live-device contact.",
        "guardrail": "Requires allow_safe_runtime=true and allow_gui_variable_delete=true. The source project is never written; all GUI edits target a scratch copy and source hash is checked before/after. Cleanup stops only ProgramRelayFBD.exe processes created after the probe baseline.",
    }


