def runtime_visible_text(control: dict[str, Any]) -> str:
    return " ".join(
        str(control.get(key) or "")
        for key in (
            "path",
            "name",
            "automation_id",
            "class_name",
            "control_type",
            "localized_control_type",
            "text_pattern_text",
            "value_pattern_value",
            "legacy_name",
            "legacy_value",
            "help_text",
        )
    ).strip()


def runtime_control_content_text(control: dict[str, Any]) -> str:
    return " ".join(
        str(control.get(key) or "")
        for key in (
            "name",
            "text_pattern_text",
            "value_pattern_value",
            "legacy_name",
            "legacy_value",
            "help_text",
        )
    ).strip()


def normalize_visible_token(value: Any) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if value is None:
        return ""
    return str(value).strip()


def build_model_value_targets(io_snapshot: dict[str, Any], max_targets: int = 300) -> list[dict[str, Any]]:
    targets: list[dict[str, Any]] = []
    for document in io_snapshot.get("documents") or []:
        document_id = str(document.get("document_id") or "")
        for variable in document.get("variables") or []:
            if not isinstance(variable, dict):
                continue
            name = str(variable.get("name") or "").strip()
            value = variable.get("raw_default_value")
            value_token = normalize_visible_token(value)
            if name and value_token:
                targets.append(
                    {
                        "kind": "variable_default",
                        "document_id": document_id,
                        "name": name,
                        "unique_id": variable.get("unique_id"),
                        "expected_value": scalar_preview(value),
                        "expected_value_token": value_token,
                    }
                )
        for element in document.get("io_elements") or []:
            if not isinstance(element, dict):
                continue
            names = [
                str(element.get("title") or "").strip(),
                str(element.get("linked_variable_name") or "").strip(),
            ]
            for field, raw_key in (("pin_default_value", "raw_pin_default_value"), ("element_value", "raw_value")):
                value = element.get(raw_key)
                value_token = normalize_visible_token(value)
                if value_token:
                    for name in names:
                        if name:
                            targets.append(
                                {
                                    "kind": field,
                                    "document_id": document_id,
                                    "name": name,
                                    "element_unique_id": element.get("unique_id"),
                                    "expected_value": scalar_preview(value),
                                    "expected_value_token": value_token,
                                }
                            )
                            break
        if len(targets) >= max_targets:
            break
    return targets[:max_targets]


def visible_text_matches_model_target_text(visible_text: str, target: dict[str, Any]) -> bool:
    text_lower = visible_text.lower()
    name = str(target.get("name") or "").strip()
    value_token = str(target.get("expected_value_token") or "").strip()
    if len(name) < 3 or not value_token or not visible_text:
        return False
    if re.search(rf"(?<![\w.]){re.escape(name.lower())}(?![\w.])", text_lower) is None:
        return False
    value_lower = value_token.lower()
    if value_lower in {"true", "false"}:
        return value_lower in text_lower or ("\u0434\u0430" in text_lower if value_lower == "true" else "\u043d\u0435\u0442" in text_lower)
    return re.search(rf"(?<![\w.]){re.escape(value_lower)}(?![\w.])", text_lower) is not None


def visible_name_matches_model_target(control: dict[str, Any], target: dict[str, Any]) -> bool:
    visible_name = str(control.get("name") or "").strip()
    return visible_text_matches_model_target_text(visible_name, target)


def collect_runtime_readback_controls(ui_tree: dict[str, Any], model_targets: list[dict[str, Any]], max_controls: int) -> dict[str, Any]:
    controls = flatten_ui_tree(ui_tree)
    runtime_surface_controls: list[dict[str, Any]] = []
    value_like_controls: list[dict[str, Any]] = []
    model_value_matches: list[dict[str, Any]] = []
    visible_text_parts: list[str] = []
    value_pattern = re.compile(r"(?i)(?:^|[\s:=])(?:true|false|on|off|0|1|\d+(?:[.,]\d+)?)(?:$|[\s;,.])")
    for control in controls:
        visible = runtime_visible_text(control)
        if visible:
            visible_text_parts.append(visible)
        haystack = visible.lower()
        compact = compact_control(control)
        if any(marker in haystack for marker in RUNTIME_SURFACE_MARKERS):
            runtime_surface_controls.append(compact)
        if value_pattern.search(haystack) and any(marker in haystack for marker in RUNTIME_SURFACE_MARKERS):
            value_like_controls.append(compact)
        for target in model_targets:
            if visible_name_matches_model_target(control, target):
                model_value_matches.append(
                    {
                        "target": target,
                        "control": compact,
                        "visible_text": compact_string(str(control.get("name") or ""), 500),
                    }
                )
                break
    matched_row_keys: set[tuple[str, str, str]] = set()
    for row_control in controls:
        row_class = str(row_control.get("class_name") or "").lower()
        row_type = str(row_control.get("control_type") or "").lower()
        row_path = str(row_control.get("path") or "")
        is_data_grid_row = "datagridrow" in row_class
        is_watch_grid_data_item = "variablesdatagrid" in row_path.lower() and "dataitem" in row_type
        if not is_data_grid_row and not is_watch_grid_data_item:
            continue
        if not row_path:
            continue
        row_text_parts = [
            runtime_control_content_text(control)
            for control in controls
            if str(control.get("path") or "") == row_path
            or str(control.get("path") or "").startswith(row_path + "/")
        ]
        row_visible_text = " ".join(part for part in row_text_parts if part)
        for target in model_targets:
            if not visible_text_matches_model_target_text(row_visible_text, target):
                continue
            row_key = (
                row_path,
                str(target.get("name") or ""),
                str(target.get("expected_value_token") or ""),
            )
            if row_key in matched_row_keys:
                continue
            matched_row_keys.add(row_key)
            model_value_matches.append(
                {
                    "target": target,
                    "control": compact_control(row_control),
                    "visible_text": compact_string(row_visible_text, 500),
                    "match_source": "datagrid_row_descendants",
                }
            )
            break
    visible_text_blob = "\n".join(visible_text_parts)
    return {
        "control_count": len(controls),
        "visible_text_chars": len(visible_text_blob),
        "visible_text_preview": compact_string(visible_text_blob, 4000),
        "runtime_surface_control_count": len(runtime_surface_controls),
        "value_like_control_count": len(value_like_controls),
        "model_value_match_count": len(model_value_matches),
        "runtime_surface_controls": runtime_surface_controls[:max_controls],
        "value_like_controls": value_like_controls[:max_controls],
        "model_value_matches": model_value_matches[:max_controls],
        "truncated": (
            len(runtime_surface_controls) > max_controls
            or len(value_like_controls) > max_controls
            or len(model_value_matches) > max_controls
        ),
    }


def find_simulator_watch_window_button_candidate(ui_tree: dict[str, Any]) -> dict[str, Any] | None:
    controls = flatten_ui_tree(ui_tree)
    candidates: list[dict[str, Any]] = []
    for control in controls:
        visible = runtime_visible_text(control).lower()
        control_type = str(control.get("control_type") or "").lower()
        rect = control.get("bounding_rect") or {}
        try:
            x = float(rect.get("x") or 0)
            y = float(rect.get("y") or 0)
            width = float(rect.get("width") or 0)
            height = float(rect.get("height") or 0)
        except (TypeError, ValueError):
            continue
        if "pane" not in control_type:
            continue
        if width < 300 or height < 24 or height > 80:
            continue
        if (
            "\u043f\u0430\u043d\u0435\u043b\u044c \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430" not in visible
            and "simulator panel" not in visible
            and "simulation panel" not in visible
        ):
            continue
        click_x = x + width - 23
        click_y = y + height / 2
        if click_x <= x or click_y <= y:
            continue
        candidates.append(
            {
                "method": "simulator_panel_right_watch_window_button",
                "control": compact_control(control),
                "panel_bounding_rect": rect,
                "click_x": round(click_x, 1),
                "click_y": round(click_y, 1),
                "offset_from_right": 23,
                "offset_from_vertical_center": 0,
                "reason": "Manual section 4.5 documents the simulator-panel watch/view-window button; this uses the right-side button position inside the UIA-detected simulator panel.",
            }
        )
    if not candidates:
        return None
    candidates.sort(
        key=lambda item: (
            float(((item.get("panel_bounding_rect") or {}).get("y")) or 0),
            -float(((item.get("panel_bounding_rect") or {}).get("width")) or 0),
        )
    )
    return candidates[0]


def detect_simulator_watch_window_surface(ui_tree: dict[str, Any], max_controls: int = 20) -> dict[str, Any]:
    controls = flatten_ui_tree(ui_tree)
    matches: list[dict[str, Any]] = []
    markers = (
        "variablesdatagrid",
        "watch window",
        "view window",
        "\u043e\u043a\u043d\u043e \u043f\u0440\u043e\u0441\u043c\u043e\u0442\u0440\u0430",
    )
    for control in controls:
        visible = runtime_visible_text(control).lower()
        automation_id = str(control.get("automation_id") or "").lower()
        class_name = str(control.get("class_name") or "").lower()
        haystack = f"{visible} {automation_id} {class_name}"
        if any(marker in haystack for marker in markers):
            matches.append(compact_control(control))
            if len(matches) >= max_controls:
                break
    return {
        "confirmed": bool(matches),
        "control_count": len(matches),
        "controls": matches,
    }


def find_watch_window_variable_ellipsis_candidate(ui_tree: dict[str, Any]) -> dict[str, Any] | None:
    candidates: list[dict[str, Any]] = []
    for control in flatten_ui_tree(ui_tree):
        if str(control.get("name") or "") != "...":
            continue
        if "variablesdatagrid" not in str(control.get("path") or "").lower():
            continue
        rect = control.get("bounding_rect") or {}
        try:
            x = float(rect.get("x") or 0)
            y = float(rect.get("y") or 0)
            width = float(rect.get("width") or 0)
            height = float(rect.get("height") or 0)
        except (TypeError, ValueError):
            continue
        if width <= 0 or height <= 0:
            continue
        candidates.append(
            {
                "method": "watch_window_variables_grid_first_row_ellipsis",
                "control": compact_control(control),
                "click_x": round(x + width / 2, 1),
                "click_y": round(y + height / 2, 1),
                "reason": "Manual section 4.5 says an empty Name-column row opens the project variable table through the ellipsis button.",
            }
        )
    if not candidates:
        return None
    candidates.sort(
        key=lambda item: (
            float(((item.get("control") or {}).get("bounding_rect") or {}).get("y") or 0),
            float(((item.get("control") or {}).get("bounding_rect") or {}).get("x") or 0),
        )
    )
    return candidates[0]


def find_variable_picker_dialog_candidate(ui_tree: dict[str, Any]) -> dict[str, Any] | None:
    for control in flatten_ui_tree(ui_tree):
        name = str(control.get("name") or "").strip().lower()
        control_type = str(control.get("control_type") or "").lower()
        if name not in {"\u0432\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u0443\u044e", "select variable"}:
            continue
        if "window" not in control_type:
            continue
        rect = control.get("bounding_rect") or {}
        try:
            x = float(rect.get("x") or 0)
            y = float(rect.get("y") or 0)
            width = float(rect.get("width") or 0)
            height = float(rect.get("height") or 0)
        except (TypeError, ValueError):
            continue
        return {
            "method": "variable_picker_dialog_window",
            "control": compact_control(control),
            "x": x,
            "y": y,
            "width": width,
            "height": height,
        }
    return None


def variable_picker_tab_click_candidate(dialog: dict[str, Any], tab: str) -> dict[str, Any]:
    tab_offsets = {"inputs": 28, "outputs": 78, "standard": 146}
    if tab not in tab_offsets:
        raise ValueError("watch_window_variable_picker_tab must be inputs, outputs, or standard")
    x = float(dialog.get("x") or 0)
    y = float(dialog.get("y") or 0)
    return {
        "method": "variable_picker_tab_geometry",
        "tab": tab,
        "click_x": round(x + tab_offsets[tab], 1),
        "click_y": round(y + 36, 1),
        "reason": "The variable picker tab strip is a custom WinForms control without TabItem UIA children, so tab selection uses bounded dialog-relative geometry.",
    }


def find_variable_picker_variable_candidate(ui_tree: dict[str, Any], variable_name: str) -> dict[str, Any] | None:
    wanted = variable_name.strip()
    if not wanted:
        return None
    candidates: list[dict[str, Any]] = []
    for control in flatten_ui_tree(ui_tree):
        visible_values = [
            str(control.get("value_pattern_value") or "").strip(),
            str(control.get("legacy_value") or "").strip(),
            str(control.get("name") or "").strip(),
        ]
        if wanted not in visible_values:
            continue
        rect = control.get("bounding_rect") or {}
        try:
            x = float(rect.get("x") or 0)
            y = float(rect.get("y") or 0)
            width = float(rect.get("width") or 0)
            height = float(rect.get("height") or 0)
        except (TypeError, ValueError):
            continue
        if width <= 0 or height <= 0:
            continue
        candidates.append(
            {
                "method": "variable_picker_value_pattern_match",
                "variable_name": wanted,
                "control": compact_control(control),
                "click_x": round(x + width / 2, 1),
                "click_y": round(y + height / 2, 1),
            }
        )
    if not candidates:
        return None
    candidates.sort(
        key=lambda item: (
            float(((item.get("control") or {}).get("bounding_rect") or {}).get("y") or 0),
            float(((item.get("control") or {}).get("bounding_rect") or {}).get("x") or 0),
        )
    )
    return candidates[0]


def find_variable_picker_ok_button_candidate(ui_tree: dict[str, Any]) -> dict[str, Any] | None:
    for control in flatten_ui_tree(ui_tree):
        name = str(control.get("name") or "").strip().lower()
        automation_id = str(control.get("automation_id") or "").strip().lower()
        control_type = str(control.get("control_type") or "").lower()
        if "button" not in control_type:
            continue
        if automation_id != "okbutton" and name not in {"ok", "\u043e\u043a"}:
            continue
        rect = control.get("bounding_rect") or {}
        try:
            x = float(rect.get("x") or 0)
            y = float(rect.get("y") or 0)
            width = float(rect.get("width") or 0)
            height = float(rect.get("height") or 0)
        except (TypeError, ValueError):
            continue
        if width <= 0 or height <= 0:
            continue
        return {
            "method": "variable_picker_ok_button",
            "control": compact_control(control),
            "click_x": round(x + width / 2, 1),
            "click_y": round(y + height / 2, 1),
        }
    return None


def detect_simulator_blocking_messages(ui_tree: dict[str, Any], max_messages: int = 20) -> list[dict[str, Any]]:
    matches: list[dict[str, Any]] = []
    for control in flatten_ui_tree(ui_tree):
        visible = runtime_visible_text(control)
        haystack = visible.lower()
        if any(marker in haystack for marker in SIMULATOR_BLOCKING_MESSAGE_MARKERS):
            matches.append(
                {
                    "reason": "blocking_text_marker",
                    "control": compact_control(control),
                    "visible_text": compact_string(visible, 500),
                }
            )
            if len(matches) >= max_messages:
                break
        name = str(control.get("name") or "").strip().lower()
        control_type = str(control.get("control_type") or "").lower()
        path = str(control.get("path") or "").lower()
        if (
            name in SIMULATOR_BLOCKING_MODAL_OK_NAMES
            and "button" in control_type
            and "owen logic" in path
            and "propertygridtoolbar" not in path
            and not any(marker in haystack for marker in SIMULATOR_ALLOWED_MODAL_OK_PATH_MARKERS)
        ):
            matches.append(
                {
                    "reason": "modal_ok_button_visible",
                    "control": compact_control(control),
                    "visible_text": compact_string(visible, 500),
                }
            )
            if len(matches) >= max_messages:
                break
    return matches


def evaluate_runtime_assertion(assertion: dict[str, Any], snapshots: list[dict[str, Any]]) -> dict[str, Any]:
    kind = str(assertion.get("kind") or "ui_text_contains").strip()
    snapshot_label = str(assertion.get("snapshot_label") or "").strip()
    selected_snapshots = [
        snapshot
        for snapshot in snapshots
        if not snapshot_label or str(snapshot.get("label") or "") == snapshot_label
    ]
    texts = [
        str((snapshot.get("runtime_summary") or {}).get("visible_text_preview") or "")
        for snapshot in selected_snapshots
    ]
    text_blob = "\n".join(texts)
    result = {
        "kind": kind,
        "snapshot_label": snapshot_label or None,
        "selected_snapshot_count": len(selected_snapshots),
        "ok": False,
    }
    if kind == "ui_text_contains":
        expected = str(assertion.get("text") or assertion.get("expected_text") or "")
        if not expected:
            raise ValueError("ui_text_contains assertion requires text or expected_text")
        case_sensitive = bool(assertion.get("case_sensitive", False))
        haystack = text_blob if case_sensitive else text_blob.lower()
        needle = expected if case_sensitive else expected.lower()
        result.update({"expected_text": expected, "case_sensitive": case_sensitive, "ok": needle in haystack})
        return result
    if kind == "ui_text_regex":
        pattern = str(assertion.get("pattern") or "")
        if not pattern:
            raise ValueError("ui_text_regex assertion requires pattern")
        flags = 0 if bool(assertion.get("case_sensitive", False)) else re.I
        matched = re.search(pattern, text_blob, flags) is not None
        result.update({"pattern": pattern, "ok": matched})
        return result
    if kind == "model_value_visible":
        name = str(assertion.get("name") or assertion.get("variable_name") or "")
        expected = normalize_visible_token(assertion.get("expected"))
        matches: list[dict[str, Any]] = []
        for snapshot in selected_snapshots:
            for match in (snapshot.get("runtime_summary") or {}).get("model_value_matches") or []:
                target = match.get("target") if isinstance(match, dict) else {}
                if not isinstance(target, dict):
                    continue
                if name and name.lower() not in str(target.get("name") or "").lower():
                    continue
                if expected and expected.lower() != str(target.get("expected_value_token") or "").lower():
                    continue
                matches.append(match)
        result.update({"name": name or None, "expected": expected or None, "match_count": len(matches), "matches": matches[:20], "ok": bool(matches)})
        return result
    raise ValueError(f"Unsupported runtime assertion kind: {kind}")


def simulator_live_readback_probe(args: dict[str, Any]) -> dict[str, Any]:
    require_windows()
    if not bool(args.get("allow_safe_runtime", False)):
        raise ValueError("owen_logic_simulator_live_readback_probe requires allow_safe_runtime=true")

    assertions = args.get("assertions") or []
    if not isinstance(assertions, list):
        raise ValueError("assertions must be an array")
    source = Path(str(args.get("project_path") or "")).expanduser().resolve()
    source_hash_before = sha256_file(source)
    scratch_value = args.get("scratch_dir")
    if scratch_value:
        scratch_dir = Path(str(scratch_value)).expanduser().resolve()
    else:
        workbench = find_workbench_root()
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        scratch_dir = (
            workbench / "30_LOCAL_HEAVY" / "sandbox_tmp" / "owen_simulator_live_readback_probe" / timestamp
            if workbench
            else Path.home() / ".codex" / "tmp" / "owen_simulator_live_readback_probe" / timestamp
        ).resolve()
    if not is_scratch_destination(scratch_dir):
        raise ValueError(f"Refusing simulator live readback probe output outside scratch/sandbox/local-heavy path: {scratch_dir}")
    screenshot_dir = scratch_dir / "screenshots"
    ui_dir = scratch_dir / "ui_snapshots"
    screenshot_dir.mkdir(parents=True, exist_ok=True)
    ui_dir.mkdir(parents=True, exist_ok=True)

    scratch = project_scratch_copy(
        {
            "project_path": str(source),
            "scratch_dir": str(scratch_dir),
            "name_suffix": "_sim_live_readback",
        }
    )
    scratch_project = Path(scratch["scratch_copy"]["path"])
    scratch_hash_before = sha256_file(scratch_project)
    loaded = read_owle_sections(scratch_project, include_hashes=False)
    project_section = loaded["sections"].get("Project")
    if not isinstance(project_section, dict):
        raise ValueError("Project section was not found or is not an object")
    static_io_snapshot = simulator_io_snapshot(project_section, str(args.get("document_id")) if args.get("document_id") else None, 300)
    model_targets = build_model_value_targets(static_io_snapshot)
    static_validation_before = project_validate({"project_path": str(scratch_project), "include_warnings": True})

    wait_seconds = max(1, min(float(args.get("wait_seconds", 8)), 120))
    action_wait_seconds = max(0, min(float(args.get("action_wait_seconds", 1)), 10))
    screenshot_enabled = bool(args.get("screenshot", True))
    include_ui_tree = bool(args.get("include_ui_tree", True))
    save_ui_tree = bool(args.get("save_ui_tree", True))
    include_offscreen = bool(args.get("include_offscreen", False))
    max_depth = clamp_int(args.get("max_depth"), 7, 0, 10)
    max_children = clamp_int(args.get("max_children"), 250, 1, 1000)
    max_runtime_controls = clamp_int(args.get("max_runtime_controls"), 100, 1, 500)
    require_value_readback = bool(args.get("require_value_readback", False))
    exercise_watch_window = bool(args.get("exercise_watch_window", False))
    exercise_watch_window_variable_picker = bool(args.get("exercise_watch_window_variable_picker", False))
    watch_window_variable_name = str(args.get("watch_window_variable_name") or "").strip()
    watch_window_variable_picker_tab = str(args.get("watch_window_variable_picker_tab") or "standard").strip().lower()
    if exercise_watch_window_variable_picker:
        if not exercise_watch_window:
            raise ValueError("exercise_watch_window_variable_picker=true requires exercise_watch_window=true")
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{0,127}", watch_window_variable_name):
            raise ValueError("watch_window_variable_name must be a simple ASCII variable identifier when picker automation is enabled")
        if watch_window_variable_picker_tab not in {"inputs", "outputs", "standard"}:
            raise ValueError("watch_window_variable_picker_tab must be inputs, outputs, or standard")
        max_depth = max(max_depth, 10)
        max_children = max(max_children, 1000)
    cleanup = bool(args.get("cleanup_launched_process", True))
    post_open_idle_wait_seconds = max(
        1,
        min(float(args.get("post_open_idle_wait_seconds", max(wait_seconds, 30))), 120),
    )
    dismiss_post_open_dialogs_enabled = bool(args.get("dismiss_post_open_information_dialogs", True))
    launch = None
    pid: int | None = None
    actions: list[dict[str, Any]] = []
    runtime_snapshots: list[dict[str, Any]] = []
    cleanup_result = None
    result: dict[str, Any] | None = None

    def capture_runtime_snapshot(label: str) -> dict[str, Any]:
        running = bool(pid and process_is_running(pid))
        windows_after = enum_windows(pid=pid, owen_only=False) if pid and running else []
        classification = classify_gui_validation_windows(windows_after)
        blocking_dialogs = [
            window
            for window in windows_after
            if select_post_open_information_dialog([window]) is not None
        ]
        shot = lifecycle_screenshot(int(pid), screenshot_dir, label, screenshot_enabled) if pid and running else None
        snapshot: dict[str, Any] = {
            "label": label,
            "running": running,
            "windows": windows_after,
            "window_classification": classification,
            "blocking_dialogs": blocking_dialogs,
            "blocking_messages": [],
            "blocking_message_count": 0,
            "blocking_dialog_count": len(blocking_dialogs),
            "screenshot": shot,
            "ui_snapshot_attempted": include_ui_tree and running,
            "ui_snapshot_ok": False,
            "ui_snapshot_path": None,
            "runtime_summary": None,
            "watch_window_button_candidate": None,
            "watch_window_surface": None,
            "watch_window_variable_ellipsis_candidate": None,
            "variable_picker_dialog_candidate": None,
            "variable_picker_variable_candidate": None,
            "variable_picker_ok_button_candidate": None,
            "ui_error": None,
        }
        if include_ui_tree and running and pid:
            try:
                ui_snapshot = ui_automation_snapshot(
                    {
                        "pid": pid,
                        "owen_only": False,
                        "max_depth": max_depth,
                        "max_children": max_children,
                        "include_offscreen": include_offscreen,
                        "timeout_seconds": 30,
                    }
                )
                ui_tree = ui_snapshot.get("ui_tree") if isinstance(ui_snapshot.get("ui_tree"), dict) else {}
                runtime_summary = collect_runtime_readback_controls(ui_tree, model_targets, max_runtime_controls) if isinstance(ui_tree, dict) else None
                blocking_messages = detect_simulator_blocking_messages(ui_tree) if isinstance(ui_tree, dict) else []
                watch_window_candidate = find_simulator_watch_window_button_candidate(ui_tree) if isinstance(ui_tree, dict) else None
                watch_window_surface = detect_simulator_watch_window_surface(ui_tree) if isinstance(ui_tree, dict) else None
                watch_window_ellipsis_candidate = find_watch_window_variable_ellipsis_candidate(ui_tree) if isinstance(ui_tree, dict) else None
                variable_picker_dialog = find_variable_picker_dialog_candidate(ui_tree) if isinstance(ui_tree, dict) else None
                variable_picker_variable = (
                    find_variable_picker_variable_candidate(ui_tree, watch_window_variable_name)
                    if isinstance(ui_tree, dict) and watch_window_variable_name
                    else None
                )
                variable_picker_ok = find_variable_picker_ok_button_candidate(ui_tree) if isinstance(ui_tree, dict) else None
                snapshot["ui_snapshot_ok"] = True
                snapshot["runtime_summary"] = runtime_summary
                snapshot["watch_window_button_candidate"] = watch_window_candidate
                snapshot["watch_window_surface"] = watch_window_surface
                snapshot["watch_window_variable_ellipsis_candidate"] = watch_window_ellipsis_candidate
                snapshot["variable_picker_dialog_candidate"] = variable_picker_dialog
                snapshot["variable_picker_variable_candidate"] = variable_picker_variable
                snapshot["variable_picker_ok_button_candidate"] = variable_picker_ok
                snapshot["blocking_messages"] = blocking_messages
                snapshot["blocking_message_count"] = len(blocking_messages)
                snapshot["blocking_dialog_count"] = len(blocking_dialogs) + len(blocking_messages)
                if save_ui_tree:
                    output_path = ui_dir / f"{label}.ui.json"
                    output_path.write_text(json.dumps(ui_snapshot, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
                    snapshot["ui_snapshot_path"] = str(output_path)
            except Exception as exc:
                snapshot["ui_error"] = str(exc)
        runtime_snapshots.append(snapshot)
        return snapshot

    def record_runtime_action(label: str, keys: list[str]) -> dict[str, Any]:
        running_before = bool(pid and process_is_running(pid))
        sent = None
        send_error = None
        if running_before:
            try:
                sent = send_hotkey({"pid": pid, "keys": keys, "delay_ms": 250})
            except Exception as exc:
                send_error = str(exc)
        else:
            send_error = "OWEN Logic process was not running before hotkey"
        if action_wait_seconds > 0:
            time.sleep(action_wait_seconds)
        snapshot = capture_runtime_snapshot(label)
        actions.append(
            {
                "label": label,
                "keys": keys,
                "running_before": running_before,
                "running_after": snapshot.get("running"),
                "sent": sent,
                "send_error": send_error,
                "runtime_snapshot_label": snapshot.get("label"),
            }
        )
        return snapshot

    def record_watch_window_action(label: str) -> dict[str, Any]:
        running_before = bool(pid and process_is_running(pid))
        click_result = None
        click_error = None
        candidate = None
        if running_before:
            if runtime_snapshots:
                candidate = runtime_snapshots[-1].get("watch_window_button_candidate")
            if candidate is None:
                candidate = capture_runtime_snapshot(f"{label}_candidate").get("watch_window_button_candidate")
            if candidate:
                try:
                    click_result = mouse_click_screen(
                        float(candidate["click_x"]),
                        float(candidate["click_y"]),
                        wait_seconds=0.6,
                    )
                except Exception as exc:
                    click_error = str(exc)
            else:
                click_error = "Simulator watch-window button candidate was not detected in the UIA tree"
        else:
            click_error = "OWEN Logic process was not running before watch-window click"
        if action_wait_seconds > 0:
            time.sleep(action_wait_seconds)
        snapshot = capture_runtime_snapshot(label)
        actions.append(
            {
                "label": label,
                "kind": "simulator_watch_window_button_click",
                "running_before": running_before,
                "running_after": snapshot.get("running"),
                "candidate": candidate,
                "click_result": click_result,
                "click_error": click_error,
                "runtime_snapshot_label": snapshot.get("label"),
            }
        )
        return snapshot

    def record_watch_window_variable_picker_action(label: str) -> dict[str, Any]:
        running_before = bool(pid and process_is_running(pid))
        click_error = None
        ellipsis_candidate = None
        ellipsis_click = None
        picker_open_snapshot = None
        tab_candidate = None
        tab_click = None
        variable_candidate = None
        variable_click = None
        after_variable_select_snapshot = None
        ok_candidate = None
        ok_click = None
        if running_before:
            if runtime_snapshots:
                ellipsis_candidate = runtime_snapshots[-1].get("watch_window_variable_ellipsis_candidate")
            if ellipsis_candidate is None:
                ellipsis_candidate = capture_runtime_snapshot(f"{label}_ellipsis_candidate").get("watch_window_variable_ellipsis_candidate")
            if not ellipsis_candidate:
                click_error = "Watch-window variable ellipsis button was not detected in the UIA tree"
            else:
                try:
                    ellipsis_click = mouse_click_screen(
                        float(ellipsis_candidate["click_x"]),
                        float(ellipsis_candidate["click_y"]),
                        wait_seconds=0.8,
                    )
                    if action_wait_seconds > 0:
                        time.sleep(action_wait_seconds)
                    picker_open_snapshot = capture_runtime_snapshot(f"{label}_picker_open")
                    dialog_candidate = picker_open_snapshot.get("variable_picker_dialog_candidate")
                    if not dialog_candidate:
                        click_error = "Variable picker dialog was not detected after ellipsis click"
                    else:
                        tab_candidate = variable_picker_tab_click_candidate(dialog_candidate, watch_window_variable_picker_tab)
                        tab_click = mouse_click_screen(
                            float(tab_candidate["click_x"]),
                            float(tab_candidate["click_y"]),
                            wait_seconds=0.8,
                        )
                        if action_wait_seconds > 0:
                            time.sleep(action_wait_seconds)
                        after_tab_snapshot = capture_runtime_snapshot(f"{label}_after_{watch_window_variable_picker_tab}_tab")
                        variable_candidate = after_tab_snapshot.get("variable_picker_variable_candidate")
                        if not variable_candidate:
                            click_error = f"Variable {watch_window_variable_name!r} was not detected in the picker"
                        else:
                            variable_click = mouse_click_screen(
                                float(variable_candidate["click_x"]),
                                float(variable_candidate["click_y"]),
                                wait_seconds=0.5,
                            )
                            if action_wait_seconds > 0:
                                time.sleep(action_wait_seconds)
                            after_variable_select_snapshot = capture_runtime_snapshot(f"{label}_after_variable_select")
                            ok_candidate = after_variable_select_snapshot.get("variable_picker_ok_button_candidate")
                            if not ok_candidate:
                                ok_candidate = after_tab_snapshot.get("variable_picker_ok_button_candidate")
                            if not ok_candidate:
                                click_error = "Variable picker OK button was not detected after variable selection"
                            else:
                                ok_click = mouse_click_screen(
                                    float(ok_candidate["click_x"]),
                                    float(ok_candidate["click_y"]),
                                    wait_seconds=1.0,
                                )
                except Exception as exc:
                    click_error = str(exc)
        else:
            click_error = "OWEN Logic process was not running before watch-window variable picker action"
        if action_wait_seconds > 0:
            time.sleep(action_wait_seconds)
        snapshot = capture_runtime_snapshot(label)
        actions.append(
            {
                "label": label,
                "kind": "simulator_watch_window_variable_picker_select",
                "variable_name": watch_window_variable_name,
                "picker_tab": watch_window_variable_picker_tab,
                "running_before": running_before,
                "running_after": snapshot.get("running"),
                "ellipsis_candidate": ellipsis_candidate,
                "ellipsis_click": ellipsis_click,
                "picker_open_snapshot_label": picker_open_snapshot.get("label") if isinstance(picker_open_snapshot, dict) else None,
                "tab_candidate": tab_candidate,
                "tab_click": tab_click,
                "variable_candidate": variable_candidate,
                "variable_click": variable_click,
                "after_variable_select_snapshot_label": after_variable_select_snapshot.get("label") if isinstance(after_variable_select_snapshot, dict) else None,
                "ok_candidate": ok_candidate,
                "ok_click": ok_click,
                "click_error": click_error,
                "variable_picker_selected": bool(variable_candidate and ok_click and not click_error),
                "runtime_snapshot_label": snapshot.get("label"),
            }
        )
        return snapshot

    try:
        launch = launch_owen_logic({"project_path": str(scratch_project), "wait_seconds": wait_seconds})
        pid = int(launch["pid"])
        windows = wait_for_owen_window(pid, wait_seconds)
        initial_idle = wait_for_lifecycle_idle(pid, post_open_idle_wait_seconds)
        post_open_windows_before_dialog_dismiss = enum_windows(pid=pid, owen_only=False)
        post_open_information_dialog_dismissal_result = None
        idle_after_post_open_dialog_dismiss = None
        windows_after_post_open_dialog_dismiss = post_open_windows_before_dialog_dismiss
        remaining_dialogs_after_post_open_dialog_dismiss: list[dict[str, Any]] = [
            window
            for window in post_open_windows_before_dialog_dismiss
            if str(window.get("class_name") or "").lower() == "#32770"
            or select_post_open_information_dialog([window]) is not None
        ]
        if dismiss_post_open_dialogs_enabled and select_post_open_information_dialog(post_open_windows_before_dialog_dismiss):
            post_open_information_dialog_dismissal_result = dismiss_post_open_information_dialogs(
                pid,
                screenshot_dir,
                screenshot_enabled,
            )
            idle_after_post_open_dialog_dismiss = wait_for_lifecycle_idle(pid, post_open_idle_wait_seconds)
            windows_after_post_open_dialog_dismiss = enum_windows(pid=pid, owen_only=False)
            remaining_dialogs_after_post_open_dialog_dismiss = [
                window
                for window in windows_after_post_open_dialog_dismiss
                if str(window.get("class_name") or "").lower() == "#32770"
                or select_post_open_information_dialog([window]) is not None
            ]
        initial_snapshot = capture_runtime_snapshot("opened_scratch")
        if bool(args.get("exercise_enter_simulator", True)):
            record_runtime_action("after_enter_simulator_shift_f5", GUI_VALIDATION_HOTKEYS["enter_simulator_shift_f5"])
        if exercise_watch_window:
            record_watch_window_action("after_watch_window_button_click")
        if exercise_watch_window_variable_picker:
            record_watch_window_variable_picker_action("after_watch_window_variable_picker")
        if bool(args.get("exercise_step", True)):
            record_runtime_action("after_step_f10", GUI_VALIDATION_HOTKEYS["step_f10"])
        if bool(args.get("exercise_start_stop", False)):
            record_runtime_action("after_start_f6", GUI_VALIDATION_HOTKEYS["start_f6"])
            record_runtime_action("after_stop_f7", GUI_VALIDATION_HOTKEYS["stop_f7"])

        assertion_results = [evaluate_runtime_assertion(assertion, runtime_snapshots) for assertion in assertions if isinstance(assertion, dict)]
        assertions_passed = all(row.get("ok") for row in assertion_results)
        source_hash_after = sha256_file(source)
        scratch_hash_after = sha256_file(scratch_project)
        static_validation_after = project_validate({"project_path": str(scratch_project), "include_warnings": True})
        ui_ok_snapshots = [snapshot for snapshot in runtime_snapshots if snapshot.get("ui_snapshot_ok")]
        runtime_surface_count = sum(int((snapshot.get("runtime_summary") or {}).get("runtime_surface_control_count") or 0) for snapshot in runtime_snapshots)
        value_like_count = sum(int((snapshot.get("runtime_summary") or {}).get("value_like_control_count") or 0) for snapshot in runtime_snapshots)
        model_value_match_count = sum(int((snapshot.get("runtime_summary") or {}).get("model_value_match_count") or 0) for snapshot in runtime_snapshots)
        watch_window_surface_count = sum(int((snapshot.get("watch_window_surface") or {}).get("control_count") or 0) for snapshot in runtime_snapshots)
        runtime_blocking_dialog_count = sum(int(snapshot.get("blocking_dialog_count") or 0) for snapshot in runtime_snapshots)
        runtime_blocking_dialogs = [
            {
                "label": snapshot.get("label"),
                "dialogs": snapshot.get("blocking_dialogs") or [],
                "messages": snapshot.get("blocking_messages") or [],
            }
            for snapshot in runtime_snapshots
            if int(snapshot.get("blocking_dialog_count") or 0) > 0
        ]
        send_errors = [
            action
            for action in actions
            if action.get("send_error")
            or action.get("click_error")
            or ("running_after" in action and not action.get("running_after"))
        ]
        value_readback_confirmed = model_value_match_count > 0
        runtime_surface_confirmed = runtime_surface_count > 0 or value_like_count > 0
        result = {
            "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
            "ok": bool(
                static_validation_before.get("ok")
                and static_validation_after.get("ok")
                and source_hash_before == source_hash_after
                and runtime_snapshots
                and (not include_ui_tree or ui_ok_snapshots)
                and not send_errors
                and not remaining_dialogs_after_post_open_dialog_dismiss
                and runtime_blocking_dialog_count == 0
                and assertions_passed
                and runtime_surface_confirmed
                and (value_readback_confirmed or not require_value_readback)
            ),
            "source_project": safe_file_info(source, include_hash=True),
            "scratch_copy": safe_file_info(scratch_project, include_hash=True),
            "scratch_dir": str(scratch_dir),
            "launch": launch,
            "windows_after_launch": windows,
            "idle_after_launch": initial_idle,
            "post_open_idle_wait_seconds": post_open_idle_wait_seconds,
            "dismiss_post_open_information_dialogs_requested": dismiss_post_open_dialogs_enabled,
            "post_open_windows_before_dialog_dismiss": post_open_windows_before_dialog_dismiss,
            "post_open_information_dialog_dismissal_result": post_open_information_dialog_dismissal_result,
            "idle_after_post_open_dialog_dismiss": idle_after_post_open_dialog_dismiss,
            "windows_after_post_open_dialog_dismiss": windows_after_post_open_dialog_dismiss,
            "remaining_dialogs_after_post_open_dialog_dismiss": remaining_dialogs_after_post_open_dialog_dismiss,
            "initial_snapshot": initial_snapshot,
            "actions": actions,
            "runtime_snapshots": runtime_snapshots,
            "runtime_snapshot_count": len(runtime_snapshots),
            "ui_snapshot_ok_count": len(ui_ok_snapshots),
            "runtime_surface_control_count_total": runtime_surface_count,
            "value_like_control_count_total": value_like_count,
            "model_value_match_count_total": model_value_match_count,
            "watch_window_surface_control_count_total": watch_window_surface_count,
            "runtime_blocking_dialog_count_total": runtime_blocking_dialog_count,
            "runtime_blocking_dialogs": runtime_blocking_dialogs,
            "runtime_surface_confirmed": runtime_surface_confirmed,
            "watch_window_surface_confirmed": watch_window_surface_count > 0,
            "watch_window_variable_picker_attempted": exercise_watch_window_variable_picker,
            "watch_window_variable_picker_selected": any(bool(action.get("variable_picker_selected")) for action in actions),
            "watch_window_variable_name": watch_window_variable_name or None,
            "value_readback_required": require_value_readback,
            "live_simulator_value_readback_confirmed": value_readback_confirmed,
            "runtime_assertions": assertion_results,
            "runtime_assertions_passed": assertions_passed,
            "model_value_targets_returned": len(model_targets),
            "model_value_targets_sample": model_targets[:30],
            "static_io_snapshot_summary": {
                "documents_returned": static_io_snapshot.get("documents_returned"),
                "document_summaries": [
                    {
                        "document_id": document.get("document_id"),
                        "variable_count": document.get("variable_count"),
                        "io_element_count": document.get("io_element_count"),
                    }
                    for document in static_io_snapshot.get("documents", [])[:20]
                    if isinstance(document, dict)
                ],
            },
            "static_validation_before": static_validation_before,
            "static_validation_after": static_validation_after,
            "source_hash_before": source_hash_before,
            "source_hash_after": source_hash_after,
            "source_hash_preserved": source_hash_before == source_hash_after,
            "scratch_hash_before": scratch_hash_before,
            "scratch_hash_after": scratch_hash_after,
            "scratch_project_exists": scratch_project.exists(),
            "screenshots": [str(path) for path in sorted(screenshot_dir.glob("*.png"))],
            "ui_snapshot_files": [str(path) for path in sorted(ui_dir.glob("*.ui.json"))],
            "risk_class": "safe_runtime",
            "validation_scope": "bounded_gui_simulator_runtime_surface_probe_and_ui_visible_assertions",
            "headless_compiler_used": False,
            "full_compiler_diagnostics_claimed": False,
            "opened_serial_port": False,
            "opened_network_socket": False,
            "live_device_action_executed": False,
            "runtime_limitation": "This tool probes OWEN Logic's live simulator GUI surface through UI Automation and only confirms value readback when a project model value is visibly matched in UI text. If UIA does not expose values, live_simulator_value_readback_confirmed remains false.",
            "guardrail": "Only a scratch copy is opened in OWEN Logic. No live-device, COM/IP, network, download, firmware, calibration, or device-setting action is executed. Runtime assertions are limited to UI-visible text captured from the scratch-opened simulator window.",
        }
    finally:
        if cleanup and pid:
            cleanup_result = stop_process_best_effort(pid)
            try:
                (scratch_dir / "cleanup_result.json").write_text(
                    json.dumps(cleanup_result, ensure_ascii=False, indent=2) + "\n",
                    encoding="utf-8",
                )
            except Exception:
                pass
    if result is None:
        raise RuntimeError("OWEN Logic simulator live readback probe did not produce a result")
    result["cleanup_requested"] = cleanup
    result["cleanup_result"] = cleanup_result
    result["cleanup_sidecar_path"] = str(scratch_dir / "cleanup_result.json") if cleanup_result else None
    result["processes_after_cleanup"] = tasklist_programrelay()
    return result


def resolve_scratch_write_target(args: dict[str, Any], name_suffix: str) -> dict[str, Any]:
    source = Path(str(args.get("project_path") or "")).expanduser().resolve()
    if not source.exists():
        raise FileNotFoundError(f"Project file not found: {source}")
    if not source.is_file():
        raise ValueError(f"Project path is not a file: {source}")
    if source.suffix.lower() != ".owle":
        raise ValueError(f"Scratch project-write tools currently support ZIP-based .owle files only: {source}")

    if bool(args.get("write_in_place", False)):
        if not bool(args.get("confirm_project_path_is_scratch", False)):
            raise ValueError("write_in_place=true requires confirm_project_path_is_scratch=true")
        if not is_scratch_destination(source):
            raise ValueError(f"Refusing in-place project write outside scratch/sandbox/local-heavy path: {source}")
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup = source.with_name(f"{source.stem}_backup_before_write_{timestamp}{source.suffix}")
        shutil.copy2(source, backup)
        return {
            "source": safe_file_info(source, include_hash=True),
            "target_path": source,
            "backup": safe_file_info(backup, include_hash=True),
            "scratch_copy": None,
            "write_mode": "in_place_confirmed_scratch",
        }

    scratch = project_scratch_copy(
        {
            "project_path": str(source),
            "scratch_dir": args.get("scratch_dir"),
            "name_suffix": name_suffix,
        }
    )
    return {
        "source": scratch["source"],
        "target_path": Path(str(scratch["scratch_copy"]["path"])).expanduser().resolve(),
        "backup": None,
        "scratch_copy": scratch["scratch_copy"],
        "write_mode": "copied_to_scratch",
    }


def read_owle_raw_entries(project: Path) -> list[dict[str, Any]]:
    if not zipfile.is_zipfile(project):
        raise ValueError(f"Project file is not a ZIP-based .owle container: {project}")
    entries: list[dict[str, Any]] = []
    with zipfile.ZipFile(project) as archive:
        for zip_info in archive.infolist():
            entries.append(
                {
                    "name": zip_info.filename,
                    "data": archive.read(zip_info.filename),
                    "date_time": zip_info.date_time,
                    "compress_type": zip_info.compress_type,
                    "external_attr": zip_info.external_attr,
                }
            )
    return entries


def read_project_section_from_entries(entries: list[dict[str, Any]]) -> dict[str, Any]:
    for entry in entries:
        if entry["name"] == "Project":
            return json.loads(entry["data"].decode("utf-8"))
    raise ValueError("Project section was not found in .owle container")


def write_owle_json_section(project: Path, entries: list[dict[str, Any]], section_name: str, section_value: Any) -> None:
    temp = project.with_name(f"{project.stem}.tmp_write{project.suffix}")
    section_text = json.dumps(section_value, ensure_ascii=False, indent=2).replace("\n", "\r\n")
    section_bytes = section_text.encode("utf-8")
    saw_section = False
    with zipfile.ZipFile(temp, "w") as archive:
        for entry in entries:
            info = zipfile.ZipInfo(entry["name"])
            info.date_time = entry.get("date_time") or (1980, 1, 1, 0, 0, 0)
            info.compress_type = entry.get("compress_type") or zipfile.ZIP_DEFLATED
            info.external_attr = int(entry.get("external_attr") or 0)
            data = section_bytes if entry["name"] == section_name else entry["data"]
            if entry["name"] == section_name:
                saw_section = True
            archive.writestr(info, data)
    if not saw_section:
        temp.unlink(missing_ok=True)
        raise ValueError(f"{section_name} section was not found in .owle container")
    os.replace(temp, project)


def write_owle_project_section(project: Path, entries: list[dict[str, Any]], project_section: dict[str, Any]) -> None:
    write_owle_json_section(project, entries, "Project", project_section)


def first_project_document(project_section: dict[str, Any]) -> tuple[str, dict[str, Any]]:
    for document_id, document in project_section.items():
        if isinstance(document, dict) and isinstance(document.get("DocumentModel"), dict):
            return str(document_id), document
    raise ValueError("No project document with DocumentModel was found")


def select_project_document(project_section: dict[str, Any], document_id: str | None = None) -> tuple[str, dict[str, Any]]:
    if document_id:
        document = project_section.get(document_id)
        if not isinstance(document, dict) or not isinstance(document.get("DocumentModel"), dict):
            raise ValueError(f"DocumentModel was not found for document_id={document_id}")
        return document_id, document
    return first_project_document(project_section)


def scalar_preview(value: Any) -> Any:
    if isinstance(value, str):
        return compact_string(value, 180)
    if isinstance(value, (int, float, bool)) or value is None:
        return value
    return {"type": type(value).__name__}


def project_metadata_set(args: dict[str, Any]) -> dict[str, Any]:
    target = resolve_scratch_write_target(args, "_metadata_scratch")
    project_path = Path(str(target["target_path"]))
    before_hash = sha256_file(project_path)
    entries = read_owle_raw_entries(project_path)
    project_section = read_project_section_from_entries(entries)
    document_id, document = select_project_document(project_section, args.get("document_id"))
    model = document["DocumentModel"]

    allowed_updates: dict[str, Any] = {}
    if args.get("last_changing_application_version") is not None:
        version = str(args.get("last_changing_application_version") or "").strip()
        if not re.fullmatch(r"\d+(?:\.\d+){0,3}", version):
            raise ValueError("last_changing_application_version must look like a dotted numeric version")
        allowed_updates["LastChangingApplicationVersion"] = version
    if not allowed_updates:
        raise ValueError("No safe metadata fields were provided to update")

    before = {key: scalar_preview(model.get(key)) for key in sorted(allowed_updates)}
    for key, value in allowed_updates.items():
        model[key] = value
    after = {key: scalar_preview(model.get(key)) for key in sorted(allowed_updates)}
    write_owle_project_section(project_path, entries, project_section)
    after_hash = sha256_file(project_path)

    return {
        "source_project": target["source"],
        "scratch_copy": target["scratch_copy"] or safe_file_info(project_path, include_hash=True),
        "backup": target["backup"],
        "write_mode": target["write_mode"],
        "document_id": document_id,
        "updated_fields": sorted(allowed_updates),
        "before": before,
        "after": after,
        "target_hash_before": before_hash,
        "target_hash_after": after_hash,
        "changed": before_hash != after_hash,
        "source_hash_after": sha256_file(Path(str(target["source"]["path"]))),
        "audit_note": compact_string(str(args.get("audit_note") or "")),
        "risk_class": "safe_write_project",
        "guardrail": "Only safe metadata fields were patched, and only on a scratch copy or explicitly confirmed scratch path.",
    }


def target_family(dev_value: Any) -> str | None:
    value = str(dev_value or "").strip().upper()
    if not value:
        return None
    if value == "MACRO":
        return "MACRO"
    match = re.match(r"([A-Z]+\d+)", value)
    if match:
        return match.group(1)
    return value.split("_", 1)[0].split("-", 1)[0] or value


def parse_map_version_catalog(path: Path, source_name: str, max_items: int) -> list[dict[str, Any]]:
    if not path.exists():
        return []
    text = path.read_text(encoding="utf-8", errors="replace")
    rows: list[dict[str, Any]] = []
    pattern = re.compile(r"<!--\s*(?P<label>.*?)\s*-->\s*<VersionSchema>\s*(?P<body>.*?)\s*</VersionSchema>", re.S)
    for match in pattern.finditer(text):
        label = re.sub(r"\s+", " ", match.group("label")).strip()
        body = match.group("body")
        dev_value = label.split("(", 1)[0].strip()
        if not re.fullmatch(r"[A-Za-z0-9_.-]+", dev_value):
            continue

        def tag_value(tag: str) -> str | None:
            tag_match = re.search(rf"<{tag}>\s*(.*?)\s*</{tag}>", body, re.S)
            return tag_match.group(1).strip() if tag_match else None

        rows.append(
            {
                "dev_value": dev_value,
                "family": target_family(dev_value),
                "label": label,
                "id": tag_value("Id"),
                "version": tag_value("Version"),
                "pr_handler": tag_value("PrHandler"),
                "source": source_name,
                "path": str(path),
            }
        )
        if len(rows) >= max_items:
            break
    return rows


def installed_target_catalog(max_items: int = 120) -> dict[str, Any]:
    install = find_installation_data()
    install_dir_value = install.get("install_dir")
    if not install_dir_value:
        return {"installation": install, "items": [], "valid_dev_values": [], "issue": "OWEN Logic installation directory was not found"}
    install_dir = Path(str(install_dir_value))
    converter_path = install.get("converter_executable")
    converter_dir = Path(str(converter_path)).parent if converter_path else install_dir / "ProjectJsonConverter"
    sources = [
        ("main_mapVersion", install_dir / "mapVersion.xml"),
        ("converter_mapVersion", converter_dir / "mapVersion.xml"),
    ]
    items: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for source_name, path in sources:
        remaining = max(0, max_items - len(items))
        if remaining <= 0:
            break
        for row in parse_map_version_catalog(path, source_name, remaining):
            key = (str(row.get("dev_value") or "").upper(), str(row.get("source") or ""))
            if key not in seen:
                seen.add(key)
                items.append(row)
    canonical: dict[str, str] = {}
    for row in items:
        dev_value = str(row.get("dev_value") or "")
        canonical.setdefault(dev_value.upper(), dev_value)
    return {
        "installation": install,
        "items": items,
        "valid_dev_values": sorted(canonical.values(), key=lambda value: value.upper()),
        "sources": [{"name": name, "path": str(path), "exists": path.exists()} for name, path in sources],
        "truncated": len(items) >= max_items,
    }


def target_catalog_lookup(catalog: dict[str, Any]) -> dict[str, str]:
    lookup: dict[str, str] = {}
    for value in catalog.get("valid_dev_values") or []:
        lookup[str(value).upper()] = str(value)
    return lookup


def summarize_project_target_document(document_id: str, document: dict[str, Any], sections: dict[str, Any] | None = None) -> dict[str, Any]:
    model = document.get("DocumentModel") if isinstance(document.get("DocumentModel"), dict) else {}
    elements = model.get("Elements") if isinstance(model.get("Elements"), list) else []
    connectors = model.get("ConnectorModels") if isinstance(model.get("ConnectorModels"), list) else []
    variables = model.get("Variables") if isinstance(model.get("Variables"), list) else []
    settings = document.get("ProjectSettingModels") if isinstance(document.get("ProjectSettingModels"), list) else []
    module_counts: dict[str, int] = {}
    variable_binding_count = 0
    for element in elements:
        if not isinstance(element, dict):
            continue
        module_name = str(element.get("ModuleName") or "").strip()
        if module_name:
            module_counts[module_name] = module_counts.get(module_name, 0) + 1
        element_model = element.get("ElementModel") if isinstance(element.get("ElementModel"), dict) else {}
        if element_model.get("VariableInfoUId"):
            variable_binding_count += 1
    modbus_device_count = 0
    for setting in settings:
        if isinstance(setting, dict) and isinstance(setting.get("DeviceModels"), list):
            modbus_device_count += len(setting.get("DeviceModels") or [])
    visualization_present = bool(sections and sections.get("Visualization"))
    dev_value = model.get("DevValue")
    discriminator = document.get("Discriminator")
    kind = "macro" if str(dev_value or "").upper() == "MACRO" or discriminator == 2 else "project"
    return {
        "document_id": document_id,
        "kind": kind,
        "dev_value": dev_value,
        "family": target_family(dev_value),
        "discriminator": discriminator,
        "application_version_created": model.get("ApplicationVersionCreated"),
        "last_changing_application_version": model.get("LastChangingApplicationVersion"),
        "element_count": len(elements),
        "connector_count": len(connectors),
        "variable_count": len(variables),
        "module_counts": dict(sorted(module_counts.items())),
        "project_setting_count": len(settings),
        "modbus_device_count": modbus_device_count,
        "variable_binding_element_count": variable_binding_count,
        "visualization_section_present": visualization_present,
        "key_file_name_present": bool(model.get("KeyFileName")),
    }


def target_migration_audit(summary: dict[str, Any]) -> dict[str, Any]:
    warnings: list[str] = []
    if summary.get("module_counts"):
        warnings.append("hardware I/O/module elements exist; manual section 8.5 says target migration may add/remove I/O and break incompatible links")
    if int(summary.get("connector_count") or 0) > 0:
        warnings.append("FBD connectors exist; validate and repair broken links after target migration")
    if int(summary.get("modbus_device_count") or 0) > 0:
        warnings.append("Modbus/interface settings exist; manual section 8.5 says unsupported interfaces may be removed during migration")
    if summary.get("visualization_section_present"):
        warnings.append("Visualization exists; manual section 8.5 describes screen/display transfer and possible PR205/PR225 scaling behavior")
    if int(summary.get("variable_binding_element_count") or 0) > 0:
        warnings.append("variable bindings exist; manual section 8.5 says bindings to missing target parameters may be removed")
    return {
        "manual_section": "rp_owen_logic.pdf section 8.5 target platform change",
        "static_warnings": warnings,
        "requires_gui_or_full_migration_engine_for_complete_claim": True,
        "dev_value_patch_scope": "DocumentModel.DevValue metadata only; does not add/remove I/O, modules, interfaces, screens, variables or functional blocks",
    }


def project_target_documents(project_section: dict[str, Any], sections: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for document_id, document in project_section.items():
        if not isinstance(document, dict) or not isinstance(document.get("DocumentModel"), dict):
            continue
        model = document["DocumentModel"]
        if "DevValue" in model:
            rows.append(summarize_project_target_document(str(document_id), document, sections))
    return rows


def select_target_document(project_section: dict[str, Any], document_id: str | None = None) -> tuple[str, dict[str, Any], dict[str, Any]]:
    if document_id:
        selected_id, document = select_project_document(project_section, document_id)
        summary = summarize_project_target_document(selected_id, document)
        if summary.get("dev_value") is None:
            raise ValueError(f"DocumentModel.DevValue was not found for document_id={selected_id}")
        return selected_id, document, summary
    candidates: list[tuple[str, dict[str, Any], dict[str, Any]]] = []
    for candidate_id, document in project_section.items():
        if isinstance(document, dict) and isinstance(document.get("DocumentModel"), dict):
            summary = summarize_project_target_document(str(candidate_id), document)
            if summary.get("dev_value") is not None and summary.get("kind") != "macro":
                candidates.append((str(candidate_id), document, summary))
    if not candidates:
        raise ValueError("No non-macro project document with DocumentModel.DevValue was found")
    if len(candidates) > 1:
        raise ValueError("More than one non-macro target document was found; provide document_id")
    return candidates[0]


def project_target_inspect(args: dict[str, Any]) -> dict[str, Any]:
    project_path = Path(str(args.get("project_path") or "")).expanduser().resolve()
    loaded = read_owle_sections(project_path, include_hashes=True)
    project_section = loaded["sections"].get("Project")
    if not isinstance(project_section, dict):
        raise ValueError("Project section is missing or not a JSON object")
    documents = project_target_documents(project_section, loaded["sections"])
    selected_document: dict[str, Any] | None = None
    if args.get("document_id"):
        selected_id, selected_raw = select_project_document(project_section, str(args.get("document_id")))
        selected_document = summarize_project_target_document(selected_id, selected_raw, loaded["sections"])
    catalog = installed_target_catalog(clamp_int(args.get("max_catalog_items"), 80, 1, 500)) if bool(args.get("include_catalog", True)) else None
    audits = []
    if bool(args.get("include_migration_audit", True)):
        for row in documents:
            if row.get("kind") != "macro":
                audits.append({"document_id": row["document_id"], **target_migration_audit(row)})
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "file": loaded["file"],
        "documents": documents,
        "selected_document": selected_document,
        "target_catalog": catalog,
        "migration_audits": audits,
        "read_only": True,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "launched_gui": False,
        "guardrail": "This tool only reads .owle target metadata and installed catalog files. It does not execute the OWEN Logic target-platform wizard.",
    }


