def target_coverage_audit(args: dict[str, Any]) -> dict[str, Any]:
    include_details = bool(args.get("include_operation_details", True))
    include_tool_names = bool(args.get("include_tool_names", True))
    operations: list[dict[str, Any]] = []
    for row in TARGET_OPERATION_COVERAGE:
        item = dict(row)
        if not include_tool_names:
            item.pop("tools", None)
        operations.append(item)

    status_counts: dict[str, int] = {}
    scope_counts: dict[str, int] = {}
    for row in TARGET_OPERATION_COVERAGE:
        status = str(row.get("status") or "unknown")
        scope = str(row.get("scope") or "unknown")
        status_counts[status] = status_counts.get(status, 0) + 1
        scope_counts[scope] = scope_counts.get(scope, 0) + 1

    proven = [
        row["operation"]
        for row in TARGET_OPERATION_COVERAGE
        if row.get("status") == "proven_current_safe_scope"
    ]
    partial = [
        row["operation"]
        for row in TARGET_OPERATION_COVERAGE
        if row.get("status") == "partial_semantic_gap"
    ]
    blocked = [
        row["operation"]
        for row in TARGET_OPERATION_COVERAGE
        if str(row.get("status") or "").startswith("blocked_")
    ]
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": True,
        "read_only": True,
        "opened_gui": False,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "live_device_action_executed": False,
        "project_mutated": False,
        "target_platform_migration_executed": False,
        "coverage_domain": "owen_logic_target_platform",
        "status_counts": status_counts,
        "scope_counts": scope_counts,
        "proven_operation_count": len(proven),
        "partial_operation_count": len(partial),
        "blocked_operation_count": len(blocked),
        "proven_operations": proven,
        "partial_operations": partial,
        "blocked_operations": blocked,
        "operations": operations if include_details else [],
        "remaining_gap_bucket": "target_gui_migration_or_live_parity",
        "remaining_gap_summary": (
            "Installed target catalog inventory, project target metadata inspection, static migration-impact audit, "
            "scratch-only target metadata patching, bounded target-platform GUI command/wizard surface evidence, and one "
            "bounded PR200 scratch GUI target migration Create/save/readback path are covered. Broad every-target "
            "family/modification parity, vendor backup/version dialog matrix coverage, and live controller target execution "
            "remain unproven or blocked by live-device preflight."
        ),
        "guardrail": (
            "This audit is read-only and does not open OWEN Logic or mutate projects. Treat only proven_current_safe_scope "
            "operations as callable under their own required opt-ins; do not promote metadata patching, wizard surface "
            "evidence, or the single proven PR200 scratch migration path to broad every-target migration completion."
        ),
    }


def normalize_dev_value(value: Any) -> str:
    dev_value = re.sub(r"\s+", "", str(value or "")).strip()
    if not dev_value:
        raise ValueError("new_dev_value must not be empty")
    if len(dev_value) > 80:
        raise ValueError("new_dev_value must be 80 characters or less")
    if not re.fullmatch(r"[A-Za-z0-9_.-]+", dev_value):
        raise ValueError("new_dev_value may contain only letters, digits, underscore, dash and dot")
    return dev_value


def project_target_patch(args: dict[str, Any]) -> dict[str, Any]:
    if not bool(args.get("allow_target_metadata_patch", False)):
        raise ValueError("allow_target_metadata_patch=true is required because target metadata changes can invalidate project hardware assumptions")
    target = resolve_scratch_write_target(args, "_target_patch_scratch")
    project_path = Path(str(target["target_path"]))
    before_hash = sha256_file(project_path)
    entries = read_owle_raw_entries(project_path)
    project_section = read_project_section_from_entries(entries)
    document_id, document, before_summary = select_target_document(project_section, args.get("document_id"))
    if before_summary.get("kind") == "macro":
        raise ValueError("Refusing to patch target metadata on a macro document")
    current_dev_value = normalize_dev_value(before_summary.get("dev_value"))
    expected = args.get("expected_current_dev_value")
    if expected is not None and normalize_dev_value(expected).upper() != current_dev_value.upper():
        raise ValueError("Selected target DevValue does not match expected_current_dev_value")
    new_dev_value = normalize_dev_value(args.get("new_dev_value"))
    if new_dev_value.upper() == current_dev_value.upper():
        raise ValueError("Target metadata patch would not change DocumentModel.DevValue")

    catalog = installed_target_catalog(500)
    lookup = target_catalog_lookup(catalog)
    canonical_new = lookup.get(new_dev_value.upper())
    if canonical_new:
        new_dev_value = canonical_new
    elif not bool(args.get("allow_unknown_dev_value", False)):
        raise ValueError(f"new_dev_value is not present in installed mapVersion catalog: {new_dev_value}")

    current_family = target_family(current_dev_value)
    new_family = target_family(new_dev_value)
    if current_family != new_family and not bool(args.get("allow_cross_family_target", False)):
        raise ValueError(
            f"Refusing cross-family target metadata patch from {current_family} to {new_family}; "
            "set allow_cross_family_target=true only for an explicit scratch migration experiment"
        )

    before_audit = target_migration_audit(before_summary)
    model = document["DocumentModel"]
    model["DevValue"] = new_dev_value
    write_owle_project_section(project_path, entries, project_section)
    after_hash = sha256_file(project_path)
    after_entries = read_owle_raw_entries(project_path)
    after_project_section = read_project_section_from_entries(after_entries)
    _, after_document, after_summary = select_target_document(after_project_section, document_id)
    after_summary = summarize_project_target_document(document_id, after_document, read_owle_sections(project_path, include_hashes=False)["sections"])
    validation = None
    if bool(args.get("validate_after", True)):
        validation = project_validate({"project_path": str(project_path), "include_warnings": True})
    after_audit = target_migration_audit(after_summary) if bool(args.get("include_migration_audit", True)) else None
    source_path = Path(str(target["source"]["path"]))
    source_hash_after = sha256_file(source_path)
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "source_project": target["source"],
        "scratch_copy": target["scratch_copy"] or safe_file_info(project_path, include_hash=True),
        "backup": target["backup"],
        "write_mode": target["write_mode"],
        "document_id": document_id,
        "before": before_summary,
        "after": after_summary,
        "before_audit": before_audit,
        "after_audit": after_audit,
        "target_hash_before": before_hash,
        "target_hash_after": after_hash,
        "changed": before_hash != after_hash,
        "source_hash_after": source_hash_after,
        "source_hash_preserved": source_hash_after == target["source"].get("sha256"),
        "validation_after": validation,
        "catalog_match": bool(canonical_new),
        "current_family": current_family,
        "new_family": new_family,
        "risk_class": "safe_write_project",
        "opened_serial_port": False,
        "opened_network_socket": False,
        "launched_gui": False,
        "gui_target_wizard_executed": False,
        "full_target_migration_claimed": False,
        "guardrail": "Only DocumentModel.DevValue target metadata was patched on a scratch copy or explicitly confirmed scratch path. This is not OWEN Logic GUI target-platform migration and does not apply the full section 8.5 compatibility transformations.",
    }


