def all_install_files(install_dir: Path) -> list[Path]:
    try:
        return sorted((path for path in install_dir.rglob("*") if path.is_file()), key=lambda item: str(item).lower())
    except OSError:
        return []


def program_file_counts(install_dir: Path, files: list[Path]) -> dict[str, Any]:
    by_extension: dict[str, int] = {}
    by_top_dir: dict[str, int] = {}
    for path in files:
        extension = path.suffix.lower() or "<none>"
        by_extension[extension] = by_extension.get(extension, 0) + 1
        try:
            relative = path.relative_to(install_dir)
            top_dir = relative.parts[0] if len(relative.parts) > 1 else "<root>"
        except ValueError:
            top_dir = "<outside>"
        by_top_dir[top_dir] = by_top_dir.get(top_dir, 0) + 1
    return {
        "total_files": len(files),
        "by_extension": dict(sorted(by_extension.items(), key=lambda item: (-item[1], item[0]))),
        "by_top_dir": dict(sorted(by_top_dir.items(), key=lambda item: (-item[1], item[0]))),
    }


def bounded_program_files(
    install_dir: Path,
    files: list[Path],
    predicate: Any,
    max_items: int,
    include_hashes: bool,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for path in files:
        if not predicate(path):
            continue
        row = {**safe_file_info(path, include_hash=include_hashes), "relative_path": safe_relative(path, install_dir)}
        if path.suffix.lower() == ".exe":
            row["version"] = file_version(path)
        rows.append(row)
        if len(rows) >= max_items:
            break
    return rows


def program_deps_summary(install_dir: Path, max_items: int) -> dict[str, Any] | None:
    deps_path = install_dir / "ProgramRelayFBD.deps.json"
    if not deps_path.exists():
        return None
    try:
        deps = json.loads(deps_path.read_text(encoding="utf-8-sig"))
    except Exception as exc:
        return {"file": safe_file_info(deps_path, include_hash=False), "json_ok": False, "error": str(exc)}
    libraries = sorted(str(key) for key in (deps.get("libraries") or {}).keys())
    return {
        "file": safe_file_info(deps_path, include_hash=False),
        "json_ok": True,
        "runtime_target": deps.get("runtimeTarget"),
        "target_names": list((deps.get("targets") or {}).keys())[:max_items],
        "library_count": len(libraries),
        "libraries_returned": libraries[:max_items],
    }


def xml_root_analysis(install_dir: Path, files: list[Path], max_items: int, include_hashes: bool) -> dict[str, Any]:
    xml_like = [path for path in files if path.suffix.lower() in {".xml", ".config"}]
    root_counts: dict[str, int] = {}
    rows: list[dict[str, Any]] = []
    parse_errors: list[dict[str, Any]] = []
    for path in xml_like:
        row: dict[str, Any] | None = None
        try:
            root = ElementTree.parse(path).getroot()
            root_tag = strip_xml_namespace(root.tag)
            root_counts[root_tag] = root_counts.get(root_tag, 0) + 1
            row = {
                **safe_file_info(path, include_hash=include_hashes),
                "relative_path": safe_relative(path, install_dir),
                "xml_ok": True,
                "root_tag": root_tag,
                "child_count": len(list(root)),
                "attrib_keys": sorted(root.attrib.keys()),
            }
        except Exception as exc:
            parse_errors.append({"relative_path": safe_relative(path, install_dir), "error": str(exc)})
            row = {
                **safe_file_info(path, include_hash=include_hashes),
                "relative_path": safe_relative(path, install_dir),
                "xml_ok": False,
                "error": str(exc),
            }
        if len(rows) < max_items:
            rows.append(row)
    return {
        "xml_like_count": len(xml_like),
        "root_counts": dict(sorted(root_counts.items(), key=lambda item: (-item[1], item[0]))),
        "files_returned": rows,
        "parse_error_count": len(parse_errors),
        "parse_errors_returned": parse_errors[:max_items],
    }


def surface_filename_hits(install_dir: Path, files: list[Path], max_items: int) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for label, keywords in PROGRAM_FILE_SURFACE_KEYWORDS.items():
        hits: list[str] = []
        for path in files:
            relative = safe_relative(path, install_dir)
            haystack = relative.casefold()
            if any(keyword.casefold() in haystack for keyword in keywords):
                hits.append(relative)
            if len(hits) >= max_items:
                break
        result[label] = {"count_returned": len(hits), "items": hits}
    return result


