def compact_compiler_surface_summary(max_items: int, include_strings: bool, include_reflection: bool) -> dict[str, Any]:
    surface = compiler_surface_probe(
        {
            "run_converter_probe": False,
            "include_reflection": include_reflection,
            "include_strings": include_strings,
            "max_strings_per_file": max_items,
        }
    )
    assemblies: list[dict[str, Any]] = []
    for row in surface.get("assemblies") or []:
        compact = {
            key: row.get(key)
            for key in ("role", "expected_name", "path", "exists", "name", "extension", "bytes", "modified", "sha256", "version_info")
            if key in row
        }
        if include_strings:
            compact["matched_strings"] = row.get("matched_strings", [])[:max_items]
            compact["matched_string_count"] = row.get("matched_string_count")
        assemblies.append(compact)
    reflection = surface.get("reflection") if isinstance(surface.get("reflection"), dict) else {}
    return {
        "compiler_surface_detected": surface.get("compiler_surface_detected"),
        "headless_compiler_cli_confirmed": surface.get("headless_compiler_cli_confirmed"),
        "full_compiler_diagnostics_claimed": surface.get("full_compiler_diagnostics_claimed"),
        "command_line_arguments_detected": surface.get("command_line_arguments_detected"),
        "assemblies": assemblies[: max_items * 2],
        "reflection_ok": reflection.get("ok"),
        "matched_type_count": len(reflection.get("matched_types") or []),
        "matched_types_returned": (reflection.get("matched_types") or [])[:max_items],
        "command_line_parser_methods": reflection.get("command_line_parser_methods"),
        "reflection_process_guard": surface.get("reflection_process_guard"),
        "limitation": surface.get("limitation"),
    }


VENDOR_MACRO_FILE_PATTERNS = ("*.tple", "*.tpl", "*.fst", "*.fbst", "*.dvtp", "*.dvtpe")


def binary_contains_text(blob: bytes, text: str) -> bool:
    return text.encode("utf-8") in blob or text.encode("utf-16le") in blob


def vendor_macro_sample_roots(install_dir: Path) -> list[dict[str, Any]]:
    roots: list[tuple[str, Path]] = [("install_dir", install_dir)]
    appdata = os.environ.get("APPDATA")
    local_appdata = os.environ.get("LOCALAPPDATA")
    if appdata:
        roots.append(("appdata_owen", Path(appdata) / "OWEN"))
    if local_appdata:
        roots.append(("localappdata_owen", Path(local_appdata) / "Owen"))
    unique: list[dict[str, Any]] = []
    seen: set[str] = set()
    for label, root in roots:
        resolved = root.expanduser().resolve()
        key = str(resolved).lower()
        if key in seen:
            continue
        seen.add(key)
        unique.append({"label": label, "root": resolved})
    return unique


def scan_vendor_macro_sample_files(install_dir: Path, max_samples: int, include_hashes: bool) -> list[dict[str, Any]]:
    roots: list[dict[str, Any]] = []
    for root_info in vendor_macro_sample_roots(install_dir):
        label = str(root_info["label"])
        root = Path(root_info["root"])
        if not root.exists():
            roots.append({"label": label, "root": str(root), "exists": False, "files": [], "returned": 0, "truncated": False})
            continue
        files: list[Path] = []
        for pattern in VENDOR_MACRO_FILE_PATTERNS:
            for path in root.rglob(pattern):
                if path.is_file():
                    files.append(path)
                    if len(files) >= max_samples:
                        break
            if len(files) >= max_samples:
                break
        files.sort(key=lambda item: str(item).lower())
        roots.append(
            {
                "label": label,
                "root": str(root),
                "exists": True,
                "patterns": list(VENDOR_MACRO_FILE_PATTERNS),
                "returned": len(files),
                "truncated": len(files) >= max_samples,
                "files": [
                    {
                        **safe_file_info(path, include_hash=include_hashes),
                        "relative_path": safe_relative(path, root),
                    }
                    for path in files
                ],
            }
        )
    return roots


DEFAULT_VENDOR_MACRO_ONLINE_URLS = (
    "https://ftp-ow.owen.ru/softupdate/OWEN%20Logic/OnlineComponents/Macros_Ver3/General/",
    "https://ftp-ow.owen.ru/softupdate/OWEN%20Logic/OnlineComponents/Macros_Ver2/General/",
)


def normalize_owen_catalog_url(value: str) -> str:
    return str(value or "").strip().replace(" ", "%20")


def owen_catalog_url_allowed(url: str) -> bool:
    parsed = urllib.parse.urlparse(normalize_owen_catalog_url(url))
    if parsed.scheme.lower() != "https":
        return False
    if parsed.netloc.lower() not in {"ftp-ow.owen.ru", "ftp.owendigital.ru"}:
        return False
    path = urllib.parse.unquote(parsed.path)
    return path.startswith("/softupdate/OWEN Logic/OnlineComponents/")


def fetch_owen_catalog_bytes(url: str, max_bytes: int, timeout_seconds: float = 15.0) -> tuple[bytes, bool, dict[str, Any]]:
    normalized = normalize_owen_catalog_url(url)
    if not owen_catalog_url_allowed(normalized):
        raise ValueError(f"URL is outside the allowed OWEN online component catalog scope: {url}")
    request = urllib.request.Request(
        normalized,
        headers={"User-Agent": "Codex-OWEN-Logic-MCP/1.0 vendor-macro-catalog-audit"},
    )
    with urllib.request.urlopen(request, timeout=timeout_seconds) as response:
        data = response.read(max(1, max_bytes) + 1)
        truncated = len(data) > max_bytes
        info = {
            "url": normalized,
            "status": getattr(response, "status", None),
            "content_type": response.headers.get("Content-Type"),
            "content_length_header": response.headers.get("Content-Length"),
        }
        return data[:max_bytes], truncated, info


def extract_owen_catalog_links(index_html: str, base_url: str) -> list[dict[str, Any]]:
    links: list[dict[str, Any]] = []
    seen: set[str] = set()
    for match in re.finditer(r'href=["\']([^"\']+)["\']', index_html, flags=re.IGNORECASE):
        href = match.group(1)
        if href in {"../", "./"} or href.startswith("?"):
            continue
        absolute = urllib.parse.urljoin(base_url, href)
        if not owen_catalog_url_allowed(absolute):
            continue
        parsed = urllib.parse.urlparse(absolute)
        basename = urllib.parse.unquote(Path(parsed.path).name)
        extension = Path(basename).suffix.lower()
        key = absolute.lower()
        if key in seen:
            continue
        seen.add(key)
        links.append(
            {
                "url": absolute,
                "name": basename,
                "extension": extension,
                "is_directory": parsed.path.endswith("/"),
                "vendor_file_candidate": extension in {".tple", ".tpl", ".fst", ".fbst", ".dvtp", ".dvtpe", ".mtd"},
            }
        )
    return links


def safe_download_file_name(url: str, index: int) -> str:
    parsed = urllib.parse.urlparse(url)
    name = urllib.parse.unquote(Path(parsed.path).name) or f"download_{index}"
    name = re.sub(r"[^A-Za-z0-9._-]+", "_", name).strip("._")
    if not name:
        name = f"download_{index}"
    return f"{index:02d}_{name}"


VENDOR_MACRO_SAMPLE_EXTENSIONS = {".tple", ".tpl", ".fst", ".fbst", ".dvtp", ".dvtpe", ".mtd"}


def summarize_vendor_component_metadata(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        return {"parseable": False}
    metadata = value.get("ComponentMetaData") if isinstance(value.get("ComponentMetaData"), dict) else {}
    return {
        "parseable": bool(metadata),
        "top_level_keys": sorted(str(key) for key in value.keys())[:80],
        "name": metadata.get("Name"),
        "unique_id": metadata.get("UniqueId"),
        "modification_id": metadata.get("ModificationId"),
        "group_name": metadata.get("GroupName"),
        "author": metadata.get("Author"),
        "description": metadata.get("Description"),
        "tags": metadata.get("Tags") if isinstance(metadata.get("Tags"), list) else [],
        "has_password": value.get("HasPassword"),
        "metadata_inputs_count": len(value.get("MetaDataInputs") or []) if isinstance(value.get("MetaDataInputs"), list) else None,
        "metadata_outputs_count": len(value.get("MetaDataOutputs") or []) if isinstance(value.get("MetaDataOutputs"), list) else None,
    }


def summarize_vendor_template_payload(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        return {"parseable": False}
    documents: list[dict[str, Any]] = []
    total_elements = 0
    total_connectors = 0
    total_variables = 0
    total_comment_blocks = 0
    dev_values: list[Any] = []
    for doc_id, doc in list(value.items())[:40]:
        document = doc if isinstance(doc, dict) else {}
        model = document.get("DocumentModel") if isinstance(document.get("DocumentModel"), dict) else {}
        elements = model.get("Elements") if isinstance(model.get("Elements"), list) else []
        connectors = model.get("ConnectorModels") if isinstance(model.get("ConnectorModels"), list) else []
        variables = model.get("Variables") if isinstance(model.get("Variables"), list) else []
        comments = model.get("CommentBlockModels") if isinstance(model.get("CommentBlockModels"), list) else []
        total_elements += len(elements)
        total_connectors += len(connectors)
        total_variables += len(variables)
        total_comment_blocks += len(comments)
        if model.get("DevValue") is not None:
            dev_values.append(model.get("DevValue"))
        element_titles: list[str] = []
        element_type_counts: dict[str, int] = {}
        for element in elements[:200]:
            element_model = element.get("ElementModel") if isinstance(element, dict) and isinstance(element.get("ElementModel"), dict) else {}
            title = element_model.get("Title")
            if title:
                element_titles.append(str(title))
            discriminator = str(element.get("Discriminator") if isinstance(element, dict) else element_model.get("Discriminator"))
            element_type_counts[discriminator] = int(element_type_counts.get(discriminator, 0)) + 1
        documents.append(
            {
                "document_id": str(doc_id),
                "document_model_unique_id": model.get("UniqueId"),
                "dev_value": model.get("DevValue"),
                "element_count": len(elements),
                "connector_count": len(connectors),
                "variable_count": len(variables),
                "comment_block_count": len(comments),
                "element_type_counts_sample": element_type_counts,
                "element_titles_sample": element_titles[:20],
                "has_password": bool(document.get("Password")),
                "discriminator": document.get("Discriminator"),
            }
        )
    return {
        "parseable": True,
        "document_count": len(value),
        "documents_returned": documents,
        "total_element_count": total_elements,
        "total_connector_count": total_connectors,
        "total_variable_count": total_variables,
        "total_comment_block_count": total_comment_blocks,
        "dev_values": sorted({str(item) for item in dev_values})[:40],
    }


def parse_vendor_zip_json_entry(archive: zipfile.ZipFile, entry_name: str, max_entry_bytes: int, include_text_previews: bool) -> dict[str, Any]:
    info = archive.getinfo(entry_name)
    raw = archive.read(entry_name)[:max_entry_bytes]
    text = raw.decode("utf-8-sig", errors="replace")
    result: dict[str, Any] = {
        "name": entry_name,
        "size": info.file_size,
        "compress_size": info.compress_size,
        "truncated_for_parse": info.file_size > max_entry_bytes,
        "first_bytes_hex": hex_bytes(raw[:32]),
    }
    if include_text_previews:
        result["text_preview"] = text[:1000]
    try:
        parsed = json.loads(text)
        result["json_parse_ok"] = True
        result["json_top_keys"] = sorted(str(key) for key in parsed.keys())[:80] if isinstance(parsed, dict) else []
        if entry_name.lower() == "metadata":
            result["component_metadata_summary"] = summarize_vendor_component_metadata(parsed)
        elif entry_name.lower() == "template":
            result["template_summary"] = summarize_vendor_template_payload(parsed)
        elif entry_name.lower() == "file_descriptor.json":
            result["file_descriptor_keys"] = sorted(str(key) for key in parsed.keys())[:80] if isinstance(parsed, dict) else []
    except json.JSONDecodeError as exc:
        result["json_parse_ok"] = False
        result["json_parse_error"] = str(exc)
    return result


def inspect_vendor_macro_file(path: Path, max_entry_bytes: int, include_text_previews: bool) -> dict[str, Any]:
    resolved = path.expanduser().resolve()
    extension = resolved.suffix.lower()
    sample: dict[str, Any] = {
        **safe_file_info(resolved, include_hash=True),
        "supported_vendor_extension": extension in VENDOR_MACRO_SAMPLE_EXTENSIONS,
        "zip_file": zipfile.is_zipfile(resolved),
    }
    if not sample["supported_vendor_extension"]:
        sample["warning"] = f"Extension {extension or '<none>'} is not one of known OWEN vendor component extensions."
    if zipfile.is_zipfile(resolved):
        try:
            with zipfile.ZipFile(resolved, "r") as archive:
                infos = archive.infolist()
                names = [info.filename for info in infos]
                lower_names = {name.lower(): name for name in names}
                sample["zip_entry_count"] = len(names)
                sample["zip_entries_returned"] = [
                    {"name": info.filename, "size": info.file_size, "compress_size": info.compress_size}
                    for info in infos[:120]
                ]
                sample["has_template_entry"] = "template" in lower_names
                sample["has_metadata_entry"] = "metadata" in lower_names
                sample["has_file_descriptor_json"] = "file_descriptor.json" in lower_names
                parsed_entries: list[dict[str, Any]] = []
                for logical_name in ("MetaData", "Template", "file_descriptor.json"):
                    entry_name = lower_names.get(logical_name.lower())
                    if entry_name:
                        parsed_entries.append(parse_vendor_zip_json_entry(archive, entry_name, max_entry_bytes, include_text_previews))
                sample["parsed_entries"] = parsed_entries
                for entry in parsed_entries:
                    if entry.get("component_metadata_summary"):
                        sample["component_metadata_summary"] = entry.get("component_metadata_summary")
                    if entry.get("template_summary"):
                        sample["template_summary"] = entry.get("template_summary")
                sample["payload_schema_observed"] = {
                    "zip_entries": names,
                    "metadata_json": bool(sample.get("component_metadata_summary")),
                    "template_json": bool(sample.get("template_summary")),
                }
        except (OSError, zipfile.BadZipFile, RuntimeError) as exc:
            sample["zip_inspection_error"] = str(exc)
    else:
        try:
            raw = resolved.read_bytes()[:512]
            sample["first_bytes_hex"] = hex_bytes(raw[:32])
            if include_text_previews:
                sample["text_preview"] = raw.decode("utf-8", errors="replace")[:300]
        except OSError as exc:
            sample["read_error"] = str(exc)
    return sample


def inspect_vendor_macro_online_sample(path: Path) -> dict[str, Any]:
    return inspect_vendor_macro_file(path, max_entry_bytes=2 * 1024 * 1024, include_text_previews=False)


def load_vendor_macro_json_payload(path: Path, max_entry_bytes: int) -> tuple[Path, dict[str, Any], dict[str, Any] | None]:
    resolved = path.expanduser().resolve()
    extension = resolved.suffix.lower()
    if extension not in VENDOR_MACRO_SAMPLE_EXTENSIONS:
        raise ValueError(f"Unsupported OWEN vendor macro/component extension: {extension or '<none>'}")
    if not resolved.exists() or not resolved.is_file():
        raise FileNotFoundError(f"Vendor macro/component sample file not found: {resolved}")
    if not zipfile.is_zipfile(resolved):
        raise ValueError(f"Vendor macro/component sample is not a ZIP-like payload: {resolved}")

    def read_json_entry(archive: zipfile.ZipFile, entry_name: str, logical_name: str) -> Any:
        info = archive.getinfo(entry_name)
        if info.file_size > max_entry_bytes:
            raise ValueError(f"{logical_name} entry is too large for safe conversion: {info.file_size} > {max_entry_bytes}")
        text = archive.read(entry_name).decode("utf-8-sig", errors="replace")
        return json.loads(text)

    with zipfile.ZipFile(resolved, "r") as archive:
        names = [info.filename for info in archive.infolist()]
        lower_names = {name.lower(): name for name in names}
        template_name = lower_names.get("template")
        if not template_name:
            raise ValueError("Vendor macro/component sample has no Template entry")
        metadata_name = lower_names.get("metadata")
        template = read_json_entry(archive, template_name, "Template")
        metadata = read_json_entry(archive, metadata_name, "MetaData") if metadata_name else None
    if not isinstance(template, dict) or not template:
        raise ValueError("Vendor Template entry must be a non-empty JSON object")
    if metadata is not None and not isinstance(metadata, dict):
        raise ValueError("Vendor MetaData entry must be a JSON object when present")
    return resolved, template, metadata


def select_vendor_template_document(
    template: dict[str, Any],
    *,
    document_id: str | None,
    document_index: int,
) -> tuple[str, dict[str, Any], dict[str, Any]]:
    documents = list(template.items())
    selected_id: str | None = None
    selected_document: Any = None
    if document_id:
        for candidate_id, candidate_document in documents:
            if str(candidate_id) == document_id:
                selected_id = str(candidate_id)
                selected_document = candidate_document
                break
        if selected_id is None:
            raise ValueError(f"Vendor Template document_id not found: {document_id}")
    else:
        if document_index < 0 or document_index >= len(documents):
            raise ValueError(f"Vendor Template document_index is out of range: {document_index}")
        selected_id, selected_document = documents[document_index]
        selected_id = str(selected_id)
    if not isinstance(selected_document, dict):
        raise ValueError("Vendor Template selected document must be an object")
    model = selected_document.get("DocumentModel") if isinstance(selected_document.get("DocumentModel"), dict) else None
    if model is None:
        raise ValueError("Vendor Template selected document has no DocumentModel object")
    return selected_id, selected_document, model


def vendor_macro_to_codex_package(args: dict[str, Any]) -> dict[str, Any]:
    max_entry_bytes = clamp_int(args.get("max_entry_bytes"), 25 * 1024 * 1024, 4096, 100 * 1024 * 1024)
    max_elements = clamp_int(args.get("max_elements"), 500, 1, 2000)
    vendor_path, template, metadata = load_vendor_macro_json_payload(Path(str(args.get("path") or "")), max_entry_bytes)
    document_arg = str(args.get("document_id")) if args.get("document_id") else None
    document_index = clamp_int(args.get("document_index"), 0, 0, max(0, len(template) - 1))
    document_id, _document, model = select_vendor_template_document(
        template,
        document_id=document_arg,
        document_index=document_index,
    )
    elements = model.get("Elements") if isinstance(model.get("Elements"), list) else []
    connectors = model.get("ConnectorModels") if isinstance(model.get("ConnectorModels"), list) else []
    variables = model.get("Variables") if isinstance(model.get("Variables"), list) else []
    comment_blocks = model.get("CommentBlockModels") if isinstance(model.get("CommentBlockModels"), list) else []
    if len(elements) > max_elements:
        raise ValueError(f"Vendor Template contains too many elements for one Codex package: {len(elements)} > {max_elements}")
    for index, element in enumerate(elements):
        if not isinstance(element, dict):
            raise ValueError(f"Vendor Template element at index {index} is not an object")
        ensure_macro_element_guardrails(
            element,
            allow_variable_block=bool(args.get("allow_variable_block_export", False)),
            allow_module_element=bool(args.get("allow_module_element_export", False)),
            action="convert from vendor Template",
        )
    for index, connector in enumerate(connectors):
        if not isinstance(connector, dict) or not connector_model(connector):
            raise ValueError(f"Vendor Template connector at index {index} is not a ConnectorModel object")

    output_arg = args.get("output_dir")
    output_dir = Path(str(output_arg)).expanduser().resolve() if output_arg else default_macro_package_dir()
    if not is_scratch_destination(output_dir):
        raise ValueError(f"Refusing to write converted vendor macro package outside scratch/sandbox/local-heavy path: {output_dir}")
    output_dir.mkdir(parents=True, exist_ok=True)

    selected_port_uids: set[str] = set()
    for element in elements:
        selected_port_uids.update(macro_element_port_uids(element))
    external_connectors: list[dict[str, Any]] = []
    for index, connector in enumerate(connectors):
        model_connector = connector_model(connector)
        from_uid = str(model_connector.get("FromPortUId") or "")
        to_uid = str(model_connector.get("ToPortUId") or "")
        if from_uid not in selected_port_uids or to_uid not in selected_port_uids:
            external_connectors.append({"index": index, "from_port_uid": from_uid, "to_port_uid": to_uid})

    import_blockers: list[str] = []
    if variables and not bool(args.get("allow_variable_template_package", False)):
        raise ValueError("Vendor Template contains DocumentModel.Variables; pass allow_variable_template_package=true to write a non-importable analysis package")
    if variables:
        import_blockers.append("DocumentModel.Variables are present and project_macro_import does not transfer vendor variables")
    if comment_blocks:
        import_blockers.append("CommentBlockModels are present and project_macro_import does not transfer vendor comment blocks")
    if external_connectors:
        import_blockers.append("One or more ConnectorModels reference ports outside the converted element set")
    import_supported = not import_blockers

    element_summaries = [
        summarize_fbd_element_for_patch(document_id, index, element)
        for index, element in enumerate(elements)
    ]
    connector_summaries = [
        summarize_fbd_connector(document_id, index, connector)
        for index, connector in enumerate(connectors)
    ]
    metadata_summary = summarize_vendor_component_metadata(metadata) if isinstance(metadata, dict) else {"parseable": False}
    component_name = metadata_summary.get("name") or model.get("UniqueId") or document_id
    fallback = f"vendor_macro_{component_name}"
    package_path = output_dir / safe_macro_package_name(args.get("package_name"), fallback)
    element_bytes = json.dumps(elements, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    connector_bytes = json.dumps(connectors, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    package = {
        "format": MACRO_PACKAGE_FORMAT,
        "vendor_macro_file": False,
        "source_vendor_macro_file": True,
        "scope": "converted_vendor_template_document",
        "created_at": datetime.now().astimezone().isoformat(),
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "source_vendor_file": safe_file_info(vendor_path, include_hash=True),
        "source_project": None,
        "source_document_id": document_id,
        "source_vendor_document_id": document_id,
        "source_component_metadata": metadata_summary,
        "import_supported": import_supported,
        "import_blockers": import_blockers,
        "limitations": [
            "This JSON is a Codex automation package converted from an OWEN vendor Template payload; it is not OWEN's proprietary macro file format.",
            "Conversion does not execute OWEN Logic GUI vendor import/export, Component Manager install/update/download, or compiler validation after GUI vendor actions.",
            "project_macro_import can import only elements and fully internal connectors; vendor variables and comment blocks are preserved in this package but are not transferred by the current importer.",
        ],
        "selection": {
            "document_id": document_id,
            "document_index": document_index,
            "element_count": len(elements),
            "connector_count": len(connectors),
            "variable_count": len(variables),
            "comment_block_count": len(comment_blocks),
            "external_connector_count": len(external_connectors),
            "elements": element_summaries,
            "connectors": connector_summaries,
            "element_sha256": sha256_bytes(element_bytes),
            "connector_sha256": sha256_bytes(connector_bytes),
        },
        "elements": [copy.deepcopy(element) for element in elements],
        "connectors": [copy.deepcopy(connector) for connector in connectors],
        "variables": [copy.deepcopy(variable) for variable in variables],
        "comment_blocks": [copy.deepcopy(comment) for comment in comment_blocks],
    }
    package_path.write_text(json.dumps(package, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return {
        "package": safe_file_info(package_path, include_hash=True),
        "format": MACRO_PACKAGE_FORMAT,
        "vendor_macro_file": False,
        "source_vendor_macro_file": True,
        "source_vendor_file": safe_file_info(vendor_path, include_hash=True),
        "source_vendor_document_id": document_id,
        "component_metadata_summary": metadata_summary,
        "scope": package["scope"],
        "element_count": len(elements),
        "connector_count": len(connectors),
        "variable_count": len(variables),
        "comment_block_count": len(comment_blocks),
        "external_connector_count": len(external_connectors),
        "import_supported": import_supported,
        "import_blockers": import_blockers,
        "read_only_vendor_file": True,
        "opened_gui": False,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "live_device_action_executed": False,
        "vendor_import_export_executed": False,
        "component_install_update_executed": False,
        "project_mutated": False,
        "risk_class": "safe_read_vendor_write_scratch_package",
        "guardrail": "Vendor file was read-only; converted Codex package JSON was written only under scratch/sandbox/local-heavy and is explicitly not a proprietary OWEN macro file.",
        "remaining_gap": (
            "This proves local vendor Template conversion into a Codex automation package. It does not execute OWEN Logic GUI "
            "vendor import/export, Component Manager install/update/download, or compiler validation after those GUI/vendor actions."
        ),
    }


VENDOR_MACRO_EXPORT_EXTENSIONS = {".tple", ".tpl", ".fst", ".fbst", ".dvtp", ".dvtpe"}


def safe_vendor_macro_archive_name(value: Any, fallback: str, extension: str) -> str:
    requested_extension = str(extension or ".tple").strip().lower()
    if not requested_extension.startswith("."):
        requested_extension = f".{requested_extension}"
    if requested_extension not in VENDOR_MACRO_EXPORT_EXTENSIONS:
        raise ValueError(f"Unsupported vendor macro archive extension: {requested_extension}")
    name = str(value or fallback).strip()
    name = re.sub(r"[^A-Za-z0-9_.-]+", "_", name).strip("._")
    if not name:
        name = fallback
    current_extension = Path(name).suffix.lower()
    if current_extension in VENDOR_MACRO_EXPORT_EXTENSIONS:
        base = name[: -len(current_extension)]
        name = f"{base}{current_extension}"
    else:
        name = f"{name}{requested_extension}"
    return name[:140]


def package_component_metadata_defaults(package: dict[str, Any], document_id: str, args: dict[str, Any]) -> dict[str, Any]:
    source_metadata = package.get("source_component_metadata")
    if not isinstance(source_metadata, dict):
        source_metadata = {}
    component_name = str(
        args.get("component_name")
        or source_metadata.get("name")
        or source_metadata.get("Name")
        or package.get("name")
        or Path(str(package.get("source_project") or "codex_macro")).stem
        or "codex_macro"
    ).strip()
    group_name = str(args.get("group_name") or source_metadata.get("group_name") or "Codex").strip()
    author = str(args.get("author") or source_metadata.get("author") or "Codex").strip()
    description = str(
        args.get("description")
        or source_metadata.get("description")
        or "Codex-generated OWEN Template/MetaData archive from a Codex OWEN macro package."
    ).strip()
    return {
        "ComponentMetaData": {
            "Name": component_name or "codex_macro",
            "UniqueId": document_id,
            "ModificationId": str(source_metadata.get("modification_id") or "00000000-0000-0000-0000-000000000000"),
            "GroupName": group_name or "Codex",
            "Author": author or "Codex",
            "Description": description,
            "Tags": list(source_metadata.get("tags") or []) if isinstance(source_metadata.get("tags"), list) else [],
            "ModificationDateTime": 0,
            "CreationDateTime": 0,
            "Image": str(source_metadata.get("image") or ""),
        },
        "HasPassword": False,
        "MetaDataInputs": [],
        "MetaDataOutputs": [],
    }


def package_element_has_module_markers(element: dict[str, Any]) -> bool:
    return any(element.get(field) is not None for field in ("ModuleName", "InputVariableIndex", "OutputVariableIndex"))


def vendor_macro_from_codex_package(args: dict[str, Any]) -> dict[str, Any]:
    package_path, package = load_macro_package(args.get("package_path"))
    source_hash_before = sha256_file(package_path)
    elements = package.get("elements")
    connectors = package.get("connectors") or []
    variables = package.get("variables") or []
    comment_blocks = package.get("comment_blocks") or []
    if not isinstance(elements, list) or not elements:
        raise ValueError("Codex macro package contains no elements")
    if not isinstance(connectors, list):
        raise ValueError("Codex macro package connectors must be an array")
    if not isinstance(variables, list):
        raise ValueError("Codex macro package variables must be an array")
    if not isinstance(comment_blocks, list):
        raise ValueError("Codex macro package comment_blocks must be an array")
    max_elements = clamp_int(args.get("max_elements"), 1000, 1, 5000)
    if len(elements) > max_elements:
        raise ValueError(f"Codex macro package contains too many elements for one vendor-like archive: {len(elements)} > {max_elements}")
    for index, element in enumerate(elements):
        if not isinstance(element, dict):
            raise ValueError(f"Codex macro package element at index {index} is not an object")
    for index, connector in enumerate(connectors):
        if not isinstance(connector, dict) or not connector_model(connector):
            raise ValueError(f"Codex macro package connector at index {index} is not a ConnectorModel object")
    for index, variable in enumerate(variables):
        if not isinstance(variable, dict):
            raise ValueError(f"Codex macro package variable at index {index} is not an object")
    for index, comment in enumerate(comment_blocks):
        if not isinstance(comment, dict):
            raise ValueError(f"Codex macro package comment block at index {index} is not an object")

    output_arg = args.get("output_dir")
    output_dir = Path(str(output_arg)).expanduser().resolve() if output_arg else (default_macro_package_dir() / "vendor_like_archive")
    if not is_scratch_destination(output_dir):
        raise ValueError(f"Refusing to write vendor-like macro archive outside scratch/sandbox/local-heavy path: {output_dir}")
    output_dir.mkdir(parents=True, exist_ok=True)

    document_id = str(package.get("source_vendor_document_id") or package.get("source_document_id") or uuid.uuid4())
    try:
        document_id = str(uuid.UUID(document_id))
    except Exception:
        document_id = str(uuid.uuid4())
    source_metadata = package.get("source_component_metadata") if isinstance(package.get("source_component_metadata"), dict) else {}
    component_name = str(args.get("component_name") or source_metadata.get("name") or "codex_macro")
    archive_name = safe_vendor_macro_archive_name(
        args.get("file_name"),
        f"{component_name}_codex_template",
        str(args.get("extension") or ".tple"),
    )
    output_path = (output_dir / archive_name).resolve()
    if output_path.exists():
        raise FileExistsError(f"Refusing to overwrite existing vendor-like archive: {output_path}")
    if not is_scratch_destination(output_path):
        raise ValueError(f"Refusing to write vendor-like macro archive outside scratch/sandbox/local-heavy path: {output_path}")

    model = {
        "UniqueId": document_id,
        "Bounds": {
            "Location": {"IsEmpty": True, "X": 0, "Y": 0},
            "Size": {"IsEmpty": True, "Width": 0, "Height": 0},
            "X": 0,
            "Y": 0,
            "Width": 0,
            "Height": 0,
            "Left": 0,
            "Top": 0,
            "Right": 0,
            "Bottom": 0,
            "IsEmpty": True,
        },
        "ApplicationVersionCreated": f"codex_owen_logic_mcp_{SERVER_VERSION}",
        "LastChangingApplicationVersion": None,
        "Elements": copy.deepcopy(elements),
        "ConnectorModels": copy.deepcopy(connectors),
        "Variables": copy.deepcopy(variables),
        "CommentBlockModels": copy.deepcopy(comment_blocks),
    }
    template = {document_id: {"DocumentModel": model}}
    metadata = package_component_metadata_defaults(package, document_id, args)
    template_bytes = json.dumps(template, ensure_ascii=False, indent=2).encode("utf-8")
    metadata_bytes = json.dumps(metadata, ensure_ascii=False, indent=2).encode("utf-8")
    max_entry_bytes = clamp_int(args.get("max_entry_bytes"), 25 * 1024 * 1024, 4096, 100 * 1024 * 1024)
    if max(len(template_bytes), len(metadata_bytes)) > max_entry_bytes:
        raise ValueError("Generated Template/MetaData entry exceeds max_entry_bytes")

    with zipfile.ZipFile(output_path, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        archive.writestr("Template", template_bytes)
        archive.writestr("MetaData", metadata_bytes)

    inspection = inspect_vendor_macro_file(output_path, max_entry_bytes, False)
    roundtrip_conversion: dict[str, Any] | None = None
    if bool(args.get("verify_roundtrip", True)):
        roundtrip_dir = output_dir / "roundtrip_codex_package"
        roundtrip_args = {
            "path": str(output_path),
            "output_dir": str(roundtrip_dir),
            "package_name": f"{output_path.stem}_roundtrip_codex_package.json",
            "max_entry_bytes": max_entry_bytes,
            "max_elements": max_elements,
            "allow_variable_template_package": bool(variables),
            "allow_variable_block_export": any(
                isinstance(element, dict) and bool(element.get("VariableInfoUId"))
                for element in elements
            ),
            "allow_module_element_export": any(
                isinstance(element, dict) and package_element_has_module_markers(element)
                for element in elements
            ),
        }
        roundtrip_conversion = vendor_macro_to_codex_package(roundtrip_args)

    source_hash_after = sha256_file(package_path)
    template_summary = inspection.get("template_summary") if isinstance(inspection.get("template_summary"), dict) else {}
    metadata_summary = inspection.get("component_metadata_summary") if isinstance(inspection.get("component_metadata_summary"), dict) else {}
    roundtrip_ok = roundtrip_conversion is None or bool(roundtrip_conversion.get("source_vendor_macro_file"))
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": bool(
            inspection.get("zip_file")
            and template_summary.get("parseable")
            and metadata_summary.get("parseable")
            and roundtrip_ok
        ),
        "archive": safe_file_info(output_path, include_hash=True),
        "format": "owen_vendor_like_template_zip",
        "vendor_macro_file": True,
        "official_owen_export": False,
        "source_codex_package": safe_file_info(package_path, include_hash=True),
        "source_package_hash_before": source_hash_before,
        "source_package_hash_after": source_hash_after,
        "source_package_hash_preserved": source_hash_after == source_hash_before,
        "source_vendor_macro_file": bool(package.get("source_vendor_macro_file")),
        "source_document_id": package.get("source_document_id"),
        "source_vendor_document_id": package.get("source_vendor_document_id"),
        "generated_document_id": document_id,
        "component_metadata_summary": summarize_vendor_component_metadata(metadata),
        "template_sha256": sha256_bytes(template_bytes),
        "metadata_sha256": sha256_bytes(metadata_bytes),
        "element_count": len(elements),
        "connector_count": len(connectors),
        "variable_count": len(variables),
        "comment_block_count": len(comment_blocks),
        "roundtrip_inspection": inspection,
        "roundtrip_conversion": roundtrip_conversion,
        "read_only_codex_package": True,
        "opened_gui": False,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "opened_http_catalog_socket": False,
        "live_device_action_executed": False,
        "vendor_import_export_executed": False,
        "component_install_update_executed": False,
        "project_mutated": False,
        "risk_class": "safe_read_codex_package_write_scratch_vendor_like_archive",
        "guardrail": "Codex package was read-only; generated Template/MetaData ZIP was written only under scratch/sandbox/local-heavy. No OWEN Logic GUI import/export or Component Manager action was executed.",
        "remaining_gap": (
            "This proves a local scratch Template/MetaData archive can be generated and parsed back by MCP. "
            "It is not evidence that OWEN Logic GUI accepts/imports the archive, and it does not execute Component Manager install/update/download or compiler validation after GUI vendor actions."
        ),
    }


def vendor_macro_sample_inspect(args: dict[str, Any]) -> dict[str, Any]:
    raw_paths: list[str] = []
    if args.get("path"):
        raw_paths.append(str(args.get("path")))
    if isinstance(args.get("paths"), list):
        raw_paths.extend(str(item) for item in args.get("paths") or [])
    raw_paths = [item for item in raw_paths if item.strip()]
    if not raw_paths:
        raise ValueError("owen_logic_vendor_macro_sample_inspect requires path or paths")
    max_entry_bytes = clamp_int(args.get("max_entry_bytes"), 2 * 1024 * 1024, 4096, 25 * 1024 * 1024)
    include_text_previews = bool(args.get("include_text_previews", False))
    files = [inspect_vendor_macro_file(Path(raw_path), max_entry_bytes, include_text_previews) for raw_path in raw_paths]
    parseable_metadata_count = sum(1 for item in files if isinstance(item.get("component_metadata_summary"), dict))
    parseable_template_count = sum(1 for item in files if isinstance(item.get("template_summary"), dict))
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": bool(files) and parseable_metadata_count == len(files) and parseable_template_count == len(files),
        "file_count": len(files),
        "parseable_metadata_count": parseable_metadata_count,
        "parseable_template_count": parseable_template_count,
        "files": files,
        "read_only": True,
        "opened_gui": False,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "live_device_action_executed": False,
        "vendor_import_export_executed": False,
        "component_install_update_executed": False,
        "project_mutated": False,
        "validation_scope": "local_vendor_macro_component_payload_inspection_only",
        "remaining_gap": (
            "This parses local vendor payload samples and summarizes Template/MetaData structure. "
            "It does not execute OWEN Logic GUI import/export, Component Manager install/update/download, "
            "or compiler validation after those actions."
        ),
    }


def vendor_macro_online_catalog_audit(args: dict[str, Any]) -> dict[str, Any]:
    urls = [normalize_owen_catalog_url(url) for url in (args.get("urls") or DEFAULT_VENDOR_MACRO_ONLINE_URLS)]
    max_index_bytes = clamp_int(args.get("max_index_bytes"), 524288, 4096, 2 * 1024 * 1024)
    max_file_bytes = clamp_int(args.get("max_file_bytes"), 5 * 1024 * 1024, 65536, 25 * 1024 * 1024)
    max_downloads = clamp_int(args.get("max_downloads"), 2, 0, 10)
    download_samples = bool(args.get("download_samples", True)) and max_downloads > 0
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    scratch_value = args.get("scratch_dir")
    if scratch_value:
        scratch_dir = Path(str(scratch_value)).expanduser().resolve()
    else:
        workbench = find_workbench_root()
        scratch_dir = (
            workbench / "30_LOCAL_HEAVY" / "sandbox_tmp" / "owen_vendor_macro_online_catalog_audit" / timestamp
            if workbench
            else Path.home() / ".codex" / "tmp" / "owen_vendor_macro_online_catalog_audit" / timestamp
        ).resolve()
    if not is_scratch_destination(scratch_dir):
        raise ValueError(f"Refusing online catalog sample output outside scratch/sandbox/local-heavy path: {scratch_dir}")

    base_result: dict[str, Any] = {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": False,
        "analysis_scope": "opt-in read-only OWEN online macro/component catalog audit",
        "urls": urls,
        "scratch_dir": str(scratch_dir),
        "allow_network_catalog": bool(args.get("allow_network_catalog", False)),
        "network_catalog_request_executed": False,
        "opened_http_catalog_socket": False,
        "opened_serial_port": False,
        "opened_controller_network_socket": False,
        "live_device_action_executed": False,
        "gui_action_executed": False,
        "project_mutated": False,
        "vendor_import_export_executed": False,
        "component_install_update_executed": False,
        "guardrail": (
            "Requires allow_network_catalog=true. It fetches only allowlisted OWEN HTTPS catalog/sample URLs into scratch; "
            "it does not import/install components, launch OWEN Logic, open COM/TCP controller connections, or mutate projects."
        ),
    }
    disallowed = [url for url in urls if not owen_catalog_url_allowed(url)]
    if disallowed:
        return {**base_result, "error": "One or more URLs are outside the OWEN online component catalog allowlist.", "disallowed_urls": disallowed}
    if not bool(args.get("allow_network_catalog", False)):
        return {
            **base_result,
            "execution_policy": "no_network_without_allow_network_catalog_true",
            "ok": False,
            "next_step": "Pass allow_network_catalog=true to fetch allowlisted OWEN HTTPS catalog indexes.",
        }

    scratch_dir.mkdir(parents=True, exist_ok=True)
    catalog_results: list[dict[str, Any]] = []
    candidates: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    for url in urls:
        try:
            data, truncated, response_info = fetch_owen_catalog_bytes(url, max_index_bytes)
            text = data.decode("utf-8", errors="replace")
            links = extract_owen_catalog_links(text, url)
            file_candidates = [link for link in links if bool(link.get("vendor_file_candidate"))]
            candidates.extend(file_candidates)
            catalog_results.append(
                {
                    **response_info,
                    "read_bytes": len(data),
                    "truncated": truncated,
                    "link_count": len(links),
                    "vendor_file_candidate_count": len(file_candidates),
                    "extensions": sorted({str(link.get("extension") or "") for link in file_candidates}),
                    "links_returned": links[:100],
                }
            )
        except Exception as exc:
            errors.append({"url": url, "error": str(exc)})

    downloads: list[dict[str, Any]] = []
    downloaded_urls: set[str] = set()
    if download_samples:
        ordered_candidates = sorted(
            candidates,
            key=lambda row: (
                0 if str(row.get("extension") or "").lower() in {".tple", ".tpl"} else 1,
                str(row.get("url") or "").lower(),
            ),
        )
        for candidate in ordered_candidates:
            if len(downloads) >= max_downloads:
                break
            url = str(candidate.get("url") or "")
            if not url or url.lower() in downloaded_urls:
                continue
            downloaded_urls.add(url.lower())
            try:
                data, truncated, response_info = fetch_owen_catalog_bytes(url, max_file_bytes)
                file_path = scratch_dir / safe_download_file_name(url, len(downloads) + 1)
                file_path.write_bytes(data)
                downloads.append(
                    {
                        **response_info,
                        "candidate": candidate,
                        "download_path": str(file_path),
                        "downloaded_bytes": len(data),
                        "truncated": truncated,
                        "sample_inspection": inspect_vendor_macro_online_sample(file_path),
                    }
                )
            except Exception as exc:
                errors.append({"url": url, "download_error": str(exc)})

    macro_payload_samples = [
        row
        for row in downloads
        if str(((row.get("candidate") or {}).get("extension") or "")).lower() in {".tple", ".tpl"}
    ]
    return {
        **base_result,
        "ok": bool(catalog_results) and (not download_samples or bool(downloads)),
        "network_catalog_request_executed": True,
        "opened_http_catalog_socket": True,
        "catalog_count": len(catalog_results),
        "candidate_count": len(candidates),
        "download_count": len(downloads),
        "macro_payload_sample_count": len(macro_payload_samples),
        "catalogs": catalog_results,
        "downloads": downloads,
        "errors": errors,
        "remaining_gap": (
            "This proves online catalog/sample discovery and bounded payload inspection only. "
            "It does not prove GUI vendor macro import/export execution, online Component Manager install/update/download, "
            "or compiler validation after those GUI/vendor actions."
        ),
    }


