def vendor_macro_coverage_audit(args: dict[str, Any]) -> dict[str, Any]:
    include_details = bool(args.get("include_operation_details", True))
    include_tool_names = bool(args.get("include_tool_names", True))
    operations: list[dict[str, Any]] = []
    for row in VENDOR_MACRO_OPERATION_COVERAGE:
        item = dict(row)
        if not include_tool_names:
            item.pop("tools", None)
        operations.append(item)

    status_counts: dict[str, int] = {}
    scope_counts: dict[str, int] = {}
    for row in VENDOR_MACRO_OPERATION_COVERAGE:
        status = str(row.get("status") or "unknown")
        scope = str(row.get("scope") or "unknown")
        status_counts[status] = status_counts.get(status, 0) + 1
        scope_counts[scope] = scope_counts.get(scope, 0) + 1

    proven = [
        row["operation"]
        for row in VENDOR_MACRO_OPERATION_COVERAGE
        if row.get("status") == "proven_current_safe_scope"
    ]
    partial = [
        row["operation"]
        for row in VENDOR_MACRO_OPERATION_COVERAGE
        if row.get("status") == "partial_semantic_gap"
    ]
    blocked = [
        row["operation"]
        for row in VENDOR_MACRO_OPERATION_COVERAGE
        if str(row.get("status") or "").startswith("blocked_")
    ]
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": True,
        "read_only": True,
        "opened_gui": False,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "opened_http_catalog_socket": False,
        "live_device_action_executed": False,
        "vendor_import_export_executed": False,
        "component_install_update_executed": False,
        "project_mutated": False,
        "coverage_domain": "owen_logic_vendor_macro_component_manager",
        "status_counts": status_counts,
        "scope_counts": scope_counts,
        "proven_operation_count": len(proven),
        "partial_operation_count": len(partial),
        "blocked_operation_count": len(blocked),
        "proven_operations": proven,
        "partial_operations": partial,
        "blocked_operations": blocked,
        "operations": operations if include_details else [],
        "remaining_gap_bucket": "proprietary_vendor_macro_format",
        "remaining_gap_summary": (
            "Installed-file and online/sample vendor audits, vendor Template to Codex package conversion, Codex package "
            "export/import, Component Manager GUI surface/action-candidate evidence, and scratch project-library download "
            "execution plus bounded post-vendor GUI validation smoke are covered. OWEN proprietary GUI vendor import/export "
            "execution, local-library or online Component Manager install/update/download execution, and full compiler "
            "diagnostics after those GUI/vendor actions remain unproven."
        ),
        "guardrail": (
            "This audit is read-only and does not open OWEN Logic, network sockets, vendor dialogs, or project files. "
            "Do not promote Codex JSON package evidence, Component Manager action candidates, or partial_semantic_gap rows "
            "to proprietary OWEN vendor import/export or install/update/download completion evidence."
        ),
    }


def vendor_macro_format_audit(args: dict[str, Any]) -> dict[str, Any]:
    max_samples = clamp_int(args.get("max_samples"), 40, 1, 200)
    include_hashes = bool(args.get("include_hashes", False))
    scan_local_roots = bool(args.get("scan_local_roots", True))
    install = find_installation_data()
    install_dir_value = install.get("install_dir")
    if not install_dir_value:
        return {
            "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
            "ok": False,
            "installation": install,
            "error": "OWEN Logic installation directory was not found",
            "read_only": True,
            "opened_gui": False,
            "opened_serial_port": False,
            "opened_network_socket": False,
            "live_device_action_executed": False,
        }

    install_dir = Path(str(install_dir_value))
    program_dll = install_dir / "ProgramRelayFBD.dll"
    dll_info: dict[str, Any] = {"path": str(program_dll), "exists": program_dll.exists()}
    blob = b""
    if program_dll.exists():
        dll_info = safe_file_info(program_dll, include_hash=include_hashes)
        try:
            blob = program_dll.read_bytes()
        except OSError as exc:
            dll_info["read_error"] = str(exc)

    expected_strings = [
        " (*.tple)|*.tple",
        " (*.tple;*.tpl)|*.tple;*.tpl",
        " (*.tple;*.tpl;*.fst;*.fbst)|*.tple;*.tpl;*.fst;*.fbst|",
        " (*.fst)|*.fst",
        " (*.fbst)|*.fbst",
        "*.tpl*",
        "*.dvtp*",
        "*.fst",
        "*.fbst",
        "file_descriptor.json",
        "MetaData",
        "MinRequiredVersion",
        "https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/Macros_Ver2/",
        "https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/Macros_Ver3/",
        "https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/DeviceTemplates_Ver2/",
        "https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/FunctionST/",
        "https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/FunctionST_Ver2/",
        "https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/FunctionblockST/",
        "https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/FunctionblockST_Ver2/",
    ]
    observed_strings = {text: bool(blob and binary_contains_text(blob, text)) for text in expected_strings}

    local_samples = scan_vendor_macro_sample_files(install_dir, max_samples, include_hashes) if scan_local_roots else []
    sample_count = sum(int(root.get("returned") or 0) for root in local_samples)

    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": True,
        "installation": install,
        "analysis_scope": "read-only proprietary OWEN component/macro file-surface audit",
        "programrelayfbd_dll": dll_info,
        "vendor_file_surfaces": {
            "macro_template_export": {
                "primary_extension": ".tple",
                "dialog_filter": " (*.tple)|*.tple",
                "observed_in_program_dll": observed_strings.get(" (*.tple)|*.tple", False),
            },
            "macro_template_import": {
                "extensions": [".tple", ".tpl"],
                "dialog_filter": " (*.tple;*.tpl)|*.tple;*.tpl",
                "observed_in_program_dll": observed_strings.get(" (*.tple;*.tpl)|*.tple;*.tpl", False),
            },
            "component_import": {
                "extensions": [".tple", ".tpl", ".fst", ".fbst"],
                "dialog_filter": " (*.tple;*.tpl;*.fst;*.fbst)|*.tple;*.tpl;*.fst;*.fbst|",
                "observed_in_program_dll": observed_strings.get(" (*.tple;*.tpl;*.fst;*.fbst)|*.tple;*.tpl;*.fst;*.fbst|", False),
            },
            "st_function": {"extension": ".fst", "observed_in_program_dll": observed_strings.get(" (*.fst)|*.fst", False)},
            "st_function_block": {"extension": ".fbst", "observed_in_program_dll": observed_strings.get(" (*.fbst)|*.fbst", False)},
            "device_template": {"extensions": [".dvtp", ".dvtpe"], "catalog_pattern_observed": observed_strings.get("*.dvtp*", False)},
            "component_archive_markers": {
                "file_descriptor_json_observed": observed_strings.get("file_descriptor.json", False),
                "metadata_marker_observed": observed_strings.get("MetaData", False),
                "min_required_version_marker_observed": observed_strings.get("MinRequiredVersion", False),
            },
        },
        "internal_api_surface": [
            {
                "type": "ProgramRelayFBD.InfrastructureLayer.Details.ExportToFileService",
                "method": "ExportMacro",
                "signature": "Task ExportMacro(Macro macro, string fileName, IExportToFileProcessor<ExportMacroCommand> processor)",
            },
            {
                "type": "ProgramRelayFBD.ApplicationLayer.Importing.ImportComponentToProjectService",
                "method": "ImportFromStream",
                "signature": "Task ImportFromStream(Stream stream, string fileExtension)",
            },
            {
                "type": "ProgramRelayFBD.InfrastructureLayer.Adapters.Macros.MacroTemplateReader",
                "method": "GetMacroesFromArchive",
                "signature": "Task<IEnumerable<Macro>> GetMacroesFromArchive(Stream archiveStream)",
            },
            {
                "type": "ProgramRelayFBD.ApplicationLayer.OnlineResources.IImportComponentsToLocalLibraryService",
                "method": "Import",
                "signature": "Task<OldFormatFilesData> Import(IList<string> fileNames, IComponentLocalLibraryPresenter libraryPresenter)",
            },
            {
                "type": "ProgramRelayFBD.ApplicationLayer.OnlineResources.IExportComponentsFromLocalLibraryService",
                "method": "Export",
                "signature": "Task Export(List<ComponentMetaDataBase> components, string destination, IComponentLocalLibraryPresenter presenter)",
            },
            {
                "type": "ProgramRelayFBD.ApplicationLayer.Macros.IRunMacroConverterService",
                "method": "Convert",
                "signature": "Task<string> Convert(string fileName)",
            },
        ],
        "online_component_urls": {
            "macros_ver2": {
                "url": "https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/Macros_Ver2/",
                "observed_in_program_dll": observed_strings.get("https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/Macros_Ver2/", False),
            },
            "macros_ver3_arrays": {
                "url": "https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/Macros_Ver3/",
                "observed_in_program_dll": observed_strings.get("https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/Macros_Ver3/", False),
            },
            "device_templates_ver2": {
                "url": "https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/DeviceTemplates_Ver2/",
                "observed_in_program_dll": observed_strings.get("https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/DeviceTemplates_Ver2/", False),
            },
            "st_functions": {
                "url": "https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/FunctionST/",
                "observed_in_program_dll": observed_strings.get("https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/FunctionST/", False),
            },
            "st_function_blocks": {
                "url": "https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/FunctionblockST/",
                "observed_in_program_dll": observed_strings.get("https://ftp.owendigital.ru/softupdate/OWEN Logic/OnlineComponents/FunctionblockST/", False),
            },
        },
        "observed_binary_strings": observed_strings,
        "local_sample_search": {
            "enabled": scan_local_roots,
            "patterns": list(VENDOR_MACRO_FILE_PATTERNS),
            "sample_count": sample_count,
            "roots": local_samples,
        },
        "codex_macro_package_is_vendor_format": False,
        "safe_automation_status": "vendor file surfaces detected; proprietary import/export execution remains intentionally unimplemented without a trusted local sample or explicit GUI workflow proof",
        "guardrail": "Read-only installed-file audit only: no GUI launch, no network request, no import/export execution, no project mutation, no COM/TCP.",
        "read_only": True,
        "opened_gui": False,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "live_device_action_executed": False,
        "limitation": "This tool identifies OWEN proprietary macro/component file surfaces and internal API names. It does not reverse the full binary/archive payload schema and does not claim vendor macro import/export parity.",
    }


def program_file_analysis(args: dict[str, Any]) -> dict[str, Any]:
    max_items = clamp_int(args.get("max_items"), 24, 1, 200)
    include_hashes = bool(args.get("include_hashes", False))
    include_file_lists = bool(args.get("include_file_lists", True))
    include_compiler_surface = bool(args.get("include_compiler_surface", True))
    include_compiler_strings = bool(args.get("include_compiler_strings", False))
    include_compiler_reflection = bool(args.get("include_compiler_reflection", False))
    include_process_check = bool(args.get("include_process_check", True))

    install = find_installation_data()
    install_dir_value = install.get("install_dir")
    if not install_dir_value:
        return {
            "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
            "ok": False,
            "installation": install,
            "error": "OWEN Logic installation directory was not found",
            "read_only": True,
            "opened_gui": False,
            "opened_serial_port": False,
            "opened_network_socket": False,
            "live_device_action_executed": False,
        }
    install_dir = Path(str(install_dir_value))
    files = all_install_files(install_dir)
    target_catalog = installed_target_catalog(500)
    valid_targets = target_catalog.get("valid_dev_values") or []
    pr_targets = [value for value in valid_targets if str(value).upper().startswith("PR")]
    required_tools = [
        "owen_logic_program_file_analysis",
        "owen_logic_project_create_from_scratch",
        "owen_logic_project_validate",
        "owen_logic_component_catalog",
        "owen_logic_display_catalog",
        "owen_logic_compiler_surface_probe",
        "owen_logic_project_target_inspect",
    ]
    current_tools = {str(tool.get("name")) for tool in TOOLS}

    file_lists: dict[str, Any] | None = None
    if include_file_lists:
        file_lists = {
            "exe_files": bounded_program_files(install_dir, files, lambda path: path.suffix.lower() == ".exe", max_items, include_hashes),
            "largest_dll_files": [
                {**safe_file_info(path, include_hash=include_hashes), "relative_path": safe_relative(path, install_dir)}
                for path in sorted((path for path in files if path.suffix.lower() == ".dll"), key=lambda item: item.stat().st_size, reverse=True)[:max_items]
            ],
            "firmware_files": bounded_program_files(install_dir, files, lambda path: path.suffix.lower() == ".fw", max_items, include_hashes),
            "json_files": bounded_program_files(install_dir, files, lambda path: path.suffix.lower() == ".json", max_items, include_hashes),
        }

    compiler_summary: dict[str, Any] | None = None
    if include_compiler_surface:
        compiler_summary = compact_compiler_surface_summary(max_items, include_compiler_strings, include_compiler_reflection)

    running_processes = tasklist_programrelay() if include_process_check and os.name == "nt" else None
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "ok": True,
        "installation": install,
        "analysis_scope": "read-only installed OWEN Logic program file/catalog/metadata analysis",
        "file_counts": program_file_counts(install_dir, files),
        "deps_json": program_deps_summary(install_dir, max_items),
        "target_catalog": {
            "valid_count": len(valid_targets),
            "pr_count": len(pr_targets),
            "valid_dev_values_returned": valid_targets[:max_items],
            "pr_dev_values_returned": pr_targets[:max_items],
            "sources": target_catalog.get("sources"),
            "truncated": target_catalog.get("truncated"),
        },
        "component_catalog": compact_component_summary(max_items, include_hashes),
        "display_catalog": compact_display_summary(max_items, include_hashes),
        "library_catalog": compact_library_summary(max_items),
        "xml_roots": xml_root_analysis(install_dir, files, max_items, include_hashes),
        "surface_filename_hits": surface_filename_hits(install_dir, files, max_items),
        "compiler_surface": compiler_summary,
        "file_lists": file_lists,
        "running_programrelayfbd_processes": running_processes,
        "required_tool_checks": {name: name in current_tools for name in required_tools},
        "required_tools_ok": all(name in current_tools for name in required_tools),
        "source_policy": {
            "created_new_owle_zip": False,
            "copied_existing_owle_as_base": False,
            "gui_used": False,
            "opened_serial_port": False,
            "opened_network_socket": False,
            "live_device_action_executed": False,
        },
        "read_only": True,
        "opened_gui": False,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "live_device_action_executed": False,
        "limitation": "This is installed-file/catalog analysis. It does not decompile full C# source, run the GUI, execute the converter on a project, open COM/IP, or claim authoritative compiler diagnostics. Compiler reflection is skipped unless include_compiler_reflection=true.",
    }


def installation_catalog(args: dict[str, Any]) -> dict[str, Any]:
    install = find_installation_data()
    install_dir_value = install.get("install_dir")
    if not install_dir_value:
        raise FileNotFoundError("OWEN Logic installation directory was not found")
    install_dir = Path(str(install_dir_value))
    converter_path = install.get("converter_executable")
    converter_dir = Path(str(converter_path)).parent if converter_path else install_dir / "ProjectJsonConverter"
    include_hashes = bool(args.get("include_file_hashes", False))
    max_files = clamp_int(args.get("max_files"), 200, 1, 1000)

    def bucket(root: Path, patterns: tuple[str, ...], label: str) -> dict[str, Any]:
        if not root.exists():
            return {"label": label, "root": str(root), "exists": False, "files": []}
        paths = list_files_limited(root, patterns, max_files)
        return {
            "label": label,
            "root": str(root),
            "exists": True,
            "file_count_returned": len(paths),
            "files": [
                {
                    **safe_file_info(path, include_hash=include_hashes),
                    "relative_path": safe_relative(path, root),
                }
                for path in paths
            ],
        }

    help_pages: dict[str, Any] | None = None
    help_pages_path = install_dir / "Help" / "HelpPages.xml"
    if help_pages_path.exists():
        try:
            tree = ElementTree.parse(help_pages_path)
            root = tree.getroot()
            all_elements = list(root.iter())
            help_pages = {
                "path": str(help_pages_path),
                "root_tag": root.tag,
                "element_count": len(all_elements),
                "sample_tags": sorted({element.tag for element in all_elements})[:20],
            }
        except Exception as exc:
            help_pages = {"path": str(help_pages_path), "error": str(exc)}

    return {
        "installation": install,
        "catalogs": {
            "help": bucket(install_dir / "Help", ("*.chm", "*.xml"), "Help files"),
            "input_output_modules": bucket(
                install_dir / "InputOutputModules",
                ("*.xml", "*.dll"),
                "Input/output module descriptions and assemblies",
            ),
            "project_json_converter_st": bucket(
                converter_dir / "ST",
                ("*.dll", "*.xml"),
                "ProjectJsonConverter ST editor/language assemblies",
            ),
            "modbus": bucket(install_dir, ("*Modbus*.dll",), "Modbus assemblies"),
            "device_templates": bucket(install_dir, ("*Template*.dll", "*Template*.xml"), "Device/template assemblies"),
        },
        "help_pages": help_pages,
    }


def project_list(args: dict[str, Any]) -> dict[str, Any]:
    root = Path(str(args.get("root_path") or "")).expanduser().resolve()
    if not root.exists():
        raise FileNotFoundError(f"Root path not found: {root}")
    if not root.is_dir():
        raise NotADirectoryError(f"Root path is not a directory: {root}")
    max_results = clamp_int(args.get("max_results"), 100, 1, 5000)
    include_hashes = bool(args.get("include_hashes", False))
    patterns = ("*.owle", "*.owl", "*.owp", "*.prj")
    files = list_files_limited(root, patterns, max_results)
    return {
        "root_path": str(root),
        "patterns": list(patterns),
        "returned": len(files),
        "truncated": len(files) >= max_results,
        "projects": [
            {
                **safe_file_info(path, include_hash=include_hashes),
                "relative_path": safe_relative(path, root),
                "is_zip": zipfile.is_zipfile(path),
            }
            for path in files
        ],
    }


def redact_json_summary(value: Any, include_source: bool, max_items: int, depth: int = 0) -> Any:
    if depth > 4:
        return "<max-depth>"
    if isinstance(value, dict):
        result: dict[str, Any] = {}
        for key, item in list(value.items())[:max_items]:
            key_text = str(key)
            if key_text.lower() == "password":
                result["password_present"] = bool(item)
            elif key_text.lower() == "sourcecode" and not include_source:
                result["source_code_present"] = bool(item)
                result["source_code_line_count"] = len(str(item).splitlines()) if item else 0
            elif isinstance(item, (dict, list)):
                result[key_text] = redact_json_summary(item, include_source, max_items, depth + 1)
            elif isinstance(item, str) and len(item) > 500:
                result[key_text] = item[:497] + "..."
            else:
                result[key_text] = item
        if len(value) > max_items:
            result["truncated_key_count"] = len(value) - max_items
        return result
    if isinstance(value, list):
        return [redact_json_summary(item, include_source, max_items, depth + 1) for item in value[:max_items]]
    return value


def summarize_project_section(project_obj: Any, max_items: int) -> dict[str, Any]:
    if not isinstance(project_obj, dict):
        return {"type": type(project_obj).__name__}
    documents: list[dict[str, Any]] = []
    for document_id, document in list(project_obj.items())[:max_items]:
        if not isinstance(document, dict):
            documents.append({"id": document_id, "type": type(document).__name__})
            continue
        metadata = document.get("MetaData")
        doc_model = document.get("DocumentModel")
        documents.append(
            {
                "id": document_id,
                "discriminator": document.get("Discriminator"),
                "keys": list(document.keys()),
                "password_present": bool(document.get("Password")),
                "metadata_type": type(metadata).__name__ if metadata is not None else None,
                "metadata_keys": list(metadata.keys()) if isinstance(metadata, dict) else None,
                "document_model_type": type(doc_model).__name__ if doc_model is not None else None,
                "document_model_keys": list(doc_model.keys())[:40] if isinstance(doc_model, dict) else None,
            }
        )
    return {
        "type": "dict",
        "document_count": len(project_obj),
        "documents_returned": len(documents),
        "documents": documents,
    }


def summarize_st_function_blocks(blocks: Any, include_source: bool, max_items: int) -> dict[str, Any]:
    if not isinstance(blocks, list):
        return {"type": type(blocks).__name__}
    result: list[dict[str, Any]] = []
    for block in blocks[:max_items]:
        if not isinstance(block, dict):
            result.append({"type": type(block).__name__})
            continue
        source = str(block.get("SourceCode") or "")
        row = {
            "id": block.get("Id"),
            "name": block.get("Name"),
            "password_present": bool(block.get("Password")),
            "input_names": block.get("InputNames"),
            "output_names": block.get("OutputNames"),
            "variable_names": block.get("VariableNames"),
            "fb_instance_count": len(block.get("FbInstances") or []),
            "source_code_present": bool(source),
            "source_code_line_count": len(source.splitlines()) if source else 0,
        }
        if include_source:
            row["source_code"] = source
        result.append(row)
    return {
        "type": "list",
        "block_count": len(blocks),
        "blocks_returned": len(result),
        "blocks": result,
    }


def summarize_visualization(visualization: Any, max_items: int) -> dict[str, Any]:
    if not isinstance(visualization, list):
        return {"type": type(visualization).__name__}
    groups: list[dict[str, Any]] = []
    for group in visualization[:max_items]:
        if not isinstance(group, dict):
            groups.append({"type": type(group).__name__})
            continue
        screens = group.get("Screens") or []
        groups.append(
            {
                "name": group.get("Name"),
                "description": group.get("Description"),
                "document_uid": group.get("DocumentUId"),
                "screen_count": len(screens) if isinstance(screens, list) else None,
                "screens": [
                    redact_json_summary(screen, include_source=False, max_items=12)
                    for screen in (screens[: min(len(screens), max_items)] if isinstance(screens, list) else [])
                ],
            }
        )
    return {"type": "list", "group_count": len(visualization), "groups_returned": len(groups), "groups": groups}


def compact_string(value: str, limit: int = 240) -> str:
    text = " ".join(value.split())
    return text[: limit - 3] + "..." if len(text) > limit else text


def redact_scalar(key: str, value: Any) -> Any:
    key_lower = key.lower()
    if key_lower == "password":
        return {"redacted": True, "present": bool(value)}
    if key_lower == "sourcecode":
        text = str(value or "")
        return {"redacted": True, "present": bool(text), "line_count": len(text.splitlines()) if text else 0}
    if key_lower in {"image", "modelserializeddata"}:
        text = str(value or "")
        return {"redacted": True, "present": bool(text), "length": len(text)}
    if isinstance(value, str):
        return compact_string(value)
    return value


def read_owle_sections(project: Path, include_hashes: bool = False) -> dict[str, Any]:
    project = project.expanduser().resolve()
    if not project.exists():
        raise FileNotFoundError(f"Project file not found: {project}")
    if not project.is_file():
        raise ValueError(f"Project path is not a file: {project}")
    if not zipfile.is_zipfile(project):
        raise ValueError(f"Project file is not a ZIP-based .owle container: {project}")

    entries: list[dict[str, Any]] = []
    sections: dict[str, Any] = {}
    with zipfile.ZipFile(project) as archive:
        for zip_info in archive.infolist():
            data = archive.read(zip_info.filename)
            entry: dict[str, Any] = {
                "name": zip_info.filename,
                "size": zip_info.file_size,
                "compressed_size": zip_info.compress_size,
                "crc": f"{zip_info.CRC:08X}",
                "json_parseable": False,
            }
            if include_hashes:
                entry["sha256"] = sha256_bytes(data)
            try:
                parsed = json.loads(data.decode("utf-8"))
                sections[zip_info.filename] = parsed
                entry["json_parseable"] = True
                entry["json_type"] = type(parsed).__name__
                entry["top_level_count"] = len(parsed) if isinstance(parsed, (dict, list)) else None
            except Exception as exc:
                entry["parse_error"] = str(exc)
            entries.append(entry)

    return {"file": safe_file_info(project, include_hash=include_hashes), "entries": entries, "sections": sections}


def project_documents(project_section: Any) -> list[dict[str, Any]]:
    if not isinstance(project_section, dict):
        return []
    documents: list[dict[str, Any]] = []
    for document_id, document in project_section.items():
        if isinstance(document, dict):
            model = document.get("DocumentModel")
            if isinstance(model, dict):
                documents.append({"id": document_id, "document": document, "model": model})
    return documents


def inspect_project_file(args: dict[str, Any]) -> dict[str, Any]:
    project = Path(str(args.get("project_path") or "")).expanduser().resolve()
    if not project.exists():
        raise FileNotFoundError(f"Project file not found: {project}")
    if not project.is_file():
        raise ValueError(f"Project path is not a file: {project}")
    include_hashes = bool(args.get("include_hashes", True))
    include_source = bool(args.get("include_source", False))
    max_items = clamp_int(args.get("max_items"), 40, 1, 500)

    info = safe_file_info(project, include_hash=include_hashes)
    is_zip = zipfile.is_zipfile(project)
    result: dict[str, Any] = {
        "file": info,
        "container": {"is_zip": is_zip, "entries": []},
        "sections": {},
        "notes": [],
    }
    if not is_zip:
        result["notes"].append("File is not a ZIP-based OWEN Logic container.")
        return result

    with zipfile.ZipFile(project) as archive:
        for zip_info in archive.infolist():
            data = archive.read(zip_info.filename)
            entry: dict[str, Any] = {
                "name": zip_info.filename,
                "size": zip_info.file_size,
                "compressed_size": zip_info.compress_size,
                "crc": f"{zip_info.CRC:08X}",
                "json_parseable": False,
            }
            if include_hashes:
                entry["sha256"] = sha256_bytes(data)
            try:
                decoded = data.decode("utf-8")
                parsed = json.loads(decoded)
                entry["json_parseable"] = True
                entry["json_type"] = type(parsed).__name__
                if isinstance(parsed, dict):
                    entry["top_level_count"] = len(parsed)
                    entry["sample_keys"] = list(parsed.keys())[:20]
                elif isinstance(parsed, list):
                    entry["top_level_count"] = len(parsed)
                if zip_info.filename == "Project":
                    result["sections"]["project"] = summarize_project_section(parsed, max_items=max_items)
                elif zip_info.filename == "StFunctionBlocks":
                    result["sections"]["st_function_blocks"] = summarize_st_function_blocks(
                        parsed, include_source=include_source, max_items=max_items
                    )
                elif zip_info.filename == "Visualization":
                    result["sections"]["visualization"] = summarize_visualization(parsed, max_items=max_items)
                else:
                    result["sections"][zip_info.filename] = redact_json_summary(
                        parsed, include_source=include_source, max_items=max_items
                    )
            except Exception as exc:
                entry["parse_error"] = str(exc)
            result["container"]["entries"].append(entry)

    return result


def decode_display_background(value: Any) -> tuple[bytes | None, dict[str, Any]]:
    if not isinstance(value, str) or not value.strip():
        return None, {"present": False}
    text = value.strip()
    encoded = text.split(",", 1)[1] if text.lower().startswith("data:") and "," in text else text
    info: dict[str, Any] = {
        "present": True,
        "base64_length": len(text),
    }
    try:
        data = base64.b64decode(encoded, validate=True)
    except Exception as exc:
        info["decode_error"] = str(exc)
        return None, info
    info.update(
        {
            "decoded_bytes": len(data),
            "sha256": sha256_bytes(data),
            "image_format": "png" if data.startswith(b"\x89PNG\r\n\x1a\n") else "unknown",
        }
    )
    return data, info


def summarize_display_element(index: int, element: Any) -> dict[str, Any]:
    if not isinstance(element, dict):
        return {"index": index, "type": type(element).__name__}
    model = element.get("ElementModel") if isinstance(element.get("ElementModel"), dict) else {}
    properties = element.get("Properties") if isinstance(element.get("Properties"), list) else []
    property_names: list[str] = []
    for property_row in properties[:30]:
        if not isinstance(property_row, dict):
            continue
        element_property = property_row.get("ElementProperty")
        if isinstance(element_property, dict) and element_property.get("Name") is not None:
            property_names.append(str(element_property.get("Name")))
    return {
        "index": index,
        "keys": list(element.keys())[:30],
        "unique_id": first_present(element, ("UniqueId", "Id", "ElementUId", "Guid")) or model.get("UniqueId"),
        "name": first_present(element, ("Name", "Title", "Caption", "Text")) or model.get("Title"),
        "title": model.get("Title"),
        "group_name": model.get("GroupName"),
        "type": first_present(element, ("Type", "ElementType", "Kind", "Discriminator")),
        "x": first_present(element, ("X", "Left")),
        "y": first_present(element, ("Y", "Top")),
        "width": first_present(element, ("Width", "W")),
        "height": first_present(element, ("Height", "H")),
        "variable_uid": first_present(element, ("VariableUId", "VariableUid", "VariableInfoUId")),
        "property_count": len(properties),
        "property_names": property_names,
        "summary": redact_json_summary(element, include_source=False, max_items=8),
    }


def summarize_display_visualization(visualization: Any, max_items: int, include_elements: bool, include_background_hash: bool) -> dict[str, Any]:
    if not isinstance(visualization, list):
        return {
            "visualization_type": type(visualization).__name__,
            "group_count": 0,
            "screen_count": 0,
            "element_count": 0,
            "groups_returned": 0,
            "groups": [],
        }

    groups: list[dict[str, Any]] = []
    total_screens = 0
    total_elements = 0
    total_backgrounds = 0
    for group_index, group in enumerate(visualization[:max_items]):
        if not isinstance(group, dict):
            groups.append({"index": group_index, "type": type(group).__name__})
            continue
        screens = group.get("Screens") or []
        screen_rows: list[dict[str, Any]] = []
        if isinstance(screens, list):
            total_screens += len(screens)
            for screen_index, screen in enumerate(screens[:max_items]):
                if not isinstance(screen, dict):
                    screen_rows.append({"index": screen_index, "type": type(screen).__name__})
                    continue
                prop = screen.get("Property") if isinstance(screen.get("Property"), dict) else {}
                screen_device = prop.get("ScreenDevice") if isinstance(prop.get("ScreenDevice"), dict) else {}
                document = screen_device.get("Document") if isinstance(screen_device.get("Document"), dict) else {}
                elements = document.get("Elements") or []
                transitions = prop.get("ListTransition", {}).get("Transitions") if isinstance(prop.get("ListTransition"), dict) else []
                background = screen.get("Background")
                _background_bytes, background_info = decode_display_background(background)
                if background_info.get("present"):
                    total_backgrounds += 1
                if not include_background_hash:
                    background_info.pop("sha256", None)
                element_count = len(elements) if isinstance(elements, list) else 0
                total_elements += element_count
                row: dict[str, Any] = {
                    "index": screen_index,
                    "unique_id": screen.get("UniqueId"),
                    "version": screen.get("Version"),
                    "title": screen_device.get("Title"),
                    "description": screen_device.get("Description"),
                    "screen_device_unique_id": screen_device.get("UniqueId"),
                    "should_hide_empty_rows": screen_device.get("ShouldHideEmptyRows"),
                    "document_unique_id": document.get("UniqueId"),
                    "symbols_per_line": document.get("SymbolsPerLine"),
                    "count_lines": document.get("CountLines"),
                    "document_width": document.get("Width"),
                    "document_height": document.get("Height"),
                    "canvas": {
                        "x": screen.get("X"),
                        "y": screen.get("Y"),
                        "width": screen.get("Width"),
                        "height": screen.get("Height"),
                    },
                    "element_count": element_count,
                    "transition_count": len(transitions) if isinstance(transitions, list) else None,
                    "background": background_info,
                }
                if include_elements:
                    row["elements_returned"] = min(element_count, max_items)
                    row["elements"] = [
                        summarize_display_element(element_index, element)
                        for element_index, element in enumerate(elements[:max_items] if isinstance(elements, list) else [])
                    ]
                screen_rows.append(row)
        groups.append(
            {
                "index": group_index,
                "name": group.get("Name"),
                "description": group.get("Description"),
                "document_uid": group.get("DocumentUId"),
                "screen_count": len(screens) if isinstance(screens, list) else None,
                "screens_returned": len(screen_rows),
                "screens": screen_rows,
            }
        )

    return {
        "visualization_type": "list",
        "group_count": len(visualization),
        "screen_count": total_screens,
        "element_count": total_elements,
        "background_count": total_backgrounds,
        "groups_returned": len(groups),
        "groups": groups,
    }


def project_display_summary(args: dict[str, Any]) -> dict[str, Any]:
    project = Path(str(args.get("project_path") or "")).expanduser().resolve()
    max_items = clamp_int(args.get("max_items"), 100, 1, 2000)
    loaded = read_owle_sections(project, include_hashes=True)
    visualization = loaded["sections"].get("Visualization")
    summary = summarize_display_visualization(
        visualization,
        max_items=max_items,
        include_elements=bool(args.get("include_elements", True)),
        include_background_hash=bool(args.get("include_background_hash", True)),
    )
    return {
        "file": loaded["file"],
        **summary,
        "source_hash_after": sha256_file(project),
        "read_only_project": True,
        "risk_class": "safe_read",
        "guardrail": "Project visualization was read-only; background image data is redacted from the tool response.",
    }


def default_display_export_dir() -> Path:
    workbench = find_workbench_root()
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    if workbench:
        return workbench / "30_LOCAL_HEAVY" / "sandbox_tmp" / "owen_logic_display_exports" / timestamp
    return (Path.home() / ".codex" / "tmp" / "owen_logic_display_exports" / timestamp).resolve()


def safe_display_export_name(value: Any, fallback: str) -> str:
    name = str(value or fallback).strip()
    name = re.sub(r"[^A-Za-z0-9_.-]+", "_", name).strip("._")
    if not name:
        name = fallback
    if not name.lower().endswith(".json"):
        name = f"{name}.json"
    return name[:140]


def project_display_export(args: dict[str, Any]) -> dict[str, Any]:
    project = Path(str(args.get("project_path") or "")).expanduser().resolve()
    before_hash = sha256_file(project)
    max_items = clamp_int(args.get("max_items"), 100, 1, 2000)
    output_arg = args.get("output_dir")
    output_dir = Path(str(output_arg)).expanduser().resolve() if output_arg else default_display_export_dir()
    if not is_scratch_destination(output_dir):
        raise ValueError(f"Refusing to write display export outside scratch/sandbox/local-heavy path: {output_dir}")
    output_dir.mkdir(parents=True, exist_ok=True)

    loaded = read_owle_sections(project, include_hashes=True)
    visualization = loaded["sections"].get("Visualization")
    summary = summarize_display_visualization(
        visualization,
        max_items=max_items,
        include_elements=True,
        include_background_hash=True,
    )
    json_path = output_dir / safe_display_export_name(args.get("package_name"), f"{project.stem}_display_summary")
    exported_backgrounds: list[dict[str, Any]] = []
    if bool(args.get("export_backgrounds", True)) and isinstance(visualization, list):
        for group_index, group in enumerate(visualization):
            if not isinstance(group, dict):
                continue
            screens = group.get("Screens") or []
            if not isinstance(screens, list):
                continue
            for screen_index, screen in enumerate(screens):
                if not isinstance(screen, dict):
                    continue
                data, info = decode_display_background(screen.get("Background"))
                if data is None:
                    continue
                stem = f"group_{group_index:03d}_screen_{screen_index:03d}_background"
                path = output_dir / f"{stem}.png"
                path.write_bytes(data)
                prop = screen.get("Property") if isinstance(screen.get("Property"), dict) else {}
                screen_device = prop.get("ScreenDevice") if isinstance(prop.get("ScreenDevice"), dict) else {}
                exported_backgrounds.append(
                    {
                        "group_index": group_index,
                        "screen_index": screen_index,
                        "screen_unique_id": screen.get("UniqueId"),
                        "screen_title": screen_device.get("Title"),
                        "background": info,
                        "file": safe_file_info(path, include_hash=True),
                    }
                )

    export_payload = {
        "format": "codex_owen_display_summary_v1",
        "created_at": datetime.now().astimezone().isoformat(),
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "source_project": loaded["file"],
        "summary": summary,
        "exported_backgrounds": exported_backgrounds,
        "limitations": [
            "This is a sanitized Codex read-only Visualization export, not OWEN Logic display editor automation.",
            "Background image base64 is not embedded in JSON; decoded background files are written separately when requested.",
        ],
    }
    json_path.write_text(json.dumps(export_payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    after_hash = sha256_file(project)
    return {
        "export": safe_file_info(json_path, include_hash=True),
        "format": export_payload["format"],
        "source_project": loaded["file"],
        "source_hash_before": before_hash,
        "source_hash_after": after_hash,
        "read_only_project": True,
        "changed_source": before_hash != after_hash,
        "group_count": summary.get("group_count"),
        "screen_count": summary.get("screen_count"),
        "element_count": summary.get("element_count"),
        "background_count": summary.get("background_count"),
        "exported_background_count": len(exported_backgrounds),
        "exported_backgrounds": exported_backgrounds,
        "risk_class": "safe_read",
        "guardrail": "Project visualization was read-only; JSON/PNG evidence was written only under scratch/sandbox/local-heavy.",
    }


def safe_display_output_stem(value: Any, fallback: str) -> str:
    name = str(value or fallback).strip()
    name = re.sub(r"[^A-Za-z0-9_.-]+", "_", name).strip("._")
    if not name:
        name = fallback
    return name[:120]


def select_display_screen_for_read(
    visualization: list[Any],
    group_index: int,
    screen_index: int,
    screen_unique_id: str | None,
) -> tuple[int, dict[str, Any], int, dict[str, Any]]:
    group = select_display_group(visualization, group_index)
    screens = group.get("Screens")
    if not isinstance(screens, list):
        raise ValueError("Selected Visualization group has no Screens list")
    if screen_unique_id:
        expected = screen_unique_id.strip().lower()
        for index, screen in enumerate(screens):
            if isinstance(screen, dict) and str(screen.get("UniqueId") or "").lower() == expected:
                return group_index, group, index, screen
        raise ValueError(f"Display screen_unique_id was not found: {screen_unique_id}")
    _group, screen = select_display_screen(visualization, group_index, screen_index)
    return group_index, group, screen_index, screen


def display_element_property_value(element: dict[str, Any], property_name: str) -> Any:
    selected = display_property_by_name(element, property_name)
    if selected is None:
        return None
    _property_index, property_row, _element_property = selected
    return display_property_raw_value(property_row)


def display_element_text_for_preview(element: dict[str, Any]) -> str:
    raw_text = display_element_property_value(element, "Text")
    if raw_text is not None:
        return compact_string(str(raw_text))
    model = display_element_model(element)
    primitives = model.get("Primitives")
    if not isinstance(primitives, list):
        return ""
    chars: list[str] = []
    for primitive in primitives:
        if isinstance(primitive, dict) and primitive.get("Text") is not None:
            chars.append(str(primitive.get("Text") or ""))
    return compact_string("".join(chars))


def display_element_visible_for_preview(element: dict[str, Any]) -> bool:
    raw = display_element_property_value(element, "IsVisible")
    if isinstance(raw, bool):
        return raw
    if isinstance(raw, str):
        return raw.strip().lower() not in {"false", "0", "no", "off"}
    return True


def display_element_preview_box(element: dict[str, Any]) -> tuple[int, int, int, int]:
    model = display_element_model(element)
    desire_size = model.get("DesireSize") if isinstance(model.get("DesireSize"), dict) else {}
    x = display_property_int_value(element, "CoordinateX", 0)
    y = display_property_int_value(element, "CoordinateY", 0)
    width = desire_size.get("Width")
    height = desire_size.get("Height")
    if not isinstance(width, int) or width <= 0:
        length = display_element_property_value(element, "ElementLength")
        try:
            width = max(24, int(length) * 40)
        except (TypeError, ValueError):
            width = 120
    if not isinstance(height, int) or height <= 0:
        height = 40
    return int(x), int(y), int(width), int(height)


def display_preview_font(font_size: int) -> Any:
    try:
        from PIL import ImageFont
    except Exception:
        return None
    candidates: list[Path] = []
    windir = os.environ.get("WINDIR")
    if windir:
        candidates.extend(
            [
                Path(windir) / "Fonts" / "segoeui.ttf",
                Path(windir) / "Fonts" / "arial.ttf",
                Path(windir) / "Fonts" / "calibri.ttf",
            ]
        )
    for candidate in candidates:
        if candidate.exists():
            try:
                return ImageFont.truetype(str(candidate), font_size)
            except Exception:
                continue
    return ImageFont.load_default()


def fit_text_for_width(draw: Any, text: str, font: Any, width: int) -> str:
    if width <= 0:
        return text

    def text_width(value: str) -> int:
        try:
            box = draw.textbbox((0, 0), value, font=font)
            return int(box[2] - box[0])
        except Exception:
            return len(value) * 8

    if text_width(text) <= width:
        return text
    ellipsis = "..."
    available = max(1, width - text_width(ellipsis))
    result = text
    while result and text_width(result) > available:
        result = result[:-1]
    return f"{result}{ellipsis}" if result else ellipsis


def render_display_preview_with_system_drawing(
    png_path: Path,
    width: int,
    height: int,
    background_data: bytes | None,
    overlays: list[dict[str, Any]],
    scale: float,
) -> dict[str, Any]:
    if os.name != "nt":
        raise RuntimeError("Pillow is unavailable and System.Drawing fallback is only supported on Windows")
    payload = {
        "outputPath": str(png_path),
        "width": int(max(1, min(4096, width))),
        "height": int(max(1, min(4096, height))),
        "backgroundBase64": base64.b64encode(background_data).decode("ascii") if background_data else None,
        "overlays": overlays,
        "scale": scale,
    }
    script = r"""
[Console]::InputEncoding = [Text.UTF8Encoding]::UTF8
[Console]::OutputEncoding = [Text.UTF8Encoding]::UTF8
Add-Type -AssemblyName System.Drawing
$inputObject = [Console]::In.ReadToEnd() | ConvertFrom-Json
$out = [string]$inputObject.outputPath
$width = [Math]::Max(1, [int]$inputObject.width)
$height = [Math]::Max(1, [int]$inputObject.height)
$scale = [double]$inputObject.scale
$bmp = $null
$gfx = $null
$source = $null
$ms = $null
try {
  if ($inputObject.backgroundBase64) {
    $bytes = [Convert]::FromBase64String([string]$inputObject.backgroundBase64)
    $ms = New-Object System.IO.MemoryStream -ArgumentList (,$bytes)
    $source = [System.Drawing.Image]::FromStream($ms)
    $bmp = New-Object System.Drawing.Bitmap -ArgumentList $source.Width, $source.Height, ([System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $gfx = [System.Drawing.Graphics]::FromImage($bmp)
    $gfx.DrawImage($source, 0, 0, $source.Width, $source.Height)
  } else {
    $bmp = New-Object System.Drawing.Bitmap -ArgumentList $width, $height, ([System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $gfx = [System.Drawing.Graphics]::FromImage($bmp)
    $gfx.Clear([System.Drawing.Color]::White)
  }
  $gfx.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
  $gfx.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::ClearTypeGridFit
  $pen = New-Object System.Drawing.Pen ([System.Drawing.Color]::FromArgb(180,64,64,64)), 1
  $brush = New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::Black)
  foreach ($overlay in @($inputObject.overlays)) {
    $box = $overlay.box
    $x = [int]$box.x
    $y = [int]$box.y
    $w = [Math]::Max(1, [int]$box.width)
    $h = [Math]::Max(1, [int]$box.height)
    $fontSize = [Math]::Max(8, [Math]::Min(96, [double]$overlay.font_size))
    try {
      $font = New-Object System.Drawing.Font "Segoe UI", $fontSize, ([System.Drawing.FontStyle]::Regular), ([System.Drawing.GraphicsUnit]::Pixel)
    } catch {
      $font = New-Object System.Drawing.Font ([System.Drawing.FontFamily]::GenericSansSerif), $fontSize, ([System.Drawing.FontStyle]::Regular), ([System.Drawing.GraphicsUnit]::Pixel)
    }
    $gfx.DrawRectangle($pen, $x, $y, $w, $h)
    $rect = New-Object System.Drawing.RectangleF -ArgumentList ([float]($x + 3)), ([float]($y + [Math]::Max(1, [int]($h * 0.18)))), ([float]($w - 6)), ([float]$h)
    $gfx.DrawString([string]$overlay.rendered_text, $font, $brush, $rect)
    $font.Dispose()
  }
  $final = $bmp
  $finalGfx = $null
  if ($scale -ne 1.0) {
    $newWidth = [Math]::Max(1, [int]($bmp.Width * $scale))
    $newHeight = [Math]::Max(1, [int]($bmp.Height * $scale))
    $final = New-Object System.Drawing.Bitmap -ArgumentList $newWidth, $newHeight, ([System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $finalGfx = [System.Drawing.Graphics]::FromImage($final)
    $finalGfx.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
    $finalGfx.DrawImage($bmp, 0, 0, $newWidth, $newHeight)
  }
  $final.Save($out, [System.Drawing.Imaging.ImageFormat]::Png)
  [pscustomobject]@{
    path = $out
    width = $final.Width
    height = $final.Height
    backend = "System.Drawing"
  } | ConvertTo-Json -Compress
} finally {
  if ($finalGfx -ne $null) { $finalGfx.Dispose() }
  if ($final -ne $null -and -not [object]::ReferenceEquals($final, $bmp)) { $final.Dispose() }
  if ($brush -ne $null) { $brush.Dispose() }
  if ($pen -ne $null) { $pen.Dispose() }
  if ($gfx -ne $null) { $gfx.Dispose() }
  if ($bmp -ne $null) { $bmp.Dispose() }
  if ($source -ne $null) { $source.Dispose() }
  if ($ms -ne $null) { $ms.Dispose() }
}
"""
    completed = subprocess.run(
        ["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", script],
        input=json.dumps(payload, ensure_ascii=False),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        encoding="utf-8",
        errors="replace",
        timeout=60,
        creationflags=subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0,
    )
    stdout = completed.stdout.strip()
    stderr = completed.stderr.strip()
    if completed.returncode != 0 or not png_path.exists():
        raise RuntimeError(stderr or stdout or f"System.Drawing preview renderer exited with code {completed.returncode}")
    try:
        rendered = json.loads(stdout)
    except json.JSONDecodeError as exc:
        raise RuntimeError(f"System.Drawing preview renderer did not return JSON: {stdout[:1000]}") from exc
    return dict(rendered)


def project_display_preview_export(args: dict[str, Any]) -> dict[str, Any]:
    try:
        from PIL import Image, ImageDraw
    except Exception as exc:
        Image = None
        ImageDraw = None
        pillow_error = str(exc)
    else:
        pillow_error = None

    project = Path(str(args.get("project_path") or "")).expanduser().resolve()
    before_hash = sha256_file(project)
    output_arg = args.get("output_dir")
    output_dir = Path(str(output_arg)).expanduser().resolve() if output_arg else default_display_export_dir()
    if not is_scratch_destination(output_dir):
        raise ValueError(f"Refusing to write display preview outside scratch/sandbox/local-heavy path: {output_dir}")
    output_dir.mkdir(parents=True, exist_ok=True)

    loaded = read_owle_sections(project, include_hashes=True)
    visualization = loaded["sections"].get("Visualization")
    if not isinstance(visualization, list):
        raise ValueError("Visualization section is not a list")
    group_index_arg = require_non_negative_index("group_index", args.get("group_index"), 0)
    screen_index_arg = require_non_negative_index("screen_index", args.get("screen_index"), 0)
    screen_unique_id = str(args.get("screen_unique_id") or "").strip() or None
    group_index, group, screen_index, screen = select_display_screen_for_read(
        visualization,
        group_index_arg,
        screen_index_arg,
        screen_unique_id,
    )
    _prop, screen_device, document = display_screen_device(screen)
    elements = document.get("Elements")
    if not isinstance(elements, list):
        elements = []

    background_data, background_info = decode_display_background(screen.get("Background"))
    image = None
    if Image is not None and bool(args.get("include_background", True)) and background_data is not None:
        try:
            image = Image.open(io.BytesIO(background_data)).convert("RGBA")
        except Exception as exc:
            background_info["open_error"] = str(exc)
    if image is None:
        width = document.get("Width") or screen.get("Width") or 320
        height = document.get("Height") or screen.get("Height") or 180
        try:
            width = max(1, min(4096, int(width)))
            height = max(1, min(4096, int(height)))
        except (TypeError, ValueError):
            width, height = 320, 180
        base_width, base_height = width, height
        if Image is not None:
            image = Image.new("RGBA", (width, height), (255, 255, 255, 255))
    else:
        base_width, base_height = int(image.width), int(image.height)
    if Image is None and pillow_error:
        background_info["renderer_fallback"] = f"Pillow unavailable: {pillow_error}"

    draw = ImageDraw.Draw(image) if ImageDraw is not None and image is not None else None
    max_text_elements = clamp_int(args.get("max_text_elements"), 100, 1, 1000)
    overlays: list[dict[str, Any]] = []
    skipped_elements: list[dict[str, Any]] = []
    for element_index, element in enumerate(elements):
        if len(overlays) >= max_text_elements:
            skipped_elements.append({"index": element_index, "reason": "max_text_elements"})
            continue
        if not isinstance(element, dict):
            skipped_elements.append({"index": element_index, "reason": "not_object"})
            continue
        model = display_element_model(element)
        if not display_element_visible_for_preview(element):
            skipped_elements.append({"index": element_index, "reason": "not_visible", "title": model.get("Title")})
            continue
        text = display_element_text_for_preview(element)
        if not text:
            skipped_elements.append({"index": element_index, "reason": "no_text", "title": model.get("Title")})
            continue
        x, y, width, height = display_element_preview_box(element)
        font_size = max(8, min(96, int(height * 0.45) if height else 16))
        if draw is not None:
            font = display_preview_font(font_size)
            fitted_text = fit_text_for_width(draw, text, font, max(1, width - 6))
            try:
                draw.rectangle((x, y, x + width, y + height), outline=(64, 64, 64, 180), width=1)
                draw.text((x + 3, y + max(1, int(height * 0.18))), fitted_text, fill=(0, 0, 0, 255), font=font)
            except UnicodeEncodeError:
                fallback_text = fitted_text.encode("latin-1", "replace").decode("latin-1")
                draw.text((x + 3, y + max(1, int(height * 0.18))), fallback_text, fill=(0, 0, 0, 255), font=font)
                fitted_text = fallback_text
        else:
            max_chars = max(1, int(max(1, width - 6) / 8))
            fitted_text = text if len(text) <= max_chars else f"{text[: max(1, max_chars - 3)]}..."
        overlays.append(
            {
                "element_index": element_index,
                "element_unique_id": model.get("UniqueId") or element.get("UniqueId"),
                "title": model.get("Title"),
                "text": text,
                "rendered_text": fitted_text,
                "box": {"x": x, "y": y, "width": width, "height": height},
                "font_size": font_size,
            }
        )

    scale_raw = args.get("scale", 1.0)
    try:
        scale = float(scale_raw)
    except (TypeError, ValueError):
        raise ValueError("scale must be a number") from None
    if scale < 0.25 or scale > 4.0:
        raise ValueError("scale must be between 0.25 and 4.0")
    if image is not None and scale != 1.0:
        resampling = getattr(getattr(Image, "Resampling", Image), "LANCZOS")
        image = image.resize((max(1, int(image.width * scale)), max(1, int(image.height * scale))), resampling)

    stem = safe_display_output_stem(args.get("package_name"), f"{project.stem}_display_preview_g{group_index:03d}_s{screen_index:03d}")
    png_path = output_dir / f"{stem}.png"
    json_path = output_dir / f"{stem}.json"
    if image is not None:
        image.save(png_path, "PNG")
        image_width, image_height = int(image.width), int(image.height)
        renderer_backend = "Pillow"
    else:
        rendered = render_display_preview_with_system_drawing(
            png_path,
            base_width,
            base_height,
            background_data if bool(args.get("include_background", True)) else None,
            overlays,
            scale,
        )
        image_width = int(rendered.get("width") or max(1, int(base_width * scale)))
        image_height = int(rendered.get("height") or max(1, int(base_height * scale)))
        renderer_backend = str(rendered.get("backend") or "System.Drawing")

    after_hash = sha256_file(project)
    payload = {
        "format": "codex_owen_display_preview_v1",
        "created_at": datetime.now().astimezone().isoformat(),
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "source_project": loaded["file"],
        "source_hash_before": before_hash,
        "source_hash_after": after_hash,
        "read_only_project": True,
        "changed_source": before_hash != after_hash,
        "preview_kind": "codex_offline_visualization_model_preview",
        "group": {
            "index": group_index,
            "name": group.get("Name"),
            "document_uid": group.get("DocumentUId"),
        },
        "screen": {
            "index": screen_index,
            "unique_id": screen.get("UniqueId"),
            "title": screen_device.get("Title"),
            "document_unique_id": document.get("UniqueId"),
            "document_width": document.get("Width"),
            "document_height": document.get("Height"),
        },
        "background": background_info,
        "preview_image": safe_file_info(png_path, include_hash=True),
        "image_size": {"width": image_width, "height": image_height, "scale": scale},
        "renderer_backend": renderer_backend,
        "element_count": len(elements),
        "text_overlay_count": len(overlays),
        "overlays": overlays,
        "skipped_elements": skipped_elements[:100],
        "limitations": [
            "This PNG is a Codex offline preview built from stored .owle Visualization JSON, background PNG and text-like element properties.",
            "It is not an OWEN Logic GUI-rendered preview, not a display editor screenshot, and not live simulator capture/readback.",
            "Only visible text-like elements with stored Text/coordinate properties are overlaid; installed widget catalog rendering is not emulated.",
        ],
    }
    json_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return {
        "preview": safe_file_info(png_path, include_hash=True),
        "manifest": safe_file_info(json_path, include_hash=True),
        "format": payload["format"],
        "source_project": loaded["file"],
        "source_hash_before": before_hash,
        "source_hash_after": after_hash,
        "read_only_project": True,
        "changed_source": before_hash != after_hash,
        "preview_kind": payload["preview_kind"],
        "group_index": group_index,
        "group_name": group.get("Name"),
        "screen_index": screen_index,
        "screen_unique_id": screen.get("UniqueId"),
        "screen_title": screen_device.get("Title"),
        "image_size": payload["image_size"],
        "background": background_info,
        "element_count": len(elements),
        "text_overlay_count": len(overlays),
        "skipped_element_count": len(skipped_elements),
        "risk_class": "safe_read",
        "guardrail": "Project visualization was read-only; offline preview PNG/JSON evidence was written only under scratch/sandbox/local-heavy.",
        "limitation": "This is not an OWEN GUI-rendered display preview or live simulation capture; it is a Codex offline preview from the stored Visualization model.",
    }


DISPLAY_ELEMENT_VALUE_FIELDS = ("Value", "IntValue", "BoolValue", "FloatValue", "DoubleValue", "StringValue")


def read_visualization_section_from_entries(entries: list[dict[str, Any]]) -> list[Any]:
    for entry in entries:
        if entry["name"] == "Visualization":
            visualization = json.loads(entry["data"].decode("utf-8"))
            if not isinstance(visualization, list):
                raise ValueError("Visualization section is not a list")
            return visualization
    raise ValueError("Visualization section was not found in .owle container")


def require_non_negative_index(name: str, value: Any, default: int = 0) -> int:
    raw = default if value is None else value
    if isinstance(raw, bool):
        raise ValueError(f"{name} must be an integer index")
    try:
        index = int(raw)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{name} must be an integer index") from exc
    if index < 0:
        raise ValueError(f"{name} must be >= 0")
    return index


def select_display_group(visualization: list[Any], group_index: int) -> dict[str, Any]:
    try:
        group = visualization[group_index]
    except IndexError as exc:
        raise ValueError(f"Visualization group_index out of range: {group_index}") from exc
    if not isinstance(group, dict):
        raise ValueError(f"Visualization group at index {group_index} is not an object")
    screens = group.get("Screens")
    if not isinstance(screens, list):
        raise ValueError(f"Visualization group at index {group_index} has no Screens list")
    return group


def select_display_screen(visualization: list[Any], group_index: int, screen_index: int) -> tuple[dict[str, Any], dict[str, Any]]:
    group = select_display_group(visualization, group_index)
    screens = group.get("Screens")
    try:
        screen = screens[screen_index]
    except IndexError as exc:
        raise ValueError(f"Visualization screen_index out of range: {screen_index}") from exc
    if not isinstance(screen, dict):
        raise ValueError(f"Visualization screen at index {screen_index} is not an object")
    return group, screen


def summarize_display_group_for_write(group_index: int, group: dict[str, Any]) -> dict[str, Any]:
    screens = group.get("Screens")
    screen_rows: list[dict[str, Any]] = []
    if isinstance(screens, list):
        for screen_index, screen in enumerate(screens[:20]):
            if not isinstance(screen, dict):
                screen_rows.append({"index": screen_index, "type": type(screen).__name__})
                continue
            try:
                _prop, screen_device, document = display_screen_device(screen)
            except ValueError:
                screen_rows.append(
                    {
                        "index": screen_index,
                        "unique_id": screen.get("UniqueId"),
                        "valid_screen_device": False,
                    }
                )
                continue
            screen_rows.append(
                {
                    "index": screen_index,
                    "unique_id": screen.get("UniqueId"),
                    "title": screen_device.get("Title"),
                    "document_unique_id": document.get("UniqueId"),
                    "element_count": len(document.get("Elements")) if isinstance(document.get("Elements"), list) else 0,
                }
            )
    return {
        "group_index": group_index,
        "name": group.get("Name"),
        "description": group.get("Description"),
        "document_uid": group.get("DocumentUId"),
        "screen_count": len(screens) if isinstance(screens, list) else None,
        "screens_returned": len(screen_rows),
        "screens": screen_rows,
    }


def display_screen_device(screen: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    prop = screen.get("Property")
    if not isinstance(prop, dict):
        raise ValueError("Selected screen has no Property object")
    screen_device = prop.get("ScreenDevice")
    if not isinstance(screen_device, dict):
        raise ValueError("Selected screen has no Property.ScreenDevice object")
    document = screen_device.get("Document")
    if not isinstance(document, dict):
        raise ValueError("Selected screen has no Property.ScreenDevice.Document object")
    return prop, screen_device, document


def display_element_model(element: dict[str, Any]) -> dict[str, Any]:
    model = element.get("ElementModel")
    return model if isinstance(model, dict) else {}


def select_display_element(document: dict[str, Any], element_index: int, element_unique_id: str | None) -> tuple[int, dict[str, Any]]:
    elements = document.get("Elements")
    if not isinstance(elements, list):
        raise ValueError("Selected screen document has no Elements list")
    if element_unique_id:
        expected = element_unique_id.strip().lower()
        for index, element in enumerate(elements):
            if not isinstance(element, dict):
                continue
            model = display_element_model(element)
            actual = str(model.get("UniqueId") or element.get("UniqueId") or "").lower()
            if actual == expected:
                return index, element
        raise ValueError(f"Display element_unique_id was not found: {element_unique_id}")
    try:
        element = elements[element_index]
    except IndexError as exc:
        raise ValueError(f"Display element_index out of range: {element_index}") from exc
    if not isinstance(element, dict):
        raise ValueError(f"Display element at index {element_index} is not an object")
    return element_index, element


def select_display_property(element: dict[str, Any], property_name: str) -> tuple[int, dict[str, Any], dict[str, Any]]:
    properties = element.get("Properties")
    if not isinstance(properties, list):
        raise ValueError("Selected display element has no Properties list")
    for index, property_row in enumerate(properties):
        if not isinstance(property_row, dict):
            continue
        element_property = property_row.get("ElementProperty")
        if isinstance(element_property, dict) and element_property.get("Name") == property_name:
            return index, property_row, element_property
    raise ValueError(f"Display element property was not found: {property_name}")


def display_property_values(property_row: dict[str, Any]) -> dict[str, Any]:
    return {field: scalar_preview(property_row.get(field)) for field in DISPLAY_ELEMENT_VALUE_FIELDS if field in property_row}


def display_property_current_value(property_row: dict[str, Any], field: str) -> Any:
    if field not in property_row:
        return None
    return property_row.get(field)


def display_patch_value_from_args(args: dict[str, Any]) -> tuple[str, Any]:
    provided: list[tuple[str, Any]] = []
    if args.get("value") is not None:
        value = args.get("value")
        if isinstance(value, str):
            value = validate_patch_string("value", value, 1000, allow_empty=True)
        elif not isinstance(value, (int, float, bool)):
            raise ValueError("value must be a string, number or boolean")
        provided.append(("Value", value))
    if args.get("int_value") is not None:
        if isinstance(args.get("int_value"), bool):
            raise ValueError("int_value must be an integer")
        provided.append(("IntValue", int(validate_patch_number("int_value", args.get("int_value"), -1000000, 1000000))))
    if args.get("bool_value") is not None:
        if not isinstance(args.get("bool_value"), bool):
            raise ValueError("bool_value must be boolean")
        provided.append(("BoolValue", bool(args.get("bool_value"))))
    if args.get("float_value") is not None:
        provided.append(("FloatValue", validate_patch_number("float_value", args.get("float_value"), -1000000, 1000000)))
    if args.get("string_value") is not None:
        provided.append(("StringValue", validate_patch_string("string_value", args.get("string_value"), 1000, allow_empty=True)))
    if len(provided) != 1:
        raise ValueError("Provide exactly one of value, int_value, bool_value, float_value or string_value")
    return provided[0]


DISPLAY_GROUP_PATCH_FIELDS = ("name", "description")


def project_display_group_property_patch(args: dict[str, Any]) -> dict[str, Any]:
    target = resolve_scratch_write_target(args, "_display_group_property_patch_scratch")
    project_path = Path(str(target["target_path"]))
    before_hash = sha256_file(project_path)
    entries = read_owle_raw_entries(project_path)
    visualization = read_visualization_section_from_entries(entries)
    group_index = require_non_negative_index("group_index", args.get("group_index"), 0)

    supplied_fields = [field for field in DISPLAY_GROUP_PATCH_FIELDS if args.get(field) is not None]
    if not supplied_fields:
        raise ValueError("At least one group property patch field is required: name or description")

    group = select_display_group(visualization, group_index)
    screens = group.get("Screens")
    expected_group_name = args.get("expected_group_name")
    if expected_group_name is not None and group.get("Name") != str(expected_group_name):
        raise ValueError(f"Selected group name guard failed: expected {expected_group_name!r}, got {group.get('Name')!r}")
    expected_document_uid = args.get("expected_document_uid")
    if expected_document_uid is not None and group.get("DocumentUId") != str(expected_document_uid):
        raise ValueError(
            f"Selected group DocumentUId guard failed: expected {expected_document_uid!r}, got {group.get('DocumentUId')!r}"
        )
    if args.get("expected_screen_count") is not None:
        expected_count = require_non_negative_index("expected_screen_count", args.get("expected_screen_count"), len(screens))
        if expected_count != len(screens):
            raise ValueError(f"Selected group screen-count guard failed: expected {expected_count}, got {len(screens)}")

    before = summarize_display_group_for_write(group_index, group)
    updates: list[dict[str, Any]] = []

    def record_update(field: str, path: str, current: Any, new_value: Any) -> None:
        updates.append(
            {
                "field": field,
                "path": path,
                "before": scalar_preview(current),
                "after": scalar_preview(new_value),
                "changed": current != new_value,
            }
        )

    if args.get("name") is not None:
        new_name = validate_patch_string("name", args.get("name"), 200, allow_empty=False)
        current = group.get("Name")
        record_update("name", "Name", current, new_name)
        if current != new_name:
            group["Name"] = new_name
    if args.get("description") is not None:
        new_description = validate_patch_string("description", args.get("description"), 1000, allow_empty=True)
        current = group.get("Description")
        record_update("description", "Description", current, new_description)
        if current != new_description:
            group["Description"] = new_description

    if any(update["changed"] for update in updates):
        write_owle_json_section(project_path, entries, "Visualization", visualization)
    after_hash = sha256_file(project_path)
    after = summarize_display_group_for_write(group_index, group)
    validation_summary: dict[str, Any] | None = None
    if bool(args.get("validate_after", True)):
        loaded = read_owle_sections(project_path, include_hashes=True)
        validation_summary = summarize_display_visualization(
            loaded["sections"].get("Visualization"),
            max_items=20,
            include_elements=True,
            include_background_hash=False,
        )
    return {
        "source_project": target["source"],
        "scratch_copy": target["scratch_copy"] or safe_file_info(project_path, include_hash=True),
        "backup": target["backup"],
        "write_mode": target["write_mode"],
        "group_index": group_index,
        "before": before,
        "after": after,
        "updates": updates,
        "target_hash_before": before_hash,
        "target_hash_after": after_hash,
        "changed": before_hash != after_hash,
        "source_hash_after": sha256_file(Path(str(target["source"]["path"]))),
        "validation_summary": validation_summary,
        "audit_note": compact_string(str(args.get("audit_note") or "")),
        "risk_class": "safe_write_project",
        "guardrail": "Only safe properties of an existing Visualization group were patched, and only on a scratch copy or explicitly confirmed scratch path.",
        "limitation": "This patches stored .owle Visualization group metadata; it does not exercise the OWEN GUI screen manager, group create/delete dialogs, installed widget catalog, or rendered preview output.",
    }


def remap_known_uuid_reference_values(value: Any, id_map: dict[str, str]) -> int:
    changed = 0

    def replacement_for(raw: str) -> str | None:
        direct = id_map.get(raw)
        if direct is not None:
            return direct
        try:
            return id_map.get(str(uuid.UUID(raw)))
        except Exception:
            return None

    def walk(node: Any) -> None:
        nonlocal changed
        if isinstance(node, dict):
            for key, child in list(node.items()):
                if isinstance(child, str) and (
                    key == "DocumentUId"
                    or key.endswith("UId")
                    or key.endswith("UniqueId")
                ):
                    replacement = replacement_for(child)
                    if replacement is not None and replacement != child:
                        node[key] = replacement
                        changed += 1
                        continue
                walk(child)
        elif isinstance(node, list):
            for item in node:
                walk(item)

    walk(value)
    return changed


def project_display_group_clone(args: dict[str, Any]) -> dict[str, Any]:
    target = resolve_scratch_write_target(args, "_display_group_clone_scratch")
    project_path = Path(str(target["target_path"]))
    before_hash = sha256_file(project_path)
    entries = read_owle_raw_entries(project_path)
    visualization = read_visualization_section_from_entries(entries)
    group_index = require_non_negative_index("group_index", args.get("group_index"), 0)

    group = select_display_group(visualization, group_index)
    screens = group.get("Screens")
    if not isinstance(screens, list):
        raise ValueError("Selected Visualization group has no Screens list")
    expected_group_name = args.get("expected_group_name")
    if expected_group_name is not None and group.get("Name") != str(expected_group_name):
        raise ValueError(f"Selected group name guard failed: expected {expected_group_name!r}, got {group.get('Name')!r}")
    expected_document_uid = args.get("expected_document_uid")
    if expected_document_uid is not None and group.get("DocumentUId") != str(expected_document_uid):
        raise ValueError(
            f"Selected group DocumentUId guard failed: expected {expected_document_uid!r}, got {group.get('DocumentUId')!r}"
        )
    if args.get("expected_screen_count") is not None:
        expected_count = require_non_negative_index("expected_screen_count", args.get("expected_screen_count"), len(screens))
        if expected_count != len(screens):
            raise ValueError(f"Selected group screen-count guard failed: expected {expected_count}, got {len(screens)}")

    source_document_uid = str(group.get("DocumentUId") or "").strip()
    if not source_document_uid:
        raise ValueError("Refusing to clone a display group without DocumentUId")
    try:
        source_document_uid = str(uuid.UUID(source_document_uid))
    except Exception as exc:
        raise ValueError(f"Refusing to clone a display group with invalid DocumentUId: {group.get('DocumentUId')!r}") from exc

    source_group_count = len(visualization)
    source_screen_count, source_element_count = display_screen_count_and_elements(visualization)
    source = summarize_display_group_for_write(group_index, group)
    existing_ids = collect_uuid_values(visualization)
    clone, id_map = remap_fbd_element_clone_ids(group, existing_ids)
    if not isinstance(clone, dict):
        raise ValueError("Internal error: cloned display group is not an object")
    if source_document_uid not in id_map:
        id_map[source_document_uid] = generate_unique_uuid(existing_ids)
    clone["DocumentUId"] = id_map[source_document_uid]
    reference_remap_count = remap_known_uuid_reference_values(clone, id_map)

    if args.get("name") is not None:
        clone["Name"] = validate_patch_string("name", args.get("name"), 200, allow_empty=False)
    else:
        source_name = group.get("Name")
        clone["Name"] = validate_patch_string("name", f"{source_name} Copy" if isinstance(source_name, str) and source_name else "Copied group", 200, allow_empty=False)
    if args.get("description") is not None:
        clone["Description"] = validate_patch_string("description", args.get("description"), 1000, allow_empty=True)
    if bool(args.get("clear_screens", False)):
        clone["Screens"] = []

    insert_index = args.get("insert_index")
    if insert_index is None:
        new_index = len(visualization)
        visualization.append(clone)
    else:
        new_index = require_non_negative_index("insert_index", insert_index, len(visualization))
        if new_index > len(visualization):
            raise ValueError(f"insert_index is out of range: {new_index}")
        visualization.insert(new_index, clone)

    created = summarize_display_group_for_write(new_index, clone)
    write_owle_json_section(project_path, entries, "Visualization", visualization)
    after_hash = sha256_file(project_path)
    final_screen_count, final_element_count = display_screen_count_and_elements(visualization)
    validation_summary: dict[str, Any] | None = None
    if bool(args.get("validate_after", True)):
        loaded = read_owle_sections(project_path, include_hashes=True)
        validation_summary = summarize_display_visualization(
            loaded["sections"].get("Visualization"),
            max_items=20,
            include_elements=True,
            include_background_hash=False,
        )
    return {
        "source_project": target["source"],
        "scratch_copy": target["scratch_copy"] or safe_file_info(project_path, include_hash=True),
        "backup": target["backup"],
        "write_mode": target["write_mode"],
        "source_group_index": group_index,
        "new_group_index": new_index,
        "source_document_uid": source.get("document_uid"),
        "new_document_uid": created.get("document_uid"),
        "source_group": source,
        "created": created,
        "group_count_before": source_group_count,
        "group_count_after": len(visualization),
        "screen_count_before": source_screen_count,
        "screen_count_after": final_screen_count,
        "total_element_count_before": source_element_count,
        "total_element_count_after": final_element_count,
        "cloned_screen_count": created.get("screen_count"),
        "id_remap_count": len(id_map),
        "reference_remap_count": reference_remap_count,
        "target_hash_before": before_hash,
        "target_hash_after": after_hash,
        "changed": before_hash != after_hash,
        "source_hash_after": sha256_file(Path(str(target["source"]["path"]))),
        "validation_summary": validation_summary,
        "audit_note": compact_string(str(args.get("audit_note") or "")),
        "risk_class": "safe_write_project",
        "guardrail": "Only an existing Visualization group was cloned with UUID remap, and only on a scratch copy or explicitly confirmed scratch path.",
        "limitation": "This creates a project-local clone of an existing display group; it does not exercise the OWEN GUI screen manager wizard, group create/delete dialogs, installed display widget catalog insertion, or rendered preview output.",
    }


def select_display_group_for_delete(
    visualization: list[Any],
    group_index: int,
    group_document_uid: str | None,
) -> tuple[int, dict[str, Any]]:
    if group_document_uid:
        expected = group_document_uid.strip().lower()
        for index, group in enumerate(visualization):
            if not isinstance(group, dict):
                continue
            actual = str(group.get("DocumentUId") or "").lower()
            if actual == expected:
                return index, select_display_group(visualization, index)
        raise ValueError(f"Display group_document_uid was not found: {group_document_uid}")
    return group_index, select_display_group(visualization, group_index)


def project_display_group_delete(args: dict[str, Any]) -> dict[str, Any]:
    target = resolve_scratch_write_target(args, "_display_group_delete_scratch")
    project_path = Path(str(target["target_path"]))
    before_hash = sha256_file(project_path)
    entries = read_owle_raw_entries(project_path)
    visualization = read_visualization_section_from_entries(entries)
    group_index_arg = require_non_negative_index("group_index", args.get("group_index"), 0)
    group_document_uid = str(args.get("group_document_uid") or "").strip() or None

    group_index, group = select_display_group_for_delete(visualization, group_index_arg, group_document_uid)
    screens = group.get("Screens")
    if not isinstance(screens, list):
        raise ValueError("Selected Visualization group has no Screens list")
    expected_group_name = args.get("expected_group_name")
    if expected_group_name is not None and group.get("Name") != str(expected_group_name):
        raise ValueError(f"Selected group name guard failed: expected {expected_group_name!r}, got {group.get('Name')!r}")
    expected_document_uid = args.get("expected_document_uid")
    if expected_document_uid is not None and group.get("DocumentUId") != str(expected_document_uid):
        raise ValueError(
            f"Selected group DocumentUId guard failed: expected {expected_document_uid!r}, got {group.get('DocumentUId')!r}"
        )
    if args.get("expected_screen_count") is not None:
        expected_count = require_non_negative_index("expected_screen_count", args.get("expected_screen_count"), len(screens))
        if expected_count != len(screens):
            raise ValueError(f"Selected group screen-count guard failed: expected {expected_count}, got {len(screens)}")
    if len(visualization) <= 1 and not bool(args.get("allow_delete_last_group", False)):
        raise ValueError("Refusing to delete the last Visualization group without allow_delete_last_group=true")

    source_group_count = len(visualization)
    source_screen_count, source_element_count = display_screen_count_and_elements(visualization)
    deleted = summarize_display_group_for_write(group_index, group)
    del visualization[group_index]
    write_owle_json_section(project_path, entries, "Visualization", visualization)
    after_hash = sha256_file(project_path)
    final_screen_count, final_element_count = display_screen_count_and_elements(visualization)
    validation_summary: dict[str, Any] | None = None
    if bool(args.get("validate_after", True)):
        loaded = read_owle_sections(project_path, include_hashes=True)
        validation_summary = summarize_display_visualization(
            loaded["sections"].get("Visualization"),
            max_items=20,
            include_elements=True,
            include_background_hash=False,
        )
    return {
        "source_project": target["source"],
        "scratch_copy": target["scratch_copy"] or safe_file_info(project_path, include_hash=True),
        "backup": target["backup"],
        "write_mode": target["write_mode"],
        "deleted_group_index": group_index,
        "deleted_document_uid": deleted.get("document_uid"),
        "deleted_group": deleted,
        "group_count_before": source_group_count,
        "group_count_after": len(visualization),
        "screen_count_before": source_screen_count,
        "screen_count_after": final_screen_count,
        "total_element_count_before": source_element_count,
        "total_element_count_after": final_element_count,
        "target_hash_before": before_hash,
        "target_hash_after": after_hash,
        "changed": before_hash != after_hash,
        "source_hash_after": sha256_file(Path(str(target["source"]["path"]))),
        "validation_summary": validation_summary,
        "audit_note": compact_string(str(args.get("audit_note") or "")),
        "risk_class": "safe_write_project",
        "guardrail": "Only an existing Visualization group was deleted, and only on a scratch copy or explicitly confirmed scratch path; deleting the last group requires allow_delete_last_group=true.",
        "limitation": "This deletes a stored .owle Visualization group; it does not exercise the OWEN GUI screen manager wizard, group create/delete dialogs, installed display widget catalog insertion, or rendered preview output.",
    }


def project_display_element_property_patch(args: dict[str, Any]) -> dict[str, Any]:
    target = resolve_scratch_write_target(args, "_display_element_property_scratch")
    project_path = Path(str(target["target_path"]))
    before_hash = sha256_file(project_path)
    entries = read_owle_raw_entries(project_path)
    visualization = read_visualization_section_from_entries(entries)
    group_index = require_non_negative_index("group_index", args.get("group_index"), 0)
    screen_index = require_non_negative_index("screen_index", args.get("screen_index"), 0)
    element_index_arg = require_non_negative_index("element_index", args.get("element_index"), 0)
    property_name = validate_patch_string("property_name", args.get("property_name") or "", 120)
    value_field, new_value = display_patch_value_from_args(args)

    group, screen = select_display_screen(visualization, group_index, screen_index)
    _prop, screen_device, document = display_screen_device(screen)
    expected_screen_title = args.get("expected_screen_title")
    if expected_screen_title is not None and screen_device.get("Title") != str(expected_screen_title):
        raise ValueError(
            f"Selected screen title guard failed: expected {expected_screen_title!r}, got {screen_device.get('Title')!r}"
        )

    element_unique_id = str(args.get("element_unique_id") or "").strip() or None
    element_index, element = select_display_element(document, element_index_arg, element_unique_id)
    model = display_element_model(element)
    expected_element_title = args.get("expected_element_title")
    if expected_element_title is not None and model.get("Title") != str(expected_element_title):
        raise ValueError(
            f"Selected element title guard failed: expected {expected_element_title!r}, got {model.get('Title')!r}"
        )

    property_index, property_row, element_property = select_display_property(element, property_name)
    expected_property_display_name = args.get("expected_property_display_name")
    if expected_property_display_name is not None and element_property.get("DisplayName") != str(expected_property_display_name):
        raise ValueError(
            "Selected property display-name guard failed: "
            f"expected {expected_property_display_name!r}, got {element_property.get('DisplayName')!r}"
        )
    if value_field not in property_row and not bool(args.get("allow_create_value_field", False)):
        raise ValueError(
            f"Selected property has no {value_field} field; set allow_create_value_field=true only for scratch-only schema experiments"
        )
    current_value = display_property_current_value(property_row, value_field)
    if args.get("expected_current_value") is not None and current_value != args.get("expected_current_value"):
        raise ValueError(
            f"Selected property current value guard failed for {value_field}: "
            f"expected {args.get('expected_current_value')!r}, got {current_value!r}"
        )

    before = {
        "group_index": group_index,
        "group_name": group.get("Name"),
        "screen_index": screen_index,
        "screen_title": screen_device.get("Title"),
        "screen_unique_id": screen.get("UniqueId"),
        "element_index": element_index,
        "element_unique_id": model.get("UniqueId") or element.get("UniqueId"),
        "element_title": model.get("Title"),
        "property_index": property_index,
        "property_name": element_property.get("Name"),
        "property_display_name": element_property.get("DisplayName"),
        "value_field": value_field,
        "value": scalar_preview(current_value),
        "all_values": display_property_values(property_row),
    }
    property_row[value_field] = new_value
    after = {
        **before,
        "value": scalar_preview(property_row.get(value_field)),
        "all_values": display_property_values(property_row),
    }
    write_owle_json_section(project_path, entries, "Visualization", visualization)
    after_hash = sha256_file(project_path)
    validation_summary: dict[str, Any] | None = None
    if bool(args.get("validate_after", True)):
        loaded = read_owle_sections(project_path, include_hashes=True)
        validation_summary = summarize_display_visualization(
            loaded["sections"].get("Visualization"),
            max_items=20,
            include_elements=True,
            include_background_hash=False,
        )
    return {
        "source_project": target["source"],
        "scratch_copy": target["scratch_copy"] or safe_file_info(project_path, include_hash=True),
        "backup": target["backup"],
        "write_mode": target["write_mode"],
        "updated_field": value_field,
        "before": before,
        "after": after,
        "target_hash_before": before_hash,
        "target_hash_after": after_hash,
        "changed": before_hash != after_hash,
        "source_hash_after": sha256_file(Path(str(target["source"]["path"]))),
        "validation_summary": validation_summary,
        "audit_note": compact_string(str(args.get("audit_note") or "")),
        "risk_class": "safe_write_project",
        "guardrail": "Only an existing Visualization element property value field was patched, and only on a scratch copy or explicitly confirmed scratch path.",
        "limitation": "This does not synthesize new OWEN display widgets or regenerate rendered text primitives; it patches the stored property field only.",
    }


def display_property_raw_value(property_row: dict[str, Any]) -> Any:
    for field in DISPLAY_ELEMENT_VALUE_FIELDS:
        if field in property_row:
            return property_row.get(field)
    return None


def display_property_by_name(element: dict[str, Any], property_name: str) -> tuple[int, dict[str, Any], dict[str, Any]] | None:
    try:
        return select_display_property(element, property_name)
    except ValueError:
        return None


def set_existing_display_property_value(
    element: dict[str, Any],
    property_name: str,
    field_name: str,
    value: Any,
    *,
    required: bool,
) -> dict[str, Any] | None:
    selected = display_property_by_name(element, property_name)
    if selected is None:
        if required:
            raise ValueError(f"Selected display element has no existing {property_name} property")
        return None
    property_index, property_row, element_property = selected
    if field_name not in property_row:
        raise ValueError(f"Selected display element property {property_name} has no existing {field_name} field")
    before = scalar_preview(property_row.get(field_name))
    property_row[field_name] = value
    return {
        "property_index": property_index,
        "property_name": element_property.get("Name"),
        "property_display_name": element_property.get("DisplayName"),
        "field": field_name,
        "before": before,
        "after": scalar_preview(property_row.get(field_name)),
    }


def display_property_int_value(element: dict[str, Any], property_name: str, default: int) -> int:
    selected = display_property_by_name(element, property_name)
    if selected is None:
        return default
    _property_index, property_row, _element_property = selected
    raw = property_row.get("IntValue")
    if isinstance(raw, bool):
        return default
    try:
        return int(raw)
    except (TypeError, ValueError):
        return default


def update_display_text_primitives(element: dict[str, Any], text: str, allow_truncation: bool) -> dict[str, Any]:
    model = display_element_model(element)
    primitives = model.get("Primitives")
    if not isinstance(primitives, list):
        return {"updated": 0, "available_slots": 0, "truncated": False}
    text_primitives = [primitive for primitive in primitives if isinstance(primitive, dict) and "Text" in primitive]
    if not text_primitives:
        return {"updated": 0, "available_slots": 0, "truncated": False}
    if len(text) > len(text_primitives) and not allow_truncation:
        raise ValueError(
            f"Text is longer than existing display text primitive slots: {len(text)} > {len(text_primitives)}; "
            "set allow_text_truncation=true or update_text_primitives=false"
        )
    chars = list(text[: len(text_primitives)])
    while len(chars) < len(text_primitives):
        chars.append(" ")
    for primitive, char in zip(text_primitives, chars):
        primitive["Text"] = char
    return {
        "updated": len(text_primitives),
        "available_slots": len(text_primitives),
        "truncated": len(text) > len(text_primitives),
    }


def summarize_display_element_for_write(group_index: int, screen_index: int, element_index: int, element: dict[str, Any]) -> dict[str, Any]:
    summary = summarize_display_element(element_index, element)
    summary["group_index"] = group_index
    summary["screen_index"] = screen_index
    properties = element.get("Properties") if isinstance(element.get("Properties"), list) else []
    property_values: dict[str, Any] = {}
    for property_row in properties:
        if not isinstance(property_row, dict):
            continue
        element_property = property_row.get("ElementProperty")
        if isinstance(element_property, dict) and element_property.get("Name"):
            property_values[str(element_property.get("Name"))] = display_property_values(property_row)
    summary["property_values"] = property_values
    return summary


def installed_display_factory_rows(max_properties: int = 200) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    install = find_installation_data()
    install_dir_value = install.get("install_dir")
    if not install_dir_value:
        raise FileNotFoundError("OWEN Logic installation directory was not found")
    install_dir = Path(str(install_dir_value))
    assembly_paths = [
        install_dir / "Owen.LibraryGraphDisplay.dll",
        install_dir / "Owen.Visualization.dll",
    ]
    resources, resource_errors = extract_dotnet_xml_resources([path for path in assembly_paths if path.exists()])
    rows: list[dict[str, Any]] = []
    errors = list(resource_errors)
    for resource in resources:
        parsed, parse_error = parse_display_factory_resource(resource, max_properties, "")
        rows.extend(parsed)
        if parse_error:
            errors.append(parse_error)
    return rows, errors


def select_installed_display_factory(args: dict[str, Any]) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    type_name = validate_patch_string("catalog_type_name_element", args.get("catalog_type_name_element"), 200, allow_empty=False)
    resource_guard = compact_string(str(args.get("catalog_resource_name") or "")).lower()
    title_guard = compact_string(str(args.get("catalog_library_element_title") or ""))
    factory_index_guard: int | None = None
    if args.get("catalog_factory_index") is not None:
        factory_index_guard = require_non_negative_index("catalog_factory_index", args.get("catalog_factory_index"), 0)

    rows, errors = installed_display_factory_rows()
    candidates: list[dict[str, Any]] = []
    for row in rows:
        if row.get("type_name_element") != type_name:
            continue
        if resource_guard and resource_guard not in str(row.get("resource_name") or "").lower():
            continue
        if title_guard and row.get("library_element_title") != title_guard:
            continue
        if factory_index_guard is not None and row.get("factory_index") != factory_index_guard:
            continue
        candidates.append(row)
    if not candidates:
        raise ValueError(
            "Installed display catalog factory was not found for "
            f"type={type_name!r}, resource={args.get('catalog_resource_name')!r}, "
            f"factory_index={factory_index_guard!r}, title={title_guard!r}"
        )
    if len(candidates) > 1 and factory_index_guard is None:
        preview = [
            {
                "resource_name": row.get("resource_name"),
                "factory_index": row.get("factory_index"),
                "library_element_title": row.get("library_element_title"),
                "type_group": row.get("type_group"),
            }
            for row in candidates[:10]
        ]
        raise ValueError(
            "Installed display catalog factory selector is ambiguous; provide catalog_factory_index or a narrower resource/title guard. "
            + json.dumps(preview, ensure_ascii=False)
        )
    return candidates[0], errors


def display_property_name_set(element: dict[str, Any]) -> set[str]:
    properties = element.get("Properties") if isinstance(element.get("Properties"), list) else []
    names: set[str] = set()
    for property_row in properties:
        if not isinstance(property_row, dict):
            continue
        element_property = property_row.get("ElementProperty")
        if isinstance(element_property, dict) and element_property.get("Name"):
            names.add(str(element_property.get("Name")))
    return names


def display_factory_property_names(factory: dict[str, Any]) -> list[str]:
    return [
        str(prop.get("name"))
        for prop in factory.get("properties") or []
        if isinstance(prop, dict) and prop.get("name")
    ]


def display_factory_project_property_aliases(name: str) -> tuple[str, ...]:
    aliases = {
        "Visible": ("Visible", "IsVisible"),
        "Name": ("Name",),
    }
    return aliases.get(name, (name,))


def score_display_archetype_for_factory(factory: dict[str, Any], element: dict[str, Any]) -> dict[str, Any]:
    factory_names = display_factory_property_names(factory)
    element_names = display_property_name_set(element)
    model = display_element_model(element)
    matched: list[str] = []
    missing: list[str] = []
    for name in factory_names:
        aliases = display_factory_project_property_aliases(name)
        if any(alias in element_names for alias in aliases):
            matched.append(name)
        else:
            missing.append(name)
    score = len(matched)
    type_name = str(factory.get("type_name_element") or "")
    title = str(model.get("Title") or "")
    if type_name == "LabelModel" and "Text" in element_names:
        score += 20
    if type_name == "LabelModel" and title.lower() in {"метка", "label", "text"}:
        score += 5
    required_missing: list[str] = []
    if type_name == "LabelModel" and "Text" not in element_names:
        required_missing.append("Text")
    return {
        "score": score,
        "matched_factory_properties": matched,
        "missing_factory_properties": missing,
        "required_missing": required_missing,
        "element_property_names": sorted(element_names),
    }


def iter_display_elements(visualization: list[Any]) -> Iterator[tuple[int, int, dict[str, Any], dict[str, Any], int, dict[str, Any]]]:
    for group_index, group in enumerate(visualization):
        if not isinstance(group, dict):
            continue
        screens = group.get("Screens")
        if not isinstance(screens, list):
            continue
        for screen_index, screen in enumerate(screens):
            try:
                _prop, screen_device, document = display_screen_device(screen)
            except ValueError:
                continue
            elements = document.get("Elements")
            if not isinstance(elements, list):
                continue
            for element_index, element in enumerate(elements):
                if isinstance(element, dict):
                    yield group_index, screen_index, screen_device, document, element_index, element


def select_display_archetype_for_insert(
    visualization: list[Any],
    target_document: dict[str, Any],
    factory: dict[str, Any],
    args: dict[str, Any],
) -> tuple[int, int, int, dict[str, Any], dict[str, Any]]:
    explicit_unique_id = str(args.get("archetype_element_unique_id") or "").strip()
    explicit_index_supplied = args.get("archetype_element_index") is not None
    if explicit_unique_id or explicit_index_supplied:
        archetype_index = require_non_negative_index("archetype_element_index", args.get("archetype_element_index"), 0)
        selected_index, element = select_display_element(target_document, archetype_index, explicit_unique_id or None)
        score = score_display_archetype_for_factory(factory, element)
        if score["required_missing"]:
            raise ValueError(f"Selected display archetype is incompatible with installed factory; missing {score['required_missing']}")
        return -1, -1, selected_index, element, score

    best: tuple[int, int, int, dict[str, Any], dict[str, Any]] | None = None
    for group_index, screen_index, _screen_device, _document, element_index, element in iter_display_elements(visualization):
        score = score_display_archetype_for_factory(factory, element)
        if score["required_missing"]:
            continue
        if best is None or int(score["score"]) > int(best[4]["score"]):
            best = (group_index, screen_index, element_index, element, score)
    if best is None or int(best[4]["score"]) <= 0:
        raise ValueError(
            "No compatible project-local Visualization archetype was found for the selected installed display factory. "
            "Provide archetype_element_index/archetype_element_unique_id on a known compatible element."
        )
    return best


def factory_summary_for_insert(factory: dict[str, Any]) -> dict[str, Any]:
    return {
        "source_assembly": factory.get("source_assembly"),
        "resource_name": factory.get("resource_name"),
        "resource_sha256": factory.get("resource_sha256"),
        "factory_index": factory.get("factory_index"),
        "type_name_element": factory.get("type_name_element"),
        "library_element_title": factory.get("library_element_title"),
        "library_element_description": factory.get("library_element_description"),
        "library_control_image_name": factory.get("library_control_image_name"),
        "type_group": factory.get("type_group"),
        "property_count": factory.get("property_count"),
        "property_names": display_factory_property_names(factory),
    }


def project_display_element_clone(args: dict[str, Any]) -> dict[str, Any]:
    target = resolve_scratch_write_target(args, "_display_element_clone_scratch")
    project_path = Path(str(target["target_path"]))
    before_hash = sha256_file(project_path)
    entries = read_owle_raw_entries(project_path)
    visualization = read_visualization_section_from_entries(entries)
    group_index = require_non_negative_index("group_index", args.get("group_index"), 0)
    screen_index = require_non_negative_index("screen_index", args.get("screen_index"), 0)
    element_index_arg = require_non_negative_index("element_index", args.get("element_index"), 0)

    group, screen = select_display_screen(visualization, group_index, screen_index)
    _prop, screen_device, document = display_screen_device(screen)
    expected_screen_title = args.get("expected_screen_title")
    if expected_screen_title is not None and screen_device.get("Title") != str(expected_screen_title):
        raise ValueError(
            f"Selected screen title guard failed: expected {expected_screen_title!r}, got {screen_device.get('Title')!r}"
        )

    element_unique_id = str(args.get("element_unique_id") or "").strip() or None
    source_index, source_element = select_display_element(document, element_index_arg, element_unique_id)
    source_model = display_element_model(source_element)
    if not source_model.get("UniqueId"):
        raise ValueError("Refusing to clone a display element without ElementModel.UniqueId")
    expected_element_title = args.get("expected_element_title")
    if expected_element_title is not None and source_model.get("Title") != str(expected_element_title):
        raise ValueError(
            f"Selected element title guard failed: expected {expected_element_title!r}, got {source_model.get('Title')!r}"
        )

    elements = document.get("Elements")
    if not isinstance(elements, list):
        raise ValueError("Selected screen document has no Elements list")
    existing_ids = collect_uuid_values(visualization)
    clone, id_map = remap_fbd_element_clone_ids(source_element, existing_ids)
    clone_model = display_element_model(clone)
    if args.get("title") is not None:
        clone_model["Title"] = validate_patch_string("title", args.get("title"), 200, allow_empty=False)

    property_updates: list[dict[str, Any]] = []
    source_x = display_property_int_value(source_element, "CoordinateX", 0)
    source_y = display_property_int_value(source_element, "CoordinateY", 0)
    if args.get("coordinate_x") is not None:
        coordinate_x = int(validate_patch_number("coordinate_x", args.get("coordinate_x"), -1000000, 1000000))
    else:
        offset_x = int(validate_patch_number("offset_x", args.get("offset_x", 1), -1000000, 1000000))
        coordinate_x = source_x + offset_x
    if args.get("coordinate_y") is not None:
        coordinate_y = int(validate_patch_number("coordinate_y", args.get("coordinate_y"), -1000000, 1000000))
    else:
        offset_y = int(validate_patch_number("offset_y", args.get("offset_y", 1), -1000000, 1000000))
        coordinate_y = source_y + offset_y
    update = set_existing_display_property_value(clone, "CoordinateX", "IntValue", coordinate_x, required=False)
    if update:
        property_updates.append(update)
    update = set_existing_display_property_value(clone, "CoordinateY", "IntValue", coordinate_y, required=False)
    if update:
        property_updates.append(update)

    text_primitive_update: dict[str, Any] | None = None
    if args.get("text") is not None:
        text = validate_patch_string("text", args.get("text"), 1000, allow_empty=True)
        update = set_existing_display_property_value(clone, "Text", "Value", text, required=True)
        if update:
            property_updates.append(update)
        if bool(args.get("update_text_primitives", True)):
            text_primitive_update = update_display_text_primitives(
                clone,
                text,
                allow_truncation=bool(args.get("allow_text_truncation", False)),
            )
    if args.get("is_visible") is not None:
        if not isinstance(args.get("is_visible"), bool):
            raise ValueError("is_visible must be boolean")
        update = set_existing_display_property_value(clone, "IsVisible", "BoolValue", bool(args.get("is_visible")), required=True)
        if update:
            property_updates.append(update)
    if args.get("element_length") is not None:
        if isinstance(args.get("element_length"), bool):
            raise ValueError("element_length must be an integer")
        length = int(validate_patch_number("element_length", args.get("element_length"), 0, 1000))
        update = set_existing_display_property_value(clone, "ElementLength", "Value", length, required=True)
        if update:
            property_updates.append(update)

    insert_index = args.get("insert_index")
    if insert_index is None:
        new_index = len(elements)
        elements.append(clone)
    else:
        new_index = require_non_negative_index("insert_index", insert_index, len(elements))
        if new_index > len(elements):
            raise ValueError(f"insert_index is out of range: {new_index}")
        elements.insert(new_index, clone)

    before = summarize_display_element_for_write(group_index, screen_index, source_index, source_element)
    after = summarize_display_element_for_write(group_index, screen_index, new_index, clone)
    write_owle_json_section(project_path, entries, "Visualization", visualization)
    after_hash = sha256_file(project_path)
    validation_summary: dict[str, Any] | None = None
    if bool(args.get("validate_after", True)):
        loaded = read_owle_sections(project_path, include_hashes=True)
        validation_summary = summarize_display_visualization(
            loaded["sections"].get("Visualization"),
            max_items=20,
            include_elements=True,
            include_background_hash=False,
        )
    return {
        "source_project": target["source"],
        "scratch_copy": target["scratch_copy"] or safe_file_info(project_path, include_hash=True),
        "backup": target["backup"],
        "write_mode": target["write_mode"],
        "group_index": group_index,
        "group_name": group.get("Name"),
        "screen_index": screen_index,
        "screen_title": screen_device.get("Title"),
        "screen_unique_id": screen.get("UniqueId"),
        "source_element_index": source_index,
        "source_element_unique_id": before.get("unique_id"),
        "new_element_index": new_index,
        "new_element_unique_id": after.get("unique_id"),
        "element_count_before": len(elements) - 1,
        "element_count_after": len(elements),
        "id_remap_count": len(id_map),
        "property_updates": property_updates,
        "text_primitive_update": text_primitive_update,
        "source_element": before,
        "created": after,
        "target_hash_before": before_hash,
        "target_hash_after": after_hash,
        "changed": before_hash != after_hash,
        "source_hash_after": sha256_file(Path(str(target["source"]["path"]))),
        "validation_summary": validation_summary,
        "audit_note": compact_string(str(args.get("audit_note") or "")),
        "risk_class": "safe_write_project",
        "guardrail": "Only an existing Visualization element was cloned with UUID remap, and only on a scratch copy or explicitly confirmed scratch path.",
        "limitation": "This creates a project-local clone of an existing display widget; it does not insert from the installed OWEN display component catalog or prove rendered preview output.",
    }


def project_display_element_insert(args: dict[str, Any]) -> dict[str, Any]:
    target = resolve_scratch_write_target(args, "_display_element_insert_scratch")
    project_path = Path(str(target["target_path"]))
    before_hash = sha256_file(project_path)
    factory, factory_errors = select_installed_display_factory(args)
    entries = read_owle_raw_entries(project_path)
    visualization = read_visualization_section_from_entries(entries)
    group_index = require_non_negative_index("group_index", args.get("group_index"), 0)
    screen_index = require_non_negative_index("screen_index", args.get("screen_index"), 0)

    group, screen = select_display_screen(visualization, group_index, screen_index)
    _prop, screen_device, document = display_screen_device(screen)
    expected_screen_title = args.get("expected_screen_title")
    if expected_screen_title is not None and screen_device.get("Title") != str(expected_screen_title):
        raise ValueError(
            f"Selected screen title guard failed: expected {expected_screen_title!r}, got {screen_device.get('Title')!r}"
        )
    elements = document.get("Elements")
    if not isinstance(elements, list):
        raise ValueError("Selected screen document has no Elements list")

    archetype_group_index, archetype_screen_index, archetype_index, archetype_element, compatibility = select_display_archetype_for_insert(
        visualization,
        document,
        factory,
        args,
    )
    archetype_model = display_element_model(archetype_element)
    if not archetype_model.get("UniqueId"):
        raise ValueError("Refusing to insert from a display archetype without ElementModel.UniqueId")
    expected_archetype_title = args.get("expected_archetype_title")
    if expected_archetype_title is not None and archetype_model.get("Title") != str(expected_archetype_title):
        raise ValueError(
            f"Selected archetype title guard failed: expected {expected_archetype_title!r}, got {archetype_model.get('Title')!r}"
        )

    existing_ids = collect_uuid_values(visualization)
    inserted, id_map = remap_fbd_element_clone_ids(archetype_element, existing_ids)
    inserted_model = display_element_model(inserted)
    if args.get("title") is not None:
        inserted_model["Title"] = validate_patch_string("title", args.get("title"), 200, allow_empty=False)
    elif factory.get("library_element_title"):
        inserted_model["Title"] = compact_string(str(factory.get("library_element_title")))

    property_updates: list[dict[str, Any]] = []
    if args.get("coordinate_x") is not None:
        coordinate_x = int(validate_patch_number("coordinate_x", args.get("coordinate_x"), -1000000, 1000000))
        update = set_existing_display_property_value(inserted, "CoordinateX", "IntValue", coordinate_x, required=False)
        if update:
            property_updates.append(update)
    if args.get("coordinate_y") is not None:
        coordinate_y = int(validate_patch_number("coordinate_y", args.get("coordinate_y"), -1000000, 1000000))
        update = set_existing_display_property_value(inserted, "CoordinateY", "IntValue", coordinate_y, required=False)
        if update:
            property_updates.append(update)

    text_primitive_update: dict[str, Any] | None = None
    if args.get("text") is not None:
        text = validate_patch_string("text", args.get("text"), 1000, allow_empty=True)
        update = set_existing_display_property_value(inserted, "Text", "Value", text, required=True)
        if update:
            property_updates.append(update)
        if bool(args.get("update_text_primitives", True)):
            text_primitive_update = update_display_text_primitives(
                inserted,
                text,
                allow_truncation=bool(args.get("allow_text_truncation", False)),
            )
    if args.get("is_visible") is not None:
        if not isinstance(args.get("is_visible"), bool):
            raise ValueError("is_visible must be boolean")
        update = set_existing_display_property_value(inserted, "IsVisible", "BoolValue", bool(args.get("is_visible")), required=False)
        if update:
            property_updates.append(update)
        update = set_existing_display_property_value(inserted, "Visible", "BoolValue", bool(args.get("is_visible")), required=False)
        if update:
            property_updates.append(update)
    if args.get("element_length") is not None:
        if isinstance(args.get("element_length"), bool):
            raise ValueError("element_length must be an integer")
        length = int(validate_patch_number("element_length", args.get("element_length"), 0, 1000))
        update = set_existing_display_property_value(inserted, "ElementLength", "Value", length, required=False)
        if update:
            property_updates.append(update)

    insert_index = args.get("insert_index")
    element_count_before = len(elements)
    if insert_index is None:
        new_index = len(elements)
        elements.append(inserted)
    else:
        new_index = require_non_negative_index("insert_index", insert_index, len(elements))
        if new_index > len(elements):
            raise ValueError(f"insert_index is out of range: {new_index}")
        elements.insert(new_index, inserted)

    archetype_summary = summarize_display_element_for_write(
        archetype_group_index if archetype_group_index >= 0 else group_index,
        archetype_screen_index if archetype_screen_index >= 0 else screen_index,
        archetype_index,
        archetype_element,
    )
    created = summarize_display_element_for_write(group_index, screen_index, new_index, inserted)
    write_owle_json_section(project_path, entries, "Visualization", visualization)
    after_hash = sha256_file(project_path)
    validation_summary: dict[str, Any] | None = None
    if bool(args.get("validate_after", True)):
        loaded = read_owle_sections(project_path, include_hashes=True)
        validation_summary = summarize_display_visualization(
            loaded["sections"].get("Visualization"),
            max_items=20,
            include_elements=True,
            include_background_hash=False,
        )
    return {
        "source_project": target["source"],
        "scratch_copy": target["scratch_copy"] or safe_file_info(project_path, include_hash=True),
        "backup": target["backup"],
        "write_mode": target["write_mode"],
        "group_index": group_index,
        "group_name": group.get("Name"),
        "screen_index": screen_index,
        "screen_title": screen_device.get("Title"),
        "screen_unique_id": screen.get("UniqueId"),
        "installed_catalog_factory": factory_summary_for_insert(factory),
        "installed_catalog_errors": factory_errors,
        "archetype_source": archetype_summary,
        "archetype_compatibility": compatibility,
        "new_element_index": new_index,
        "new_element_unique_id": created.get("unique_id"),
        "element_count_before": element_count_before,
        "element_count_after": len(elements),
        "id_remap_count": len(id_map),
        "property_updates": property_updates,
        "text_primitive_update": text_primitive_update,
        "created": created,
        "target_hash_before": before_hash,
        "target_hash_after": after_hash,
        "changed": before_hash != after_hash,
        "source_hash_after": sha256_file(Path(str(target["source"]["path"]))),
        "validation_summary": validation_summary,
        "audit_note": compact_string(str(args.get("audit_note") or "")),
        "risk_class": "safe_write_project",
        "guardrail": "Installed display catalog metadata was matched, then a compatible project-local Visualization archetype was cloned with UUID remap only on a scratch copy or explicitly confirmed scratch path.",
        "limitation": "This is an offline .owle model insertion backed by installed catalog metadata and a project-local archetype. It does not synthesize arbitrary installed widgets without a compatible archetype, execute the OWEN GUI display editor, prove OWEN GUI rendering, or run simulation.",
    }


def project_display_element_delete(args: dict[str, Any]) -> dict[str, Any]:
    target = resolve_scratch_write_target(args, "_display_element_delete_scratch")
    project_path = Path(str(target["target_path"]))
    before_hash = sha256_file(project_path)
    entries = read_owle_raw_entries(project_path)
    visualization = read_visualization_section_from_entries(entries)
    group_index = require_non_negative_index("group_index", args.get("group_index"), 0)
    screen_index = require_non_negative_index("screen_index", args.get("screen_index"), 0)
    element_index_arg = require_non_negative_index("element_index", args.get("element_index"), 0)

    group, screen = select_display_screen(visualization, group_index, screen_index)
    _prop, screen_device, document = display_screen_device(screen)
    expected_screen_title = args.get("expected_screen_title")
    if expected_screen_title is not None and screen_device.get("Title") != str(expected_screen_title):
        raise ValueError(
            f"Selected screen title guard failed: expected {expected_screen_title!r}, got {screen_device.get('Title')!r}"
        )

    elements = document.get("Elements")
    if not isinstance(elements, list):
        raise ValueError("Selected screen document has no Elements list")
    element_unique_id = str(args.get("element_unique_id") or "").strip() or None
    element_index, element = select_display_element(document, element_index_arg, element_unique_id)
    model = display_element_model(element)
    expected_element_title = args.get("expected_element_title")
    if expected_element_title is not None and model.get("Title") != str(expected_element_title):
        raise ValueError(
            f"Selected element title guard failed: expected {expected_element_title!r}, got {model.get('Title')!r}"
        )

    guard_property: dict[str, Any] | None = None
    if args.get("guard_property_name") is not None:
        guard_property_name = validate_patch_string("guard_property_name", args.get("guard_property_name"), 120)
        _property_index, property_row, element_property = select_display_property(element, guard_property_name)
        current_value = display_property_raw_value(property_row)
        if args.get("expected_property_value") is not None and current_value != args.get("expected_property_value"):
            raise ValueError(
                f"Selected property current value guard failed for {guard_property_name}: "
                f"expected {args.get('expected_property_value')!r}, got {current_value!r}"
            )
        guard_property = {
            "property_name": element_property.get("Name"),
            "property_display_name": element_property.get("DisplayName"),
            "value": scalar_preview(current_value),
        }

    if len(elements) <= 1 and not bool(args.get("allow_empty_screen", False)):
        raise ValueError("Refusing to delete the last display element on a screen without allow_empty_screen=true")

    deleted = summarize_display_element_for_write(group_index, screen_index, element_index, element)
    element_count_before = len(elements)
    del elements[element_index]
    write_owle_json_section(project_path, entries, "Visualization", visualization)
    after_hash = sha256_file(project_path)
    validation_summary: dict[str, Any] | None = None
    if bool(args.get("validate_after", True)):
        loaded = read_owle_sections(project_path, include_hashes=True)
        validation_summary = summarize_display_visualization(
            loaded["sections"].get("Visualization"),
            max_items=20,
            include_elements=True,
            include_background_hash=False,
        )
    return {
        "source_project": target["source"],
        "scratch_copy": target["scratch_copy"] or safe_file_info(project_path, include_hash=True),
        "backup": target["backup"],
        "write_mode": target["write_mode"],
        "group_index": group_index,
        "group_name": group.get("Name"),
        "screen_index": screen_index,
        "screen_title": screen_device.get("Title"),
        "screen_unique_id": screen.get("UniqueId"),
        "deleted_element_index": element_index,
        "deleted_element_unique_id": deleted.get("unique_id"),
        "deleted": deleted,
        "guard_property": guard_property,
        "element_count_before": element_count_before,
        "element_count_after": len(elements),
        "target_hash_before": before_hash,
        "target_hash_after": after_hash,
        "changed": before_hash != after_hash,
        "source_hash_after": sha256_file(Path(str(target["source"]["path"]))),
        "validation_summary": validation_summary,
        "audit_note": compact_string(str(args.get("audit_note") or "")),
        "risk_class": "safe_write_project",
        "guardrail": "Only an existing Visualization element was deleted, and only on a scratch copy or explicitly confirmed scratch path.",
        "limitation": "This does not prove OWEN's rendered display preview; it only updates the .owle Visualization model.",
    }


def display_screen_count_and_elements(visualization: list[Any]) -> tuple[int, int]:
    screen_count = 0
    element_count = 0
    for group in visualization:
        if not isinstance(group, dict):
            continue
        screens = group.get("Screens")
        if not isinstance(screens, list):
            continue
        screen_count += len(screens)
        for screen in screens:
            if not isinstance(screen, dict):
                continue
            try:
                _prop, _screen_device, document = display_screen_device(screen)
            except ValueError:
                continue
            elements = document.get("Elements")
            if isinstance(elements, list):
                element_count += len(elements)
    return screen_count, element_count


def summarize_display_screen_for_write(group_index: int, screen_index: int, group: dict[str, Any], screen: dict[str, Any]) -> dict[str, Any]:
    _prop, screen_device, document = display_screen_device(screen)
    elements = document.get("Elements") if isinstance(document.get("Elements"), list) else []
    return {
        "group_index": group_index,
        "group_name": group.get("Name"),
        "screen_index": screen_index,
        "unique_id": screen.get("UniqueId"),
        "title": screen_device.get("Title"),
        "description": screen_device.get("Description"),
        "should_hide_empty_rows": screen_device.get("ShouldHideEmptyRows"),
        "screen_device_unique_id": screen_device.get("UniqueId"),
        "document_unique_id": document.get("UniqueId"),
        "element_count": len(elements),
        "symbols_per_line": document.get("SymbolsPerLine"),
        "count_lines": document.get("CountLines"),
        "document_width": document.get("Width"),
        "document_height": document.get("Height"),
        "canvas": {
            "x": screen.get("X"),
            "y": screen.get("Y"),
            "width": screen.get("Width"),
            "height": screen.get("Height"),
        },
    }


def project_display_screen_clone(args: dict[str, Any]) -> dict[str, Any]:
    target = resolve_scratch_write_target(args, "_display_screen_clone_scratch")
    project_path = Path(str(target["target_path"]))
    before_hash = sha256_file(project_path)
    entries = read_owle_raw_entries(project_path)
    visualization = read_visualization_section_from_entries(entries)
    group_index = require_non_negative_index("group_index", args.get("group_index"), 0)
    screen_index = require_non_negative_index("screen_index", args.get("screen_index"), 0)

    group, screen = select_display_screen(visualization, group_index, screen_index)
    screens = group.get("Screens")
    if not isinstance(screens, list):
        raise ValueError("Selected Visualization group has no Screens list")
    expected_group_name = args.get("expected_group_name")
    if expected_group_name is not None and group.get("Name") != str(expected_group_name):
        raise ValueError(f"Selected group name guard failed: expected {expected_group_name!r}, got {group.get('Name')!r}")

    _prop, screen_device, document = display_screen_device(screen)
    expected_screen_title = args.get("expected_screen_title")
    if expected_screen_title is not None and screen_device.get("Title") != str(expected_screen_title):
        raise ValueError(
            f"Selected screen title guard failed: expected {expected_screen_title!r}, got {screen_device.get('Title')!r}"
        )
    if not screen.get("UniqueId"):
        raise ValueError("Refusing to clone a display screen without UniqueId")
    if not screen_device.get("UniqueId"):
        raise ValueError("Refusing to clone a display screen without Property.ScreenDevice.UniqueId")
    if not document.get("UniqueId"):
        raise ValueError("Refusing to clone a display screen without Property.ScreenDevice.Document.UniqueId")

    source_screen_count, source_element_count = display_screen_count_and_elements(visualization)
    source = summarize_display_screen_for_write(group_index, screen_index, group, screen)
    existing_ids = collect_uuid_values(visualization)
    clone, id_map = remap_fbd_element_clone_ids(screen, existing_ids)
    if not isinstance(clone, dict):
        raise ValueError("Internal error: cloned display screen is not an object")
    _clone_prop, clone_screen_device, clone_document = display_screen_device(clone)

    if args.get("title") is not None:
        clone_screen_device["Title"] = validate_patch_string("title", args.get("title"), 200, allow_empty=False)
    if args.get("description") is not None:
        clone_screen_device["Description"] = validate_patch_string("description", args.get("description"), 1000, allow_empty=True)
    if args.get("should_hide_empty_rows") is not None:
        if not isinstance(args.get("should_hide_empty_rows"), bool):
            raise ValueError("should_hide_empty_rows must be boolean")
        clone_screen_device["ShouldHideEmptyRows"] = bool(args.get("should_hide_empty_rows"))
    if bool(args.get("clear_elements", False)):
        clone_document["Elements"] = []

    canvas_updates: dict[str, Any] = {}
    for field, minimum in (("x", -1000000), ("y", -1000000), ("width", 0), ("height", 0)):
        if args.get(field) is None:
            continue
        new_value = int(validate_patch_number(field, args.get(field), minimum, 1000000))
        clone[field.upper() if field in {"x", "y"} else field.capitalize()] = new_value
        canvas_updates[field] = new_value

    insert_index = args.get("insert_index")
    if insert_index is None:
        new_index = len(screens)
        screens.append(clone)
    else:
        new_index = require_non_negative_index("insert_index", insert_index, len(screens))
        if new_index > len(screens):
            raise ValueError(f"insert_index is out of range: {new_index}")
        screens.insert(new_index, clone)

    created = summarize_display_screen_for_write(group_index, new_index, group, clone)
    write_owle_json_section(project_path, entries, "Visualization", visualization)
    after_hash = sha256_file(project_path)
    final_screen_count, final_element_count = display_screen_count_and_elements(visualization)
    validation_summary: dict[str, Any] | None = None
    if bool(args.get("validate_after", True)):
        loaded = read_owle_sections(project_path, include_hashes=True)
        validation_summary = summarize_display_visualization(
            loaded["sections"].get("Visualization"),
            max_items=20,
            include_elements=True,
            include_background_hash=False,
        )
    return {
        "source_project": target["source"],
        "scratch_copy": target["scratch_copy"] or safe_file_info(project_path, include_hash=True),
        "backup": target["backup"],
        "write_mode": target["write_mode"],
        "group_index": group_index,
        "group_name": group.get("Name"),
        "source_screen_index": screen_index,
        "new_screen_index": new_index,
        "source_screen_unique_id": source.get("unique_id"),
        "new_screen_unique_id": created.get("unique_id"),
        "source_document_unique_id": source.get("document_unique_id"),
        "new_document_unique_id": created.get("document_unique_id"),
        "source_screen": source,
        "created": created,
        "screen_count_before": source_screen_count,
        "screen_count_after": final_screen_count,
        "total_element_count_before": source_element_count,
        "total_element_count_after": final_element_count,
        "cloned_screen_element_count": created.get("element_count"),
        "id_remap_count": len(id_map),
        "canvas_updates": canvas_updates,
        "target_hash_before": before_hash,
        "target_hash_after": after_hash,
        "changed": before_hash != after_hash,
        "source_hash_after": sha256_file(Path(str(target["source"]["path"]))),
        "validation_summary": validation_summary,
        "audit_note": compact_string(str(args.get("audit_note") or "")),
        "risk_class": "safe_write_project",
        "guardrail": "Only an existing Visualization screen was cloned with UUID remap, and only on a scratch copy or explicitly confirmed scratch path.",
        "limitation": "This creates a project-local clone of an existing display screen; it does not exercise the OWEN GUI screen manager wizard, installed display widget catalog insertion, or rendered preview output.",
    }


def select_display_screen_for_delete(
    visualization: list[Any],
    group_index: int,
    screen_index: int,
    screen_unique_id: str | None,
) -> tuple[dict[str, Any], list[Any], int, dict[str, Any]]:
    group, _screen = select_display_screen(visualization, group_index, screen_index)
    screens = group.get("Screens")
    if not isinstance(screens, list):
        raise ValueError("Selected Visualization group has no Screens list")
    if screen_unique_id:
        expected = screen_unique_id.strip().lower()
        for index, screen in enumerate(screens):
            if not isinstance(screen, dict):
                continue
            actual = str(screen.get("UniqueId") or "").lower()
            if actual == expected:
                return group, screens, index, screen
        raise ValueError(f"Display screen_unique_id was not found: {screen_unique_id}")
    return group, screens, screen_index, _screen


DISPLAY_SCREEN_PATCH_FIELDS = ("title", "description", "should_hide_empty_rows", "x", "y", "width", "height")


def project_display_screen_property_patch(args: dict[str, Any]) -> dict[str, Any]:
    target = resolve_scratch_write_target(args, "_display_screen_property_patch_scratch")
    project_path = Path(str(target["target_path"]))
    before_hash = sha256_file(project_path)
    entries = read_owle_raw_entries(project_path)
    visualization = read_visualization_section_from_entries(entries)
    group_index = require_non_negative_index("group_index", args.get("group_index"), 0)
    screen_index_arg = require_non_negative_index("screen_index", args.get("screen_index"), 0)
    screen_unique_id = str(args.get("screen_unique_id") or "").strip() or None

    supplied_fields = [field for field in DISPLAY_SCREEN_PATCH_FIELDS if args.get(field) is not None]
    if not supplied_fields:
        raise ValueError("At least one screen property patch field is required: title, description, should_hide_empty_rows, x, y, width or height")

    group, _screens, screen_index, screen = select_display_screen_for_delete(
        visualization,
        group_index,
        screen_index_arg,
        screen_unique_id,
    )
    expected_group_name = args.get("expected_group_name")
    if expected_group_name is not None and group.get("Name") != str(expected_group_name):
        raise ValueError(f"Selected group name guard failed: expected {expected_group_name!r}, got {group.get('Name')!r}")
    _prop, screen_device, document = display_screen_device(screen)
    expected_screen_title = args.get("expected_screen_title")
    if expected_screen_title is not None and screen_device.get("Title") != str(expected_screen_title):
        raise ValueError(
            f"Selected screen title guard failed: expected {expected_screen_title!r}, got {screen_device.get('Title')!r}"
        )
    expected_document_unique_id = args.get("expected_document_unique_id")
    if expected_document_unique_id is not None and document.get("UniqueId") != str(expected_document_unique_id):
        raise ValueError(
            f"Selected screen document UniqueId guard failed: expected {expected_document_unique_id!r}, got {document.get('UniqueId')!r}"
        )
    elements = document.get("Elements")
    element_count = len(elements) if isinstance(elements, list) else 0
    if args.get("expected_screen_element_count") is not None:
        expected_count = require_non_negative_index(
            "expected_screen_element_count",
            args.get("expected_screen_element_count"),
            element_count,
        )
        if expected_count != element_count:
            raise ValueError(
                f"Selected screen element-count guard failed: expected {expected_count}, got {element_count}"
            )

    before = summarize_display_screen_for_write(group_index, screen_index, group, screen)
    updates: list[dict[str, Any]] = []

    def record_update(field: str, path: str, current: Any, new_value: Any) -> None:
        updates.append(
            {
                "field": field,
                "path": path,
                "before": scalar_preview(current),
                "after": scalar_preview(new_value),
                "changed": current != new_value,
            }
        )

    if args.get("title") is not None:
        new_title = validate_patch_string("title", args.get("title"), 200, allow_empty=False)
        current = screen_device.get("Title")
        record_update("title", "Property.ScreenDevice.Title", current, new_title)
        if current != new_title:
            screen_device["Title"] = new_title
    if args.get("description") is not None:
        new_description = validate_patch_string("description", args.get("description"), 1000, allow_empty=True)
        current = screen_device.get("Description")
        record_update("description", "Property.ScreenDevice.Description", current, new_description)
        if current != new_description:
            screen_device["Description"] = new_description
    if args.get("should_hide_empty_rows") is not None:
        if not isinstance(args.get("should_hide_empty_rows"), bool):
            raise ValueError("should_hide_empty_rows must be boolean")
        new_hide_empty_rows = bool(args.get("should_hide_empty_rows"))
        current = screen_device.get("ShouldHideEmptyRows")
        record_update("should_hide_empty_rows", "Property.ScreenDevice.ShouldHideEmptyRows", current, new_hide_empty_rows)
        if current != new_hide_empty_rows:
            screen_device["ShouldHideEmptyRows"] = new_hide_empty_rows
    for field, minimum in (("x", -1000000), ("y", -1000000), ("width", 0), ("height", 0)):
        if args.get(field) is None:
            continue
        new_value = int(validate_patch_number(field, args.get(field), minimum, 1000000))
        screen_key = field.upper() if field in {"x", "y"} else field.capitalize()
        current = screen.get(screen_key)
        record_update(field, screen_key, current, new_value)
        if current != new_value:
            screen[screen_key] = new_value

    if any(update["changed"] for update in updates):
        write_owle_json_section(project_path, entries, "Visualization", visualization)
    after_hash = sha256_file(project_path)
    after = summarize_display_screen_for_write(group_index, screen_index, group, screen)
    validation_summary: dict[str, Any] | None = None
    if bool(args.get("validate_after", True)):
        loaded = read_owle_sections(project_path, include_hashes=True)
        validation_summary = summarize_display_visualization(
            loaded["sections"].get("Visualization"),
            max_items=20,
            include_elements=True,
            include_background_hash=False,
        )
    return {
        "source_project": target["source"],
        "scratch_copy": target["scratch_copy"] or safe_file_info(project_path, include_hash=True),
        "backup": target["backup"],
        "write_mode": target["write_mode"],
        "group_index": group_index,
        "group_name": group.get("Name"),
        "screen_index": screen_index,
        "screen_unique_id": screen.get("UniqueId"),
        "document_unique_id": after.get("document_unique_id"),
        "before": before,
        "after": after,
        "updates": updates,
        "target_hash_before": before_hash,
        "target_hash_after": after_hash,
        "changed": before_hash != after_hash,
        "source_hash_after": sha256_file(Path(str(target["source"]["path"]))),
        "validation_summary": validation_summary,
        "audit_note": compact_string(str(args.get("audit_note") or "")),
        "risk_class": "safe_write_project",
        "guardrail": "Only safe properties of an existing Visualization screen were patched, and only on a scratch copy or explicitly confirmed scratch path.",
        "limitation": "This patches stored .owle Visualization screen properties; it does not exercise the OWEN GUI screen manager, installed widget catalog, or rendered preview output.",
    }


