def first_present(mapping: dict[str, Any], keys: tuple[str, ...]) -> Any:
    for key in keys:
        if key in mapping and mapping.get(key) is not None:
            return mapping.get(key)
    return None


def scalar_fields(mapping: Any, exclude: set[str] | None = None) -> dict[str, Any]:
    if not isinstance(mapping, dict):
        return {}
    excluded = exclude or set()
    fields: dict[str, Any] = {}
    for key, value in mapping.items():
        if key in excluded:
            continue
        if isinstance(value, (dict, list)):
            continue
        fields[str(key)] = redact_scalar(str(key), value)
    return fields


def infer_modbus_read_write(variable: dict[str, Any]) -> str:
    candidates = [
        str(value).lower()
        for value in (
            first_present(variable, ("ReadWrite", "Access", "Direction", "RequestType", "Mode")),
            first_present(variable, ("Operation", "Command", "FunctionName")),
        )
        if value is not None
    ]
    text = " ".join(candidates)
    if "read" in text and "write" in text:
        return "read_write"
    if "write" in text or "зап" in text:
        return "write"
    if "read" in text or "чт" in text:
        return "read"
    bool_pairs = {
        "read": first_present(variable, ("IsRead", "CanRead", "ReadEnabled", "EnableRead")),
        "write": first_present(variable, ("IsWrite", "CanWrite", "WriteEnabled", "EnableWrite")),
    }
    if bool(bool_pairs["read"]) and bool(bool_pairs["write"]):
        return "read_write"
    if bool(bool_pairs["write"]):
        return "write"
    if bool(bool_pairs["read"]):
        return "read"
    read_function = first_present(variable, ("ReadFunction", "ReadFunctionCode"))
    write_function = first_present(variable, ("WriteFunction", "WriteFunctionCode"))
    try:
        has_read = int(read_function) != 0 if read_function is not None else False
        has_write = int(write_function) != 0 if write_function is not None else False
        if has_read and has_write:
            return "read_write"
        if has_write:
            return "write"
        if has_read:
            return "read"
    except Exception:
        pass
    return "unknown"


def modbus_device_base_row(
    document_id: str,
    setting_index: int,
    setting: dict[str, Any],
    device_index: int,
    device: dict[str, Any],
) -> dict[str, Any]:
    metadata = device.get("ComponentMetaDataModel") if isinstance(device.get("ComponentMetaDataModel"), dict) else {}
    return {
        "row_type": "device",
        "document_id": document_id,
        "setting_index": setting_index,
        "device_index": device_index,
        "variable_index": "",
        "setting_uid": setting.get("UniqueId"),
        "slot_number": setting.get("SlotNumber"),
        "protocol": setting.get("Protocol"),
        "rs485_mode": setting.get("Rs485Mode"),
        "speed": setting.get("Speed"),
        "data_bits": setting.get("DataBits"),
        "stop_bits": setting.get("StopBitCount"),
        "parity": setting.get("Parity"),
        "setting_timeout": setting.get("Timeout"),
        "device_uid": device.get("UniqueId"),
        "device_name": metadata.get("Name"),
        "device_address": device.get("Address"),
        "registers_per_request_count": device.get("RegistersPerRequestCount"),
        "use_group_requests": device.get("UseGroupRequests"),
        "device_rs485_mode": device.get("Rs485Mode"),
        "elder_reg_forward": device.get("IsElderRegForward"),
        "elder_byte_forward": device.get("IsElderByteForward"),
        "polling": device.get("Polling"),
        "timeout": device.get("TimeOut"),
        "attempts": device.get("Attempts"),
        "status_variable": device.get("StatusVariable"),
        "enable_polling_variable": device.get("EnablePollingVariable"),
        "variable_uid": "",
        "variable_name": "",
        "display_name": "",
        "data_type": "",
        "function_code": "",
        "start_address": "",
        "register_address": "",
        "register_count": "",
        "bit_number": "",
        "read_write": "",
        "is_retain": "",
        "comment": device.get("Comment"),
        "variable_scalar_fields_json": "",
        "metadata_scalar_fields_json": "",
    }


def modbus_variable_row(base: dict[str, Any], index: int, variable: dict[str, Any], metadata: dict[str, Any]) -> dict[str, Any]:
    row = dict(base)
    row.update(
        {
            "row_type": "variable",
            "variable_index": index,
            "variable_uid": first_present(variable, ("UniqueId", "VariableUid", "VariableUId", "VariableId", "Id")),
            "variable_name": first_present(variable, ("Name", "VariableName", "SystemName")),
            "display_name": first_present(variable, ("DisplayName", "Caption", "Title")),
            "data_type": first_present(variable, ("DataType", "VariableDataType", "Type", "TypeName")),
            "function_code": first_present(
                variable,
                ("FunctionCode", "ModbusFunctionCode", "RequestFunctionCode", "ReadFunctionCode", "ReadFunction", "WriteFunctionCode", "WriteFunction"),
            ),
            "start_address": first_present(variable, ("StartAddress", "StartRegister", "StartRegisterAddress", "Offset")),
            "register_address": first_present(
                variable,
                ("RegisterAddress", "Register", "RegisterNumber", "Address", "ModbusAddress"),
            ),
            "register_count": first_present(
                variable,
                ("RegisterCount", "RegistersCount", "RegisterQuantity", "Quantity", "Count", "Length"),
            ),
            "bit_number": first_present(variable, ("BitNumber", "BitIndex", "Bit", "MaskBit")),
            "read_write": infer_modbus_read_write(variable),
            "is_retain": first_present(variable, ("IsRetain", "Retain")),
            "comment": first_present(variable, ("Comment", "Description")),
            "variable_scalar_fields_json": json.dumps(
                scalar_fields(variable, {"ComponentMetaDataModel", "VariableMetaDataModel"}),
                ensure_ascii=False,
                sort_keys=True,
            ),
            "metadata_scalar_fields_json": json.dumps(scalar_fields(metadata), ensure_ascii=False, sort_keys=True),
        }
    )
    return row


def write_modbus_export_files(output_dir: Path, project: Path, rows: list[dict[str, Any]], summary: dict[str, Any]) -> dict[str, str]:
    output_dir = output_dir.expanduser().resolve()
    if not is_scratch_destination(output_dir):
        raise ValueError(f"Refusing to write Modbus export outside scratch/sandbox/local-heavy path: {output_dir}")
    output_dir.mkdir(parents=True, exist_ok=True)
    safe_stem = re.sub(r"[^A-Za-z0-9_.-]+", "_", project.stem).strip("._") or "owen_project"
    csv_path = output_dir / f"{safe_stem}_modbus_register_map.csv"
    json_path = output_dir / f"{safe_stem}_modbus_register_map.json"
    with csv_path.open("w", encoding="utf-8", newline="") as fh:
        writer = csv.DictWriter(fh, fieldnames=MODBUS_EXPORT_COLUMNS, extrasaction="ignore")
        writer.writeheader()
        for row in rows:
            writer.writerow({column: row.get(column, "") for column in MODBUS_EXPORT_COLUMNS})
    json_path.write_text(
        json.dumps({"summary": summary, "rows": rows}, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    return {"csv_path": str(csv_path), "json_path": str(json_path)}


def project_modbus_export_map(args: dict[str, Any]) -> dict[str, Any]:
    max_rows = clamp_int(args.get("max_rows"), 2000, 1, 20000)
    include_empty_devices = bool(args.get("include_empty_devices", True))
    project = Path(str(args.get("project_path") or "")).expanduser().resolve()
    source_hash_before = sha256_file(project)
    loaded = read_owle_sections(project, include_hashes=False)
    project_section = loaded["sections"].get("Project")
    documents = project_documents(project_section)
    rows: list[dict[str, Any]] = []
    device_count = 0
    variable_model_count = 0
    variable_row_count = 0
    rows_truncated = False

    for doc in documents:
        document = doc["document"]
        settings = document.get("ProjectSettingModels") or []
        if not isinstance(settings, list):
            continue
        for setting_index, setting in enumerate(settings):
            if not isinstance(setting, dict):
                continue
            device_models = setting.get("DeviceModels")
            if not isinstance(device_models, list):
                continue
            for device_index, device in enumerate(device_models):
                if not isinstance(device, dict):
                    continue
                device_count += 1
                base = modbus_device_base_row(doc["id"], setting_index, setting, device_index, device)
                variables = device.get("VariableModels") if isinstance(device.get("VariableModels"), list) else []
                variable_model_count += sum(1 for variable in variables if isinstance(variable, dict))
                metadata_rows = (
                    device.get("VariableMetaDataModels")
                    if isinstance(device.get("VariableMetaDataModels"), list)
                    else []
                )
                if include_empty_devices and len(rows) < max_rows:
                    rows.append(base)
                elif include_empty_devices:
                    rows_truncated = True
                for variable_index, variable in enumerate(variables):
                    if len(rows) >= max_rows:
                        rows_truncated = True
                        break
                    if not isinstance(variable, dict):
                        continue
                    metadata = metadata_rows[variable_index] if variable_index < len(metadata_rows) and isinstance(metadata_rows[variable_index], dict) else {}
                    rows.append(modbus_variable_row(base, variable_index, variable, metadata))
                    variable_row_count += 1
                if len(rows) >= max_rows:
                    rows_truncated = True
                    break
            if len(rows) >= max_rows:
                rows_truncated = True
                break
        if len(rows) >= max_rows:
            rows_truncated = True
            break

    source_hash_after = sha256_file(project)
    summary = {
        "project_path": str(project),
        "device_count": device_count,
        "variable_model_count": variable_model_count,
        "variable_row_count": variable_row_count,
        "rows_returned": len(rows),
        "rows_truncated": rows_truncated,
        "include_empty_devices": include_empty_devices,
        "source_hash_before": source_hash_before,
        "source_hash_after": source_hash_after,
        "source_hash_preserved": source_hash_before == source_hash_after,
        "read_only": True,
        "risk_class": "safe_read",
        "guardrail": "Project is read-only; optional Modbus map CSV/JSON files are written only under scratch/sandbox/local-heavy.",
    }
    output_files = None
    if args.get("output_dir"):
        output_files = write_modbus_export_files(Path(str(args["output_dir"])), project, rows, summary)
    return {
        "file": loaded["file"],
        **summary,
        "output_files": output_files,
        "columns": MODBUS_EXPORT_COLUMNS,
        "rows": rows,
    }


