def load_modbus_import_rows(map_path: Path) -> list[dict[str, Any]]:
    if not map_path.exists() or not map_path.is_file():
        raise FileNotFoundError(f"Modbus import map file was not found: {map_path}")
    suffix = map_path.suffix.lower()
    if suffix == ".json":
        data = json.loads(map_path.read_text(encoding="utf-8"))
        if isinstance(data, dict):
            rows = data.get("rows")
        else:
            rows = data
        if not isinstance(rows, list):
            raise ValueError("Modbus import JSON must be a rows array or an object containing a rows array")
        return [dict(row) for row in rows if isinstance(row, dict)]
    if suffix == ".csv":
        with map_path.open("r", encoding="utf-8-sig", newline="") as fh:
            return [dict(row) for row in csv.DictReader(fh)]
    raise ValueError("Modbus import map_path must point to a .csv or .json file")


def select_modbus_import_row(args: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any]]:
    if args.get("row") is not None and args.get("map_path") is not None:
        raise ValueError("Use either inline row or map_path, not both")
    if args.get("row") is not None:
        row = args.get("row")
        if not isinstance(row, dict):
            raise ValueError("row must be an object")
        return dict(row), {"source": "inline_row", "row_index": None, "row_count": 1}
    if not args.get("map_path"):
        raise ValueError("Provide map_path or inline row")

    map_path = Path(str(args.get("map_path"))).expanduser().resolve()
    rows = load_modbus_import_rows(map_path)
    if not rows:
        raise ValueError("Modbus import map contains no rows")
    if args.get("row_index") is not None:
        row_index = int(args.get("row_index"))
        if row_index < 0 or row_index >= len(rows):
            raise ValueError(f"row_index is out of range: {row_index}")
        return rows[row_index], {"source": "map_path", "path": str(map_path), "row_index": row_index, "row_count": len(rows)}
    for row_index, row in enumerate(rows):
        if str(row.get("row_type") or "").strip().lower() == "device":
            return row, {"source": "map_path", "path": str(map_path), "row_index": row_index, "row_count": len(rows)}
    raise ValueError("Modbus import map contains no device row")


def modbus_import_is_blank(value: Any) -> bool:
    return value is None or (isinstance(value, str) and value.strip() == "")


def modbus_import_bool(column: str, value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, int) and not isinstance(value, bool):
        if value in (0, 1):
            return bool(value)
    text = str(value).strip().lower()
    if text in {"true", "1", "yes", "y", "да"}:
        return True
    if text in {"false", "0", "no", "n", "нет"}:
        return False
    raise ValueError(f"Cannot parse boolean Modbus import column {column!r}: {value!r}")


def modbus_import_int(column: str, value: Any) -> int:
    if isinstance(value, bool):
        raise ValueError(f"Cannot parse integer Modbus import column {column!r} from boolean")
    if isinstance(value, int):
        return value
    text = str(value).strip()
    if not re.fullmatch(r"[-+]?\d+", text):
        raise ValueError(f"Cannot parse integer Modbus import column {column!r}: {value!r}")
    return int(text)


def normalize_modbus_import_value(column: str, target_field: str, raw_value: Any, rules: dict[str, dict[str, Any]]) -> Any:
    if modbus_import_is_blank(raw_value):
        return None
    rule = rules[target_field]
    kind = str(rule.get("type"))
    if kind == "bool":
        return modbus_import_bool(column, raw_value)
    if kind == "int":
        return modbus_import_int(column, raw_value)
    if kind == "uuid":
        return str(uuid.UUID(str(raw_value).strip()))
    if kind == "string":
        return str(raw_value)
    raise ValueError(f"Unsupported Modbus import target field {target_field!r}")


def optional_import_int(row: dict[str, Any], column: str) -> int | None:
    value = row.get(column)
    if modbus_import_is_blank(value):
        return None
    return modbus_import_int(column, value)


def build_modbus_import_patches(
    row: dict[str, Any],
    import_fields: list[Any] | None,
) -> tuple[dict[str, Any], dict[str, Any], list[dict[str, str]]]:
    supported_columns = set(MODBUS_IMPORT_SETTING_COLUMNS) | set(MODBUS_IMPORT_DEVICE_COLUMNS)
    selected_columns = {str(field) for field in import_fields or []}
    if selected_columns:
        unsupported = sorted(selected_columns - supported_columns)
        if unsupported:
            raise ValueError(f"Unsupported Modbus import field(s): {unsupported}; supported: {sorted(supported_columns)}")

    setting_patch: dict[str, Any] = {}
    device_patch: dict[str, Any] = {}
    imported_fields: list[dict[str, str]] = []

    for column, target_field in MODBUS_IMPORT_SETTING_COLUMNS.items():
        if selected_columns and column not in selected_columns:
            continue
        if column not in row:
            continue
        value = normalize_modbus_import_value(column, target_field, row.get(column), MODBUS_SETTING_PATCH_RULES)
        if value is None:
            continue
        setting_patch[target_field] = value
        imported_fields.append({"column": column, "target": f"setting.{target_field}"})

    for column, target_field in MODBUS_IMPORT_DEVICE_COLUMNS.items():
        if selected_columns and column not in selected_columns:
            continue
        if column not in row:
            continue
        value = normalize_modbus_import_value(column, target_field, row.get(column), MODBUS_DEVICE_PATCH_RULES)
        if value is None:
            continue
        device_patch[target_field] = value
        imported_fields.append({"column": column, "target": f"device.{target_field}"})

    if not setting_patch and not device_patch:
        raise ValueError("Selected Modbus import row did not contain any supported non-empty scalar fields to import")
    return setting_patch, device_patch, imported_fields


def parse_modbus_import_metadata(column: str, value: Any) -> dict[str, Any] | None:
    if modbus_import_is_blank(value):
        return None
    if isinstance(value, dict):
        return sanitize_modbus_variable_metadata(value)
    parsed = json.loads(str(value))
    if not isinstance(parsed, dict):
        raise ValueError(f"Modbus import column {column!r} must contain a JSON object")
    return sanitize_modbus_variable_metadata(parsed)


def build_modbus_import_variable_create_args(
    row: dict[str, Any],
    args: dict[str, Any],
    row_type: str,
) -> tuple[dict[str, Any], list[dict[str, str]]]:
    supported_columns = set(MODBUS_IMPORT_VARIABLE_COLUMNS)
    selected_columns = {str(field) for field in args.get("import_fields") or []}
    if selected_columns:
        unsupported = sorted(selected_columns - supported_columns)
        if unsupported:
            raise ValueError(f"Unsupported Modbus variable import field(s): {unsupported}; supported: {sorted(supported_columns)}")

    create_args: dict[str, Any] = {
        "project_path": args.get("project_path"),
        "allow_safe_create": True,
        "validate_after": bool(args.get("validate_after", True)),
        "include_map_after": bool(args.get("include_map_after", True)),
        "allow_address_overlap": bool(args.get("allow_address_overlap", False)),
    }
    for key in ("scratch_dir", "write_in_place", "confirm_project_path_is_scratch", "map_output_dir"):
        if args.get(key) is not None:
            create_args[key] = args.get(key)

    create_args["document_id"] = args.get("document_id") or row.get("document_id") or None
    create_args["setting_index"] = args.get("setting_index") if args.get("setting_index") is not None else optional_import_int(row, "setting_index")
    create_args["device_index"] = args.get("device_index") if args.get("device_index") is not None else optional_import_int(row, "device_index")
    if row.get("setting_uid"):
        create_args["setting_unique_id"] = str(row.get("setting_uid"))
    if row.get("device_uid"):
        create_args["device_unique_id"] = str(row.get("device_uid"))
        create_args["expected_device_unique_id"] = str(row.get("device_uid"))
    if not modbus_import_is_blank(row.get("device_address")):
        create_args["expected_address"] = modbus_import_int("device_address", row.get("device_address"))

    imported_fields: list[dict[str, str]] = []

    def can_import(column: str) -> bool:
        return (not selected_columns or column in selected_columns) and column in row and not modbus_import_is_blank(row.get(column))

    if can_import("variable_uid"):
        create_args["variable_unique_id"] = str(uuid.UUID(str(row.get("variable_uid")).strip()))
        imported_fields.append({"column": "variable_uid", "target": "variable.UniqueId"})
    if can_import("variable_name"):
        create_args["variable_name"] = str(row.get("variable_name"))
        imported_fields.append({"column": "variable_name", "target": "variable.Name"})
    if can_import("display_name"):
        create_args["display_name"] = str(row.get("display_name"))
        imported_fields.append({"column": "display_name", "target": "variable.DisplayName"})
    if can_import("data_type"):
        create_args["data_type"] = modbus_import_int("data_type", row.get("data_type"))
        imported_fields.append({"column": "data_type", "target": "variable.DataType"})
    if can_import("function_code"):
        create_args["function_code"] = modbus_import_int("function_code", row.get("function_code"))
        imported_fields.append({"column": "function_code", "target": "variable.FunctionCode"})

    address_column = None
    if can_import("register_address"):
        address_column = "register_address"
    elif can_import("start_address"):
        address_column = "start_address"
    if address_column:
        create_args["register_address"] = modbus_import_int(address_column, row.get(address_column))
        imported_fields.append({"column": address_column, "target": "variable.RegisterAddress"})

    if can_import("register_count"):
        create_args["register_count"] = modbus_import_int("register_count", row.get("register_count"))
        imported_fields.append({"column": "register_count", "target": "variable.RegisterCount"})
    if can_import("bit_number"):
        create_args["bit_number"] = modbus_import_int("bit_number", row.get("bit_number"))
        imported_fields.append({"column": "bit_number", "target": "variable.BitNumber"})
    if can_import("read_write"):
        create_args["read_write"] = str(row.get("read_write"))
        imported_fields.append({"column": "read_write", "target": "variable.ReadWrite"})
    if can_import("is_retain"):
        create_args["is_retain"] = modbus_import_bool("is_retain", row.get("is_retain"))
        imported_fields.append({"column": "is_retain", "target": "variable.IsRetain"})
    if can_import("comment"):
        create_args["comment"] = str(row.get("comment"))
        imported_fields.append({"column": "comment", "target": "variable.Comment"})
    if can_import("metadata_scalar_fields_json"):
        metadata = parse_modbus_import_metadata("metadata_scalar_fields_json", row.get("metadata_scalar_fields_json"))
        if metadata is not None:
            create_args["metadata"] = metadata
            imported_fields.append({"column": "metadata_scalar_fields_json", "target": "variable_metadata"})

    if not create_args.get("variable_name"):
        raise ValueError(f"Selected Modbus {row_type or 'variable'} import row did not contain variable_name")
    if create_args.get("register_address") is None:
        raise ValueError(f"Selected Modbus {row_type or 'variable'} import row did not contain register_address or start_address")
    if not imported_fields:
        raise ValueError("Selected Modbus variable import row did not contain any supported non-empty fields to import")
    return create_args, imported_fields


def project_modbus_import_map(args: dict[str, Any]) -> dict[str, Any]:
    if not bool(args.get("allow_safe_import", False)):
        raise ValueError("owen_logic_project_modbus_import_map requires allow_safe_import=true")
    row, row_source = select_modbus_import_row(args)
    row_type = str(row.get("row_type") or "").strip().lower()
    if row_type == "variable":
        create_args, imported_fields = build_modbus_import_variable_create_args(row, args, row_type)
        create_result = project_modbus_variable_create(create_args)
        return {
            "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
            "row_source": row_source,
            "selected_row_type": "variable",
            "imported_fields": imported_fields,
            "variable_create_args": {
                key: scalar_preview(value)
                for key, value in create_args.items()
                if key
                not in {
                    "allow_safe_create",
                    "project_path",
                    "scratch_dir",
                    "write_in_place",
                    "confirm_project_path_is_scratch",
                    "map_output_dir",
                    "metadata",
                }
            },
            "create_result": create_result,
            "source_project": create_result.get("source_project"),
            "scratch_copy": create_result.get("scratch_copy"),
            "write_mode": create_result.get("write_mode"),
            "changed": create_result.get("changed"),
            "created": create_result.get("created"),
            "validation_after": create_result.get("validation_after"),
            "modbus_map_after": create_result.get("modbus_map_after"),
            "source_hash_after": create_result.get("source_hash_after"),
            "source_hash_preserved": create_result.get("source_hash_preserved"),
            "opened_serial_port": create_result.get("opened_serial_port"),
            "opened_network_socket": create_result.get("opened_network_socket"),
            "launched_gui": create_result.get("launched_gui"),
            "risk_class": "safe_write_project",
            "guardrail": "Imported one Modbus variable/register map row through the same scratch-only guardrails as owen_logic_project_modbus_variable_create.",
            "limitation": "This is an offline .owle variable/register row import and export/readback path. It does not prove OWEN Logic GUI Modbus import/export dialog parity or live COM/TCP execution.",
        }
    if row_type and row_type != "device":
        raise ValueError("Only row_type=device or row_type=variable is supported for Modbus map import")
    setting_patch, device_patch, imported_fields = build_modbus_import_patches(row, args.get("import_fields"))
    patch_args: dict[str, Any] = {
        "project_path": args.get("project_path"),
        "setting_patch": setting_patch,
        "device_patch": device_patch,
        "validate_after": bool(args.get("validate_after", True)),
        "include_map_after": bool(args.get("include_map_after", True)),
    }
    for key in ("scratch_dir", "write_in_place", "confirm_project_path_is_scratch", "map_output_dir"):
        if args.get(key) is not None:
            patch_args[key] = args.get(key)

    patch_args["document_id"] = args.get("document_id") or row.get("document_id") or None
    patch_args["setting_index"] = args.get("setting_index") if args.get("setting_index") is not None else optional_import_int(row, "setting_index")
    patch_args["device_index"] = args.get("device_index") if args.get("device_index") is not None else optional_import_int(row, "device_index")
    if row.get("setting_uid"):
        patch_args["setting_unique_id"] = str(row.get("setting_uid"))
        patch_args["expected_setting_unique_id"] = str(row.get("setting_uid"))
    if row.get("device_uid"):
        patch_args["device_unique_id"] = str(row.get("device_uid"))
        patch_args["expected_device_unique_id"] = str(row.get("device_uid"))

    patch_result = project_modbus_device_patch(patch_args)
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "row_source": row_source,
        "selected_row_type": row_type or "device",
        "imported_fields": imported_fields,
        "setting_patch": setting_patch,
        "device_patch": device_patch,
        "patch_result": patch_result,
        "source_project": patch_result.get("source_project"),
        "scratch_copy": patch_result.get("scratch_copy"),
        "write_mode": patch_result.get("write_mode"),
        "changed": patch_result.get("changed"),
        "changes": patch_result.get("changes"),
        "validation_after": patch_result.get("validation_after"),
        "modbus_map_after": patch_result.get("modbus_map_after"),
        "source_hash_after": patch_result.get("source_hash_after"),
        "source_hash_preserved": patch_result.get("source_hash_preserved"),
        "risk_class": "safe_write_project",
        "guardrail": "Imported only existing Modbus setting/device scalar fields through the same scratch-only guardrails as owen_logic_project_modbus_device_patch.",
        "limitation": "This is an offline map-row import into the stored .owle model. It does not exercise OWEN Logic GUI Modbus import/export dialogs or open COM/TCP connections.",
    }


MODBUS_VARIABLE_FUNCTION_LIMITS: dict[int, dict[str, Any]] = {
    1: {"access": "read", "quantity_min": 1, "quantity_max": 0x07D0, "kind": "bits"},
    2: {"access": "read", "quantity_min": 1, "quantity_max": 0x07D0, "kind": "bits"},
    3: {"access": "read", "quantity_min": 1, "quantity_max": 0x007D, "kind": "registers"},
    4: {"access": "read", "quantity_min": 1, "quantity_max": 0x007D, "kind": "registers"},
    5: {"access": "write", "quantity_min": 1, "quantity_max": 1, "kind": "single_coil"},
    6: {"access": "write", "quantity_min": 1, "quantity_max": 1, "kind": "single_register"},
    15: {"access": "write", "quantity_min": 1, "quantity_max": 0x07B0, "kind": "bits_write"},
    16: {"access": "write", "quantity_min": 1, "quantity_max": 0x007B, "kind": "registers_write"},
}


def normalize_modbus_variable_function(value: Any) -> int:
    function_code = normalize_function_code(value if value is not None else 3)
    if function_code not in MODBUS_VARIABLE_FUNCTION_LIMITS:
        supported = ", ".join(str(code) for code in sorted(MODBUS_VARIABLE_FUNCTION_LIMITS))
        raise ValueError(f"Unsupported Modbus variable function code {function_code}; supported: {supported}")
    return function_code


def normalize_modbus_variable_count(function_code: int, value: Any) -> int:
    limits = MODBUS_VARIABLE_FUNCTION_LIMITS[function_code]
    count = 1 if value in {None, ""} else int(value)
    minimum = int(limits["quantity_min"])
    maximum = int(limits["quantity_max"])
    if count < minimum or count > maximum:
        raise ValueError(f"register_count for function {function_code} must be in range {minimum}..{maximum}")
    return count


def normalize_modbus_read_write(function_code: int, value: Any) -> str:
    if value is None or str(value).strip() == "":
        return str(MODBUS_VARIABLE_FUNCTION_LIMITS[function_code]["access"])
    normalized = str(value).strip().lower()
    aliases = {
        "r": "read",
        "read": "read",
        "w": "write",
        "write": "write",
        "rw": "read_write",
        "readwrite": "read_write",
        "read_write": "read_write",
        "read/write": "read_write",
        "unknown": "unknown",
    }
    if normalized not in aliases:
        raise ValueError("read_write must be one of read, write, read_write, or unknown")
    return aliases[normalized]


def sanitize_modbus_variable_metadata(value: Any) -> dict[str, Any]:
    if value is None:
        return {}
    if not isinstance(value, dict):
        raise ValueError("metadata must be an object")
    metadata: dict[str, Any] = {}
    for key, raw in value.items():
        text_key = str(key)
        if len(text_key) > 100:
            raise ValueError(f"metadata key is too long: {text_key[:40]!r}")
        if isinstance(raw, (dict, list)):
            raise ValueError(f"metadata field {text_key!r} must be scalar")
        if isinstance(raw, str) and len(raw) > 1000:
            raise ValueError(f"metadata field {text_key!r} is too long")
        metadata[text_key] = raw
    return metadata


def modbus_variable_span(variable: dict[str, Any]) -> tuple[int | None, int | None, int | None]:
    try:
        function_code = normalize_modbus_variable_function(
            first_present(
                variable,
                ("FunctionCode", "ModbusFunctionCode", "RequestFunctionCode", "ReadFunctionCode", "ReadFunction", "WriteFunctionCode", "WriteFunction"),
            )
        )
        start_address = int(
            first_present(variable, ("StartAddress", "StartRegister", "StartRegisterAddress", "Offset", "RegisterAddress", "Register", "RegisterNumber", "Address", "ModbusAddress"))
        )
        count_raw = first_present(variable, ("RegisterCount", "RegistersCount", "RegisterQuantity", "Quantity", "Count", "Length"))
        register_count = normalize_modbus_variable_count(function_code, count_raw)
    except Exception:
        return None, None, None
    return function_code, start_address, start_address + register_count - 1


def find_modbus_variable_address_overlaps(
    variables: list[Any],
    function_code: int,
    start_address: int,
    register_count: int,
) -> list[dict[str, Any]]:
    end_address = start_address + register_count - 1
    overlaps: list[dict[str, Any]] = []
    for index, variable in enumerate(variables):
        if not isinstance(variable, dict):
            continue
        existing_function, existing_start, existing_end = modbus_variable_span(variable)
        if existing_function != function_code or existing_start is None or existing_end is None:
            continue
        if start_address <= existing_end and existing_start <= end_address:
            overlaps.append(
                {
                    "variable_index": index,
                    "function_code": existing_function,
                    "start_address": existing_start,
                    "end_address": existing_end,
                    "name": first_present(variable, ("Name", "VariableName", "SystemName")),
                    "unique_id": first_present(variable, ("UniqueId", "VariableUid", "VariableUId", "VariableId", "Id")),
                }
            )
    return overlaps


def build_modbus_variable_model(args: dict[str, Any], existing_ids: set[str], existing_names: set[str]) -> tuple[dict[str, Any], dict[str, Any]]:
    name = validate_variable_name(str(args.get("variable_name") or ""))
    if name in existing_names:
        raise ValueError(f"Modbus variable/register row name already exists in selected device: {name}")
    requested_uid = args.get("variable_unique_id")
    if requested_uid not in {None, ""}:
        unique_id = normalize_uuid(str(requested_uid))
        if unique_id in existing_ids:
            raise ValueError(f"Modbus variable/register row UUID already exists: {unique_id}")
        existing_ids.add(unique_id)
    else:
        unique_id = generate_unique_uuid(existing_ids)

    data_type = int(args.get("data_type", 0))
    if data_type < 0 or data_type > 255:
        raise ValueError(f"data_type must be an integer between 0 and 255: {data_type}")
    function_code = normalize_modbus_variable_function(args.get("function_code", 3))
    register_address = require_modbus_range("register_address", args.get("register_address"), 0, 0xFFFF)
    register_count = normalize_modbus_variable_count(function_code, args.get("register_count", 1))
    read_write = normalize_modbus_read_write(function_code, args.get("read_write"))

    variable: dict[str, Any] = {
        "UniqueId": unique_id,
        "Name": name,
        "DisplayName": str(args.get("display_name") or name),
        "DataType": data_type,
        "FunctionCode": function_code,
        "StartAddress": register_address,
        "RegisterAddress": register_address,
        "RegisterCount": register_count,
        "ReadWrite": read_write,
        "IsRetain": bool(args.get("is_retain", False)),
    }
    if args.get("comment") is not None:
        variable["Comment"] = validate_patch_string("comment", args.get("comment"), 1000, allow_empty=True)
    if args.get("polling") is not None:
        variable["Polling"] = require_modbus_range("polling", args.get("polling"), 0, 86400000)
    if args.get("bit_number") is not None:
        variable["BitNumber"] = require_modbus_range("bit_number", args.get("bit_number"), 0, 15)

    metadata = sanitize_modbus_variable_metadata(args.get("metadata"))
    return variable, metadata


MODBUS_NETWORK_VARIABLE_DATA_TYPES = {3: "Long", 4: "Float"}
MODBUS_NETWORK_READ_FUNCTION_COIL_STATUS = 1
MODBUS_NETWORK_WRITE_FUNCTION_SINGLE_COIL = 5


def modbus_network_register_count(data_type: int) -> int:
    if data_type == 3:
        return 1
    if data_type == 4:
        return 2
    raise ValueError("Network variable descriptors support only OWEN data_type 3 (Long) or 4 (Float)")


def build_network_rs485_variable_model(
    args: dict[str, Any],
    existing_ids: set[str],
    existing_names: set[str],
    device: dict[str, Any],
    document_id: str,
) -> tuple[dict[str, Any], dict[str, Any] | None, dict[str, Any]]:
    name = validate_variable_name(str(args.get("variable_name") or ""))
    if name in existing_names:
        raise ValueError(f"Network variable name already exists in selected device: {name}")

    deprecated_descriptor_fields = [
        field
        for field in (
            "network_variable_unique_id",
            "mapping_parameter_unique_id",
            "mapping_parameter_name",
            "mapping_parameter_path",
            "default_value",
        )
        if args.get(field) not in {None, ""}
    ]
    if deprecated_descriptor_fields:
        raise ValueError(
            "create_network_variable_descriptor=true creates the observed same-UUID DocumentModel network descriptor but no MappingParameter descriptor; "
            f"unsupported descriptor-only fields: {deprecated_descriptor_fields}"
        )
    if bool(args.get("is_retain", False)):
        raise ValueError("create_network_variable_descriptor=true cannot accept is_retain; OWEN GUI stores network descriptors with IsRetain=true regardless of the CSV field")

    data_type = int(args.get("data_type", 3))
    if data_type not in MODBUS_NETWORK_VARIABLE_DATA_TYPES:
        raise ValueError("create_network_variable_descriptor=true requires data_type 3 (Long) or 4 (Float); Boolean network variables are rejected by OWEN Logic CSV validation")
    register_address = require_modbus_range("register_address", args.get("register_address"), 0, 0xFFFF)
    expected_count = modbus_network_register_count(data_type)
    requested_count = int(args.get("register_count", expected_count))
    if requested_count != expected_count:
        raise ValueError(f"register_count for network data_type {data_type} must be {expected_count}")

    requested_model_uid = args.get("variable_unique_id")
    if requested_model_uid not in {None, ""}:
        model_uid = normalize_uuid(str(requested_model_uid))
        if model_uid in existing_ids:
            raise ValueError(f"Modbus/Rs485 variable model UUID already exists: {model_uid}")
        existing_ids.add(model_uid)
    else:
        model_uid = generate_unique_uuid(existing_ids)

    comment = validate_patch_string("comment", args.get("comment"), 1000, allow_empty=True) if args.get("comment") is not None else ""

    bit_number = require_modbus_range("bit_number", args.get("bit_number", 0), 0, 15)
    device_uid = normalize_uuid(str(device.get("UniqueId") or ""))
    variable = {
        "UniqueId": model_uid,
        "Name": name,
        "DataType": data_type,
        "Register": register_address,
        "RegisterCount": expected_count,
        "BitNumber": bit_number,
        "ReadFunction": MODBUS_NETWORK_READ_FUNCTION_COIL_STATUS,
        "WriteFunction": MODBUS_NETWORK_WRITE_FUNCTION_SINGLE_COIL,
        "StartReadingVariable": MODBUS_ZERO_UUID,
        "StartWritingVariable": MODBUS_ZERO_UUID,
        "RwStatusVariable": MODBUS_ZERO_UUID,
        "Comment": comment,
        "OwnerDeviceId": device_uid,
        "WritedVariableToChanged": True,
    }
    metadata_arg = args.get("metadata")
    if metadata_arg is not None and metadata_arg != {}:
        raise ValueError("create_network_variable_descriptor=true does not persist VariableMetaDataModels rows in the observed OWEN GUI CSV path")
    network_descriptor = {
        "VariableModel": {
            "UniqueId": model_uid,
            "OwnerUniqueId": document_id,
            "Comment": None,
            "DefaultValue": 0,
        },
        "DataType": data_type,
        "VariableModelByModbus": model_uid,
        "IsRetain": True,
        "Discriminator": 2,
    }
    return variable, None, network_descriptor


def document_model_variables(document: dict[str, Any], document_id: str) -> list[Any]:
    model = document.get("DocumentModel")
    if not isinstance(model, dict):
        raise ValueError(f"DocumentModel was not found for document_id={document_id}")
    variables = model.get("Variables")
    if variables is None:
        variables = []
        model["Variables"] = variables
    if not isinstance(variables, list):
        raise ValueError(f"DocumentModel.Variables is not a list for document_id={document_id}")
    return variables


def append_network_variable_descriptor(document: dict[str, Any], document_id: str, network_descriptor: dict[str, Any]) -> dict[str, Any]:
    variables = document_model_variables(document, document_id)
    variable_model = network_descriptor.get("VariableModel") if isinstance(network_descriptor.get("VariableModel"), dict) else {}
    network_uid = str(variable_model.get("UniqueId") or "")
    if any(
        isinstance(variable, dict)
        and (
            str((variable.get("VariableModel") if isinstance(variable.get("VariableModel"), dict) else {}).get("UniqueId") or "") == network_uid
            or str(variable.get("VariableModelByModbus") or "") == network_uid
        )
        for variable in variables
    ):
        raise ValueError(f"Network variable descriptor UUID already exists in DocumentModel.Variables: {network_uid}")
    variables.append(network_descriptor)
    return {
        "network_variable_unique_id": network_uid,
        "descriptor_created": True,
        "mapping_parameter_created": False,
        "document_variable_count_after": len(variables),
        "storage_model": "DocumentModel.Variables[Discriminator=2] plus ProjectSettingModels[Discriminator=4].DeviceModels[].VariableModels[]",
    }


def summarize_created_modbus_variable(
    document_id: str,
    setting_index: int,
    setting: dict[str, Any],
    device_index: int,
    device: dict[str, Any],
    variable_index: int,
) -> dict[str, Any]:
    variables = device.get("VariableModels") if isinstance(device.get("VariableModels"), list) else []
    metadata_rows = device.get("VariableMetaDataModels") if isinstance(device.get("VariableMetaDataModels"), list) else []
    variable = variables[variable_index]
    metadata = metadata_rows[variable_index] if variable_index < len(metadata_rows) and isinstance(metadata_rows[variable_index], dict) else {}
    base = modbus_device_base_row(document_id, setting_index, setting, device_index, device)
    return modbus_variable_row(base, variable_index, variable, metadata)


def project_modbus_variable_create(args: dict[str, Any]) -> dict[str, Any]:
    if not bool(args.get("allow_safe_create", False)):
        raise ValueError("owen_logic_project_modbus_variable_create requires allow_safe_create=true")

    target = resolve_scratch_write_target(args, "_modbus_variable_create_scratch")
    project_path = Path(str(target["target_path"]))
    before_hash = sha256_file(project_path)
    entries = read_owle_raw_entries(project_path)
    project_section = read_project_section_from_entries(entries)
    document_arg = str(args.get("document_id")) if args.get("document_id") else None
    setting_uid_arg = str(args.get("setting_unique_id")) if args.get("setting_unique_id") else None
    device_uid_arg = str(args.get("device_unique_id")) if args.get("device_unique_id") else None
    document_id, setting_index, setting, device_index, device = select_modbus_device(
        project_section,
        document_arg,
        args.get("setting_index"),
        setting_uid_arg,
        args.get("device_index"),
        device_uid_arg,
    )

    if args.get("expected_device_unique_id") is not None and str(device.get("UniqueId") or "") != str(args.get("expected_device_unique_id")):
        raise ValueError("Selected Modbus device does not match expected_device_unique_id")
    if args.get("expected_address") is not None and int(device.get("Address", -1)) != int(args.get("expected_address")):
        raise ValueError("Selected Modbus device does not match expected_address")

    variables = device.get("VariableModels")
    if variables is None:
        variables = []
        device["VariableModels"] = variables
    if not isinstance(variables, list):
        raise ValueError("Selected Modbus device VariableModels is not a list")
    metadata_rows = device.get("VariableMetaDataModels")
    if metadata_rows is None:
        metadata_rows = []
        device["VariableMetaDataModels"] = metadata_rows
    if not isinstance(metadata_rows, list):
        raise ValueError("Selected Modbus device VariableMetaDataModels is not a list")
    while len(metadata_rows) < len(variables):
        metadata_rows.append({})

    before = summarize_modbus_setting_device(document_id, setting_index, setting, device_index, device)
    existing_names = {
        str(first_present(variable, ("Name", "VariableName", "SystemName")) or "")
        for variable in variables
        if isinstance(variable, dict)
    }
    existing_ids = collect_uuid_values(project_section)
    create_network_descriptor = bool(args.get("create_network_variable_descriptor", False))
    network_descriptor_result = None
    if create_network_descriptor:
        if int(device.get("Rs485Mode", -1)) != 1:
            raise ValueError("create_network_variable_descriptor=true requires a selected device with Rs485Mode=1 (OWEN Master/self network page); remote device pages have CSV export disabled")
        new_variable, new_metadata, network_descriptor = build_network_rs485_variable_model(
            args,
            existing_ids,
            existing_names,
            device,
            document_id,
        )
    else:
        new_variable, new_metadata = build_modbus_variable_model(args, existing_ids, existing_names)
        network_descriptor = None

    function_code = normalize_modbus_variable_function(
        first_present(
            new_variable,
            ("FunctionCode", "ModbusFunctionCode", "RequestFunctionCode", "ReadFunctionCode", "ReadFunction", "WriteFunctionCode", "WriteFunction"),
        )
    )
    start_address = int(
        first_present(
            new_variable,
            ("StartAddress", "StartRegister", "StartRegisterAddress", "Offset", "RegisterAddress", "Register", "RegisterNumber", "Address", "ModbusAddress"),
        )
    )
    register_count = int(first_present(new_variable, ("RegisterCount", "RegistersCount", "RegisterQuantity", "Quantity", "Count", "Length")) or 1)
    overlaps = find_modbus_variable_address_overlaps(variables, function_code, start_address, register_count)
    if overlaps and not bool(args.get("allow_address_overlap", False)):
        raise ValueError(f"Refusing Modbus register row address overlap without allow_address_overlap=true: {overlaps}")

    insert_index_arg = args.get("insert_index")
    if insert_index_arg is None:
        variable_index = len(variables)
        variables.append(new_variable)
        if new_metadata is not None:
            metadata_rows.append(new_metadata)
    else:
        variable_index = int(insert_index_arg)
        if variable_index < 0 or variable_index > len(variables):
            raise ValueError(f"insert_index is out of range: {variable_index}")
        if create_network_descriptor and variable_index < len(metadata_rows):
            raise ValueError("create_network_variable_descriptor=true supports append-only insertion to preserve OWEN GUI metadata layout")
        variables.insert(variable_index, new_variable)
        if new_metadata is not None:
            metadata_rows.insert(variable_index, new_metadata)

    if create_network_descriptor:
        document = project_section.get(document_id)
        if not isinstance(document, dict):
            raise ValueError(f"Project document was not found for document_id={document_id}")
        assert network_descriptor is not None
        network_descriptor_result = append_network_variable_descriptor(document, document_id, network_descriptor)

    created = summarize_created_modbus_variable(document_id, setting_index, setting, device_index, device, variable_index)
    after = summarize_modbus_setting_device(document_id, setting_index, setting, device_index, device)
    write_owle_project_section(project_path, entries, project_section)
    after_hash = sha256_file(project_path)
    validation = None
    if bool(args.get("validate_after", True)):
        validation = project_validate({"project_path": str(project_path), "include_warnings": True})
    map_after = None
    if bool(args.get("include_map_after", True)):
        map_args: dict[str, Any] = {
            "project_path": str(project_path),
            "include_empty_devices": True,
            "max_rows": 200,
        }
        if args.get("map_output_dir"):
            map_args["output_dir"] = args.get("map_output_dir")
        map_after = project_modbus_export_map(map_args)

    source_hash_after = sha256_file(Path(str(target["source"]["path"])))
    return {
        "server": {"name": SERVER_NAME, "version": SERVER_VERSION},
        "source_project": target["source"],
        "scratch_copy": target["scratch_copy"] or safe_file_info(project_path, include_hash=True),
        "backup": target["backup"],
        "write_mode": target["write_mode"],
        "document_id": document_id,
        "setting_index": setting_index,
        "device_index": device_index,
        "setting_unique_id": setting.get("UniqueId"),
        "device_unique_id": device.get("UniqueId"),
        "new_variable_index": variable_index,
        "new_variable_unique_id": new_variable.get("UniqueId"),
        "created_network_variable_descriptor": bool(network_descriptor_result and network_descriptor_result.get("descriptor_created")),
        "created_network_variable_table_row": create_network_descriptor,
        "network_variable_descriptor": network_descriptor_result,
        "variable_count_before": int(before["device"].get("VariableModelCount") or 0),
        "variable_count_after": int(after["device"].get("VariableModelCount") or 0),
        "created": created,
        "address_overlap_count": len(overlaps),
        "address_overlaps": overlaps,
        "before": before,
        "after": after,
        "validation_after": validation,
        "modbus_map_after": map_after,
        "target_hash_before": before_hash,
        "target_hash_after": after_hash,
        "changed": before_hash != after_hash,
        "source_hash_after": source_hash_after,
        "source_hash_preserved": source_hash_after == target["source"].get("sha256"),
        "opened_serial_port": False,
        "opened_network_socket": False,
        "launched_gui": False,
        "gui_modbus_dialog_executed": False,
        "risk_class": "safe_write_project",
        "guardrail": "Created one offline Modbus DeviceModels.VariableModels register row only on a scratch copy or explicitly confirmed scratch path. Address/function/name/UUID guardrails are enforced; no COM/TCP, live device contact or GUI Modbus dialog is executed.",
        "limitation": "This is offline .owle register-row creation and export/readback evidence. create_network_variable_descriptor=true uses the legacy option name and creates the GUI-observed network-table Rs485 row plus matching DocumentModel network descriptor with the same UUID; OWEN GUI CSV evidence showed no separate MappingParameter row for this path. No COM/TCP is opened.",
    }


def project_modbus_device_patch(args: dict[str, Any]) -> dict[str, Any]:
    setting_patch = require_patch_object("setting_patch", args.get("setting_patch"))
    device_patch = require_patch_object("device_patch", args.get("device_patch"))
    if not setting_patch and not device_patch:
        raise ValueError("At least one of setting_patch or device_patch must include a field")

    target = resolve_scratch_write_target(args, "_modbus_device_patch_scratch")
    project_path = Path(str(target["target_path"]))
    before_hash = sha256_file(project_path)
    entries = read_owle_raw_entries(project_path)
    project_section = read_project_section_from_entries(entries)
    document_arg = str(args.get("document_id")) if args.get("document_id") else None
    setting_uid_arg = str(args.get("setting_unique_id")) if args.get("setting_unique_id") else None
    device_uid_arg = str(args.get("device_unique_id")) if args.get("device_unique_id") else None
    document_id, setting_index, setting, device_index, device = select_modbus_device(
        project_section,
        document_arg,
        args.get("setting_index"),
        setting_uid_arg,
        args.get("device_index"),
        device_uid_arg,
    )

    if args.get("expected_setting_unique_id") is not None and str(setting.get("UniqueId") or "") != str(args.get("expected_setting_unique_id")):
        raise ValueError("Selected Modbus setting does not match expected_setting_unique_id")
    if args.get("expected_device_unique_id") is not None and str(device.get("UniqueId") or "") != str(args.get("expected_device_unique_id")):
        raise ValueError("Selected Modbus device does not match expected_device_unique_id")
    if args.get("expected_address") is not None and int(device.get("Address", -1)) != int(args.get("expected_address")):
        raise ValueError("Selected Modbus device does not match expected_address")

    before = summarize_modbus_setting_device(document_id, setting_index, setting, device_index, device)
    variable_ids = collect_variable_ids(project_section)
    changes = []
    changes.extend(apply_modbus_patch_fields(setting, setting_patch, MODBUS_SETTING_PATCH_RULES, "setting", variable_ids))
    changes.extend(apply_modbus_patch_fields(device, device_patch, MODBUS_DEVICE_PATCH_RULES, "device", variable_ids))
    if not any(change["changed"] for change in changes):
        raise ValueError("Modbus patch did not change any selected field")
    after = summarize_modbus_setting_device(document_id, setting_index, setting, device_index, device)

    write_owle_project_section(project_path, entries, project_section)
    after_hash = sha256_file(project_path)
    validation = None
    if bool(args.get("validate_after", True)):
        validation = project_validate({"project_path": str(project_path), "include_warnings": True})
    map_after = None
    if bool(args.get("include_map_after", True)):
        map_args: dict[str, Any] = {
            "project_path": str(project_path),
            "include_empty_devices": True,
            "max_rows": 100,
        }
        if args.get("map_output_dir"):
            map_args["output_dir"] = args.get("map_output_dir")
        map_after = project_modbus_export_map(map_args)

    source_hash_after = sha256_file(Path(str(target["source"]["path"])))
    source_hash_preserved = source_hash_after == target["source"].get("sha256")
    return {
        "source_project": target["source"],
        "scratch_copy": target["scratch_copy"] or safe_file_info(project_path, include_hash=True),
        "backup": target["backup"],
        "write_mode": target["write_mode"],
        "document_id": document_id,
        "setting_index": setting_index,
        "device_index": device_index,
        "setting_unique_id": setting.get("UniqueId"),
        "device_unique_id": device.get("UniqueId"),
        "changes": changes,
        "before": before,
        "after": after,
        "validation_after": validation,
        "modbus_map_after": map_after,
        "target_hash_before": before_hash,
        "target_hash_after": after_hash,
        "changed": before_hash != after_hash,
        "source_hash_after": source_hash_after,
        "source_hash_preserved": source_hash_preserved,
        "opened_serial_port": False,
        "opened_network_socket": False,
        "launched_gui": False,
        "risk_class": "safe_write_project",
        "guardrail": "Only existing Modbus ProjectSettingModels/DeviceModels scalar fields were patched, only on a scratch copy or explicitly confirmed scratch path. The tool does not open COM/TCP, does not contact devices and does not execute GUI Modbus import/export dialogs.",
    }


