    setting_fields = sorted(MODBUS_SETTING_PATCH_RULES)
    device_fields = sorted(MODBUS_DEVICE_PATCH_RULES)
    import_setting_columns = sorted(MODBUS_IMPORT_SETTING_COLUMNS)
